INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92179, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检测是用办法查一查东西好不好。", "primary_collocate": null, "pronunciation": "jiǎn cè", "ipa": "tɕjɛn˨˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "请你检测一下这瓶水干不干净。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买来的肉，我们先检测再吃。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈想检测牛奶有没有问题。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一个小办法检测鸡蛋新不新。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车以前，先检测一下车好不好。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种米我们检测过，没有问题。", "target_word": "检测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王检测手机，发现屏幕坏了。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请医生检测学生的视力。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在检测这台电脑好不好用。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水管有没有漏水，先检测一下才知道。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "检测了", "label": "体标"}, {"form": "检测过", "label": "体标"}, {"form": "检测仪", "label": "复合"}], "register": "中性", "sense_fingerprint": "用办法查看东西的好坏、有没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赏识美好的事物，不能用来判断水干不干净。"}, {"text": "检测", "is_correct": true, "explanation": "正确：用办法查一查水干不干净，与句意相合。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于美化，不说“装饰水干不干净”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于坏了的东西，不说“修理水干不干净”。"}], "explanations": {"欣赏": "语义：“欣赏”是赏识美好的事物，不能用来判断水干不干净。", "检测": "正确：用办法查一查水干不干净，与句意相合。", "装饰": "搭配：“装饰”用于美化，不说“装饰水干不干净”。", "修理": "搭配：“修理”用于坏了的东西，不说“修理水干不干净”。"}, "sentence_index": 0, "correct_answer": "检测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我检测了老师的话，全部听懂了。", "explanation": "这里应该用〈听〉。检测用于查看物品的好坏和状态，听别人说话要用听。"}, {"text": "我检测了他的心情，觉得他很高兴。", "explanation": "这里应该用〈体会〉。检测用于查看物品的好坏和状态，体会别人的心情要用体会。"}, {"text": "我检测了墙上的画，觉得很好。", "explanation": "这里应该用〈看〉。检测是检查好坏、有没有问题的方法，欣赏墙上的画要用看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸奖", "is_correct": false, "explanation": "搭配：“夸奖”的对象是人或成绩，不能说“夸奖手机”。"}, {"text": "检测", "is_correct": true, "explanation": "正确：查看手机的状态，结果发现屏幕坏了，与句意相合。"}, {"text": "咏叹", "is_correct": false, "explanation": "语域：“咏叹”偏书面文学用语，口语中不合适，且不能用于手机。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“发现屏幕坏了”的查看结果不合。"}], "explanations": {"夸奖": "搭配：“夸奖”的对象是人或成绩，不能说“夸奖手机”。", "检测": "正确：查看手机的状态，结果发现屏幕坏了，与句意相合。", "咏叹": "语域：“咏叹”偏书面文学用语，口语中不合适，且不能用于手机。", "赞美": "语义：“赞美”是称赞，与“发现屏幕坏了”的查看结果不合。"}, "sentence_index": 6, "correct_answer": "检测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我检测他的脾气。", "explanation": "这里应该用〈了解〉。检测用于查看物品的好坏和状态，认识一个人的脾气要用了解。"}, {"text": "我检测他已经到家了。", "explanation": "这里应该用〈猜〉。检测要用办法查出结果，说自己的推测要用猜。"}, {"text": "我检测了一下妈妈的笑容，她看起来很开心。", "explanation": "这里应该用〈欣赏〉。检测用于查看物品的好坏和状态，欣赏美好的笑容要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你检测了这个西瓜甜不甜。", "corrected_sentence": "请你检测一下这个西瓜甜不甜。", "error_description": "错误：“检测了这个西瓜”。正确：“检测一下这个西瓜”。请别人做一件事时用“一下”，不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑我们检测着，没有问题。", "corrected_sentence": "这台电脑我们检测过，没有问题。", "error_description": "错误：“检测着”。正确：“检测过”。说已经做完、有了结果的经历，要用“过”，不用表示正在持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
