INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92180, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器或方法检查测定，以确定质量、状态等。", "primary_collocate": null, "pronunciation": "jiǎn cè", "ipa": "tɕjɛn˨˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "工人用仪器检测水的质量。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用新机器检测病人的血。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器可以检测空气里的灰尘。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶进商店以前，要先检测一下。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用试纸检测了这杯水。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每天都会检测产品的质量。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民请人检测土地适不适合种菜。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家正在检测桥的安全状态。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用新方法检测过这种药。", "target_word": "检测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机店的人检测了我的电池，说还能用。", "target_word": "检测", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "检测了", "label": "体标"}, {"form": "检测过", "label": "体标"}, {"form": "检测仪", "label": "复合"}], "register": "中性", "sense_fingerprint": "用仪器或专门方法检查并测定质量、状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "语义：品尝要靠味觉，不能用仪器去品尝水的质量。"}, {"text": "检测", "is_correct": true, "explanation": "正确：用仪器测定水的质量，与句中“用仪器”相合。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“节约”用于水、电等用量，不说“水的质量”。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”是美化物体，不用来检查“水的质量”。"}], "explanations": {"品尝": "语义：品尝要靠味觉，不能用仪器去品尝水的质量。", "检测": "正确：用仪器测定水的质量，与句中“用仪器”相合。", "节约": "搭配：“节约”用于水、电等用量，不说“水的质量”。", "装饰": "搭配：“装饰”是美化物体，不用来检查“水的质量”。"}, "sentence_index": 0, "correct_answer": "检测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我检测了一下这张地图，很快找到了回家的路。", "explanation": "这里应该用〈看〉。检测指用仪器或专门方法测定质量、状态，看地图找路要用看。"}, {"text": "妈妈每天检测我的作业。", "explanation": "这里应该用〈检查〉。检测指用仪器或专门方法测定，日常看作业要用检查。"}, {"text": "我检测了一下天气预报。", "explanation": "这里应该用〈查看〉。检测用于测定物品的质量或状态，读天气预报要用查看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不用于判断土地是否适合种菜。"}, {"text": "检测", "is_correct": true, "explanation": "正确：请人测定土地是否适合种菜，与句意相合。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋、房间，不说“装修土地”。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”针对事情或人，与判断土地适不适合种菜无关。"}], "explanations": {"欣赏": "语义：“欣赏”指赏识美好的事物，不用于判断土地是否适合种菜。", "检测": "正确：请人测定土地是否适合种菜，与句意相合。", "装修": "搭配：“装修”用于房屋、房间，不说“装修土地”。", "祝贺": "语义：“祝贺”针对事情或人，与判断土地适不适合种菜无关。"}, "sentence_index": 6, "correct_answer": "检测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们检测了一下这次的作文题目。", "explanation": "这里应该用〈分析〉。检测指用仪器或专门方法测定质量、状态，分析题目要用分析。"}, {"text": "我检测明天会下雨。", "explanation": "这里应该用〈估计〉。检测要用仪器或方法查出结果，说自己的推测要用估计。"}, {"text": "我检测了一下这部电影，觉得很感人。", "explanation": "这里应该用〈欣赏〉。检测指用仪器或专门方法测定质量、状态，欣赏电影要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人检测了出水里的细菌。", "corrected_sentence": "工人检测出了水里的细菌。", "error_description": "错误：“检测了出”。正确：“检测出了”。结果补语“出”要紧跟动词，“了”应放在补语之后，不能插在“检测”和“出”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们检测了过这批新药。", "corrected_sentence": "他们检测过这批新药。", "error_description": "错误：“检测了过”。正确：“检测过”。“过”已表示曾经经历，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和蔼", "is_correct": true, "explanation": "“和蔼”与“凶”相对，表示待人亲切，是“严厉”（很凶）的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "与“严厉”没有反义关系，“聪明”形容头脑灵活。"}, {"text": "高大", "is_correct": false, "explanation": "与“严厉”没有反义关系，“高大”形容身材或体积。"}, {"text": "整齐", "is_correct": false, "explanation": "与“严厉”没有反义关系，“整齐”形容排列或外观规整。"}], "correct_answer": "和蔼", "explanations": {"和蔼": "“和蔼”与“凶”相对，表示待人亲切，是“严厉”（很凶）的反义词。", "聪明": "与“严厉”没有反义关系，“聪明”形容头脑灵活。", "高大": "与“严厉”没有反义关系，“高大”形容身材或体积。", "整齐": "与“严厉”没有反义关系，“整齐”形容排列或外观规整。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和蔼", "is_correct": true, "explanation": "“和蔼”与“凶”相对，表示待人亲切，是“严厉”（很凶）的反义词。"}, {"text": "勤劳", "is_correct": false, "explanation": "与“严厉”没有反义关系，“勤劳”形容人肯干。"}, {"text": "明亮", "is_correct": false, "explanation": "与“严厉”没有反义关系，“明亮”形容光线或颜色。"}, {"text": "安静", "is_correct": false, "explanation": "与“严厉”没有反义关系，“安静”形容环境或人声音小。"}], "correct_answer": "和蔼", "explanations": {"和蔼": "“和蔼”与“凶”相对，表示待人亲切，是“严厉”（很凶）的反义词。", "勤劳": "与“严厉”没有反义关系，“勤劳”形容人肯干。", "明亮": "与“严厉”没有反义关系，“明亮”形容光线或颜色。", "安静": "与“严厉”没有反义关系，“安静”形容环境或人声音小。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很凶，不能做错一点。", "primary_collocate": null, "pronunciation": "yán lì", "ipa": "jɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们的数学老师很严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看起来很严厉，其实很爱我。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表情很严厉，小朋友都怕他。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不严厉，爷爷很严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着我，眼神很严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师太严厉了，我们不敢出错。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他严厉地训斥了我一顿，因为我没做作业。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅很严厉，一点错也不能有。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么你今天这么严厉？", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕严厉的老师，因为做错就会挨骂。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严厉地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "人很凶，不允许出一点错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严厉", "is_correct": true, "explanation": "“严厉”形容人凶、不许出错，用来评价老师，符合句意。"}, {"text": "白", "is_correct": false, "explanation": "体貌：“白”形容皮肤颜色，不能用来形容老师的性格。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容食物或易碎的东西，不用来形容人。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味觉，与“数学老师”的性格没有关系。"}], "explanations": {"严厉": "“严厉”形容人凶、不许出错，用来评价老师，符合句意。", "白": "体貌：“白”形容皮肤颜色，不能用来形容老师的性格。", "脆": "搭配：“脆”形容食物或易碎的东西，不用来形容人。", "咸": "语义：“咸”是味觉，与“数学老师”的性格没有关系。"}, "sentence_index": 0, "correct_answer": "严厉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的风很严厉，大家都躲在屋里。", "explanation": "这里应该用〈猛烈〉。严厉形容人凶、不许出错，不用来形容风。"}, {"text": "这盘菜很严厉，我不太敢吃。", "explanation": "这里应该用〈辣〉。严厉不用来形容菜的味道。"}, {"text": "这只鸟的叫声很严厉。", "explanation": "这里应该用〈清脆〉。严厉形容人凶、不许出错的样子，鸟的叫声没有这种态度，不能说“严厉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严厉", "is_correct": true, "explanation": "“严厉”形容人凶、不许出错，与“训斥”的语气相合。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”的神情与训斥的语气不合。"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”的神情与训斥的语气相反。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与“训斥”相反，“温柔地训斥”自相矛盾。"}], "explanations": {"严厉": "“严厉”形容人凶、不许出错，与“训斥”的语气相合。", "甜蜜": "语义：“甜蜜”的神情与训斥的语气不合。", "欢快": "语义：“欢快”的神情与训斥的语气相反。", "温柔": "语义：“温柔”与“训斥”相反，“温柔地训斥”自相矛盾。"}, "sentence_index": 6, "correct_answer": "严厉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯茶很严厉。", "explanation": "这里应该用〈苦〉。严厉不用来形容茶的味道。"}, {"text": "这间房间很严厉。", "explanation": "这里应该用〈宽敞〉。严厉不用来形容房间的大小。"}, {"text": "这把椅子很严厉。", "explanation": "这里应该用〈结实〉。严厉不用来形容物体的牢固程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她严厉的看着弟弟，说：“快去写作业！”", "corrected_sentence": "她严厉地看着弟弟，说：“快去写作业！”", "error_description": "修饰语错误：“严厉”修饰动词“看着”时要用“地”，应写作“严厉地看着”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师批评我时说很严厉，我不敢回嘴。", "corrected_sentence": "老师批评我时说得很严厉，我不敢回嘴。", "error_description": "补语标记缺失：“说”后带程度补语“很严厉”时要用“得”连接，应写作“说得很严厉”，不能说“说很严厉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽容", "is_correct": true, "explanation": "“宽容”指对人宽大、不严格追究，与“严厉”（严肃而厉害、要求严格）意思相对。"}, {"text": "清楚", "is_correct": false, "explanation": "与“严厉”没有反义关系，二者意思没有对立。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“严厉”没有反义关系，“粗糙”形容物体表面。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“严厉”没有反义关系，“漂亮”形容外貌或事物美观。"}], "correct_answer": "宽容", "explanations": {"宽容": "“宽容”指对人宽大、不严格追究，与“严厉”（严肃而厉害、要求严格）意思相对。", "清楚": "与“严厉”没有反义关系，二者意思没有对立。", "粗糙": "与“严厉”没有反义关系，“粗糙”形容物体表面。", "漂亮": "与“严厉”没有反义关系，“漂亮”形容外貌或事物美观。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽容", "is_correct": true, "explanation": "“宽容”指对人宽大、不严格追究，与“严厉”（严肃而厉害、要求严格）意思相对。"}, {"text": "明亮", "is_correct": false, "explanation": "与“严厉”没有反义关系，“明亮”形容光线或颜色。"}, {"text": "轻便", "is_correct": false, "explanation": "与“严厉”没有反义关系，“轻便”形容东西轻巧方便。"}, {"text": "湿润", "is_correct": false, "explanation": "与“严厉”没有反义关系，“湿润”形容含水分多的状态。"}], "correct_answer": "宽容", "explanations": {"宽容": "“宽容”指对人宽大、不严格追究，与“严厉”（严肃而厉害、要求严格）意思相对。", "明亮": "与“严厉”没有反义关系，“明亮”形容光线或颜色。", "轻便": "与“严厉”没有反义关系，“轻便”形容东西轻巧方便。", "湿润": "与“严厉”没有反义关系，“湿润”形容含水分多的状态。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严肃而厉害；要求很严格。", "primary_collocate": null, "pronunciation": "yán lì", "ipa": "jɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "王老师对学生要求很严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理严厉地批评了迟到的人。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很严厉，大家都不敢说话。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律对这种行为的处罚很严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的态度非常严厉，没有人敢迟到。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用严厉的声音说：“不许再去了。”", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对安全问题有严厉的规定。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不对孩子说严厉的话。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练训练队员时十分严厉。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，政府会严厉处理。", "target_word": "严厉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严厉地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "态度、要求、处罚严肃而厉害，很严格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严厉", "is_correct": true, "explanation": "“严厉”指要求严格、态度严肃，与“要求很”搭配，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味觉，不能用来形容“要求”。"}, {"text": "快乐", "is_correct": false, "explanation": "搭配：“要求”不能用“快乐”来修饰，二者搭配不当。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不用来修饰“要求”。"}], "explanations": {"严厉": "“严厉”指要求严格、态度严肃，与“要求很”搭配，符合句意。", "甜": "语义：“甜”是味觉，不能用来形容“要求”。", "快乐": "搭配：“要求”不能用“快乐”来修饰，二者搭配不当。", "高大": "体貌：“高大”形容人或物的外形，不用来修饰“要求”。"}, "sentence_index": 0, "correct_answer": "严厉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台风来得很严厉，人们都躲在家里。", "explanation": "这里应该用〈猛烈〉。严厉形容人的态度、要求或处罚，不用来形容台风等自然现象。"}, {"text": "这场比赛很严厉，两队都很努力。", "explanation": "这里应该用〈激烈〉。严厉形容人的态度或规定，不形容比赛的强弱。"}, {"text": "他的心情很严厉。", "explanation": "这里应该用〈平静〉。严厉用于人的态度或规定，不用来说心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严厉", "is_correct": true, "explanation": "“严厉”指要求严格，与“规定”搭配，符合句意。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或事物惹人喜爱，不用来形容规定。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”形容感情或生活的幸福，不修饰“规定”。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”修饰人，不修饰“规定”。"}], "explanations": {"严厉": "“严厉”指要求严格，与“规定”搭配，符合句意。", "可爱": "语义：“可爱”形容人或事物惹人喜爱，不用来形容规定。", "甜蜜": "语义：“甜蜜”形容感情或生活的幸福，不修饰“规定”。", "年轻": "搭配：“年轻”修饰人，不修饰“规定”。"}, "sentence_index": 6, "correct_answer": "严厉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜很严厉。", "explanation": "这里应该用〈甜〉。严厉用于人的态度、要求或处罚，不用来形容味道。"}, {"text": "那条小路很严厉。", "explanation": "这里应该用〈安静〉。严厉不用来形容环境。"}, {"text": "这块石头很严厉。", "explanation": "这里应该用〈粗糙〉。严厉不用来形容物体的表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司严厉的禁止迟到。", "corrected_sentence": "这家公司严厉地禁止迟到。", "error_description": "修饰语错误：“严厉”修饰动词“禁止”时要用“地”，写作“严厉地禁止”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对这件事，政府会严厉的处理。", "corrected_sentence": "对这件事，政府会严厉地处理。", "error_description": "修饰语错误：“严厉”修饰动词“处理”时要用“地”，应写作“严厉地处理”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
