INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所知是自己知道的事情。", "primary_collocate": null, "pronunciation": "suǒ zhī", "ipa": "swo˨˩ ʈʂʅ˥", "syllable_count": 2, "sentences": [{"text": "据我所知，他今天不在家。", "target_word": "所知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "就我所知，这家店九点开门。", "target_word": "所知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我所知有限，不能回答你。", "target_word": "所知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把所知的事都告诉了老师。", "target_word": "所知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这件事，我所知很少。", "target_word": "所知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把你所知的情况说一说。", "target_word": "所知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他所知不多，不便再追问。", "target_word": "所知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "据我所知，她还没有结婚。", "target_word": "所知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这就是我所知的全部情况。", "target_word": "所知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "就我所知，这条路不通车。", "target_word": "所知", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "所知：自己知道的事情，常见于据我所知、就我所知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所知", "is_correct": true, "explanation": "正确。所知指自己知道的事情。"}, {"text": "所指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是所指向的对象。"}, {"text": "所致", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是由某种原因造成。"}, {"text": "所值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。"}, {"text": "锁止", "is_correct": false, "explanation": "suǒ zhǐ 与 suǒ zhī 只在末字声调不同，意思是锁住使其不能动。"}], "explanations": {"所知": "正确。所知指自己知道的事情。", "所指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是所指向的对象。", "所致": "zhì（第四声）与 zhī（第一声）声调不同，意思是由某种原因造成。", "所值": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。", "锁止": "suǒ zhǐ 与 suǒ zhī 只在末字声调不同，意思是锁住使其不能动。"}, "sentence_index": null, "correct_answer": "所知"}, "level_3": {"options": [{"text": "所知", "is_correct": true, "explanation": "正确。「据我所知」表示“就我知道的情况”，与后句“他今天不在家”的判断相符。"}, {"text": "所愿", "is_correct": false, "explanation": "语义：“所愿”是愿望，不能作为判断依据，“据我所愿”无法引出“他今天不在家”。"}, {"text": "所爱", "is_correct": false, "explanation": "搭配：“据”常与“所知、所见、所闻”搭配，不与“所爱”搭配。"}, {"text": "所恨", "is_correct": false, "explanation": "语义：“所恨”指讨厌的事，与对他行踪的判断无关。"}], "explanations": {"所知": "正确。「据我所知」表示“就我知道的情况”，与后句“他今天不在家”的判断相符。", "所愿": "语义：“所愿”是愿望，不能作为判断依据，“据我所愿”无法引出“他今天不在家”。", "所爱": "搭配：“据”常与“所知、所见、所闻”搭配，不与“所爱”搭配。", "所恨": "语义：“所恨”指讨厌的事，与对他行踪的判断无关。"}, "sentence_index": 0, "correct_answer": "所知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把所知的钱都存进了银行。", "explanation": "这里应该用〈所有〉。所知指自己知道的事情，不指钱财；“所有的钱”才是拥有的财物。"}, {"text": "他对这件事有一块所知。", "explanation": "这里量词用错。所知是抽象的，应该用〈一点〉，不用“一块”。"}, {"text": "他的所知去了北京，还没回来。", "explanation": "所知是抽象名词，不能像人一样去北京。这里把它误当成了会移动的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所知", "is_correct": true, "explanation": "正确。“他所知不多”指他知道的事情少，与“不便再追问”相符。"}, {"text": "所欲", "is_correct": false, "explanation": "语义：“所欲”指欲望，不是知道的事，无法解释“不便再追问”。"}, {"text": "所望", "is_correct": false, "explanation": "语义：“所望”指期望，不能说明为什么不便再追问。"}, {"text": "所念", "is_correct": false, "explanation": "搭配：“所念”多指所想念的人或事，与“不多”和“追问”搭配不当。"}], "explanations": {"所知": "正确。“他所知不多”指他知道的事情少，与“不便再追问”相符。", "所欲": "语义：“所欲”指欲望，不是知道的事，无法解释“不便再追问”。", "所望": "语义：“所望”指期望，不能说明为什么不便再追问。", "所念": "搭配：“所念”多指所想念的人或事，与“不多”和“追问”搭配不当。"}, "sentence_index": 6, "correct_answer": "所知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的所知很强，什么问题都难不倒他。", "explanation": "这里应该用〈能力〉。所知指知道的事，不指能力的强弱；“很强”要搭配“能力”。"}, {"text": "他掌握了一项所知，很快就能应用。", "explanation": "这里量词用错。所知不用“一项”，“项”用于技能、任务等；这里应该用〈一点〉。"}, {"text": "他把所知装进了书包里带走。", "explanation": "所知指自己知道的事情，是抽象的，不能像物品一样装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "据我所知了，这件事还没有结束。", "corrected_sentence": "据我所知，这件事还没有结束。", "error_description": "错误：“所知”后多加了“了”。“据我所知”是固定说法，“所知”后面不能加“了”。正确：“据我所知”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "就我所知了，这条路晚上不通车。", "corrected_sentence": "就我所知，这条路晚上不通车。", "error_description": "错误：“就我所知”是固定说法，“所知”后不能加“了”。正确：“就我所知”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
