INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家主权管辖下的全部领土。", "primary_collocate": null, "pronunciation": "guó tǔ", "ipa": "kwo˧˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要保卫国家的国土，不能让别人占领。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任何国家都不允许外国军队进入自己的国土。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛是我国国土的一部分，不能分开。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，敌人退出了我们的国土。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边防军人每天守卫着祖国的国土。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国土不容侵犯，这是每个国家的基本原则。", "target_word": "国土", "complexity_tier": "T3", "furigana": "guó tǔ bù róng qīn fàn zhè shì měi gè guó jiā de jī běn yuán zé", "sentence_source": "generated"}, {"text": "两国签了条约，承认彼此的国土完整。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，保卫国土是每个人的责任。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的任务是守住国土，不让敌人进来。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，红线里面就是我国的国土。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國土", "label": "繁体"}, {"form": "国土安全", "label": "复合"}, {"form": "国土资源", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家主权管辖下的领土，常与保卫、主权搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国土", "is_correct": true, "explanation": "正确：“国土”指国家主权管辖下的领土，与“保卫”“占领”搭配。"}, {"text": "人民", "is_correct": false, "explanation": "语义：“人民”指人，不是领土，不能被占领。"}, {"text": "货币", "is_correct": false, "explanation": "语义：“货币”是流通的钱，不是领土，不能被占领。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“占领”搭配阵地、城市等地域，不说“占领空气”。"}], "explanations": {"国土": "正确：“国土”指国家主权管辖下的领土，与“保卫”“占领”搭配。", "人民": "语义：“人民”指人，不是领土，不能被占领。", "货币": "语义：“货币”是流通的钱，不是领土，不能被占领。", "空气": "搭配：“占领”搭配阵地、城市等地域，不说“占领空气”。"}, "sentence_index": 0, "correct_answer": "国土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国土的老板很有钱，经常请大家吃饭。", "explanation": "这里应该用〈公司〉。“国土”指领土，不能指一家公司，应说“这家公司的老板”。"}, {"text": "我的国土在一个小村子里。", "explanation": "这里应该用〈故乡〉。“国土”指国家的全部领土，不能说成一个小村子。"}, {"text": "学校的国土很大，有很多操场。", "explanation": "这里应该用〈校园〉。学校不是国家，“国土”不能用来说校园的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国土", "is_correct": true, "explanation": "正确：“国土”指领土，与“承认”“完整”搭配，说领土主权。"}, {"text": "军队", "is_correct": false, "explanation": "搭配：条约承认的是领土完整，“承认彼此的军队完整”不成话。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”指吃喝，不是国家的范围，不能说“不可分割”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是作品，不是领土，与“两国签约承认”无关。"}], "explanations": {"国土": "正确：“国土”指领土，与“承认”“完整”搭配，说领土主权。", "军队": "搭配：条约承认的是领土完整，“承认彼此的军队完整”不成话。", "饮食": "语义：“饮食”指吃喝，不是国家的范围，不能说“不可分割”。", "歌曲": "语义：“歌曲”是作品，不是领土，与“两国签约承认”无关。"}, "sentence_index": 6, "correct_answer": "国土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的国土很大，有很多工厂。", "explanation": "这里应该用〈面积〉。“国土”只指国家主权管辖下的领土，不能用来说一座城市的大小。"}, {"text": "他办好了这个国土的护照，可以出国了。", "explanation": "这里应该用〈国家〉。“国土”指领土，不能拥有护照，护照属于国家。"}, {"text": "这个国土今年参加比赛，拿了第一名。", "explanation": "“国土”指领土，不能指参赛的队伍或团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只国土上住着我们的祖先。", "corrected_sentence": "这片国土上住着我们的祖先。", "error_description": "量词错误：“只”用于动物等，不能修饰“国土”；应改为“片”或“块”，即“这片国土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人终于退出了我们的国土上。", "corrected_sentence": "敌人终于退出了我们的国土。", "error_description": "方位词多余：“退出”后直接带处所“国土”，不能再加“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
