INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手表是戴在手腕上看时间的东西。", "primary_collocate": null, "pronunciation": "shǒu biǎo", "ipa": "ʂoʊ²¹⁴ piɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他手腕上戴着一块手表。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表慢了五分钟。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送了我一块新手表。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块手表是用电池的。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了一下手表，已经八点了。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把手表放在桌子上。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手表坏了，所以迟到了。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块手表不贵，但是很好看。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手的时候，请先摘下手表。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手表来看时间。", "target_word": "手表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手錶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戴在手腕上看时间的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": false, "explanation": "搭配：眼镜的量词用“副”，不用“块”；且眼镜不戴在手腕上。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链戴在颈部，不戴在手腕上。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是戴在手腕上的东西。"}, {"text": "手表", "is_correct": true, "explanation": "手表：戴在手腕上看时间的东西，符合句意。"}], "explanations": {"眼镜": "搭配：眼镜的量词用“副”，不用“块”；且眼镜不戴在手腕上。", "项链": "语义：项链戴在颈部，不戴在手腕上。", "手机": "语义：手机不是戴在手腕上的东西。", "手表": "手表：戴在手腕上看时间的东西，符合句意。"}, "sentence_index": 0, "correct_answer": "手表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手腕上戴着一本手表。", "explanation": "这里量词用错。“本”用于书册，手表应该用“块”。"}, {"text": "他手腕上戴着一辆手表。", "explanation": "这里量词用错。“辆”用于车辆，手表应该用“块”。"}, {"text": "他手腕上戴着一把手表。", "explanation": "这里量词用错。“把”用于有柄的器具，手表应该用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流不是人可以拥有并“坏了”的东西。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人可以拥有并“坏了”的东西。"}, {"text": "树叶", "is_correct": false, "explanation": "体貌：树叶是植物的部分，不是可以“坏了”的用品。"}, {"text": "手表", "is_correct": true, "explanation": "手表：会坏、会让人迟到的戴在手腕上的钟表，符合句意。"}], "explanations": {"河流": "语义：河流不是人可以拥有并“坏了”的东西。", "月亮": "语义：月亮不是人可以拥有并“坏了”的东西。", "树叶": "体貌：树叶是植物的部分，不是可以“坏了”的用品。", "手表": "手表：会坏、会让人迟到的戴在手腕上的钟表，符合句意。"}, "sentence_index": 6, "correct_answer": "手表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用手表来写字。", "explanation": "这里应该用“笔”。笔用来写字，手表是看时间的，不能用来写字。"}, {"text": "我用手表来扇风。", "explanation": "这里应该用“扇子”。扇子用来扇风，手表不能扇风。"}, {"text": "我用手表来做饭。", "explanation": "这里应该用“锅”。锅用来做饭，手表不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈给我买了一本手表。", "corrected_sentence": "我妈妈给我买了一块手表。", "error_description": "量词错误：应为“一块”，不应为“一本”。“本”用于书册，手表用“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天在公园里丢了一张手表。", "corrected_sentence": "他昨天在公园里丢了一块手表。", "error_description": "量词错误：应为“一块”，不应为“一张”。“张”用于纸、桌子等平面的东西，手表用“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
