INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "构成整体根基的、最基本的问题。", "primary_collocate": null, "pronunciation": "jī chǔ wèn tí", "ipa": "tɕi˥ ʈʂʰu˨˩˦ wən˥˩ tʰi˧˥", "syllable_count": 4, "sentences": [{"text": "这个城市的基础问题是水不够用。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要解决交通难题，先要抓住基础问题。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育公平是社会发展的基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "粮食够不够吃，是国家的基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院的基础问题是医生太少。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的基础问题不解决，换谁来也没用。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议讨论的是学校的基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水和电是村子发展的基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只谈小事，没有碰过真正的基础问题。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把基础问题解决好，别的事才容易做。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基礎問題", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "决定整体好坏的根本性问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1928561-c547-4f0d-a7bb-b100578bce76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基础问题", "is_correct": true, "explanation": "正确：“这个城市的基础问题”指决定全局的根本问题，与后面“水不够用”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气候现象，不是能解决的问题，说“天气是水不够用”不通。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不能说“公园是水不够用”，与全句的主语不搭。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能与“水不够用”搭配，说价格不够用不成立。"}], "explanations": {"基础问题": "正确：“这个城市的基础问题”指决定全局的根本问题，与后面“水不够用”相符。", "天气": "语义：天气是气候现象，不是能解决的问题，说“天气是水不够用”不通。", "公园": "语义：公园是场所，不能说“公园是水不够用”，与全句的主语不搭。", "价格": "搭配：“价格”不能与“水不够用”搭配，说价格不够用不成立。"}, "sentence_index": 0, "correct_answer": "基础问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的基础问题很完善，居民生活方便。", "explanation": "这里应该用〈基础设施〉。“完善”修饰设施、制度，“基础问题”指决定全局的根本问题，不能说完善。"}, {"text": "他把基础问题借给了同学看。", "explanation": "这里应该用〈笔记〉。“借给……看”的对象是书、笔记等有形的东西，“基础问题”是抽象的问题，不能借出。"}, {"text": "我的基础问题被小偷偷走了。", "explanation": "这里应该用〈钱包〉。“偷走”的对象是有形的财物，“基础问题”是抽象的问题，不能被偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基础问题", "is_correct": true, "explanation": "正确：“学校的基础问题”是会议讨论的内容，符合“讨论”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体征，不能说学校的身高，无法作为讨论内容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或动物的属性，学校没有体重，不能作为讨论内容。"}, {"text": "血压", "is_correct": false, "explanation": "搭配：“血压”一般说人的血压，与“学校”搭配不当。"}], "explanations": {"基础问题": "正确：“学校的基础问题”是会议讨论的内容，符合“讨论”的语境。", "身高": "语义：身高是人的体征，不能说学校的身高，无法作为讨论内容。", "体重": "语义：体重是人或动物的属性，学校没有体重，不能作为讨论内容。", "血压": "搭配：“血压”一般说人的血压，与“学校”搭配不当。"}, "sentence_index": 6, "correct_answer": "基础问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼的基础问题很牢固，住着很放心。", "explanation": "这里应该用〈地基〉。“牢固”修饰地基、结构，“基础问题”是抽象的问题，不能用牢固形容。"}, {"text": "我们先要打好基础问题，才能往上盖。", "explanation": "这里应该用〈根基〉。“打好根基”指打地基的根底，“基础问题”是问题，不能用来表示根基。"}, {"text": "我们要向基础问题学习，才能进步。", "explanation": "这里应该用〈老师〉。“向……学习”的对象应是人或经验，“基础问题”是问题，不能用来学习，应说向老师学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥有一只基础问题，就是地基不稳。", "corrected_sentence": "这座桥有一个基础问题，就是地基不稳。", "error_description": "量词错误：“基础问题”应配量词“个”，“只”多用于动物等，不能用来数问题，应为“一个基础问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革有三场基础问题要解决。", "corrected_sentence": "这次改革有三个基础问题要解决。", "error_description": "量词错误：“场”用于比赛、演出、雨等，不能用来数“基础问题”，应为“三个基础问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
