INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打跑是把坏人打得赶快跑开。", "primary_collocate": null, "pronunciation": "dǎ pǎo", "ipa": "ta˨˩ pʰau̯˨˩", "syllable_count": 2, "sentences": [{"text": "他一拳就把坏人打跑了。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥打跑了欺负我的坏人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保安打跑了想偷东西的小偷。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保安很快就把坏人打跑了。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个人打跑了抢包的坏人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我真想把这些坏人都打跑。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸拿起棍子，打跑了闯进家里的坏人。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们一起打跑了那几个坏人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候打跑过欺负同学的坏孩子。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人再来，我们就把他们打跑。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打跑了", "label": "完成体"}, {"form": "打跑过", "label": "经历体"}, {"form": "打不跑", "label": "可能补语（否定）"}], "register": "口语", "sense_fingerprint": "把坏人打得赶快跑开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92193, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑（dǎ pǎo）：把坏人打得赶快跑开，是听到的正确词。"}, {"text": "大炮", "is_correct": false, "explanation": "大炮（dà pào）：dǎ 第三声与 dà 第四声声调不同，pǎo 与 pào 也只差声调，意思是大炮。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫（dǎ sǎo）：第二个音节声母 p 换成 s，声调相同，意思是清扫。"}, {"text": "打好", "is_correct": false, "explanation": "打好（dǎ hǎo）：第二个音节声母 p 换成 h，声调相同，意思是把事情做好。"}], "explanations": {"打跑": "打跑（dǎ pǎo）：把坏人打得赶快跑开，是听到的正确词。", "大炮": "大炮（dà pào）：dǎ 第三声与 dà 第四声声调不同，pǎo 与 pào 也只差声调，意思是大炮。", "打扫": "打扫（dǎ sǎo）：第二个音节声母 p 换成 s，声调相同，意思是清扫。", "打好": "打好（dǎ hǎo）：第二个音节声母 p 换成 h，声调相同，意思是把事情做好。"}, "sentence_index": null, "correct_answer": "打跑"}, "level_3": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑：把坏人打得赶快跑开，正好接在“他一拳就把坏人……了”之后。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对人的好意表示，与“一拳就”打击坏人的语境矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能带“把”字句的宾语，“一拳就把坏人哭了”不成立。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：拥抱坏人与“一拳就”的打击语境矛盾。"}], "explanations": {"打跑": "打跑：把坏人打得赶快跑开，正好接在“他一拳就把坏人……了”之后。", "感谢": "语义：“感谢”是对人的好意表示，与“一拳就”打击坏人的语境矛盾。", "哭": "配价：“哭”不能带“把”字句的宾语，“一拳就把坏人哭了”不成立。", "拥抱": "语义：拥抱坏人与“一拳就”的打击语境矛盾。"}, "sentence_index": 0, "correct_answer": "打跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在拳击比赛中打跑了对手。", "explanation": "这里应该用〈打败〉。打跑说对方被打得逃开，拳击中对手不会逃走，应说打败。"}, {"text": "我们打跑了那扇生锈的铁门。", "explanation": "这里应该用〈砸开〉。打跑指人或动物被打得逃走，铁门不会逃跑，应说砸开。"}, {"text": "他在车站打跑了远行的朋友。", "explanation": "这里应该用〈送别〉。车站送行是告别，不是把人打得逃走，应说送别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑：把闯进家里的坏人赶走，符合“爸爸拿起棍子”的语境。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，保护闯进家里的坏人与拿棍子的语境矛盾。"}, {"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”的宾语应是棍子之类的物体，不能说挥舞人。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”用于值得称赞的人，表扬闯入者说不通。"}], "explanations": {"打跑": "打跑：把闯进家里的坏人赶走，符合“爸爸拿起棍子”的语境。", "保护": "语义：“保护”是护卫，保护闯进家里的坏人与拿棍子的语境矛盾。", "挥舞": "搭配：“挥舞”的宾语应是棍子之类的物体，不能说挥舞人。", "表扬": "语义：“表扬”用于值得称赞的人，表扬闯入者说不通。"}, "sentence_index": 6, "correct_answer": "打跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热烈地打跑了新来的同学。", "explanation": "这里应该用〈迎接〉。打跑带有驱赶的意思，与热烈欢迎的语境矛盾，应说迎接。"}, {"text": "他把那张旧桌子打跑了。", "explanation": "这里应该用〈打坏〉。打跑说的是把人或动物打得逃走，桌子不会逃跑，应说打坏。"}, {"text": "消防员打跑了被困的老人。", "explanation": "这里应该用〈救出〉。打跑让人逃走，被困的老人需要被救出，不能说打跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店员们一起把那个坏蛋打跑了着。", "corrected_sentence": "店员们一起把那个坏蛋打跑了。", "error_description": "错误：“打跑了着”，“了”与“着”不能同时用在同一动词上。正确：“打跑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾经打跑着那群抢劫的人。", "corrected_sentence": "我们曾经打跑过那群抢劫的人。", "error_description": "错误：“打跑着”，“曾经”表示经历，应用经历体“过”，不用进行体“着”。正确：“打跑过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
