INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打击对方使逃走。", "primary_collocate": null, "pronunciation": "dǎ pǎo", "ipa": "ta˨˩ pʰau̯˨˩", "syllable_count": 2, "sentences": [{"text": "战士们把敌人打跑了。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打跑了入侵的敌人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们用棍子打跑了野狗。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支小部队打跑了很多敌人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人拿着棍子，打跑了偷菜的人。", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们打跑敌人以后，回到了村子。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想打跑敌人，保护自己的家。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们打跑过敌人吗？", "target_word": "打跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察打跑了抢钱的坏人。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起打跑了闯进村子的土匪。", "target_word": "打跑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打跑了", "label": "完成体"}, {"form": "打跑过", "label": "经历体"}, {"form": "打不跑", "label": "可能补语（否定）"}], "register": "口语", "sense_fingerprint": "打击对方，使其逃走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑（dǎ pǎo）：打击对方使其逃走，是听到的正确词。"}, {"text": "大炮", "is_correct": false, "explanation": "大炮（dà pào）：dǎ 第三声与 dà 第四声声调不同，pǎo 与 pào 也只差声调，意思是大炮。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫（dǎ sǎo）：第二个音节声母 p 换成 s，声调相同，意思是清扫。"}, {"text": "打好", "is_correct": false, "explanation": "打好（dǎ hǎo）：第二个音节声母 p 换成 h，声调相同，意思是把事情做好。"}], "explanations": {"打跑": "打跑（dǎ pǎo）：打击对方使其逃走，是听到的正确词。", "大炮": "大炮（dà pào）：dǎ 第三声与 dà 第四声声调不同，pǎo 与 pào 也只差声调，意思是大炮。", "打扫": "打扫（dǎ sǎo）：第二个音节声母 p 换成 s，声调相同，意思是清扫。", "打好": "打好（dǎ hǎo）：第二个音节声母 p 换成 h，声调相同，意思是把事情做好。"}, "sentence_index": null, "correct_answer": "打跑"}, "level_3": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑：把敌人打得逃走，正好接在“战士们把敌人……了”之后。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫的意思，战士保护敌人与战斗语境矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”用于值得称赞的人，表扬敌人说不通。"}, {"text": "来", "is_correct": false, "explanation": "配价：“来”不能带“把”字句的宾语，“把敌人来了”不成立。"}], "explanations": {"打跑": "打跑：把敌人打得逃走，正好接在“战士们把敌人……了”之后。", "保护": "语义：“保护”是护卫的意思，战士保护敌人与战斗语境矛盾。", "表扬": "语义：“表扬”用于值得称赞的人，表扬敌人说不通。", "来": "配价：“来”不能带“把”字句的宾语，“把敌人来了”不成立。"}, "sentence_index": 0, "correct_answer": "打跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支小部队打跑了那座旧桥。", "explanation": "这里应该用〈拆除〉。打跑指人或动物被打得逃走，旧桥不会逃跑，应说拆除。"}, {"text": "他把那只旧杯子打跑了。", "explanation": "这里应该用〈打碎〉。打跑指人或动物被打得逃走，杯子不会逃跑，应说打碎。"}, {"text": "这支小部队打跑了他的邀请。", "explanation": "这里应该用〈拒绝〉。打跑只用于人或动物，邀请不能被打跑，应说拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打跑", "is_correct": true, "explanation": "打跑：想把敌人赶走以保护家园，正好符合语境。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”表示亲近，与“想……敌人，保护自己的家”的敌对语境冲突。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：没有人想感谢敌人，与“保护自己的家”的意思相反。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能带事物宾语，“想哭敌人”不成立。"}], "explanations": {"打跑": "打跑：想把敌人赶走以保护家园，正好符合语境。", "拥抱": "语义：“拥抱”表示亲近，与“想……敌人，保护自己的家”的敌对语境冲突。", "感谢": "语义：没有人想感谢敌人，与“保护自己的家”的意思相反。", "哭": "配价：“哭”不能带事物宾语，“想哭敌人”不成立。"}, "sentence_index": 6, "correct_answer": "打跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在比赛中打跑了对手，赢得了冠军。", "explanation": "这里应该用〈击败〉。打跑指把对方打得逃走，比赛中战胜对手应说击败。"}, {"text": "消防员打跑了被困的老人。", "explanation": "这里应该用〈救出〉。打跑让人逃走，被困的老人需要被救出，不能说打跑。"}, {"text": "他热情地打跑了远道而来的朋友。", "explanation": "这里应该用〈接待〉。打跑带有驱赶的意思，与热情接待的语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们终于把入侵者打跑了着。", "corrected_sentence": "士兵们终于把入侵者打跑了。", "error_description": "错误：“打跑了着”，“了”与“着”不能同时用在同一动词上。正确：“打跑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经打跑着入侵者。", "corrected_sentence": "他们曾经打跑过入侵者。", "error_description": "错误：“打跑着”，“曾经”表示经历，应用经历体“过”，不用进行体“着”。正确：“打跑过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
