INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找不到是找了很久也没找到。", "primary_collocate": null, "pronunciation": "zhǎo bu dào", "ipa": "ʈʂau̯˨˩ pu tau̯˥˩", "syllable_count": 3, "sentences": [{"text": "我找了一个小时，还是找不到钥匙。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了很久，也找不到回家的路。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈找了一上午，还是找不到那本书。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找了半天，我还是找不到我的眼镜。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子找不到玩具，哭了很久。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找遍了房间，还是找不到那张照片。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们找了一晚上，还是找不到小猫。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了好几家店，都找不到这种药。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了很久，怎么也找不到我的车。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把包翻了一遍，还是找不到手机。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找得到", "label": "可能补语"}, {"form": "没找到", "label": "否定"}, {"form": "找不到了", "label": "体标"}], "register": "口语", "sense_fingerprint": "找了很久仍然没有找到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找不到", "is_correct": true, "explanation": "正确。找不到表示找了很久仍没有找到，与“还是”的语气一致。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“钥匙”为宾语，句子无法成立。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能以钥匙为宾语，句子不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与“找了一个小时”的寻找过程不符。"}], "explanations": {"找不到": "正确。找不到表示找了很久仍没有找到，与“还是”的语气一致。", "吃": "搭配：“吃”不能以“钥匙”为宾语，句子无法成立。", "煮": "搭配：“煮”的对象是食物，不能以钥匙为宾语，句子不通。", "忘记": "语义：“忘记”指记不住，与“找了一个小时”的寻找过程不符。"}, "sentence_index": 0, "correct_answer": "找不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车窗上结了霜，我找不到外面。", "explanation": "这里应该用〈看不到〉。车窗结霜后视线被挡，应说看不到外面；“找不到”指寻找后没有发现，不能用于外面这样的方位。"}, {"text": "这个箱子太重了，我一个人找不到。", "explanation": "这里应该用〈搬不动〉。箱子重是搬的问题，不是寻找的问题，不能说找不到。"}, {"text": "他说话太快，我找不到。", "explanation": "这里应该用〈听不懂〉。说话快是听懂的问题，不是寻找的问题，不能说找不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找不到", "is_correct": true, "explanation": "正确。“找了一晚上”与“还是”表示找了很久仍未找到小猫。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给动物吃东西，与“找了一晚上”的寻找动作不符。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”一般不以“小猫”为宾语，句子无法成立。"}, {"text": "养", "is_correct": false, "explanation": "语义：“养”表示饲养，与“找了一晚上”的寻找过程和“还是”的语气矛盾。"}], "explanations": {"找不到": "正确。“找了一晚上”与“还是”表示找了很久仍未找到小猫。", "喂": "语义：“喂”指给动物吃东西，与“找了一晚上”的寻找动作不符。", "放": "搭配：“放”一般不以“小猫”为宾语，句子无法成立。", "养": "语义：“养”表示饲养，与“找了一晚上”的寻找过程和“还是”的语气矛盾。"}, "sentence_index": 6, "correct_answer": "找不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作业太多了，我今天找不到。", "explanation": "这里应该用〈做不完〉。作业多是做完的问题，不是寻找的问题，不能说找不到。"}, {"text": "她在屋里大声喊我，我却找不到她的声音。", "explanation": "这里应该用〈听到〉。她在大声喊，声音应说听到，不能说找不到。"}, {"text": "这碗汤太烫了，我找不到。", "explanation": "这里应该用〈喝不了〉。汤烫是喝的问题，不是寻找的问题，不能说找不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我翻了书包，还是找不到了那串钥匙。", "corrected_sentence": "我翻了书包，还是找不到那串钥匙。", "error_description": "错误在“了”的位置。“了”不能插在可能补语“找不到”与宾语“那串钥匙”之间；应删去，改为“还是找不到那串钥匙”。若要保留“了”，应放在句末，即“还是找不到那串钥匙了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找遍了书架，还是没找不到那本词典。", "corrected_sentence": "我们找遍了书架，还是找不到那本词典。", "error_description": "错误在“没”。“找不到”本身已含否定，前面不能再加“没”，形成双重否定；应删去“没”，改为“还是找不到那本词典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
