INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寻找后没有发现。", "primary_collocate": null, "pronunciation": "zhǎo bu dào", "ipa": "ʈʂau̯˨˩ pu tau̯˥˩", "syllable_count": 3, "sentences": [{"text": "这个地方太小，地图上找不到。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书包里找不到钱包。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很小，网上找不到它。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要的书我在书店找不到。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处看了看，找不到出口。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开电脑，却找不到那个文件。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太黑了，我找不到灯的开关。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我在词典里找不到。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到答案的时候，可以问老师。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说在这里找不到他。", "target_word": "找不到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找得到", "label": "可能补语"}, {"form": "没找到", "label": "否定"}, {"form": "找不到了", "label": "体标"}], "register": "口语", "sense_fingerprint": "寻找之后没有发现所找的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找不到", "is_correct": true, "explanation": "正确。找不到表示在地图上查找后没有发现，与“地图上”的语境一致。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“长大”指人或植物生长，不能用来说地方在地图上的情况。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与地图上的查找毫无关系，句子不通。"}, {"text": "闻到", "is_correct": false, "explanation": "搭配：“闻到”的对象多是气味，不能说“地图上闻到”。"}], "explanations": {"找不到": "正确。找不到表示在地图上查找后没有发现，与“地图上”的语境一致。", "长大": "语义：“长大”指人或植物生长，不能用来说地方在地图上的情况。", "结婚": "语义：“结婚”与地图上的查找毫无关系，句子不通。", "闻到": "搭配：“闻到”的对象多是气味，不能说“地图上闻到”。"}, "sentence_index": 0, "correct_answer": "找不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子太重了，我一个人找不到。", "explanation": "这里应该用〈搬不动〉。箱子重是搬的问题，不是寻找的问题，不能说找不到。"}, {"text": "这扇窗户上结了霜，我找不到外面。", "explanation": "这里应该用〈看不到〉。窗户结霜后视线被挡，应说看不到外面；“找不到”指寻找后没有发现，不能用于外面这样的方位。"}, {"text": "他说话太快，我找不到。", "explanation": "这里应该用〈听不懂〉。说话快是听懂的问题，不是寻找的问题，不能说找不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找不到", "is_correct": true, "explanation": "正确。房间很黑，找不到灯的开关，说明在黑暗中没有找到开关。"}, {"text": "关上", "is_correct": false, "explanation": "语义：“关上”会让房间更暗，与“房间太黑了”的需要相矛盾。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”与“找”的动作以及“太黑了”的情境都不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象不能是开关，句子无法成立。"}], "explanations": {"找不到": "正确。房间很黑，找不到灯的开关，说明在黑暗中没有找到开关。", "关上": "语义：“关上”会让房间更暗，与“房间太黑了”的需要相矛盾。", "扔掉": "语义：“扔掉”与“找”的动作以及“太黑了”的情境都不符。", "喝": "搭配：“喝”的对象不能是开关，句子无法成立。"}, "sentence_index": 6, "correct_answer": "找不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作业太多了，我今天找不到。", "explanation": "这里应该用〈做不完〉。作业多是做完的问题，不是寻找的问题，不能说找不到。"}, {"text": "这碗汤太烫了，我找不到。", "explanation": "这里应该用〈喝不了〉。汤烫是喝的问题，不是寻找的问题，不能说找不到。"}, {"text": "这首歌太难了，我找不到。", "explanation": "这里应该用〈学不会〉。歌难是学会的问题，不是寻找的问题，不能说找不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在厨房里找不到过那把小刀。", "corrected_sentence": "我在厨房里找不到那把小刀。", "error_description": "错误在“过”。可能补语“找不到”本身已表示结果，后面不能再加体标“过”；应去掉“过”，改为“我在厨房里找不到那把小刀。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在教室里找不到了那支红笔。", "corrected_sentence": "我们在教室里找不到那支红笔。", "error_description": "错误在“了”的位置。“找不到”后面要直接接宾语，“了”不能放在宾语前；应去掉“了”，改为“找不到那支红笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
