INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们脚下很大很大的地。", "primary_collocate": null, "pronunciation": "dà dì", "ipa": "ta˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "我们站在大地上，脚下很踏实。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，大地上长出了很多小草。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们光着脚，在大地上跑来跑去。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，大地变绿了。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，大地闻起来很香。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在大地上种庄稼。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震的时候，大地在动。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躺下来，背靠着大地看天。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照着大地，到处都很暖和。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜的雪，大地全变白了。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "脚下广阔的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92197, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确答案：大地（dà dì），指广阔的地面。"}, {"text": "打底", "is_correct": false, "explanation": "第一个音节 dǎ（第三声）与 dà（第四声）声调不同，第二个音节 dǐ（第三声）与 dì（第四声）声调也不同，意思是打底（打底色、打基础）。"}, {"text": "打的", "is_correct": false, "explanation": "第一个音节 dǎ 与 dà 声调不同，第二个音节 dī（第一声）与 dì 声调不同，意思是乘出租车。"}, {"text": "大体", "is_correct": false, "explanation": "第二个音节 tǐ 与 dì 声母不同（t 与 d），声调也不同，意思是大体、大致。"}], "explanations": {"大地": "正确答案：大地（dà dì），指广阔的地面。", "打底": "第一个音节 dǎ（第三声）与 dà（第四声）声调不同，第二个音节 dǐ（第三声）与 dì（第四声）声调也不同，意思是打底（打底色、打基础）。", "打的": "第一个音节 dǎ 与 dà 声调不同，第二个音节 dī（第一声）与 dì 声调不同，意思是乘出租车。", "大体": "第二个音节 tǐ 与 dì 声母不同（t 与 d），声调也不同，意思是大体、大致。"}, "sentence_index": null, "correct_answer": "大地"}, "level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确。大地是能站稳的广阔地面，与“脚下很踏实”相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海面不能站人，“脚下很踏实”与之矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“站在……上”要求能承托人的处所，不说“站在空气上”。"}, {"text": "云层", "is_correct": false, "explanation": "语义：云层在空中，人站不到上面，与“脚下很踏实”矛盾。"}], "explanations": {"大地": "正确。大地是能站稳的广阔地面，与“脚下很踏实”相符。", "海洋": "语义：海面不能站人，“脚下很踏实”与之矛盾。", "空气": "搭配：“站在……上”要求能承托人的处所，不说“站在空气上”。", "云层": "语义：云层在空中，人站不到上面，与“脚下很踏实”矛盾。"}, "sentence_index": 0, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都擦房间的大地。", "explanation": "这里应该用〈地板〉。大地指广阔的自然地面，不用来指房间里的地板。"}, {"text": "这家农户拥有很多大地。", "explanation": "这里应该用〈土地〉。大地是广阔的自然地面，不能说“拥有大地”；可以拥有、买卖的地块要用土地。"}, {"text": "这块大地很小。", "explanation": "这里应该用〈地块〉。大地指广阔的自然地面，不能用来指一小块地块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92197, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确答案：大地（dà dì），指广阔的地面。"}, {"text": "答题", "is_correct": false, "explanation": "第一个音节 dá 与 dà 声调不同；第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是答题。"}, {"text": "大题", "is_correct": false, "explanation": "第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是大题（大的题目）。"}, {"text": "大底", "is_correct": false, "explanation": "第二个音节 dǐ（第三声）与 dì（第四声）声调不同，意思是鞋的外底。"}, {"text": "大的", "is_correct": false, "explanation": "第二个音节 de 为轻声，韵母与 dì 不同，意思是“大的（那一个）”。"}], "explanations": {"大地": "正确答案：大地（dà dì），指广阔的地面。", "答题": "第一个音节 dá 与 dà 声调不同；第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是答题。", "大题": "第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是大题（大的题目）。", "大底": "第二个音节 dǐ（第三声）与 dì（第四声）声调不同，意思是鞋的外底。", "大的": "第二个音节 de 为轻声，韵母与 dì 不同，意思是“大的（那一个）”。"}, "sentence_index": null, "correct_answer": "大地"}, "level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确。地震时地面会震动，“大地在动”与语境相符。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不会在地震中“动”，与“地震”的语境矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“在动”不搭配“天气”，不说“天气在动”。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能在地震中移动，句子不成立。"}], "explanations": {"大地": "正确。地震时地面会震动，“大地在动”与语境相符。", "春天": "语义：春天是季节，不会在地震中“动”，与“地震”的语境矛盾。", "天气": "搭配：“在动”不搭配“天气”，不说“天气在动”。", "数学": "语义：数学是学科，不能在地震中移动，句子不成立。"}, "sentence_index": 6, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块大地刚铺好，很平整。", "explanation": "这里应该用〈地面〉。大地指广阔的自然地面，不能用来指人工铺好的一块地面。"}, {"text": "客厅的大地很柔软。", "explanation": "这里应该用〈地毯〉。大地指自然地面，不能用来指室内铺在地上、柔软的毯子。"}, {"text": "这座桥的大地很牢固。", "explanation": "这里应该用〈地基〉。大地指地面和地球表面，不能用来指建筑下面承重的地基。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们大地上玩耍。", "corrected_sentence": "孩子们在大地上玩耍。", "error_description": "介词缺失：“大地上”表示处所，前面须加“在”，应说“在大地上玩耍”，不能说“大地上玩耍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕阳照着这只大地，田野一片金黄。", "corrected_sentence": "夕阳照着这片大地，田野一片金黄。", "error_description": "量词错误：“大地”指一大片土地，应用量词“片”，应说“这片大地”，不能用“只”。“只”用于动物、器物等，不能修饰“大地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
