INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "广阔的地面；地球表面。", "primary_collocate": null, "pronunciation": "dà dì", "ipa": "ta˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "飞机下面是一片广阔的大地。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪落下来，大地一片白。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来，照亮了大地。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大地上有山，也有河。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，大地很安静，只有风声。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，北方的大地全是冰雪。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢走在大地上，看远处的山。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，金黄的麦子铺满了大地。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，大地变得很干净。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片大地上住着很多人。", "target_word": "大地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "广阔的地面、地球表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确答案：大地（dà dì），指广阔的地面。"}, {"text": "打底", "is_correct": false, "explanation": "第一个音节 dǎ（第三声）与 dà（第四声）声调不同，第二个音节 dǐ（第三声）与 dì（第四声）声调也不同，意思是打底（打底色、打基础）。"}, {"text": "打的", "is_correct": false, "explanation": "第一个音节 dǎ 与 dà 声调不同，第二个音节 dī（第一声）与 dì 声调不同，意思是乘出租车。"}, {"text": "大体", "is_correct": false, "explanation": "第二个音节 tǐ 与 dì 声母不同（t 与 d），声调也不同，意思是大体、大致。"}], "explanations": {"大地": "正确答案：大地（dà dì），指广阔的地面。", "打底": "第一个音节 dǎ（第三声）与 dà（第四声）声调不同，第二个音节 dǐ（第三声）与 dì（第四声）声调也不同，意思是打底（打底色、打基础）。", "打的": "第一个音节 dǎ 与 dà 声调不同，第二个音节 dī（第一声）与 dì 声调不同，意思是乘出租车。", "大体": "第二个音节 tǐ 与 dì 声母不同（t 与 d），声调也不同，意思是大体、大致。"}, "sentence_index": null, "correct_answer": "大地"}, "level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确。飞机下面的广阔地面即是大地，与“广阔”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：飞机下面不会是房间，“一片广阔的房间”与语境矛盾。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“广阔”不修饰书桌，“一片广阔的书桌”不成立。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：夜空在上方，不在飞机下面，与“飞机下面是”矛盾。"}], "explanations": {"大地": "正确。飞机下面的广阔地面即是大地，与“广阔”相符。", "房间": "语义：飞机下面不会是房间，“一片广阔的房间”与语境矛盾。", "书桌": "搭配：“广阔”不修饰书桌，“一片广阔的书桌”不成立。", "夜空": "语义：夜空在上方，不在飞机下面，与“飞机下面是”矛盾。"}, "sentence_index": 0, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家农户拥有很多大地。", "explanation": "这里应该用〈土地〉。大地是广阔的自然地面，不能说“拥有大地”；可以拥有、买卖的地块要用土地。"}, {"text": "我们把客厅的大地打了蜡。", "explanation": "这里应该用〈地板〉。大地指广阔的自然地面，不能用来指室内铺设、可以打蜡的地板。"}, {"text": "这栋楼的大地打得很深。", "explanation": "这里应该用〈地基〉。大地指广阔的地面和地球表面，不能用来指楼房下面承重的地基。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92198, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确答案：大地（dà dì），指广阔的地面。"}, {"text": "答题", "is_correct": false, "explanation": "第一个音节 dá 与 dà 声调不同；第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是答题。"}, {"text": "大题", "is_correct": false, "explanation": "第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是大题（大的题目）。"}, {"text": "大底", "is_correct": false, "explanation": "第二个音节 dǐ（第三声）与 dì（第四声）声调不同，意思是鞋的外底。"}, {"text": "大的", "is_correct": false, "explanation": "第二个音节 de 为轻声，韵母与 dì 不同，意思是“大的（那一个）”。"}], "explanations": {"大地": "正确答案：大地（dà dì），指广阔的地面。", "答题": "第一个音节 dá 与 dà 声调不同；第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是答题。", "大题": "第二个音节 tí 与 dì 声母不同（t 与 d），声调也不同，意思是大题（大的题目）。", "大底": "第二个音节 dǐ（第三声）与 dì（第四声）声调不同，意思是鞋的外底。", "大的": "第二个音节 de 为轻声，韵母与 dì 不同，意思是“大的（那一个）”。"}, "sentence_index": null, "correct_answer": "大地"}, "level_3": {"options": [{"text": "大地", "is_correct": true, "explanation": "正确。大地是可以走在上面、能远望山的广阔地面，与语境相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空在上方，人不能走在上面，与“走在……上”矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“走在”要求能承托脚步的处所，不说“走在空气上”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能走在上面，与“走在……上”的句意不符。"}], "explanations": {"大地": "正确。大地是可以走在上面、能远望山的广阔地面，与语境相符。", "天空": "语义：天空在上方，人不能走在上面，与“走在……上”矛盾。", "空气": "搭配：“走在”要求能承托脚步的处所，不说“走在空气上”。", "钢琴": "语义：钢琴是乐器，不能走在上面，与“走在……上”的句意不符。"}, "sentence_index": 6, "correct_answer": "大地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块大地的价格很高。", "explanation": "这里应该用〈地皮〉。大地指广阔的自然地面，不能用来指可以买卖的一块地皮。"}, {"text": "教室的大地刚拖过。", "explanation": "这里应该用〈瓷砖〉。大地指广阔的自然地面，不能用来指室内铺在地上的瓷砖。"}, {"text": "这间小屋的大地只有一张床那么大。", "explanation": "这里应该用〈地面〉。大地指广阔的自然地面，不能用来指小屋里的地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月光照着一只大地，洁白无瑕。", "corrected_sentence": "月光照着一片大地，洁白无瑕。", "error_description": "量词错误：“大地”指广阔的地面，应配量词“片”，说“一片大地”，不能说“一只大地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "牧民们大地上赶羊。", "corrected_sentence": "牧民们在大地上赶羊。", "error_description": "介词缺失：“大地上”表示处所，前面须加“在”，应说“在大地上赶羊”，不能说“大地上赶羊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放下", "is_correct": true, "explanation": "放下与“抬”相对，指把举起或抬着的东西放到下面。"}, {"text": "写", "is_correct": false, "explanation": "写是书写的动作，与“抬”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑是表情或声音的动作，与“抬”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡指睡觉，与“抬”没有反义关系。"}], "correct_answer": "放下", "explanations": {"放下": "放下与“抬”相对，指把举起或抬着的东西放到下面。", "写": "写是书写的动作，与“抬”没有反义关系。", "笑": "笑是表情或声音的动作，与“抬”没有反义关系。", "睡": "睡指睡觉，与“抬”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放下", "is_correct": true, "explanation": "放下与“抬”相对，指把几人一起抬着的东西放到地上或下面。"}, {"text": "跳", "is_correct": false, "explanation": "跳是身体向上腾起的动作，与“抬”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝指吞咽液体，与“抬”没有反义关系。"}, {"text": "哭", "is_correct": false, "explanation": "哭指流泪或发出悲伤的声音，与“抬”没有反义关系。"}], "correct_answer": "放下", "explanations": {"放下": "放下与“抬”相对，指把几人一起抬着的东西放到地上或下面。", "跳": "跳是身体向上腾起的动作，与“抬”没有反义关系。", "喝": "喝指吞咽液体，与“抬”没有反义关系。", "哭": "哭指流泪或发出悲伤的声音，与“抬”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抬是把东西往上举起来，或几个人一起拿起来。", "primary_collocate": null, "pronunciation": "tái", "ipa": "tʰaɪ˧˥", "syllable_count": 1, "sentences": [{"text": "他慢慢抬起了左脚。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家把椅子抬到外面去。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子很重，我一个人抬不起来。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们抬着水桶去浇花。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗抬起头看着我。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以前抬过这么重的桌子吗？", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和叔叔一起抬来了一张大床。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你抬一下这把椅子的另一头。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人抬着手，向远处的朋友挥了挥。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人把冰箱抬到了厨房。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抬了", "label": "体标"}, {"form": "抬着", "label": "体标"}, {"form": "抬过", "label": "体标"}, {"form": "抬抬", "label": "重叠"}, {"form": "抬高", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西往上举起，或几个人一起拿起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬（tái）指把东西往上举起，或几个人一起拿起，正是听到的词。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 tái 声调不同（第四声 / 第二声），意思是太。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 tái 声母不同（c / t），意思是才。"}, {"text": "桃", "is_correct": false, "explanation": "táo 与 tái 韵母不同（-ao / -ai），意思是桃子。"}], "explanations": {"抬": "抬（tái）指把东西往上举起，或几个人一起拿起，正是听到的词。", "太": "tài 与 tái 声调不同（第四声 / 第二声），意思是太。", "才": "cái 与 tái 声母不同（c / t），意思是才。", "桃": "táo 与 tái 韵母不同（-ao / -ai），意思是桃子。"}, "sentence_index": null, "correct_answer": "抬"}, "level_3": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬起，指把左脚慢慢向上抬起，符合“他慢慢抬起了左脚”的句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声唱歌，与抬起左脚的动作无关。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“左脚”作宾语，“跳起了左脚”不成立。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚撞击，不是慢慢向上举起。"}], "explanations": {"抬": "抬起，指把左脚慢慢向上抬起，符合“他慢慢抬起了左脚”的句意。", "唱": "语义：“唱”指发声唱歌，与抬起左脚的动作无关。", "跳": "配价：“跳”是不及物动词，不能带“左脚”作宾语，“跳起了左脚”不成立。", "踢": "语义：“踢”指用脚撞击，不是慢慢向上举起。"}, "sentence_index": 0, "correct_answer": "抬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抬着墙慢慢走。", "explanation": "这里应该用〈扶〉。墙不能搬动，扶墙是用手靠着，不能说抬。"}, {"text": "她抬着新鞋子去上学。", "explanation": "这里应该用〈穿〉。鞋子要穿在脚上，“抬”指举起或搬动，不能表示穿。"}, {"text": "他抬着一杯水喝了一口。", "explanation": "这里应该用〈端〉。端指双手托着较轻的器物，杯子应说端；抬多指搬动较重的东西，不说“抬着一杯水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬（tái）指把东西往上举起，或几个人一起拿起，正是听到的词。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 tái 声调不同（第一声 / 第二声），意思是胎，如胎儿。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 tái 声母不同（p / t），意思是排，如排队。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tái 韵母不同（-an / -ai），意思是谈，如谈话。"}], "explanations": {"抬": "抬（tái）指把东西往上举起，或几个人一起拿起，正是听到的词。", "胎": "tāi 与 tái 声调不同（第一声 / 第二声），意思是胎，如胎儿。", "排": "pái 与 tái 声母不同（p / t），意思是排，如排队。", "谈": "tán 与 tái 韵母不同（-an / -ai），意思是谈，如谈话。"}, "sentence_index": null, "correct_answer": "抬"}, "level_3": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬，指爸爸和叔叔一起把大床搬来，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与搬运大床无关。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”不能带“一张大床”作宾语，与搬运不合。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写来一张大床”。"}], "explanations": {"抬": "抬，指爸爸和叔叔一起把大床搬来，符合句意。", "唱": "语义：“唱”指唱歌，与搬运大床无关。", "吃": "配价：“吃”不能带“一张大床”作宾语，与搬运不合。", "写": "搭配：“写”的对象是文字，不能说“写来一张大床”。"}, "sentence_index": 6, "correct_answer": "抬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抬着电梯按钮等门开。", "explanation": "这里应该用〈按〉。电梯按钮要用手指按，不能说抬。"}, {"text": "他抬着烟站在门口。", "explanation": "这里应该用〈夹〉。烟通常夹在手指间，不能说抬。"}, {"text": "她抬着眼镜看书。", "explanation": "这里应该用〈戴〉。眼镜要戴在脸上，不能说抬着眼镜看书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子我抬动得。", "corrected_sentence": "这个箱子我抬得动。", "error_description": "可能补语的正确形式是“抬得动”，不能说“抬动得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床太重，我们两个人抬不得动。", "corrected_sentence": "这张床太重，我们两个人抬不动。", "error_description": "可能补语的否定形式是“抬不动”，不能在“不”后面再加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
