INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放下", "is_correct": true, "explanation": "放下与“抬”相对，指把几人一起抬着的东西放到地上或下面。"}, {"text": "写", "is_correct": false, "explanation": "写是书写的动作，与“抬”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃指进食，与“抬”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "睡指睡觉，与“抬”没有反义关系。"}], "correct_answer": "放下", "explanations": {"放下": "放下与“抬”相对，指把几人一起抬着的东西放到地上或下面。", "写": "写是书写的动作，与“抬”没有反义关系。", "吃": "吃指进食，与“抬”没有反义关系。", "睡": "睡指睡觉，与“抬”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向上举起；两人或多人共同搬动。", "primary_collocate": null, "pronunciation": "tái", "ipa": "tʰaɪ˧˥", "syllable_count": 1, "sentences": [{"text": "请你把右手抬起来。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬了抬手，向我们打招呼。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太重，我们两个人抬吧。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们抬着一个大箱子上楼。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他腿受伤了，抬不高。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四个人把病人抬上了车。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子抬着手想拿书架上的书。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头太重，一个人抬不动。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把沙发抬进了新家。", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意帮我抬这台电视？", "target_word": "抬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抬了", "label": "体标"}, {"form": "抬着", "label": "体标"}, {"form": "抬过", "label": "体标"}, {"form": "抬抬", "label": "重叠"}, {"form": "抬高", "label": "复合"}], "register": "中性", "sense_fingerprint": "向上举起或多人共同搬动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬（tái）指向上举起或几人共同搬动，正是听到的词。"}, {"text": "来", "is_correct": false, "explanation": "lái 与 tái 声母不同（l / t），意思是来。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 tái 声调不同（第四声 / 第二声），意思是太。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 tái 声调不同（第一声 / 第二声），意思是胎，如胎儿。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tái 韵母不同（-an / -ai），意思是谈，如谈话。"}], "explanations": {"抬": "抬（tái）指向上举起或几人共同搬动，正是听到的词。", "来": "lái 与 tái 声母不同（l / t），意思是来。", "太": "tài 与 tái 声调不同（第四声 / 第二声），意思是太。", "胎": "tāi 与 tái 声调不同（第一声 / 第二声），意思是胎，如胎儿。", "谈": "tán 与 tái 韵母不同（-an / -ai），意思是谈，如谈话。"}, "sentence_index": null, "correct_answer": "抬"}, "level_3": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬起，指把右手向上举起，符合“请你把右手抬起来”的句意。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”不能带“右手”作宾语，“把右手坐起来”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与举起右手的动作不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱起来”指开始唱歌，不能用于手的动作。"}], "explanations": {"抬": "抬起，指把右手向上举起，符合“请你把右手抬起来”的句意。", "坐": "配价：“坐”不能带“右手”作宾语，“把右手坐起来”不成立。", "吃": "语义：“吃”指进食，与举起右手的动作不符。", "唱": "搭配：“唱起来”指开始唱歌，不能用于手的动作。"}, "sentence_index": 0, "correct_answer": "抬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抬着一块饼干边走边吃。", "explanation": "这里应该用〈拿〉。饼干很轻，手拿着吃即可，不能说抬；抬指向上托起较重的东西或几个人一起搬动。"}, {"text": "他抬着一个书包上学去了。", "explanation": "这里应该用〈背〉。书包要背在肩上，不说抬；抬指双手向上托起或几人搬动。"}, {"text": "他抬着一支笔写作业。", "explanation": "这里应该用〈捏〉。笔很轻，写字时用手指捏着，不能说抬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬（tái）指向上举起或几人共同搬动，正是听到的词。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 tái 声母不同（c / t），意思是才。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 tái 声母不同（p / t），意思是排，如排队。"}, {"text": "桃", "is_correct": false, "explanation": "táo 与 tái 韵母不同（-ao / -ai），意思是桃子。"}], "explanations": {"抬": "抬（tái）指向上举起或几人共同搬动，正是听到的词。", "才": "cái 与 tái 声母不同（c / t），意思是才。", "排": "pái 与 tái 声母不同（p / t），意思是排，如排队。", "桃": "táo 与 tái 韵母不同（-ao / -ai），意思是桃子。"}, "sentence_index": null, "correct_answer": "抬"}, "level_3": {"options": [{"text": "抬", "is_correct": true, "explanation": "抬，指把手向上举起，符合“孩子抬着手想拿书架上的书”的句意。"}, {"text": "扛", "is_correct": false, "explanation": "配价：“扛”的宾语一般是物品，不能说“扛着手”。"}, {"text": "摇", "is_correct": false, "explanation": "语义：“摇手”表示挥手示意，与想拿书架上的书不符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象一般是物品，不能说“搬着手”。"}], "explanations": {"抬": "抬，指把手向上举起，符合“孩子抬着手想拿书架上的书”的句意。", "扛": "配价：“扛”的宾语一般是物品，不能说“扛着手”。", "摇": "语义：“摇手”表示挥手示意，与想拿书架上的书不符。", "搬": "搭配：“搬”的对象一般是物品，不能说“搬着手”。"}, "sentence_index": 6, "correct_answer": "抬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她抬着一本书去车站。", "explanation": "这里应该用〈带〉。书很轻，随身带着即可，不能说抬；抬指向上托起较重的东西或几个人一起搬动。"}, {"text": "他抬着足球跑向球门。", "explanation": "这里应该用〈踢〉。足球是用脚踢着跑，不能说抬。"}, {"text": "他抬着车去上班。", "explanation": "这里应该用〈开〉。车要靠驾驶，不能说抬着车去上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人抬了着一张床上楼。", "corrected_sentence": "两个人抬着一张床上楼。", "error_description": "“了”和“着”不能同时用在同一个动词后面。表示持续的动作应说“抬着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把箱子抬了楼上。", "corrected_sentence": "他们把箱子抬到了楼上。", "error_description": "“抬”表示搬到某处，后面的处所要用介词“到”引出，不能直接说“抬了楼上”，应说“抬到了楼上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
