INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包着地球的一层空气。", "primary_collocate": null, "pronunciation": "dà qì", "ipa": "tɑ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "地球外面有一层大气。", "target_word": "大气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大气里有很多氧气。", "target_word": "大气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大气保护着我们的地球。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山越高，大气越薄。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大气中的水会变成雨。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的烟会污染大气。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞船飞出了大气，进入太空。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有大气，地球上就不会有生命。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家每天都在观察大气的变化。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大气变热，冰山会慢慢化掉。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大气层", "label": "复合"}, {"form": "大气压", "label": "复合"}], "register": "中性", "sense_fingerprint": "包着地球的一层空气，即地球外面的空气层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确选项：目标词“大气”（dàqì）。"}, {"text": "打气", "is_correct": false, "explanation": "dǎqì（第三声）与 dàqì（第四声）只有第一个音节声调不同，意思是给轮胎、球等充气。"}, {"text": "大漆", "is_correct": false, "explanation": "dàqī（qī 第一声）与 dàqì（qì 第四声）只有第二个音节声调不同，意思是一种涂料。"}, {"text": "大旗", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）只有第二个音节声调不同，意思是大的旗帜。"}], "explanations": {"大气": "正确选项：目标词“大气”（dàqì）。", "打气": "dǎqì（第三声）与 dàqì（第四声）只有第一个音节声调不同，意思是给轮胎、球等充气。", "大漆": "dàqī（qī 第一声）与 dàqì（qì 第四声）只有第二个音节声调不同，意思是一种涂料。", "大旗": "qí（第二声）与 qì（第四声）只有第二个音节声调不同，意思是大的旗帜。"}, "sentence_index": null, "correct_answer": "大气"}, "level_3": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确：“大气”指包着地球的一层空气，与“一层”和“地球外面”搭配。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是大片水体，不能像一层东西那样包着地球。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是人造材料，不指包着地球的空气层。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固体，不是包着地球的空气层。"}], "explanations": {"大气": "正确：“大气”指包着地球的一层空气，与“一层”和“地球外面”搭配。", "海洋": "语义：海洋是大片水体，不能像一层东西那样包着地球。", "玻璃": "语义：玻璃是人造材料，不指包着地球的空气层。", "冰块": "语义：冰块是固体，不是包着地球的空气层。"}, "sentence_index": 0, "correct_answer": "大气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的大气很闷，打开窗户就好了。", "explanation": "这里应该用〈空气〉。大气指包围地球的大范围空气层，房间里的空气要用“空气”。"}, {"text": "今天的大气很好，适合出去玩。", "explanation": "这里应该用〈天气〉。大气指包围地球的空气层，描述晴雨冷热要用“天气”。"}, {"text": "这个城市的大气很温和，冬天不太冷。", "explanation": "这里应该用〈气候〉。大气指包围地球的空气层，描述一个地方长期的冷暖状况要用“气候”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92201, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确选项：目标词“大气”（dàqì）。"}, {"text": "大戏", "is_correct": false, "explanation": "xì 与 qì 声调相同，只有声母不同（x 与 q），意思是大型戏剧。"}, {"text": "大忌", "is_correct": false, "explanation": "jì 与 qì 声调相同，只有声母不同（j 与 q），意思是重大的禁忌。"}, {"text": "打起", "is_correct": false, "explanation": "dǎqǐ 与 dàqì 声母韵母相同，只有声调不同，意思是振作、开始。"}], "explanations": {"大气": "正确选项：目标词“大气”（dàqì）。", "大戏": "xì 与 qì 声调相同，只有声母不同（x 与 q），意思是大型戏剧。", "大忌": "jì 与 qì 声调相同，只有声母不同（j 与 q），意思是重大的禁忌。", "打起": "dǎqǐ 与 dàqì 声母韵母相同，只有声调不同，意思是振作、开始。"}, "sentence_index": null, "correct_answer": "大气"}, "level_3": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确：飞船要飞出的是包围地球的大气，之后才能进入太空。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土是地面的土壤，飞船不会从泥土中飞出，句意不通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子是盛放液体的容器，飞船不能从杯子里飞出，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“飞出”一般不与“房间”搭配，且“进入太空”要求先离开地球的大气。"}], "explanations": {"大气": "正确：飞船要飞出的是包围地球的大气，之后才能进入太空。", "泥土": "语义：泥土是地面的土壤，飞船不会从泥土中飞出，句意不通。", "杯子": "语义：杯子是盛放液体的容器，飞船不能从杯子里飞出，句意不通。", "房间": "搭配：“飞出”一般不与“房间”搭配，且“进入太空”要求先离开地球的大气。"}, "sentence_index": 6, "correct_answer": "大气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间地下室的大气很潮，墙上都长霉了。", "explanation": "这里应该用〈空气〉。大气指包围地球的空气层，地下室里的空气要用“空气”。"}, {"text": "天上的大气白白的，像一团棉花。", "explanation": "这里应该用〈云〉。大气指包围地球的空气层，白色、棉絮状、飘在天上的东西是“云”。"}, {"text": "早上的大气很浓，几米外就看不清人。", "explanation": "这里应该用〈雾〉。大气指包围地球的空气层，形容雾气浓厚、看不清远处要用“雾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗行星周围有一座很厚的大气。", "corrected_sentence": "这颗行星周围有一层很厚的大气。", "error_description": "量词错误：“大气”是包着星球的一层空气，应说“一层大气”。错误形式是“一座大气”，“座”用于山、房屋等大型固定的东西，不能修饰大气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家通过观测一块大气来预报天气。", "corrected_sentence": "科学家通过观测大气来预报天气。", "error_description": "量词错误：大气是整体的空气层，不能用“块”计数。错误形式是“一块大气”，正确说法是直接说“大气”，或用“层”来计数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
