INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包围地球的整个空气层。", "primary_collocate": null, "pronunciation": "dà qì", "ipa": "tɑ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "地球的大气很厚。", "target_word": "大气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月亮上没有大气。", "target_word": "大气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大气分成好几层。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球的大气从地面一直延伸到很高的太空。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星的大气比地球的薄。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳的热通过大气到达地面。", "target_word": "大气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大气的流动形成了风。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流星进入大气后会烧起来。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大气温度会随着高度变化。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用卫星研究整个大气。", "target_word": "大气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大气层", "label": "复合"}, {"form": "大气圈", "label": "复合"}], "register": "中性", "sense_fingerprint": "包围地球的整个空气层，作为一个整体来说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确选项：目标词“大气”（dàqì）。"}, {"text": "打气", "is_correct": false, "explanation": "dǎqì（第三声）与 dàqì（第四声）只有第一个音节声调不同，意思是给轮胎、球等充气。"}, {"text": "大漆", "is_correct": false, "explanation": "dàqī（qī 第一声）与 dàqì（qì 第四声）只有第二个音节声调不同，意思是一种涂料。"}, {"text": "大旗", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）只有第二个音节声调不同，意思是大的旗帜。"}], "explanations": {"大气": "正确选项：目标词“大气”（dàqì）。", "打气": "dǎqì（第三声）与 dàqì（第四声）只有第一个音节声调不同，意思是给轮胎、球等充气。", "大漆": "dàqī（qī 第一声）与 dàqì（qì 第四声）只有第二个音节声调不同，意思是一种涂料。", "大旗": "qí（第二声）与 qì（第四声）只有第二个音节声调不同，意思是大的旗帜。"}, "sentence_index": null, "correct_answer": "大气"}, "level_3": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确：“大气”指包围地球的整个空气层，可以说它很厚。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林是地面上的植被，不是包围地球的气层，不能说地球的森林很厚。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是人造材料，“地球的玻璃很厚”不指包围地球的物质层。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本是纸制的物品，“地球的书本”不指包围地球的空气层。"}], "explanations": {"大气": "正确：“大气”指包围地球的整个空气层，可以说它很厚。", "森林": "语义：森林是地面上的植被，不是包围地球的气层，不能说地球的森林很厚。", "玻璃": "语义：玻璃是人造材料，“地球的玻璃很厚”不指包围地球的物质层。", "书本": "语义：书本是纸制的物品，“地球的书本”不指包围地球的空气层。"}, "sentence_index": 0, "correct_answer": "大气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "操场上的大气很新鲜。", "explanation": "这里应该用〈空气〉。大气指包围地球的整个空气层，操场上的空气要用“空气”。"}, {"text": "今天的大气很好，适合去野餐。", "explanation": "这里应该用〈天气〉。大气指包围地球的整个空气层，描述晴雨冷热要用“天气”。"}, {"text": "早上的大气很浓，几米外看不清人。", "explanation": "这里应该用〈雾〉。大气指包围地球的整个空气层，形容雾气浓厚要用“雾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92202, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确选项：目标词“大气”（dàqì）。"}, {"text": "大戏", "is_correct": false, "explanation": "xì 与 qì 声调相同，只有声母不同（x 与 q），意思是大型戏剧。"}, {"text": "大忌", "is_correct": false, "explanation": "jì 与 qì 声调相同，只有声母不同（j 与 q），意思是重大的禁忌。"}, {"text": "打起", "is_correct": false, "explanation": "dǎqǐ 与 dàqì 声母韵母相同，只有声调不同，意思是振作、开始。"}], "explanations": {"大气": "正确选项：目标词“大气”（dàqì）。", "大戏": "xì 与 qì 声调相同，只有声母不同（x 与 q），意思是大型戏剧。", "大忌": "jì 与 qì 声调相同，只有声母不同（j 与 q），意思是重大的禁忌。", "打起": "dǎqǐ 与 dàqì 声母韵母相同，只有声调不同，意思是振作、开始。"}, "sentence_index": null, "correct_answer": "大气"}, "level_3": {"options": [{"text": "大气", "is_correct": true, "explanation": "正确：大气是包围地球的空气层，它的流动会形成风。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液在血管中流动，不会形成风，与句意冲突。"}, {"text": "电流", "is_correct": false, "explanation": "语义：电流在导线中流动，不会形成风，句意不通。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：“形成风”的主语应是空气或气流，人群的流动不能形成风。"}], "explanations": {"大气": "正确：大气是包围地球的空气层，它的流动会形成风。", "血液": "语义：血液在血管中流动，不会形成风，与句意冲突。", "电流": "语义：电流在导线中流动，不会形成风，句意不通。", "人群": "搭配：“形成风”的主语应是空气或气流，人群的流动不能形成风。"}, "sentence_index": 6, "correct_answer": "大气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库的大气很潮，东西都发霉了。", "explanation": "这里应该用〈空气〉。大气指包围地球的整个空气层，仓库里的空气要用“空气”。"}, {"text": "这个地区的大气很温和，一年到头都不太冷。", "explanation": "这里应该用〈气候〉。大气指包围地球的整个空气层，描述一个地区长期的冷暖要用“气候”。"}, {"text": "天边的大气白白的，像一团棉花。", "explanation": "这里应该用〈云〉。大气指包围地球的整个空气层，白色、棉絮状、飘在天边的东西是“云”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球周围有一座很厚的大气。", "corrected_sentence": "地球周围有一层很厚的大气。", "error_description": "量词错误：大气是包围地球的一层空气，应用“层”计数。错误形式是“一座大气”，“座”用于山、房屋等，不能修饰大气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一颗大气包围着地球，保护着我们。", "corrected_sentence": "整个大气包围着地球，保护着我们。", "error_description": "量词与数量错误：大气是整体的空气层，应说“整个大气”。错误形式是“一颗大气”，“颗”用于星星、珠子等小而圆的东西，不能修饰大气。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
