INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长大了的男人。", "primary_collocate": null, "pronunciation": "dà nán rén", "ipa": "tɑ˥˩ nan˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他已经是大男人了。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家有两个大男人。", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大男人吃得很多。", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三个大男人坐在小车里。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些大男人在公园打球。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他长成了大男人。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个大男人一起搬沙发。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个大男人一顿能吃五碗饭。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个大男人在厨房做饭。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着已经像个大男人。", "target_word": "大男人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "长大成人的男人，指年龄和身体上已经成年的男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大男人", "is_correct": true, "explanation": "正确：“大男人”指长大成人的男子，与“他已经是……了”的句意相合。"}, {"text": "女人", "is_correct": false, "explanation": "语义：“女人”与句中“他”的性别相反，不能说“他已经是女人了”。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是无生命的材料，不能用来说明一个人已经成年。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿指刚出生不久的幼儿，与“已经长大”的句意冲突。"}], "explanations": {"大男人": "正确：“大男人”指长大成人的男子，与“他已经是……了”的句意相合。", "女人": "语义：“女人”与句中“他”的性别相反，不能说“他已经是女人了”。", "木头": "语义：木头是无生命的材料，不能用来说明一个人已经成年。", "婴儿": "语义：婴儿指刚出生不久的幼儿，与“已经长大”的句意冲突。"}, "sentence_index": 0, "correct_answer": "大男人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个大男人在吃奶。", "explanation": "这里应该用〈婴儿〉。大男人指长大成人的男子，不能指还在吃奶的婴儿。"}, {"text": "这个大男人今年才两岁，还在学走路。", "explanation": "这里应该用〈小孩〉。大男人指长大成人的男子，两岁的孩子不能这样称呼。"}, {"text": "这三位女士都是大男人，很会照顾孩子。", "explanation": "这里应该用〈女性〉。大男人只指成年男子，不能用来指女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大男人", "is_correct": true, "explanation": "正确：“大男人”指成年男子，可以搬沙发。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“搬沙发”要求有生命的施事，石头不能搬东西，句意不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫体型太小，不能与“两个”一起搬动沙发。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是小型电子设备，不能搬沙发，句意不通。"}], "explanations": {"大男人": "正确：“大男人”指成年男子，可以搬沙发。", "石头": "配价：“搬沙发”要求有生命的施事，石头不能搬东西，句意不通。", "小猫": "语义：小猫体型太小，不能与“两个”一起搬动沙发。", "手机": "语义：手机是小型电子设备，不能搬沙发，句意不通。"}, "sentence_index": 6, "correct_answer": "大男人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她已经是个大男人了。", "explanation": "语义：“大男人”只指成年男子，不能用于女性。"}, {"text": "这位女歌手是个大男人，唱歌很好听。", "explanation": "这里应该用〈女性〉。大男人只指成年男子，不能用来形容女歌手。"}, {"text": "我家的大男人昨天刚学会说话。", "explanation": "这里应该用〈幼儿〉。“大男人”指长大成人的男子，不能指刚学会说话的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口站着一只大男人。", "corrected_sentence": "门口站着一个大男人。", "error_description": "量词错误：“大男人”指人，应用“个”计数。错误形式是“一只大男人”，“只”一般用于动物或小东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯里站着一条大男人。", "corrected_sentence": "电梯里站着一个大男人。", "error_description": "量词错误：“大男人”指人，应用“个”计数。错误形式是“一条大男人”，“条”用于细长的东西或动物，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
