INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年男子，常带有应当坚强的意味。", "primary_collocate": null, "pronunciation": "dà nán rén", "ipa": "tɑ˥˩ nan˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "你一个大男人，别哭。", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大男人要有责任。", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大男人怎么能怕黑？", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说大男人不能哭。", "target_word": "大男人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你是大男人，要照顾家人。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个大男人，这点苦都受不了？", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大男人不该总让女朋友付钱。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说大男人要坚强，他就不敢说累。", "target_word": "大男人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大男人也会累，也需要休息。", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你一个大男人，还怕打针吗？", "target_word": "大男人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "成年男子，说话时带有男人就应该坚强、有担当的意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大男人", "is_correct": true, "explanation": "正确：“大男人”指成年男子，句中带有应当坚强的意味，与“别哭”的劝说相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有哭的能力，与“别哭”的劝说语境不合。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人没有哭泣的情感，“你一个机器人，别哭”不符合常理。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是木材，没有哭泣的能力，“你一个木板”不成话。"}], "explanations": {"大男人": "正确：“大男人”指成年男子，句中带有应当坚强的意味，与“别哭”的劝说相合。", "石头": "语义：石头没有哭的能力，与“别哭”的劝说语境不合。", "机器人": "语义：机器人没有哭泣的情感，“你一个机器人，别哭”不符合常理。", "木板": "语义：木板是木材，没有哭泣的能力，“你一个木板”不成话。"}, "sentence_index": 0, "correct_answer": "大男人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个大男人才五岁，还不会系鞋带。", "explanation": "这里应该用〈小男孩〉。“大男人”指成年男子，句中强调的是应当坚强的成年男性，五岁的孩子不能这样称呼。"}, {"text": "我妈妈是个大男人，每天给我们做饭。", "explanation": "这里应该用〈女人〉。“大男人”只指成年男子，不能用来指妈妈。"}, {"text": "这个刚学走路的孩子是个大男人，还要人抱。", "explanation": "这里应该用〈幼儿〉。“大男人”指成年男子，不能指刚学走路的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大男人", "is_correct": true, "explanation": "正确：“大男人”指成年男子，句中表示男人应当承担，与“不该让女朋友付钱”相合。"}, {"text": "空调", "is_correct": false, "explanation": "配价：“付钱”要求有生命、能支付的施事，空调不能付钱，句意不通。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物没有女朋友，也不能付钱，句意不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆设，不能与“女朋友”和“付钱”构成合理的句子。"}], "explanations": {"大男人": "正确：“大男人”指成年男子，句中表示男人应当承担，与“不该让女朋友付钱”相合。", "空调": "配价：“付钱”要求有生命、能支付的施事，空调不能付钱，句意不通。", "宠物": "语义：宠物没有女朋友，也不能付钱，句意不通。", "花瓶": "语义：花瓶是摆设，不能与“女朋友”和“付钱”构成合理的句子。"}, "sentence_index": 6, "correct_answer": "大男人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明是个大男人，才上幼儿园。", "explanation": "这里应该用〈小男孩〉。“大男人”指成年男子，幼儿园的孩子不能这样称呼。"}, {"text": "我奶奶是个大男人，很会照顾家人。", "explanation": "这里应该用〈女人〉。“大男人”只指成年男子，不能用来指奶奶。"}, {"text": "那个三岁的小男孩是个大男人，还不会说话。", "explanation": "这里应该用〈幼儿〉。“大男人”指成年男子，不能指三岁的小男孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经是一只真正的大男人了，要担起责任。", "corrected_sentence": "他已经是一个真正的大男人了，要担起责任。", "error_description": "量词错误：“大男人”指人，应用“个”计数。错误形式是“一只”，“只”一般用于动物或小东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这么做，像一头大男人。", "corrected_sentence": "他这么做，像个大男人。", "error_description": "量词错误：“大男人”指人，应用“个”。错误形式是“一头”，“头”多用于牛、猪等动物，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拆迁是把旧房子拆了，让人搬走。", "primary_collocate": null, "pronunciation": "chāi qiān", "ipa": "ʈʂʰaɪ˥ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这个小区明年要拆迁，我们得搬家了。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老街去年拆迁了，邻居都搬走了。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府通知我们下个月拆迁。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的旧楼马上就要拆迁。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的老房子拆迁后，他们搬到了新区。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子拆迁时，爷爷舍不得离开。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里正在拆迁，路上到处是灰。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说我们这条街要拆迁了。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家拆迁以后换了一套大房子。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片旧房子已经拆迁很久了。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆迁了", "label": "体标（了）"}, {"form": "拆迁过", "label": "体标（过）"}, {"form": "拆迁户", "label": "复合词"}, {"form": "拆遷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把旧房子拆掉，让住的人搬走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拆迁", "is_correct": true, "explanation": "正确答案。“明年要拆迁”与“我们得搬家了”相符，拆迁即拆房、让人搬走。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是欢庆，与“我们得搬家了”的被迫处境不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“小区”不能作“欢迎”的施事，“小区明年要欢迎”说不通，也与“得搬家”不合。"}, {"text": "种", "is_correct": false, "explanation": "配价：“种”要求植物作宾语，“种小区”不成立。"}], "explanations": {"拆迁": "正确答案。“明年要拆迁”与“我们得搬家了”相符，拆迁即拆房、让人搬走。", "庆祝": "语义：“庆祝”是欢庆，与“我们得搬家了”的被迫处境不合。", "欢迎": "语义：“小区”不能作“欢迎”的施事，“小区明年要欢迎”说不通，也与“得搬家”不合。", "种": "配价：“种”要求植物作宾语，“种小区”不成立。"}, "sentence_index": 0, "correct_answer": "拆迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这群大象明年要拆迁到保护区。", "explanation": "这里应该用〈搬迁〉。拆迁只用于房屋和原住户，大象等动物迁居要用搬迁。"}, {"text": "工人把机器拆迁下来，搬进了仓库。", "explanation": "这里应该用〈拆卸〉。拆迁只用于房屋和原住户，拆机器要用拆卸。"}, {"text": "这块广告牌已经拆迁了。", "explanation": "这里应该用〈拆除〉。拆迁专指拆房并安置原住户，广告牌等设施的拆除要用拆除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆迁", "is_correct": true, "explanation": "正确答案。“村里正在拆迁”指拆房施工，与“路上到处是灰”相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的是美景，与满路灰尘的场面冲突。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”要带受表扬的人，“村里正在表扬”没有合适的对象。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲走动，与满路灰尘的施工场面不合。"}], "explanations": {"拆迁": "正确答案。“村里正在拆迁”指拆房施工，与“路上到处是灰”相符。", "欣赏": "语义：“欣赏”的是美景，与满路灰尘的场面冲突。", "表扬": "搭配：“表扬”要带受表扬的人，“村里正在表扬”没有合适的对象。", "散步": "语义：“散步”是悠闲走动，与满路灰尘的施工场面不合。"}, "sentence_index": 6, "correct_answer": "拆迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们明年想拆迁去城里住。", "explanation": "这里应该用〈搬家〉。拆迁是拆房并迁走原住户，住户自己迁居不能说拆迁。"}, {"text": "候鸟每年都拆迁到南方过冬。", "explanation": "这里应该用〈迁徙〉。拆迁针对房屋和居民，动物的迁徙不能说拆迁。"}, {"text": "工厂把旧船拆迁成了钢材。", "explanation": "这里应该用〈拆解〉。拆迁只用于房屋和居民，拆船要用拆解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那几栋老楼下个月已经拆迁。", "corrected_sentence": "那几栋老楼下个月要拆迁。", "error_description": "错误形式：“下个月已经拆迁”；正确形式：“下个月要拆迁”。“下个月”指将来，“已经”表示已经完成，二者矛盾，应用“要”表示将来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街的老房子去年拆迁着。", "corrected_sentence": "这条街的老房子去年拆迁了。", "error_description": "错误形式：“拆迁着”；正确形式：“拆迁了”。“去年”表示事情已经完成，应用“了”表示完成，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
