INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拆除旧房屋并迁移原住户。", "primary_collocate": null, "pronunciation": "chāi qiān", "ipa": "ʈʂʰaɪ˥ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "政府决定拆迁这片旧房屋。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工程要先拆迁，再盖新楼。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司负责拆迁和安置居民。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了修路，政府拆迁了二十多户人家。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拆迁前，工作人员先通知了住户。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按规定给拆迁的住户补偿。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这条路要拆迁三十户，大家都很关心。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商答应拆迁后给居民新房子。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了建公园，这里的旧房子全部拆迁了。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拆迁以前，工作人员先登记了每家的情况。", "target_word": "拆迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆迁了", "label": "体标（了）"}, {"form": "拆迁过", "label": "体标（过）"}, {"form": "拆迁办", "label": "复合词"}, {"form": "拆遷", "label": "繁体"}], "register": "书面", "sense_fingerprint": "拆除旧房屋并安排原住户迁走（多指官方、工程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拆迁", "is_correct": true, "explanation": "正确答案。“政府决定拆迁这片旧房屋”指官方拆房并安置住户，符合该义项。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象是人，不能说“表扬旧房屋”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语“这片旧房屋”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，“唱旧房屋”说不通。"}], "explanations": {"拆迁": "正确答案。“政府决定拆迁这片旧房屋”指官方拆房并安置住户，符合该义项。", "表扬": "搭配：“表扬”的对象是人，不能说“表扬旧房屋”。", "散步": "配价：“散步”是不及物动词，不能带宾语“这片旧房屋”。", "唱": "语义：“唱”的对象是歌曲，“唱旧房屋”说不通。"}, "sentence_index": 0, "correct_answer": "拆迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些大熊猫明年要拆迁到新基地。", "explanation": "这里应该用〈搬迁〉。拆迁只用于房屋和原住户，动物迁居要用搬迁。"}, {"text": "工人们把路边的旧路灯拆迁了。", "explanation": "这里应该用〈拆除〉。拆迁只用于房屋并安置住户，路灯等设施的拆除要用拆除。"}, {"text": "田里的杂草要拆迁。", "explanation": "这里应该用〈清除〉。拆迁只用于房屋和原住户，杂草不能拆迁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆迁", "is_correct": true, "explanation": "正确答案。“要拆迁三十户”指拆房并迁走这三十户住户，符合该义项。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带宾语“三十户”。"}, {"text": "阅读", "is_correct": false, "explanation": "搭配：“阅读”的对象是文字，不能说“阅读三十户”。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是离合词，不能带宾语“三十户”。"}], "explanations": {"拆迁": "正确答案。“要拆迁三十户”指拆房并迁走这三十户住户，符合该义项。", "游泳": "配价：“游泳”是不及物动词，不能带宾语“三十户”。", "阅读": "搭配：“阅读”的对象是文字，不能说“阅读三十户”。", "睡觉": "配价：“睡觉”是离合词，不能带宾语“三十户”。"}, "sentence_index": 6, "correct_answer": "拆迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一家人去年拆迁到了上海。", "explanation": "这里应该用〈搬家〉。拆迁是拆房并迁走原住户，住户自己迁居不能说拆迁。"}, {"text": "他把自行车拆迁下来修理。", "explanation": "这里应该用〈拆卸〉。拆迁只用于房屋和原住户，拆自行车要用拆卸。"}, {"text": "工人把货物拆迁上车。", "explanation": "这里应该用〈搬运〉。拆迁只指拆房安置住户，不能用于搬运货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府已经把这片旧房屋拆迁着。", "corrected_sentence": "政府已经把这片旧房屋拆迁了。", "error_description": "错误形式：“已经把这片旧房屋拆迁着”；正确形式：“已经把这片旧房屋拆迁了”。“着”表示动作进行或状态持续，与“已经”表示的完成义矛盾，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧房子已经拆迁的完了。", "corrected_sentence": "这些旧房子已经拆迁完了。", "error_description": "错误形式：“拆迁的完了”；正确形式：“拆迁完了”。结果补语“完”要紧跟在动词后面表示拆迁结束，“的”不能插在动词和补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
