INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92207, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不小心做错了。", "primary_collocate": null, "pronunciation": "shī wù", "ipa": "ʂʅ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他在比赛中失误了。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员一失误，对方就进球了。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太紧张，在台上失误了。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他投篮时失误了两次。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时别分心，一失误就危险。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少失误，所以大家都相信他。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹琴的时候她失误了一次。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球员今天老是失误。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“失误了不要紧，再来一次。”", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕失误，所以练了很多遍。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失误了", "label": "体标"}], "register": "中性", "sense_fingerprint": "失误：做事或比赛时因不小心而出错（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92207, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "失误", "is_correct": true, "explanation": "「失误」指做事或比赛时因不小心而出错，是正确答案。"}, {"text": "事务", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，「事务」指工作中的事情，不指出错。"}, {"text": "失去", "is_correct": false, "explanation": "wù 与 qù 声母不同，「失去」指丢掉、失掉。"}, {"text": "失序", "is_correct": false, "explanation": "wù 与 xù 声母不同，「失序」指秩序被打乱。"}, {"text": "失速", "is_correct": false, "explanation": "wù 与 sù 声母不同，「失速」指速度下降或失控。"}, {"text": "私物", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），「私物」指个人的东西。"}], "explanations": {"失误": "「失误」指做事或比赛时因不小心而出错，是正确答案。", "事务": "shì（第四声）与 shī（第一声）声调不同，「事务」指工作中的事情，不指出错。", "失去": "wù 与 qù 声母不同，「失去」指丢掉、失掉。", "失序": "wù 与 xù 声母不同，「失序」指秩序被打乱。", "失速": "wù 与 sù 声母不同，「失速」指速度下降或失控。", "私物": "shī 与 sī 声母不同（sh 与 s），「私物」指个人的东西。"}, "sentence_index": null, "correct_answer": "失误"}, "level_3": {"options": [{"text": "失误", "is_correct": true, "explanation": "正确。「失误」指比赛中因不小心而出错，与句中的比赛相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指人生下来，不能说在比赛中出生。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：「殉职」是书面语，指因公牺牲，语域和意思都与比赛不合。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：「发胖」指体形变胖，不能用来说比赛中的情况。"}], "explanations": {"失误": "正确。「失误」指比赛中因不小心而出错，与句中的比赛相符。", "出生": "语义：「出生」指人生下来，不能说在比赛中出生。", "殉职": "语域：「殉职」是书面语，指因公牺牲，语域和意思都与比赛不合。", "发胖": "体貌：「发胖」指体形变胖，不能用来说比赛中的情况。"}, "sentence_index": 0, "correct_answer": "失误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的失误很动听，大家都喜欢。", "explanation": "这里应该用〈旋律〉。失误指做事时的差错，不能用来形容歌曲动听。"}, {"text": "两家人之间的失误终于解开了。", "explanation": "这里应该用〈误会〉。失误指做事时的疏忽，不用于两人之间的误解，也不能说「解开」。"}, {"text": "兄妹俩在战乱中失误了，多年后才重逢。", "explanation": "这里应该用〈失散〉。失误指做事出错，不能用来说亲人在战乱中走散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92207, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "失误", "is_correct": true, "explanation": "「失误」指做事或比赛时因不小心而出错，是正确答案。"}, {"text": "事物", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，「事物」指事情和东西。"}, {"text": "失步", "is_correct": false, "explanation": "wù 与 bù 声母不同，「失步」指走路或行动跟不上节拍。"}, {"text": "诗句", "is_correct": false, "explanation": "wù 与 jù 声母不同，「诗句」指诗的句子。"}, {"text": "实务", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，「实务」指实际的工作事务。"}], "explanations": {"失误": "「失误」指做事或比赛时因不小心而出错，是正确答案。", "事物": "shì（第四声）与 shī（第一声）声调不同，「事物」指事情和东西。", "失步": "wù 与 bù 声母不同，「失步」指走路或行动跟不上节拍。", "诗句": "wù 与 jù 声母不同，「诗句」指诗的句子。", "实务": "shí（第二声）与 shī（第一声）声调不同，「实务」指实际的工作事务。"}, "sentence_index": null, "correct_answer": "失误"}, "level_3": {"options": [{"text": "失误", "is_correct": true, "explanation": "正确。「失误」指弹琴时因不小心而弹错，与句中的弹琴相符。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：「失眠」指睡不着觉，与弹琴的情境不相干。"}, {"text": "阵亡", "is_correct": false, "explanation": "语域：「阵亡」是书面语，指战死，与弹琴的语境不合。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：「长高」指身高增加，不是弹琴时会发生的事。"}], "explanations": {"失误": "正确。「失误」指弹琴时因不小心而弹错，与句中的弹琴相符。", "失眠": "语义：「失眠」指睡不着觉，与弹琴的情境不相干。", "阵亡": "语域：「阵亡」是书面语，指战死，与弹琴的语境不合。", "长高": "体貌：「长高」指身高增加，不是弹琴时会发生的事。"}, "sentence_index": 6, "correct_answer": "失误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥昨天失误了，所以车子都过不去。", "explanation": "失误只用于人做事时出错，不能用来说桥梁这类无生命的东西；这里应该用〈塌了〉。"}, {"text": "电灯昨晚失误了，屋里一片漆黑。", "explanation": "失误的主语应是人，电灯不会失误；这里应该用〈坏了〉或〈不亮了〉。"}, {"text": "他的脚失误了，所以在路上摔倒了。", "explanation": "这里应该用〈滑〉或〈扭伤〉。失误指人做事时出错，不能以「脚」作主语；脚一滑应说〈滑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他太紧张，失误的很厉害。", "corrected_sentence": "他太紧张，失误得很厉害。", "error_description": "程度补语要用「得」引出，不能用「的」：「失误的很厉害」应说「失误得很厉害」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在比赛中被失误了一次。", "corrected_sentence": "他在比赛中失误了一次。", "error_description": "「被失误」错误，应说「失误」。「失误」是不及物动词，不能用「被」构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
