INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他犯了一只失误。", "corrected_sentence": "他犯了一个失误。", "error_description": "量词错误：「失误」应用「个」或「次」，「只」用于动物等，不能用于失误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这次犯了一个很大失误。", "corrected_sentence": "他这次犯了一个很大的失误。", "error_description": "「很大失误」错误，应说「很大的失误」。「很」加形容词修饰名词时，中间通常要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
