INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92209, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拉话是随便聊天，说说话。", "primary_collocate": null, "pronunciation": "lā huà", "ipa": "la˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "晚饭后，奶奶常和邻居在门口拉话。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在树下拉话，一直拉到天黑。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末老朋友来家里，我们喝着茶拉话。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上班时间不要拉话，先把工作做完。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老人们坐在一起拉话晒太阳。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩在厨房里边择菜边拉话。", "target_word": "拉话", "complexity_tier": "T3", "furigana": "jiě mèi liǎ zài chú fáng lǐ biān zé cài biān lā huà", "sentence_source": "generated"}, {"text": "你有空就来我家拉话吧。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们睡了，夫妻俩在院子里拉话。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车上，旁边的老人主动和我拉话。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很爱热闹，见了谁都想拉话。", "target_word": "拉话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拉过话", "label": "体标"}, {"form": "拉拉话", "label": "重叠"}], "register": "口语", "sense_fingerprint": "拉话：和别人随便聊天，说说话（口语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a127e4-6f10-4f8a-b8d9-beff9815793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拉话", "is_correct": true, "explanation": "拉话指随便聊天，“奶奶常和邻居在门口”正是闲聊的场景。"}, {"text": "入睡", "is_correct": false, "explanation": "配价：“入睡”是不及物动词，不能与“和邻居”一起表示共同的动作。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”是一次性的事件，与“常”不合，也不是在门口进行的活动。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状态，不能和邻居在门口共同进行。"}], "explanations": {"拉话": "拉话指随便聊天，“奶奶常和邻居在门口”正是闲聊的场景。", "入睡": "配价：“入睡”是不及物动词，不能与“和邻居”一起表示共同的动作。", "出生": "语义：“出生”是一次性的事件，与“常”不合，也不是在门口进行的活动。", "生病": "语义：“生病”是身体状态，不能和邻居在门口共同进行。"}, "sentence_index": 0, "correct_answer": "拉话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长在开学典礼上拉话，强调了纪律。", "explanation": "这里应该用〈讲话〉。拉话只指随便聊天，典礼上的正式致辞要用讲话，不能用拉话。"}, {"text": "原告在法庭上拉话，法官随即宣布了判决。", "explanation": "这里应该用〈陈述〉。拉话只指随便聊天，法庭上当事人的正式陈述不能用拉话。"}, {"text": "这次会议请他来拉话。", "explanation": "这里应该用〈发言〉。拉话只指随便聊天，会上有准备地发表意见要用发言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拉话", "is_correct": true, "explanation": "拉话指随便聊天，“有空就来我家”的邀请正适合这种活动。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指来得晚，与“有空就来”的邀请语境不符。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：“摔倒”是意外，不是邀请对方来做的活动。"}, {"text": "发抖", "is_correct": false, "explanation": "体貌：“发抖”描写身体状态，不能作为来访时的活动。"}], "explanations": {"拉话": "拉话指随便聊天，“有空就来我家”的邀请正适合这种活动。", "迟到": "语义：“迟到”指来得晚，与“有空就来”的邀请语境不符。", "摔倒": "语义：“摔倒”是意外，不是邀请对方来做的活动。", "发抖": "体貌：“发抖”描写身体状态，不能作为来访时的活动。"}, "sentence_index": 6, "correct_answer": "拉话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在礼堂里拉话，手里拿着讲稿一字一句地念。", "explanation": "这里应该用〈演讲〉。拉话只指随便聊天，照着讲稿面向听众的讲演要用演讲。"}, {"text": "正方和反方在台上拉话，互相驳斥对方的观点。", "explanation": "这里应该用〈辩论〉。拉话只指随便聊天，针锋相对地驳斥对方观点要用辩论。"}, {"text": "两国代表在会议桌前拉话，并就关税税率展开了激烈的交锋。", "explanation": "这里应该用〈谈判〉。拉话只指随便聊天，就关税这类正式协商中的激烈交锋要用谈判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们拉话了一下午。", "corrected_sentence": "我们拉话拉了一下午。", "error_description": "错误：带时量补语的离合词“拉话”，动词要重复或拆开，“拉话了一下午”不成立，应写作“拉话拉了一下午”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拉话得很开心。", "corrected_sentence": "她拉话拉得很开心。", "error_description": "错误：带补语的离合词“拉话”，补语前要重复动词，应写作“拉话拉得”，不能只写“拉话得”。正确：“她拉话拉得很开心。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
