INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92213, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指路是告诉别人怎么走。", "primary_collocate": null, "pronunciation": "zhǐ lù", "ipa": "ʈʂɻ̩˨˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "我不知道路，请你给我指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位老人在路口给我们指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指路指得很清楚。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客问路，小李热情地给他们指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手机没电了，请您帮我指路好吗？", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察站在路口，给开车的人指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我们指路，让我们往右走。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你给我指路，我找到银行了。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太复杂了，没有人指路，我们会迷路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子很乐意给陌生人指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指指路", "label": "重叠"}, {"form": "指了路", "label": "体标"}, {"form": "指个路", "label": "离合"}], "register": "中性", "sense_fingerprint": "为问路的人说明具体怎么走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92213, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直路", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直的道路。"}, {"text": "指路", "is_correct": true, "explanation": "指路：告诉别人怎么走，即本题的词条。"}, {"text": "支路", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是岔路。"}, {"text": "直露", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是直接显露、不加掩饰。"}], "explanations": {"直路": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直的道路。", "指路": "指路：告诉别人怎么走，即本题的词条。", "支路": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是岔路。", "直露": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是直接显露、不加掩饰。"}, "sentence_index": null, "correct_answer": "指路"}, "level_3": {"options": [{"text": "讲故事", "is_correct": false, "explanation": "语义：“讲故事”与“我不知道路”无关，不能用来请人指示方向。"}, {"text": "指路", "is_correct": true, "explanation": "指路：告诉别人怎么走，与“我不知道路”前后呼应。"}, {"text": "修路", "is_correct": false, "explanation": "语义：“修路”是建造道路，与请人告诉怎么走不符。"}, {"text": "点菜", "is_correct": false, "explanation": "搭配：“点菜”只用于餐馆点餐，不能用于问路。"}], "explanations": {"讲故事": "语义：“讲故事”与“我不知道路”无关，不能用来请人指示方向。", "指路": "指路：告诉别人怎么走，与“我不知道路”前后呼应。", "修路": "语义：“修路”是建造道路，与请人告诉怎么走不符。", "点菜": "搭配：“点菜”只用于餐馆点餐，不能用于问路。"}, "sentence_index": 0, "correct_answer": "指路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指路了我的错误。", "explanation": "这里应该用〈指出〉。指路是告诉别人怎么走，不能用来指出错误。"}, {"text": "我向他指路这座城市的历史。", "explanation": "这里应该用〈介绍〉。指路是告诉别人怎么走，不能用来说明城市的历史。"}, {"text": "他负责指路这份文件。", "explanation": "这里应该用〈翻译〉。指路是告诉别人怎么走，不能用来处理文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“往右走”没有关系，不能说明方向。"}, {"text": "指路", "is_correct": true, "explanation": "指路：告诉别人怎么走，与后面“让我们往右走”前后呼应。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带宾语（送什么），“给我们送”后面缺少宾语。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”是做家务，与说明方向无关。"}], "explanations": {"唱歌": "语义：“唱歌”与“往右走”没有关系，不能说明方向。", "指路": "指路：告诉别人怎么走，与后面“让我们往右走”前后呼应。", "送": "配价：“送”需要带宾语（送什么），“给我们送”后面缺少宾语。", "做饭": "语义：“做饭”是做家务，与说明方向无关。"}, "sentence_index": 6, "correct_answer": "指路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆员帮我指路资料。", "explanation": "这里应该用〈查询〉。指路是告诉别人怎么走，不能用来找资料。"}, {"text": "医生指路了我的身体。", "explanation": "这里应该用〈检查〉。指路是告诉别人怎么走，不能用来检查身体。"}, {"text": "师傅指路了坏掉的自行车。", "explanation": "这里应该用〈修理〉。指路是告诉别人怎么走，不能用来处理损坏的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大叔指路指地很仔细，我们马上就找到了。", "corrected_sentence": "这位大叔指路指得很仔细，我们马上就找到了。", "error_description": "“指路”后面带表示程度的补语时，要用结构助词“得”，不能用“地”。应改为“指路指得很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人指路得特别细，我们一下子就明白了。", "corrected_sentence": "这位老人指路指得特别细，我们一下子就明白了。", "error_description": "“指路”后面带“得”的补语时，要重复动词，应说“指路指得特别细”，不能说“指路得特别细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
