INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人前进的道路。", "primary_collocate": null, "pronunciation": "zhǐ lù", "ipa": "ʈʂɻ̩˨˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "在我最难的时候，老师给我指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书为年轻人指路，让他们找到方向。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为我的人生指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的一番话为我指路，让我知道以后怎么做。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常常给我指路，教我怎样做人。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在迷茫的时候，朋友给我指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师不只教知识，还给学生指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢您在工作上给我指路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位前辈给年轻人指路，让大家少走弯路。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事给我们指路，让我们看到希望。", "target_word": "指路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指指路", "label": "重叠"}, {"form": "指了路", "label": "体标"}, {"form": "指个路", "label": "离合"}], "register": "中性", "sense_fingerprint": "在人生或事业上为人指明方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92214, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直路", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直的道路。"}, {"text": "指路", "is_correct": true, "explanation": "指路：为人指明前进的方向，即本题的词条。"}, {"text": "支路", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是岔路。"}, {"text": "直露", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是直接显露、不加掩饰。"}], "explanations": {"直路": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直的道路。", "指路": "指路：为人指明前进的方向，即本题的词条。", "支路": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是岔路。", "直露": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是直接显露、不加掩饰。"}, "sentence_index": null, "correct_answer": "指路"}, "level_3": {"options": [{"text": "洗车", "is_correct": false, "explanation": "语义：“洗车”是清洁车辆，与在困难时给人指引无关。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带宾语（送什么），“给我送”后面缺少宾语。"}, {"text": "指路", "is_correct": true, "explanation": "指路：为人指明前进的方向，与“最难的时候”的语境相符。"}, {"text": "点菜", "is_correct": false, "explanation": "搭配：“点菜”用于餐馆点餐，不能用来指引人生的方向。"}], "explanations": {"洗车": "语义：“洗车”是清洁车辆，与在困难时给人指引无关。", "送": "配价：“送”需要带宾语（送什么），“给我送”后面缺少宾语。", "指路": "指路：为人指明前进的方向，与“最难的时候”的语境相符。", "点菜": "搭配：“点菜”用于餐馆点餐，不能用来指引人生的方向。"}, "sentence_index": 0, "correct_answer": "指路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他指路士兵冲锋。", "explanation": "这里应该用〈指挥〉。指路是为人指明前进的方向，不能用来指挥士兵的行动。"}, {"text": "教练指路运动员的动作。", "explanation": "这里应该用〈指导〉。指路是指明前进的方向，不用于具体动作的教授。"}, {"text": "老师指路了这道题的解法。", "explanation": "这里应该用〈讲解〉。指路表示为人指明方向，不能用来说明解题的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理发", "is_correct": false, "explanation": "语义：“理发”指剪头发，与指导学生的人生方向无关。"}, {"text": "指路", "is_correct": true, "explanation": "指路：为学生指明前进的方向，与“不只教知识”的语境相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：“开车”是驾驶车辆，与教育学生的语境不符。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”是修理车辆，与教育学生的语境不符。"}], "explanations": {"理发": "语义：“理发”指剪头发，与指导学生的人生方向无关。", "指路": "指路：为学生指明前进的方向，与“不只教知识”的语境相符。", "开车": "语义：“开车”是驾驶车辆，与教育学生的语境不符。", "修车": "语义：“修车”是修理车辆，与教育学生的语境不符。"}, "sentence_index": 6, "correct_answer": "指路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他指路孩子的情绪。", "explanation": "这里应该用〈安抚〉。指路是指明前进的方向，不能用来安抚情绪。"}, {"text": "老师指路了我的作业。", "explanation": "这里应该用〈批改〉。指路是为人指明前进的方向，不能用来说明批阅作业。"}, {"text": "学校指路人才。", "explanation": "这里应该用〈培养〉。指路是指明前进的方向，不能用来说明培育人才。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚毕业的时候，前辈跟我指路，让我少走了很多弯路。", "corrected_sentence": "我刚毕业的时候，前辈为我指路，让我少走了很多弯路。", "error_description": "“指路”的对象要用介词“为”或“给”引出，“跟”不能用在这里。应改为“前辈为我指路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对未来很迷茫，叔叔把我指路，让我看清了方向。", "corrected_sentence": "我对未来很迷茫，叔叔给我指路，让我看清了方向。", "error_description": "错误在介词。“指路”的对象要用“给”或“为”引出，不能用“把”；应说“叔叔给我指路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
