INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审查；审问。", "primary_collocate": null, "pronunciation": "shěn", "ipa": "ʂən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个计划要先由领导审，再决定做不做。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在审那个偷东西的人。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察审了他三个小时，他什么也不说。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章写好后，要先送去审，才能发表。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份材料已经审过了，没有问题。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的书都要先审，才能进学校。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到小偷后，连夜审了他。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影上映以前，要先送到有关部门审。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很大，上面派人来审，要查清楚。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的广告，都要经理先审一下。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "審", "label": "繁体"}, {"form": "审了", "label": "体标"}, {"form": "审过", "label": "体标"}, {"form": "审查", "label": "复合"}, {"form": "审问", "label": "复合"}], "register": "正式", "sense_fingerprint": "按规定检查材料是否合格，或警察询问嫌疑人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是审查材料或询问。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。"}, {"text": "省", "is_correct": false, "explanation": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是审查材料或询问。", "神": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。", "省": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。", "诊": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”指审查、审核，与“计划”“再决定做不做”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，计划不能吃。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只说衣服、鞋袜，不能说穿计划。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”搭配歌曲、戏曲，不能用于计划。"}], "explanations": {"审": "正确：“审”指审查、审核，与“计划”“再决定做不做”的语境相合。", "吃": "语义：“吃”指把食物咽下去，计划不能吃。", "穿": "搭配：“穿”只说衣服、鞋袜，不能说穿计划。", "唱": "搭配：“唱”搭配歌曲、戏曲，不能用于计划。"}, "sentence_index": 0, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生审了他的心脏，说没什么问题。", "explanation": "这里应该用〈检查〉。“审”用于审查材料或询问，检查身体要用“检查”。"}, {"text": "我把玩具审进箱子里了。", "explanation": "这里应该用〈放〉。“审”指审查或审问，不能表示把东西放进某处。"}, {"text": "兽医审了小狗。", "explanation": "这里应该用〈看〉。给小狗看病要用“看”，“审问”的对象只能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是审查材料或询问。"}, {"text": "肾", "is_correct": false, "explanation": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是审查材料或询问。", "肾": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。", "深": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。", "枕": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”指审问、审查，与“警察抓到小偷”的语境相合。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等，不能用于人。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，与“警察抓到小偷后”的语境不符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”搭配花、果子等，不能用于人。"}], "explanations": {"审": "正确：“审”指审问、审查，与“警察抓到小偷”的语境相合。", "戴": "搭配：“戴”搭配帽子、眼镜等，不能用于人。", "咬": "语义：“咬”指用牙齿夹住，与“警察抓到小偷后”的语境不符。", "摘": "搭配：“摘”搭配花、果子等，不能用于人。"}, "sentence_index": 6, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机把汽油审进了油箱。", "explanation": "这里应该用〈加〉。“审”指审查或审问，不能表示把汽油注入油箱。"}, {"text": "妈妈用扫帚审地，然后擦桌子。", "explanation": "这里应该用〈扫〉。“审”指审查或审问，不能表示用扫帚清理地面。"}, {"text": "小王把脏衣服审干净了。", "explanation": "这里应该用〈洗〉。“审”没有清洗的意思，把脏衣服洗干净要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会计师把那家公司的账了审三次。", "corrected_sentence": "会计师把那家公司的账审了三次。", "error_description": "“了”位置错误：“了”应紧跟动词“审”，即“审了三次”，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同，经理要先把它审。", "corrected_sentence": "这份合同，经理要先把它审一下。", "error_description": "补语缺失：“把”字句中动词后要带补语，如“一下”，应为“把它审一下”，不能只说“把它审”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提前", "is_correct": true, "explanation": "提前：与推迟互为反义，推迟是把事情往后改，提前是把事情往前改。"}, {"text": "完成", "is_correct": false, "explanation": "完成：指做成功，与推迟不是反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "保持：指维持原状，与推迟不是反义关系。"}, {"text": "坚持", "is_correct": false, "explanation": "坚持：指持续做下去，与推迟不是反义关系。"}], "correct_answer": "提前", "explanations": {"提前": "提前：与推迟互为反义，推迟是把事情往后改，提前是把事情往前改。", "完成": "完成：指做成功，与推迟不是反义关系。", "保持": "保持：指维持原状，与推迟不是反义关系。", "坚持": "坚持：指持续做下去，与推迟不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提前", "is_correct": true, "explanation": "提前：与推迟互为反义，推迟是把事情往后改，提前是把事情往前改。"}, {"text": "整理", "is_correct": false, "explanation": "整理：指把杂乱的东西理顺摆好，与推迟不是反义关系。"}, {"text": "结束", "is_correct": false, "explanation": "结束：指事情终止，与推迟不是反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：指交换意见，与推迟不是反义关系。"}], "correct_answer": "提前", "explanations": {"提前": "提前：与推迟互为反义，推迟是把事情往后改，提前是把事情往前改。", "整理": "整理：指把杂乱的东西理顺摆好，与推迟不是反义关系。", "结束": "结束：指事情终止，与推迟不是反义关系。", "讨论": "讨论：指交换意见，与推迟不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "推迟是把事情改到更晚的时候做。", "primary_collocate": null, "pronunciation": "tuī chí", "ipa": "tʰuei̯˥ ʈʂʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事不能再推迟了。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是把工作推迟到最后一天。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别把今天的事推迟到明天。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把买车的事推迟一年。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把结婚的事推迟了。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业别推迟到明天做。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作太忙，我把休假推迟了。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把看医生的事推迟了好几天。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司推迟了新产品的发布。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王推迟过好几次约会。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推迟了", "label": "完成体"}, {"form": "推迟过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "把事情改到更晚的时候做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推迟", "is_correct": true, "explanation": "推迟：把事情改到更晚的时候做，正好填入“这件事不能再……了”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，“这件事”不能被喝。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”需要有形的东西作宾语，事情不能被咬。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指物体掉落，“摔这件事”搭配不当。"}], "explanations": {"推迟": "推迟：把事情改到更晚的时候做，正好填入“这件事不能再……了”。", "喝": "语义：“喝”的对象是饮料，“这件事”不能被喝。", "咬": "语义：“咬”需要有形的东西作宾语，事情不能被咬。", "摔": "搭配：“摔”指物体掉落，“摔这件事”搭配不当。"}, "sentence_index": 0, "correct_answer": "推迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈推迟了生病的孩子。", "explanation": "这里应该用〈照顾〉。推迟的对象是时间或事情，不能用于人，照顾生病的孩子应说照顾。"}, {"text": "他想把买车的事推迟到去年。", "explanation": "这里应该用〈提前〉。推迟是把事情往后改，不能推迟到更早的去年，应说提前。"}, {"text": "她推迟了那扇窗户。", "explanation": "这里应该用〈打开〉。推迟的对象是时间或事情，窗户不能推迟，应说打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推迟", "is_correct": true, "explanation": "推迟：把休假改到更晚的时候，正好填入“我把休假……了”。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”针对文件，休假不能被打印。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指把东西咽下去，休假不能被吞下。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”针对器物或房屋，休假不能被修。"}], "explanations": {"推迟": "推迟：把休假改到更晚的时候，正好填入“我把休假……了”。", "打印": "搭配：“打印”针对文件，休假不能被打印。", "吞": "语义：“吞”指把东西咽下去，休假不能被吞下。", "修": "搭配：“修”针对器物或房屋，休假不能被修。"}, "sentence_index": 6, "correct_answer": "推迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推迟了一个朋友。", "explanation": "这里应该用〈陪伴〉。推迟的对象是时间或事情，不能用于人，陪伴朋友应说陪伴。"}, {"text": "我推迟了这块石头。", "explanation": "这里应该用〈搬〉。推迟只用于时间或安排，石头不能推迟，应说搬。"}, {"text": "他推迟了那个苹果。", "explanation": "这里应该用〈吃〉。推迟的对象是时间或事情，苹果不能推迟，应说吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把那个项目推迟了着三天。", "corrected_sentence": "我们把那个项目推迟了三天。", "error_description": "错误：“推迟了着三天”，“了”与“着”不能同时用在同一动词上。正确：“推迟了三天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场比赛推迟得了很久。", "corrected_sentence": "那场比赛推迟了很久。", "error_description": "错误：“推迟得了很久”，多出的“得”与“了”冲突。正确：“推迟了很久”，“了”直接跟在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
