INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把预定的时间往后延。", "primary_collocate": null, "pronunciation": "tuī chí", "ipa": "tʰuei̯˥ ʈʂʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "会议推迟到下星期了。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为下雨，比赛推迟了。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把考试推迟到星期五。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机推迟了两个小时起飞。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把出发的时间推迟一天吧。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时间推迟了吗？", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的生日晚会推迟到明天晚上。", "target_word": "推迟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行推迟过一次。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，我把出发时间推迟了。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把开学的时间推迟了一个星期。", "target_word": "推迟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推迟了", "label": "完成体"}, {"form": "推迟过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "把预定的时间往后延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推迟", "is_correct": true, "explanation": "推迟：把时间往后延，正好填入“会议……到下星期了”。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”指人或车动身离去，会议不能离开到某个时间。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”要求事情作宾语，不能接“到下星期”这样的时间补语。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物，会议不能被修理。"}], "explanations": {"推迟": "推迟：把时间往后延，正好填入“会议……到下星期了”。", "离开": "语义：“离开”指人或车动身离去，会议不能离开到某个时间。", "完成": "配价：“完成”要求事情作宾语，不能接“到下星期”这样的时间补语。", "修理": "语义：“修理”针对器物，会议不能被修理。"}, "sentence_index": 0, "correct_answer": "推迟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去推迟生病的奶奶。", "explanation": "这里应该用〈看望〉。推迟的对象是时间或安排，不能用于人，探望生病的奶奶应说看望。"}, {"text": "我们把出发的时间推迟到昨天。", "explanation": "这里应该用〈提前〉。推迟是把时间往后延，不能推迟到更早的昨天，应说提前。"}, {"text": "他推迟了这句话，没有再解释。", "explanation": "这里应该用〈收回〉。推迟的对象是时间或安排，不能用于一句话，应说收回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推迟", "is_correct": true, "explanation": "推迟：把晚会的时间往后延，正好填入“他的生日晚会……到明天晚上”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，生日晚会不能被吃。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是物品，生日晚会不能被洗。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指物体掉落，不能搭配“生日晚会”这样的活动。"}], "explanations": {"推迟": "推迟：把晚会的时间往后延，正好填入“他的生日晚会……到明天晚上”。", "吃": "语义：“吃”的对象是食物，生日晚会不能被吃。", "洗": "语义：“洗”的对象是物品，生日晚会不能被洗。", "摔": "搭配：“摔”指物体掉落，不能搭配“生日晚会”这样的活动。"}, "sentence_index": 6, "correct_answer": "推迟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校热情地推迟了新生。", "explanation": "这里应该用〈迎接〉。推迟的对象是时间或安排，不能用于新生，热情接待新生应说迎接。"}, {"text": "学校推迟了三十位老师。", "explanation": "这里应该用〈招募〉。推迟只用于时间或事情，老师是人，招募三十位老师应说招募。"}, {"text": "他推迟了一个微笑。", "explanation": "这里应该用〈露出〉。微笑是动作，不能推迟，应说露出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展览推迟了到下个月。", "corrected_sentence": "展览推迟到了下个月。", "error_description": "错误：“推迟了到下个月”，“了”位置不对。正确：“推迟到了下个月”，“到”引出时间补语，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演唱会已经推迟过过两次了。", "corrected_sentence": "演唱会已经推迟过两次了。", "error_description": "错误：“推迟过过两次”，经历体“过”重复出现。正确：“推迟过两次”，“过”只出现一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。"}, {"text": "热情", "is_correct": false, "explanation": "无关：「热情」是待人的态度，与专制的作风没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "无关：「粗心」指做事不仔细，与专制没有反义关系。"}, {"text": "勤快", "is_correct": false, "explanation": "无关：「勤快」指爱干活，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。", "热情": "无关：「热情」是待人的态度，与专制的作风没有反义关系。", "粗心": "无关：「粗心」指做事不仔细，与专制没有反义关系。", "勤快": "无关：「勤快」指爱干活，与专制没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
