INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个人说了算，不管别人怎么想。", "primary_collocate": null, "pronunciation": "zhuān zhì", "ipa": "ʈʂuan˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他的父亲很专制，家里的事都他说了算。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理太专制，从来不听同事的意见。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢专制的老板，他从不让我们说话。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子很专制，连穿什么衣服都要管。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很专制，学生不能问问题。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事专制，大家都不愿意和他商量。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么专制，也听听孩子怎么想。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时很专制，奶奶什么都得听他的。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长太专制了，没人敢说自己的看法。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的家长总是不听孩子的想法。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专制主义", "label": "复合"}], "register": "通用", "sense_fingerprint": "形容人或家长、上司的作风：独断专行，凡事自己说了算，不听别人的意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确答案，指一个人说了算，不听别人的意见。"}, {"text": "专职", "is_correct": false, "explanation": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。"}, {"text": "装置", "is_correct": false, "explanation": "装置与专制的韵母不同（ang 与 an），意思是设备。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志与专制的读音不同（zhuàng 与 zhuān，韵母和声调都不同），意思是远大的志向。"}, {"text": "专指", "is_correct": false, "explanation": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。"}, {"text": "转制", "is_correct": false, "explanation": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}], "explanations": {"专制": "正确答案，指一个人说了算，不听别人的意见。", "专职": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。", "装置": "装置与专制的韵母不同（ang 与 an），意思是设备。", "壮志": "壮志与专制的读音不同（zhuàng 与 zhuān，韵母和声调都不同），意思是远大的志向。", "专指": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。", "转制": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}, "sentence_index": null, "correct_answer": "专制"}, "level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「很专制」指父亲独断，与后半句「家里的事都他说了算」一致。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指大家共同商量，与「家里的事都他说了算」矛盾。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：「懦弱」指没有主见、胆小，与「事都他说了算」的强势形象相反。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，不说作风，与句中的管理方式无关。"}], "explanations": {"专制": "正确：「很专制」指父亲独断，与后半句「家里的事都他说了算」一致。", "民主": "语义：「民主」指大家共同商量，与「家里的事都他说了算」矛盾。", "懦弱": "语义：「懦弱」指没有主见、胆小，与「事都他说了算」的强势形象相反。", "高大": "体貌：「高大」说身材，不说作风，与句中的管理方式无关。"}, "sentence_index": 0, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友很专制，每次聊天都先问问我的想法。", "explanation": "这里应该用〈体贴〉。专制指一个人说了算、不顾别人想法，句子说他先问我的想法，正好相反。"}, {"text": "他做事很专制，常常听取大家的建议。", "explanation": "这里应该用〈民主〉。专制指独断专行、不顾别人的意见，句子说他常听取大家的建议，应该用民主。"}, {"text": "奶奶很专制，每次做决定都要先问全家人。", "explanation": "这里应该用〈民主〉。专制指一个人说了算，句子说做决定前要问全家人，应该用民主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「这么专制」指做事独断，与后半句「也听听孩子怎么想」形成对比。"}, {"text": "平等", "is_correct": false, "explanation": "语义：「平等」与「别这么……」的劝阻语气及后文不协调，句意前后矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」说身材，与说话做事的态度无关。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」说身体，不能用来评价做事的态度。"}], "explanations": {"专制": "正确：「这么专制」指做事独断，与后半句「也听听孩子怎么想」形成对比。", "平等": "语义：「平等」与「别这么……」的劝阻语气及后文不协调，句意前后矛盾。", "矮小": "体貌：「矮小」说身材，与说话做事的态度无关。", "瘦弱": "体貌：「瘦弱」说身体，不能用来评价做事的态度。"}, "sentence_index": 6, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐很专制，凡事都愿意听别人的想法。", "explanation": "这里应该用〈随和〉。专制指一个人说了算、不管别人怎么想，句子说她愿意听别人的想法，与之相反。"}, {"text": "这个孩子很专制，每次做游戏都让别人先选。", "explanation": "这里应该用〈谦让〉。专制指独断专行，句子说他让别人先选，应该用谦让。"}, {"text": "她当班长很专制，什么事都先让同学们一起投票决定。", "explanation": "这里应该用〈民主〉。专制指一个人说了算、不顾别人，句子说她让大家投票决定，应该用民主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个人很更专制，什么事都要自己做主。", "corrected_sentence": "他这个人很专制，什么事都要自己做主。", "error_description": "「很」和「更」都表示程度，不能叠用。应去掉「更」，说「他这个人很专制」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对孩子专制很得，什么都要管。", "corrected_sentence": "他对孩子专制得很，什么都要管。", "error_description": "「专制得很」是「形容词＋得＋很」的补语结构，「专制很得」语序错误，应说「专制得很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。"}, {"text": "繁荣", "is_correct": false, "explanation": "无关：「繁荣」指经济兴旺，与专制的统治方式没有反义关系。"}, {"text": "富强", "is_correct": false, "explanation": "无关：「富强」指国家富足强盛，与专制没有反义关系。"}, {"text": "和平", "is_correct": false, "explanation": "无关：「和平」指没有战争，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。", "繁荣": "无关：「繁荣」指经济兴旺，与专制的统治方式没有反义关系。", "富强": "无关：「富强」指国家富足强盛，与专制没有反义关系。", "和平": "无关：「和平」指没有战争，与专制没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。"}, {"text": "安定", "is_correct": false, "explanation": "无关：「安定」指社会平稳，与专制没有反义关系。"}, {"text": "落后", "is_correct": false, "explanation": "无关：「落后」指发展慢，与专制没有反义关系。"}, {"text": "贫穷", "is_correct": false, "explanation": "无关：「贫穷」指缺少钱财，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。", "安定": "无关：「安定」指社会平稳，与专制没有反义关系。", "落后": "无关：「落后」指发展慢，与专制没有反义关系。", "贫穷": "无关：「贫穷」指缺少钱财，与专制没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "独自掌握权力，独断专行。", "primary_collocate": null, "pronunciation": "zhuān zhì", "ipa": "ʈʂuan˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家以前很专制，国王一个人掌握所有权力。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的国王不让人民选举官员。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的政治很专制，权力都在皇帝手里。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个专制的政府不允许报纸批评它。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们起来反对专制的统治。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的国家没有真正的选举。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军掌权后越来越专制。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上说，那个朝代的政治非常专制。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们推翻了专制的王朝，建立了新国家。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在专制的社会里，老百姓不能自由说话。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专制主义", "label": "复合"}], "register": "书面", "sense_fingerprint": "形容国家、政府、统治者独自掌握权力，不受限制，不让人民参与", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确答案，指独自掌握权力，不受限制。"}, {"text": "专职", "is_correct": false, "explanation": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。"}, {"text": "装置", "is_correct": false, "explanation": "装置与专制的韵母不同（ang 与 an），意思是设备。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志与专制的读音不同（zhuàng 与 zhuān，韵母和声调都不同），意思是远大的志向。"}, {"text": "专指", "is_correct": false, "explanation": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。"}, {"text": "转制", "is_correct": false, "explanation": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}], "explanations": {"专制": "正确答案，指独自掌握权力，不受限制。", "专职": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。", "装置": "装置与专制的韵母不同（ang 与 an），意思是设备。", "壮志": "壮志与专制的读音不同（zhuàng 与 zhuān，韵母和声调都不同），意思是远大的志向。", "专指": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。", "转制": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}, "sentence_index": null, "correct_answer": "专制"}, "level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「很专制」说明统治方式，与「国王一个人掌握所有权力」一致。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指权力属于人民，与「国王一个人掌握所有权力」矛盾。"}, {"text": "自由", "is_correct": false, "explanation": "语义：「自由」指不受约束，与「国王一个人掌握所有权力」矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」说身材，不能用来形容国家的统治方式。"}], "explanations": {"专制": "正确：「很专制」说明统治方式，与「国王一个人掌握所有权力」一致。", "民主": "语义：「民主」指权力属于人民，与「国王一个人掌握所有权力」矛盾。", "自由": "语义：「自由」指不受约束，与「国王一个人掌握所有权力」矛盾。", "瘦": "体貌：「瘦」说身材，不能用来形容国家的统治方式。"}, "sentence_index": 0, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家对外很专制，欢迎各国游客。", "explanation": "这里应该用〈开放〉。专制指统治者独揽权力，形容对外交流要用开放。"}, {"text": "这个国家的人民很专制，可以随便说话。", "explanation": "这里应该用〈自由〉。专制指统治者独揽权力，不能用来形容人民。"}, {"text": "这届政府很专制，经常举行全民投票，听取人民的意见。", "explanation": "这里应该用〈民主〉。专制指统治者独揽权力、不让人民参与，句子说政府经常举行全民投票、听取人民意见，应该用民主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「越来越专制」指掌权后独断加剧，与句意一致。"}, {"text": "平等", "is_correct": false, "explanation": "语义：「平等」与「掌权后」的语境矛盾，掌权者不会越来越平等。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」说身体，与掌权后的作风无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，不说作风，句子不通。"}], "explanations": {"专制": "正确：「越来越专制」指掌权后独断加剧，与句意一致。", "平等": "语义：「平等」与「掌权后」的语境矛盾，掌权者不会越来越平等。", "瘦弱": "体貌：「瘦弱」说身体，与掌权后的作风无关。", "高大": "体貌：「高大」说身材，不说作风，句子不通。"}, "sentence_index": 6, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个古国很专制，人民可以自由地选择自己的领导人。", "explanation": "这里应该用〈民主〉。专制指统治者独揽权力、不许人民选择，句子说人民可以自由选领导人，与专制相反。"}, {"text": "这位国王很专制，允许大家提不同意见。", "explanation": "这里应该用〈宽容〉。专制指独断专行，形容能接纳不同意见要用宽容。"}, {"text": "这次考试很专制，每个人都有机会。", "explanation": "这里应该用〈公平〉。专制指独揽权力，形容对每个人一视同仁要用公平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个王朝后期越来越很专制，人民的意见没人听。", "corrected_sentence": "那个王朝后期越来越专制，人民的意见没人听。", "error_description": "「越来越」和「很」都表示程度，不能叠用。应去掉「很」，说「越来越专制」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当上皇帝以后，统治的很专制。", "corrected_sentence": "他当上皇帝以后，统治得很专制。", "error_description": "「统治」后面引出程度补语，要用助词「得」，不用「的」。错误形式是「统治的很专制」，正确应为「统治得很专制」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
