INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "推销是想办法让别人买你的东西。", "primary_collocate": null, "pronunciation": "tuī xiāo", "ipa": "tʰuei˥ ɕiau˥", "syllable_count": 2, "sentences": [{"text": "他每天去很多公司，推销新手机。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在街上向行人推销水果。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会说话，一下子推销了十件衣服。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员热情地向我推销新产品。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没学过推销，所以卖得不多。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人推销东西时，我不太想听。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥想办法向老人推销一台电视。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上门推销，但是没人开门。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢电话里有人推销东西。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个阿姨在门口向我推销面包。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "推销员", "label": "复合"}, {"form": "推销了", "label": "体标"}], "register": "口语", "sense_fingerprint": "当面劝说别人买自己的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推销", "is_correct": true, "explanation": "正确：推销指想办法让人买东西，与“去很多公司推销新手机”的语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”不能带“新手机”作宾语，句意不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”指生病，不能带“新手机”，句意不通。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指使东西跌落或弄坏，与“去很多公司”的推销意图不符。"}], "explanations": {"推销": "正确：推销指想办法让人买东西，与“去很多公司推销新手机”的语境相符。", "游泳": "配价：“游泳”不能带“新手机”作宾语，句意不通。", "感冒": "语义：“感冒”指生病，不能带“新手机”，句意不通。", "摔": "语义：“摔”指使东西跌落或弄坏，与“去很多公司”的推销意图不符。"}, "sentence_index": 0, "correct_answer": "推销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很好，我推销你们来尝尝。", "explanation": "这里应该用〈推荐〉。推销的对象是商品，要劝人买东西；请人品尝、介绍好菜用推荐，不能用来指人。"}, {"text": "我把自己种的菜推销给邻居，一分钱也不要。", "explanation": "这里应该用〈分享〉。推销含有劝人购买的意思，与“一分钱也不要”矛盾，无偿送给邻居要用分享。"}, {"text": "社区向老人推销了免费的水果。", "explanation": "这里应该用〈发放〉。推销含有劝人购买的意思，与“免费”矛盾，免费分给老人要用发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推销", "is_correct": true, "explanation": "正确：推销指想办法让人买东西，与“哥哥想办法向老人推销一台电视”相符。"}, {"text": "咨询", "is_correct": false, "explanation": "配价：“咨询”的宾语是问题或意见，不能带“一台电视”这样的具体物品。"}, {"text": "嘱咐", "is_correct": false, "explanation": "配价：“嘱咐”带的是话语或事情，不说“嘱咐一台电视”。"}, {"text": "研磨", "is_correct": false, "explanation": "语义：“研磨”指把东西磨碎，与电视无关，句意不通。"}], "explanations": {"推销": "正确：推销指想办法让人买东西，与“哥哥想办法向老人推销一台电视”相符。", "咨询": "配价：“咨询”的宾语是问题或意见，不能带“一台电视”这样的具体物品。", "嘱咐": "配价：“嘱咐”带的是话语或事情，不说“嘱咐一台电视”。", "研磨": "语义：“研磨”指把东西磨碎，与电视无关，句意不通。"}, "sentence_index": 6, "correct_answer": "推销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了钱，把朋友的秘密推销给了记者。", "explanation": "这里应该用〈出卖〉。推销是劝人购买商品，把朋友的秘密卖给别人以牟利要用出卖。"}, {"text": "他被推销到了山区去支教。", "explanation": "这里应该用〈派〉。推销的对象是商品，人员调派要用“派”，不能说“推销”。"}, {"text": "班长推销了全班的作业。", "explanation": "这里应该用〈收〉。推销的对象是商品，收取作业不是买卖，应用“收”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他老人推销了一台吸尘器。", "corrected_sentence": "他向老人推销了一台吸尘器。", "error_description": "错误在“向”的省略：应为“他向老人推销了一台吸尘器”。推销的对象要用“向”引出，直接说“他老人推销”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我推销过保险过。", "corrected_sentence": "我推销过保险。", "error_description": "“过”多余。“推销过”已表示经历，句末“保险”后不能再加“过”。应为“我推销过保险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
