INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92222, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设法让人购买商品。", "primary_collocate": null, "pronunciation": "tuī xiāo", "ipa": "tʰuei˥ ɕiau˥", "syllable_count": 2, "sentences": [{"text": "公司派他去南方推销新产品。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们通过网络向顾客推销商品。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了推销这批货，老板想了很多办法。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理正在向客户推销新的汽车。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店用打折来推销旧商品。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在电视上推销自己做的茶叶。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个产品很好，不需要大力推销。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂请他们帮忙推销新生产的牛奶。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠推销保险赚了不少钱。", "target_word": "推销", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司常常用礼物来推销商品。", "target_word": "推销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推销员", "label": "复合"}, {"form": "推销了", "label": "体标"}], "register": "中性", "sense_fingerprint": "商家或公司想办法让顾客购买商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推销", "is_correct": true, "explanation": "正确：推销指想办法让人买商品，与“公司派他去南方推销新产品”相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，不能带“新产品”，句意不通。"}, {"text": "嘱咐", "is_correct": false, "explanation": "配价：“嘱咐”的宾语是话语或事情，不能带“新产品”。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指给动物或幼小者提供食物，与产品无关。"}], "explanations": {"推销": "正确：推销指想办法让人买商品，与“公司派他去南方推销新产品”相符。", "咳嗽": "语义：“咳嗽”是身体动作，不能带“新产品”，句意不通。", "嘱咐": "配价：“嘱咐”的宾语是话语或事情，不能带“新产品”。", "喂养": "语义：“喂养”指给动物或幼小者提供食物，与产品无关。"}, "sentence_index": 0, "correct_answer": "推销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很好看，我推销你读一读。", "explanation": "这里应该用〈推荐〉。推销的对象是商品，劝人读书要用推荐，不能说“推销你读”。"}, {"text": "学校向学生推销了免费的午餐券。", "explanation": "这里应该用〈发放〉。推销含有劝人购买的意思，与“免费”矛盾，免费发给学生要用发放。"}, {"text": "老师在班上推销了一次考试。", "explanation": "这里应该用〈举行〉。推销的对象是可以买卖的商品，考试是活动，要用举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推销", "is_correct": true, "explanation": "正确：推销指想办法让人买商品，与“不需要大力推销”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与产品无关，句意不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”与产品无关，句意不通。"}, {"text": "安慰", "is_correct": false, "explanation": "配价：“安慰”的对象是人，不能用于产品。"}], "explanations": {"推销": "正确：推销指想办法让人买商品，与“不需要大力推销”相符。", "游泳": "语义：“游泳”与产品无关，句意不通。", "咳嗽": "语义：“咳嗽”与产品无关，句意不通。", "安慰": "配价：“安慰”的对象是人，不能用于产品。"}, "sentence_index": 6, "correct_answer": "推销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我推销了一下午的作业。", "explanation": "这里应该用〈完成〉。推销的对象是商品，作业不能买卖，应用“完成”。"}, {"text": "政府把这笔钱推销到了农村。", "explanation": "这里应该用〈拨〉。推销的对象是商品，钱款的调拨要用“拨”，不能用推销。"}, {"text": "我把做好的饼干推销给邻居，一分钱也没收。", "explanation": "这里应该用〈分享〉。推销含有让人购买的意思，与“一分钱也没收”矛盾，无偿送人要用分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他客户推销了新汽车。", "corrected_sentence": "他向客户推销了新汽车。", "error_description": "错误在“向”的省略：应为“他向客户推销了新汽车”。推销的对象要用“向”引出，直接说“他客户推销”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把茶叶推销了顾客。", "corrected_sentence": "他把茶叶推销给了顾客。", "error_description": "错误在“给”的省略：应为“推销给了顾客”。推销的接受者要用“给”引出，不能直接把“顾客”当作宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
