INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "正对着的那一边。", "primary_collocate": null, "pronunciation": "duì miàn", "ipa": "tweɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "学校对面有一家很大的书店。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路对面是一个小公园。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家对面是一座高楼。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河对面的山上有很多树。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看对面，那里有一个红色的门。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市在车站对面，很容易找到。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的商店已经关门了。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了这条路，对面就是学校。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从窗口往对面看，能看到一片湖。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮局的对面有一个地铁站。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对面儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "指街道、河流、建筑等正对着的另一侧，用来说明地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对面", "is_correct": true, "explanation": "对面：正对着学校的另一侧，与“学校对面有一家很大的书店”的位置关系相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能作为学校里开设书店的处所。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的设施，不是可以开设书店的地点。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“有一家很大的书店”需要商业性的场所，操场不能与之搭配。"}], "explanations": {"对面": "对面：正对着学校的另一侧，与“学校对面有一家很大的书店”的位置关系相符。", "厨房": "语义：厨房是做饭的地方，不能作为学校里开设书店的处所。", "黑板": "语义：黑板是教室里的设施，不是可以开设书店的地点。", "操场": "搭配：“有一家很大的书店”需要商业性的场所，操场不能与之搭配。"}, "sentence_index": 0, "correct_answer": "对面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家对面的星期天很热闹。", "explanation": "语义：这里误把〈对面〉用成了时间上的相对位置；〈对面〉只表示空间上相对的一侧，“星期天”没有对面。"}, {"text": "我的成绩对面提高了三分。", "explanation": "语义：这里误把〈对面〉用成了抽象数值上的相对位置；〈对面〉只表示空间上相对的一侧，“成绩”没有对面。"}, {"text": "我的心里对面坐着一个朋友。", "explanation": "语义：这里误把〈对面〉用成了心理内部空间中的相对位置；〈对面〉指外部空间中相对的一侧，心里没有对面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对面", "is_correct": true, "explanation": "对面：商店所在的街道另一侧，与“已经关门了”搭配自然。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是能营业的商店。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是盛饭的器具，不能作为商店的所在位置。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不是商店，“课本的商店”不成立。"}], "explanations": {"对面": "对面：商店所在的街道另一侧，与“已经关门了”搭配自然。", "书包": "语义：书包是装东西的袋子，不是能营业的商店。", "饭碗": "语义：饭碗是盛饭的器具，不能作为商店的所在位置。", "课本": "语义：课本是学习用的书，不是商店，“课本的商店”不成立。"}, "sentence_index": 6, "correct_answer": "对面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的对面下了三天雨。", "explanation": "语义：这里误把〈对面〉用成了活动的相对一侧；〈对面〉指地点中相对的一侧，“旅行”是活动，不是地点。"}, {"text": "他的心情对面很好。", "explanation": "语义：这里误把〈对面〉用成了心理状态的相对一侧；〈对面〉指空间位置，“心情”没有相对的一侧。"}, {"text": "这场比赛的对面很安静。", "explanation": "语义：这里误把〈对面〉用成了比赛这类活动的相对一侧；〈对面〉指地点中相对的一侧，“比赛”不是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店车站对面。", "corrected_sentence": "书店在车站对面。", "error_description": "漏掉了介词“在”。处所短语要用“在”引出，“书店在车站对面”中“在车站对面”表示书店的位置，应说“书店在车站对面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "超市在公园对面里。", "corrected_sentence": "超市在公园对面。", "error_description": "错误：“对面”本身就是方位名词，后面不能再加方位词“里”，“对面里”不成立。应说“超市在公园对面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
