INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "相对的一面；正对着的位置。", "primary_collocate": null, "pronunciation": "duì miàn", "ipa": "tweɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他坐在我的对面，一直在笑。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对面坐着一位老人。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，爸爸坐在妈妈对面。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站到老师的对面。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在我对面，隔着桌子说话。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里，我的对面是小李。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在我对面，我们每天都见面。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人隔着桌子，一个在这边，一个在对面。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在我对面等着，我马上过去。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的那个人是我的老同学。", "target_word": "对面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对面儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "指与某人或某物相对的位置，常说坐在某人对面、站在某人对面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对面", "is_correct": true, "explanation": "对面：与“我”相对的位置，符合“他坐在我的对面”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不能作为人坐的位置。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘是输入设备，不能作为人坐的位置。"}, {"text": "对岸", "is_correct": false, "explanation": "搭配：“对岸”指隔着水域的一边，与“我的”这种指人的位置不搭配。"}], "explanations": {"对面": "对面：与“我”相对的位置，符合“他坐在我的对面”。", "窗户": "语义：窗户是建筑构件，不能作为人坐的位置。", "键盘": "语义：键盘是输入设备，不能作为人坐的位置。", "对岸": "搭配：“对岸”指隔着水域的一边，与“我的”这种指人的位置不搭配。"}, "sentence_index": 0, "correct_answer": "对面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的对面有一场大雨。", "explanation": "语义：这里误把〈对面〉用成了时间上的相对位置；〈对面〉只表示空间上相对的位置，“昨天”没有对面。"}, {"text": "他的声音对面很大。", "explanation": "语义：这里误把〈对面〉用成了声音的相对一侧；〈对面〉只表示空间位置，“声音”没有对面。"}, {"text": "他的回忆对面站着一个人。", "explanation": "语义：这里误把〈对面〉用成了回忆这类抽象内容中的相对位置；〈对面〉需要具体的空间，“回忆”不是空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对面", "is_correct": true, "explanation": "对面：与“我”相对的邻居位置，与“每天都见面”搭配自然。"}, {"text": "远方", "is_correct": false, "explanation": "语义：“远方”与“每天都见面”矛盾，不能说住在远方的我。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“住在”后面要接居所，“书包”不能作居所。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底与“我们每天都见面”不相容，人不能住在海底。"}], "explanations": {"对面": "对面：与“我”相对的邻居位置，与“每天都见面”搭配自然。", "远方": "语义：“远方”与“每天都见面”矛盾，不能说住在远方的我。", "书包": "搭配：“住在”后面要接居所，“书包”不能作居所。", "海底": "语义：海底与“我们每天都见面”不相容，人不能住在海底。"}, "sentence_index": 6, "correct_answer": "对面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜的对面很好吃。", "explanation": "语义：这里误把〈对面〉用成了食物的相对一侧；〈对面〉指空间位置，“这盘菜”没有相对的一侧。"}, {"text": "我的心情对面很好。", "explanation": "语义：这里误把〈对面〉用成了心理状态的相对一侧；〈对面〉指空间位置，“心情”没有相对的一侧。"}, {"text": "这个问题的对面很难回答。", "explanation": "语义：这里误把〈对面〉用成了问题的相对一面；〈对面〉指与人或物相对的空间位置，“问题”没有对面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈坐在我对面上吃饭。", "corrected_sentence": "妈妈坐在我对面吃饭。", "error_description": "错误：“对面”本身已是方位，后面不能再加方位词“上”，“对面上”不成词。应说“妈妈坐在我对面吃饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小红是我的对面坐下了。", "corrected_sentence": "小红在我的对面坐下了。", "error_description": "错误：表示位置时应用“在”，不能用“是”。“是”表示判断，不能引出处所。正确应说“小红在我的对面坐下了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：掩饰是盖住，暴露是让人看见，二者意思相反。"}, {"text": "修建", "is_correct": false, "explanation": "无关：修建是建造房屋或设施，与掩饰没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：散步是随意走走，与掩饰没有反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "无关：放弃是不再坚持，与掩饰不构成反义。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：掩饰是盖住，暴露是让人看见，二者意思相反。", "修建": "无关：修建是建造房屋或设施，与掩饰没有反义关系。", "散步": "无关：散步是随意走走，与掩饰没有反义关系。", "放弃": "无关：放弃是不再坚持，与掩饰不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：掩饰是盖住，暴露是让人看见，二者意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "无关：购买是付钱取得东西，与掩饰没有反义关系。"}, {"text": "答应", "is_correct": false, "explanation": "无关：答应是同意，与掩饰没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：旅行是出门游览，与掩饰没有反义关系。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：掩饰是盖住，暴露是让人看见，二者意思相反。", "购买": "无关：购买是付钱取得东西，与掩饰没有反义关系。", "答应": "无关：答应是同意，与掩饰没有反义关系。", "旅行": "无关：旅行是出门游览，与掩饰没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "掩饰是盖住不让别人看出来。", "primary_collocate": null, "pronunciation": "yǎn shì", "ipa": "jɛn˨˩˦ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他想掩饰自己的紧张。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着掩饰了心里的难过。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低下头，想掩饰自己的窘迫。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把错误掩饰起来了。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话太快，是为了掩饰害怕。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都看出来了，他在掩饰什么。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想掩饰心里的失望，可是大家都看到了。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用帽子掩饰了乱头发。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种紧张很难掩饰。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别掩饰了，我知道你不高兴。", "target_word": "掩饰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掩饰了", "label": "体标（了）"}, {"form": "掩饰着", "label": "体标（着）"}, {"form": "掩饰过", "label": "体标（过）"}, {"form": "掩飾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把某种样子或情绪盖住，不让别人看出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰（yǎnshì）指盖住情绪或样子，不让别人看出来。"}, {"text": "仰视", "is_correct": false, "explanation": "仰视（yǎngshì）与掩饰的第一个音节韵母不同（yǎng 是 ang，yǎn 是 an），意思是抬头看。"}, {"text": "厌世", "is_correct": false, "explanation": "厌世（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是厌恶世事。"}, {"text": "艳事", "is_correct": false, "explanation": "艳事（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是风流韵事。"}], "explanations": {"掩饰": "正确：掩饰（yǎnshì）指盖住情绪或样子，不让别人看出来。", "仰视": "仰视（yǎngshì）与掩饰的第一个音节韵母不同（yǎng 是 ang，yǎn 是 an），意思是抬头看。", "厌世": "厌世（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是厌恶世事。", "艳事": "艳事（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是风流韵事。"}, "sentence_index": null, "correct_answer": "掩饰"}, "level_3": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰表示盖住情绪，不让别人看出来，与“想……自己的紧张”的语境相合。"}, {"text": "欺骗", "is_correct": false, "explanation": "搭配：“欺骗”的对象通常是人，不能直接带“紧张”作宾语。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示数量变多，“想增加自己的紧张”与常理相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是客人或人，不能说“欢迎自己的紧张”。"}], "explanations": {"掩饰": "正确：掩饰表示盖住情绪，不让别人看出来，与“想……自己的紧张”的语境相合。", "欺骗": "搭配：“欺骗”的对象通常是人，不能直接带“紧张”作宾语。", "增加": "语义：“增加”表示数量变多，“想增加自己的紧张”与常理相反。", "欢迎": "搭配：“欢迎”的对象是客人或人，不能说“欢迎自己的紧张”。"}, "sentence_index": 0, "correct_answer": "掩饰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雪掩饰了整个村庄。", "explanation": "这里应该用〈覆盖〉。掩饰指盖住情绪或样子，不让别人看出来；大雪盖住村庄要用覆盖。"}, {"text": "他把钱掩饰在床底下。", "explanation": "这里应该用〈隐藏〉。掩饰用于情绪或样子，藏东西要用隐藏。"}, {"text": "他把钥匙掩饰在书包里。", "explanation": "这里应该用〈藏〉。掩饰指盖住情绪或样子、不让人看出；把钥匙藏进书包要用藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰（yǎnshì）指盖住情绪或样子，不让别人看出来。"}, {"text": "验视", "is_correct": false, "explanation": "验视（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是检查察看。"}, {"text": "严实", "is_correct": false, "explanation": "严实（yánshi）与掩饰的第一个音节声调不同（yán 是第二声，yǎn 是第三声），意思是严密、紧密。"}, {"text": "显示", "is_correct": false, "explanation": "显示（xiǎnshì）与掩饰的声母不同（x 与 y），意思是表现出来让人看到。"}], "explanations": {"掩饰": "正确：掩饰（yǎnshì）指盖住情绪或样子，不让别人看出来。", "验视": "验视（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是检查察看。", "严实": "严实（yánshi）与掩饰的第一个音节声调不同（yán 是第二声，yǎn 是第三声），意思是严密、紧密。", "显示": "显示（xiǎnshì）与掩饰的声母不同（x 与 y），意思是表现出来让人看到。"}, "sentence_index": null, "correct_answer": "掩饰"}, "level_3": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：“想掩饰心里的失望，可是大家都看到了”中，掩饰是想盖住失望的动作，前后语义连贯。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是客人或人，不能说“欢迎心里的失望”。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”是从可选之物中选择，“挑选心里的失望”说不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”的对象是值得称赞的人或事，失望不能被赞美。"}], "explanations": {"掩饰": "正确：“想掩饰心里的失望，可是大家都看到了”中，掩饰是想盖住失望的动作，前后语义连贯。", "欢迎": "搭配：“欢迎”的对象是客人或人，不能说“欢迎心里的失望”。", "挑选": "语义：“挑选”是从可选之物中选择，“挑选心里的失望”说不通。", "赞美": "语义：“赞美”的对象是值得称赞的人或事，失望不能被赞美。"}, "sentence_index": 6, "correct_answer": "掩饰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士每天都在掩饰病人。", "explanation": "这里应该用〈保护〉。掩饰只用于盖住情绪或样子，不能用来照顾或防护病人。"}, {"text": "窗帘掩饰了阳光。", "explanation": "这里应该用〈遮挡〉。掩饰指盖住情绪或样子；窗帘挡住阳光要用遮挡。"}, {"text": "灯光掩饰了整个房间。", "explanation": "这里应该用〈照亮〉。掩饰不用于光线照明；灯光让房间变亮要用照亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她努力掩饰起来自己的慌张。", "corrected_sentence": "她努力掩饰住自己的慌张。", "error_description": "错误形式：“掩饰起来自己的慌张”；正确形式：“掩饰住自己的慌张”。结果补语“住”要紧跟动词，后面接宾语；“起来”后不能直接带宾语，应说“掩饰住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很会掩饰了，大家看不出她的情绪。", "corrected_sentence": "她很会掩饰，大家看不出她的情绪。", "error_description": "“很会掩饰”描述的是能力，“掩饰”后不能直接加“了”表示完成；应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
