is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰（yǎnshì）指设法遮盖真实的情况、身份或感情。"}, {"text": "仰视", "is_correct": false, "explanation": "仰视（yǎngshì）与掩饰的第一个音节韵母不同（yǎng 是 ang，yǎn 是 an），意思是抬头看。"}, {"text": "厌世", "is_correct": false, "explanation": "厌世（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是厌恶世事。"}, {"text": "艳事", "is_correct": false, "explanation": "艳事（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是风流韵事。"}], "explanations": {"掩饰": "正确：掩饰（yǎnshì）指设法遮盖真实的情况、身份或感情。", "仰视": "仰视（yǎngshì）与掩饰的第一个音节韵母不同（yǎng 是 ang，yǎn 是 an），意思是抬头看。", "厌世": "厌世（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是厌恶世事。", "艳事": "艳事（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是风流韵事。"}, "sentence_index": null, "correct_answer": "掩饰"}, "level_3": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰表示设法遮盖真实情况，“用谎话掩饰事实”符合语境。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是值得称赞的人或事，“用谎话赞美事实”说不通。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”说的是数量变多，“用谎话增加事实”句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能说批评“事实”。"}], "explanations": {"掩饰": "正确：掩饰表示设法遮盖真实情况，“用谎话掩饰事实”符合语境。", "赞美": "搭配：“赞美”的对象是值得称赞的人或事，“用谎话赞美事实”说不通。", "增加": "语义：“增加”说的是数量变多，“用谎话增加事实”句意不通。", "批评": "搭配：“批评”的对象是人或行为，不能说批评“事实”。"}, "sentence_index": 0, "correct_answer": "掩饰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验掩饰了这个理论的正确性。", "explanation": "这里应该用〈证明〉。掩饰是设法遮盖真实情况，实验证明理论正确要用证明，两者意思相反。"}, {"text": "调查掩饰了他的说法。", "explanation": "这里应该用〈证实〉。调查的目的是查明真相，掩饰是设法遮盖真相，与调查目的相反。"}, {"text": "云层掩饰了太阳。", "explanation": "这里应该用〈遮挡〉。掩饰指设法遮盖真实情况或感情，云挡住太阳要用遮挡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92226, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：掩饰（yǎnshì）指设法遮盖真实的情况、身份或感情。"}, {"text": "验视", "is_correct": false, "explanation": "验视（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是检查察看。"}, {"text": "严实", "is_correct": false, "explanation": "严实（yánshi）与掩饰的第一个音节声调不同（yán 是第二声，yǎn 是第三声），意思是严密、紧密。"}, {"text": "显示", "is_correct": false, "explanation": "显示（xiǎnshì）与掩饰的声母不同（x 与 y），意思是表现出来让人看到。"}], "explanations": {"掩饰": "正确：掩饰（yǎnshì）指设法遮盖真实的情况、身份或感情。", "验视": "验视（yànshì）与掩饰的第一个音节声调不同（yàn 是第四声，yǎn 是第三声），意思是检查察看。", "严实": "严实（yánshi）与掩饰的第一个音节声调不同（yán 是第二声，yǎn 是第三声），意思是严密、紧密。", "显示": "显示（xiǎnshì）与掩饰的声母不同（x 与 y），意思是表现出来让人看到。"}, "sentence_index": null, "correct_answer": "掩饰"}, "level_3": {"options": [{"text": "掩饰", "is_correct": true, "explanation": "正确：“掩饰不住内心的高兴”中，掩饰不住表示盖不住，符合语境。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是走路活动，“散步不住内心的高兴”句意不通。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”不能带可能补语“不住”，“挑选不住内心的高兴”不成立。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是客人或人，不能与“不住内心的高兴”搭配。"}], "explanations": {"掩饰": "正确：“掩饰不住内心的高兴”中，掩饰不住表示盖不住，符合语境。", "散步": "语义：“散步”是走路活动，“散步不住内心的高兴”句意不通。", "挑选": "搭配：“挑选”不能带可能补语“不住”，“挑选不住内心的高兴”不成立。", "欢迎": "搭配：“欢迎”的对象是客人或人，不能与“不住内心的高兴”搭配。"}, "sentence_index": 6, "correct_answer": "掩饰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "质检员掩饰了这批机器。", "explanation": "这里应该用〈检查〉。掩饰是设法遮盖真实情况，质检员的职责是查看机器，不能用掩饰代替检查。"}, {"text": "消防员掩饰了群众。", "explanation": "这里应该用〈保护〉。掩饰指设法遮盖真实情况或感情，不能用来指防护人。"}, {"text": "灯光掩饰了整个房间。", "explanation": "这里应该用〈照亮〉。掩饰不用于光线照明；灯光让房间变亮要用照亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他怎么也掩饰不住了真实的心情。", "corrected_sentence": "他怎么也掩饰不住真实的心情。", "error_description": "“掩饰不住”后面不能在宾语前加“了”，应去掉这个“了”，说“掩饰不住真实的心情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很会掩饰了，大家看不出他的真实感情。", "corrected_sentence": "他很会掩饰，大家看不出他的真实感情。", "error_description": "“很会掩饰”描述的是能力，“掩饰”后不能直接加“了”表示完成；应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "至好是和你最好、最亲近的朋友。", "primary_collocate": null, "pronunciation": "zhì hǎo", "ipa": "tʂɻ̩˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我多年的至好，我们无话不谈。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李明和我是至好，从小一起长大。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把我当作至好，什么事都告诉我。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的几位至好都来参加我的婚礼了。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我们仍然是至好。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了一位至好，心里非常难过。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是父亲的至好，常来我们家做客。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有一个无话不谈的至好？", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，他没有一个至好。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和她成了至好，每天一起上班。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "最要好、最亲近的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至好", "is_correct": true, "explanation": "正确：“至好”指最亲近的朋友，与“多年”和“无话不谈”的交情相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“无话不谈”矛盾，不可能是多年的交情。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”与“无话不谈”的亲近关系相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是人，不能用“是……的”来指一段交情。"}], "explanations": {"至好": "正确：“至好”指最亲近的朋友，与“多年”和“无话不谈”的交情相符。", "陌生人": "语义：“陌生人”与“无话不谈”矛盾，不可能是多年的交情。", "敌人": "语义：“敌人”与“无话不谈”的亲近关系相矛盾。", "桌子": "搭配：“桌子”不是人，不能用“是……的”来指一段交情。"}, "sentence_index": 0, "correct_answer": "至好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市遇到一位至好，聊了几句。", "explanation": "这里应该用〈熟人〉。“至好”指交情极深的最亲近的朋友，不能用来指只是认识的人。"}, {"text": "我和他只是至好，见面打个招呼而已。", "explanation": "这里应该用〈点头之交〉。“至好”指交情极深的最亲近的朋友，不能用于只是见面打个招呼、交情很浅的人。"}, {"text": "我在路口问路，一个至好热心地给我指了方向。", "explanation": "这里应该用〈路人〉。“至好”指交情极深的最亲近的朋友，不能用于素不相识、只是偶然相遇的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至好", "is_correct": true, "explanation": "正确：“至好”指交情极深的朋友，与“父亲的”和“常来做客”相符。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”与“常来我们家做客”的关系相矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指不相识的过路人，与“常来我们家做客”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”不是人，不能用来指“父亲的”这样的交情关系。"}], "explanations": {"至好": "正确：“至好”指交情极深的朋友，与“父亲的”和“常来做客”相符。", "仇人": "语义：“仇人”与“常来我们家做客”的关系相矛盾。", "路人": "语义：“路人”指不相识的过路人，与“常来我们家做客”矛盾。", "房子": "搭配：“房子”不是人，不能用来指“父亲的”这样的交情关系。"}, "sentence_index": 6, "correct_answer": "至好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的至好，十年来一直在背后骂我。", "explanation": "这里应该用〈敌人〉。“至好”指交情极深的朋友，不能用于在背后辱骂、与自己为敌的人。"}, {"text": "他是我的至好，我从来没有见过他。", "explanation": "这里应该用〈陌生人〉。“至好”指交情极深的朋友，与“从来没有见过”直接矛盾。"}, {"text": "他是我的至好，二十年前陷害过我。", "explanation": "这里应该用〈仇人〉。“至好”指交情极深的最亲近的朋友，不能用于陷害过自己的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我从小至好，我们无话不谈。", "corrected_sentence": "他是我从小的至好，我们无话不谈。", "error_description": "“至好”前的定语“从小”后要加“的”，应说“从小的至好”，漏掉“的”是错误形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我身边有几至好，每天都见面。", "corrected_sentence": "我身边有几个至好，每天都见面。", "error_description": "“几”后漏了量词“个”，应说“几个至好”，不能直接用“几”加名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "唱（chàng）指发出乐音，与“握”没有反义关系。"}, {"text": "松", "is_correct": true, "explanation": "松（松开）与“握”在“用手紧紧抓住”的义项上构成反义。"}, {"text": "走", "is_correct": false, "explanation": "走（zǒu）指行走，与“握”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写（xiě）指书写，与“握”没有反义关系。"}], "correct_answer": "松", "explanations": {"唱": "唱（chàng）指发出乐音，与“握”没有反义关系。", "松": "松（松开）与“握”在“用手紧紧抓住”的义项上构成反义。", "走": "走（zǒu）指行走，与“握”没有反义关系。", "写": "写（xiě）指书写，与“握”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跳", "is_correct": false, "explanation": "跳（tiào）指跃起，与“握”没有反义关系。"}, {"text": "放", "is_correct": true, "explanation": "放（放开）与“握”在“用手紧紧抓住”的义项上构成反义，指不再抓住。"}, {"text": "笑", "is_correct": false, "explanation": "笑（xiào）指发出笑容，与“握”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读（dú）指看着文字出声或默念，与“握”没有反义关系。"}], "correct_answer": "放", "explanations": {"跳": "跳（tiào）指跃起，与“握”没有反义关系。", "放": "放（放开）与“握”在“用手紧紧抓住”的义项上构成反义，指不再抓住。", "笑": "笑（xiào）指发出笑容，与“握”没有反义关系。", "读": "读（dú）指看着文字出声或默念，与“握”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "握是用手紧紧抓住。", "primary_collocate": null, "pronunciation": "wò", "ipa": "u̯ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "他用右手紧紧握着笔。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子握住了妈妈的手。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她握着一杯热茶，坐在窗边。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请握紧栏杆，车要开了。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他握了握拳头，没有说话。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，手要握紧，不要松开。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我手里握着一把钥匙。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握着方向盘，看着前面的路。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她握紧绳子，慢慢往上爬。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来没握过这么重的东西。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "握着", "label": "持续体"}, {"form": "握了", "label": "完成体"}, {"form": "握过", "label": "经历体"}, {"form": "握握", "label": "重叠"}], "register": "通用", "sense_fingerprint": "用手紧紧抓住东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "握", "is_correct": true, "explanation": "正确答案。wò（第四声）意思是用手紧紧抓住。"}, {"text": "我", "is_correct": false, "explanation": "我（wǒ，第三声）与 wò（第四声）声调不同，意思是“我”。"}, {"text": "窝", "is_correct": false, "explanation": "窝（wō，第一声）与 wò（第四声）声调不同，意思是“鸟窝、巢穴”。"}, {"text": "物", "is_correct": false, "explanation": "物（wù）与 wò 韵母不同（u 与 o），意思是“东西、事物”。"}], "explanations": {"握": "正确答案。wò（第四声）意思是用手紧紧抓住。", "我": "我（wǒ，第三声）与 wò（第四声）声调不同，意思是“我”。", "窝": "窝（wō，第一声）与 wò（第四声）声调不同，意思是“鸟窝、巢穴”。", "物": "物（wù）与 wò 韵母不同（u 与 o），意思是“东西、事物”。"}, "sentence_index": null, "correct_answer": "握"}, "level_3": {"options": [{"text": "松", "is_correct": false, "explanation": "语义：“松”与“紧紧”意思相反，“紧紧松着笔”自相矛盾。"}, {"text": "握", "is_correct": true, "explanation": "正确。“握”表示用手紧紧抓住，与“紧紧”搭配，指握着笔。"}, {"text": "抬", "is_correct": false, "explanation": "搭配：“抬”多用于较重的东西，不说“抬笔”。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要带所写的内容作宾语，不能直接带“笔”。"}], "explanations": {"松": "语义：“松”与“紧紧”意思相反，“紧紧松着笔”自相矛盾。", "握": "正确。“握”表示用手紧紧抓住，与“紧紧”搭配，指握着笔。", "抬": "搭配：“抬”多用于较重的东西，不说“抬笔”。", "写": "配价：“写”需要带所写的内容作宾语，不能直接带“笔”。"}, "sentence_index": 0, "correct_answer": "握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈握着一团晨雾，走过马路。", "explanation": "晨雾无形，不能用手握住，“握”不能这样搭配。"}, {"text": "他握着一缕香气，走进了办公室。", "explanation": "香气无形，不能用手握住，“握”不能这样搭配。"}, {"text": "她握着一阵风，慢慢走回了家。", "explanation": "这里应该用〈迎〉。风无形，不能被手紧紧抓住，“握”不能这样搭配，应说“迎着风”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "握", "is_correct": true, "explanation": "正确答案。wò（第四声）意思是用手紧紧抓住。"}, {"text": "墨", "is_correct": false, "explanation": "墨（mò）与 wò 声母不同（m 与 w），声调相同，意思是“墨水”。"}, {"text": "破", "is_correct": false, "explanation": "破（pò）与 wò 声母不同（p 与 w），声调相同，意思是“破损”。"}, {"text": "误", "is_correct": false, "explanation": "误（wù）与 wò 韵母不同（u 与 o），意思是“耽误、错误”。"}], "explanations": {"握": "正确答案。wò（第四声）意思是用手紧紧抓住。", "墨": "墨（mò）与 wò 声母不同（m 与 w），声调相同，意思是“墨水”。", "破": "破（pò）与 wò 声母不同（p 与 w），声调相同，意思是“破损”。", "误": "误（wù）与 wò 韵母不同（u 与 o），意思是“耽误、错误”。"}, "sentence_index": null, "correct_answer": "握"}, "level_3": {"options": [{"text": "吹", "is_correct": false, "explanation": "搭配：“吹”是用嘴吹气，不能说“手里吹着一把钥匙”。"}, {"text": "握", "is_correct": true, "explanation": "正确。“握”表示用手紧紧抓住，符合“手里握着一把钥匙”的句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢掉，与“手里”拿着的句意相反。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”不能直接带“一把钥匙”这样的具体物品作宾语。"}], "explanations": {"吹": "搭配：“吹”是用嘴吹气，不能说“手里吹着一把钥匙”。", "握": "正确。“握”表示用手紧紧抓住，符合“手里握着一把钥匙”的句意。", "扔": "语义：“扔”表示丢掉，与“手里”拿着的句意相反。", "说": "配价：“说”不能直接带“一把钥匙”这样的具体物品作宾语。"}, "sentence_index": 6, "correct_answer": "握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力握了一下门铃，门马上开了。", "explanation": "这里应该用〈按〉。“握”是用手紧紧抓住，按门铃是用手指压下去，不能用“握”。"}, {"text": "他握着一片云，走出了房间。", "explanation": "这里“握”的对象选错了：云无形，无法用手握住；指拿着东西应用〈拿〉。"}, {"text": "我手里握着一声叹气，久久不肯放手。", "explanation": "叹气是声音，不是东西，不能用手握住，“握”的对象选错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她小心地握了住那只小鸟。", "corrected_sentence": "她小心地握住了那只小鸟。", "error_description": "错误：“握了住”；正确：“握住了”。补语“住”要紧跟动词“握”，“了”放在补语之后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把刀我从没握着过。", "corrected_sentence": "这把刀我从没握过。", "error_description": "错误：“握着过”；正确：“握过”。“过”是经历体标记，应直接跟在动词后，不能再加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
