INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "与人互相握手，表示问候、致意或感谢。", "primary_collocate": null, "pronunciation": "wò", "ipa": "u̯ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "经理笑着握了握我的手。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出手，和我握了一下。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都握着他的手，说谢谢。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师握着我的手，说：“欢迎你。”", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握住医生的手，一直说谢谢。", "target_word": "握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，两个队长互相握了握对方的手。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她握着我的手说：“再见，路上小心。”", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先伸出手，我马上握住了他的手。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们握着手，高兴得说不出话。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷握着客人的手，不愿放开。", "target_word": "握", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "握着", "label": "持续体"}, {"form": "握了", "label": "完成体"}, {"form": "握过", "label": "经历体"}, {"form": "握握", "label": "重叠"}], "register": "通用", "sense_fingerprint": "用手紧紧抓住对方的手，表示问候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92230, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "握", "is_correct": true, "explanation": "正确答案。wò（第四声）意思是用手紧紧抓住，也指握手。"}, {"text": "我", "is_correct": false, "explanation": "我（wǒ，第三声）与 wò（第四声）声调不同，意思是“我”。"}, {"text": "窝", "is_correct": false, "explanation": "窝（wō，第一声）与 wò（第四声）声调不同，意思是“鸟窝”。"}, {"text": "雾", "is_correct": false, "explanation": "雾（wù）与 wò 韵母不同（u 与 o），意思是“雾气”。"}], "explanations": {"握": "正确答案。wò（第四声）意思是用手紧紧抓住，也指握手。", "我": "我（wǒ，第三声）与 wò（第四声）声调不同，意思是“我”。", "窝": "窝（wō，第一声）与 wò（第四声）声调不同，意思是“鸟窝”。", "雾": "雾（wù）与 wò 韵母不同（u 与 o），意思是“雾气”。"}, "sentence_index": null, "correct_answer": "握"}, "level_3": {"options": [{"text": "放", "is_correct": false, "explanation": "语义：“放”表示放置，与握手问候的意思不合。"}, {"text": "握", "is_correct": true, "explanation": "正确。“握了握”是重叠形式，表示握手问候，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“手”搭配表示这种握手的动作。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”不能以“手”作宾语，句子无法成立。"}], "explanations": {"放": "语义：“放”表示放置，与握手问候的意思不合。", "握": "正确。“握了握”是重叠形式，表示握手问候，符合句意。", "吃": "搭配：“吃”不能与“手”搭配表示这种握手的动作。", "写": "配价：“写”不能以“手”作宾语，句子无法成立。"}, "sentence_index": 0, "correct_answer": "握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "见面时，他握了握我的鼻子，表示问候。", "explanation": "握手问候要握对方的手，不能握鼻子，这里“握”的对象选错了。"}, {"text": "老师握了握孩子的头，说：“欢迎你。”", "explanation": "这里应该用〈摸〉。“握”指握手或用手紧紧抓住，摸头是轻轻触碰，不能用“握”。"}, {"text": "老师握着一缕阳光，说：“欢迎你。”", "explanation": "阳光无形，不能用手握住，这里“握”的对象选错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92230, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "握", "is_correct": true, "explanation": "正确答案。wò（第四声）意思是用手紧紧抓住，也指握手。"}, {"text": "墨", "is_correct": false, "explanation": "墨（mò）与 wò 声母不同（m 与 w），声调相同，意思是“墨水”。"}, {"text": "破", "is_correct": false, "explanation": "破（pò）与 wò 声母不同（p 与 w），声调相同，意思是“破损”。"}, {"text": "物", "is_correct": false, "explanation": "物（wù）与 wò 韵母不同（u 与 o），意思是“东西、事物”。"}], "explanations": {"握": "正确答案。wò（第四声）意思是用手紧紧抓住，也指握手。", "墨": "墨（mò）与 wò 声母不同（m 与 w），声调相同，意思是“墨水”。", "破": "破（pò）与 wò 声母不同（p 与 w），声调相同，意思是“破损”。", "物": "物（wù）与 wò 韵母不同（u 与 o），意思是“东西、事物”。"}, "sentence_index": null, "correct_answer": "握"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”表示用牙齿夹住，与温和道别的句意不合。"}, {"text": "握", "is_correct": true, "explanation": "正确。“握着我的手”表示握手道别，符合句意。"}, {"text": "运", "is_correct": false, "explanation": "搭配：“运”多用于货物，不说“运我的手”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢掉，与温和道别的句意相反。"}], "explanations": {"咬": "语义：“咬”表示用牙齿夹住，与温和道别的句意不合。", "握": "正确。“握着我的手”表示握手道别，符合句意。", "运": "搭配：“运”多用于货物，不说“运我的手”。", "扔": "语义：“扔”表示丢掉，与温和道别的句意相反。"}, "sentence_index": 6, "correct_answer": "握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷握着一阵清风，走进了屋里。", "explanation": "清风无形，不能用手握住，“握”不能这样搭配。"}, {"text": "爷爷握着一朵白云，不愿放开。", "explanation": "白云无形，不能用手握住，“握”的对象选错了。"}, {"text": "爷爷握着一个时辰，不愿放开。", "explanation": "时辰是抽象的时间，不能用手握住，应改用〈度过〉，说“度过一个时辰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们第一次见面时，握手过。", "corrected_sentence": "我们第一次见面时，握过手。", "error_description": "错误：“握手过”；正确：“握过手”。“握手”是离合词，“过”要插在“握”和“手”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他见到我，马上伸出手握握了。", "corrected_sentence": "他见到我，马上伸出手握了握。", "error_description": "错误：“握握了”；正确：“握了握”。重叠形式中“了”应放在第一个“握”之后，表示动作完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
