INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西有多长，有多宽，有多大。", "primary_collocate": null, "pronunciation": "chǐ cun", "ipa": "tʂʰɨ˨˩ tsʰuən", "syllable_count": 2, "sentences": [{"text": "这张桌子的尺寸是多少？", "target_word": "尺寸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买衣服以前，我先量了一下尺寸。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子的尺寸太大，放不进车里。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我这块布的尺寸。", "target_word": "尺寸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋的尺寸不对，我穿着太小。", "target_word": "尺寸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门的尺寸要先量好，再买新门。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片的尺寸不一样，放不进同一个相框。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子尺寸正好，刚好放下一本书。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按着尺寸把木板切好了。", "target_word": "尺寸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的尺寸越来越大了。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准尺寸", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西的长、宽、大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尺寸", "is_correct": true, "explanation": "正确。「尺寸」指东西的长、宽、大小，可以用「多少」提问。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「多少」问的是数量，颜色不能用「多少」来提问。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」指人或动物的高度，不能用来说桌子。"}, {"text": "禀赋", "is_correct": false, "explanation": "语域：「禀赋」是书面语，指天生的能力，与桌子不合。"}], "explanations": {"尺寸": "正确。「尺寸」指东西的长、宽、大小，可以用「多少」提问。", "颜色": "搭配：「多少」问的是数量，颜色不能用「多少」来提问。", "身高": "语义：「身高」指人或动物的高度，不能用来说桌子。", "禀赋": "语域：「禀赋」是书面语，指天生的能力，与桌子不合。"}, "sentence_index": 0, "correct_answer": "尺寸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的尺寸是二十公斤。", "explanation": "这里应该用〈重量〉。尺寸指长宽大小，不用公斤计量。"}, {"text": "他的尺寸是三十岁。", "explanation": "这里应该用〈年龄〉。尺寸只指物体的大小，不能用来说人的年龄。"}, {"text": "这块布的尺寸是红色。", "explanation": "这里应该用〈颜色〉。尺寸指大小，不能用来说颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尺寸", "is_correct": true, "explanation": "正确。照片大小不同，才会放不进同一个相框。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」与能否放进相框无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：照片的名字不同，与能否放进相框没有关系。"}, {"text": "风韵", "is_correct": false, "explanation": "语域：「风韵」是书面语，指风度韵味，与照片大小不合。"}], "explanations": {"尺寸": "正确。照片大小不同，才会放不进同一个相框。", "味道": "语义：「味道」与能否放进相框无关。", "名字": "语义：照片的名字不同，与能否放进相框没有关系。", "风韵": "语域：「风韵」是书面语，指风度韵味，与照片大小不合。"}, "sentence_index": 6, "correct_answer": "尺寸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的尺寸跑得很快。", "explanation": "搭配：「跑」用于速度或行进，尺寸不能跑。"}, {"text": "这间房的尺寸很甜。", "explanation": "搭配：「甜」形容味道，尺寸不能是甜的。"}, {"text": "这双鞋的尺寸很聪明。", "explanation": "搭配：「聪明」形容人的智力，尺寸不能聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只合适的尺寸。", "corrected_sentence": "我找到了一个合适的尺寸。", "error_description": "量词错误：「尺寸」的量词应是「个」，「只」用于动物等，不能用于尺寸。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台手机的尺寸变了大。", "corrected_sentence": "这台手机的尺寸变大了。", "error_description": "「变了大」错误，应说「变大了」。「了」应放在动补结构之后，不能插在「变」和「大」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
