INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "长短、大小的度数。", "primary_collocate": null, "pronunciation": "chǐ cun", "ipa": "tʂʰɨ˨˩ tsʰuən", "syllable_count": 2, "sentences": [{"text": "做衣服要先知道身体的尺寸。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张画的尺寸是五十厘米宽，八十厘米长。", "target_word": "尺寸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间的尺寸是三米乘四米。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鞋有很多尺寸，你要哪一个？", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的鞋尺寸很大，店里没有。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "床的尺寸不对，房间放不下。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道自己戒指的尺寸吗？", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上买鞋要看清楚尺寸。", "target_word": "尺寸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子有大小两种尺寸。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗帘的尺寸比窗户小了一点儿。", "target_word": "尺寸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准尺寸", "label": "复合"}], "register": "中性", "sense_fingerprint": "长短大小的具体度数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dde39b2-d898-475e-ae86-85b21cca451a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尺寸", "is_correct": true, "explanation": "正确。做衣服需要知道身体的长宽大小。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「身体的」后接的是可以量的大小，「心情」不能被量。"}, {"text": "方言", "is_correct": false, "explanation": "语义：「方言」是语言的地域变体，与做衣服无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」与做衣服需要的身体数据无关。"}], "explanations": {"尺寸": "正确。做衣服需要知道身体的长宽大小。", "心情": "搭配：「身体的」后接的是可以量的大小，「心情」不能被量。", "方言": "语义：「方言」是语言的地域变体，与做衣服无关。", "名字": "语义：「名字」与做衣服需要的身体数据无关。"}, "sentence_index": 0, "correct_answer": "尺寸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的尺寸是六十公斤。", "explanation": "这里应该用〈体重〉。尺寸指长宽大小，不用公斤计量人的体重。"}, {"text": "她的尺寸是二十五岁。", "explanation": "这里应该用〈年龄〉。尺寸不能用来说人的年龄。"}, {"text": "这碗汤的尺寸很咸。", "explanation": "这里应该用〈味道〉。尺寸没有咸淡，不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尺寸", "is_correct": true, "explanation": "正确。戒指的尺寸指它的大小，问的正是尺寸。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：戒指没有脾气，「脾气」不能用于戒指。"}, {"text": "口味", "is_correct": false, "explanation": "语义：「口味」指食物的味道偏好，与戒指无关。"}, {"text": "芳龄", "is_correct": false, "explanation": "语域：「芳龄」是书面语，用于称呼女性的年龄，不能用于戒指。"}], "explanations": {"尺寸": "正确。戒指的尺寸指它的大小，问的正是尺寸。", "脾气": "搭配：戒指没有脾气，「脾气」不能用于戒指。", "口味": "语义：「口味」指食物的味道偏好，与戒指无关。", "芳龄": "语域：「芳龄」是书面语，用于称呼女性的年龄，不能用于戒指。"}, "sentence_index": 6, "correct_answer": "尺寸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗帘的尺寸生病了。", "explanation": "搭配：「生病」的主语应是人或动物，尺寸不会生病。"}, {"text": "窗帘的尺寸被我吃了一半。", "explanation": "搭配：「吃」的对象是食物，尺寸不能被吃。"}, {"text": "这个窗帘的尺寸很聪明。", "explanation": "搭配：「聪明」形容人，尺寸不能聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鞋是很多尺寸可以选。", "corrected_sentence": "这种鞋有很多尺寸可以选。", "error_description": "「是」错误，应说「有」。表示存在或拥有时要用「有」，不能用「是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想换一只大一点儿的尺寸。", "corrected_sentence": "我想换一个大一点儿的尺寸。", "error_description": "量词错误：「尺寸」应用「个」，「只」用于动物等，不能用于尺寸。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '551cb690-3d3e-48aa-a46f-dedc26c65641') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
