INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街头是大路边上，有很多人走来走去的地方。", "primary_collocate": null, "pronunciation": "jiē tóu", "ipa": "tɕjɛ˥ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "街头有很多人在走路。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的街头特别热闹。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在街头拍照片。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街头有一个老人在唱歌。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，街头的人少了很多。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街头的小吃又好吃又便宜。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在街头看人表演。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上街头的灯都亮了。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在街头买了一杯热茶。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，街头挂满了红灯笼。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "街頭", "label": "繁体"}, {"form": "街头艺人", "label": "复合"}], "register": "中性", "sense_fingerprint": "街头：人来人往的公共街道场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街头", "is_correct": true, "explanation": "正确：街头指街上人来人往的公共场所，符合“有很多人在走路”的句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，人不能在上面走路，“课本有很多人在走路”与常识不符。"}, {"text": "天花板", "is_correct": false, "explanation": "搭配：人走路需要地面，“天花板”不搭配“有很多人在走路”。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：瓶子是容器，不是人可以走动的场所。"}], "explanations": {"街头": "正确：街头指街上人来人往的公共场所，符合“有很多人在走路”的句意。", "课本": "语义：课本是书，人不能在上面走路，“课本有很多人在走路”与常识不符。", "天花板": "搭配：人走路需要地面，“天花板”不搭配“有很多人在走路”。", "瓶子": "语义：瓶子是容器，不是人可以走动的场所。"}, "sentence_index": 0, "correct_answer": "街头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着街头一直走到了公园。", "explanation": "这里应该用〈街道〉。沿着一条路一直走要说“街道”；“街头”指街上人来人往的场所，不指一条路。"}, {"text": "这家超市的街头非常宽敞，货架一直排到门口。", "explanation": "这里应该用〈店内〉。“街头”指街道上人来人往的场所，不指超市内部的空间。"}, {"text": "街头中间有一条白线。", "explanation": "这里应该用〈马路〉。“街头”指人群聚集的街道场所，不指有中线和白线的道路；说路面标线要用“马路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街头", "is_correct": true, "explanation": "正确：街头是街上人来人往的地方，孩子们可以在那里看人表演，符合句意。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，不是人可以聚集看表演的场所。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，孩子们不能在里面看人表演。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：看表演需要可以聚集观众的地面场所，“在天空看人表演”搭配不通。"}], "explanations": {"街头": "正确：街头是街上人来人往的地方，孩子们可以在那里看人表演，符合句意。", "字典": "语义：字典是书，不是人可以聚集看表演的场所。", "冰箱": "语义：冰箱是电器，孩子们不能在里面看人表演。", "天空": "搭配：看表演需要可以聚集观众的地面场所，“在天空看人表演”搭配不通。"}, "sentence_index": 6, "correct_answer": "街头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的街头有一张床和一个衣柜。", "explanation": "这里应该用〈卧室〉。“街头”指街上人来人往的地方，不指家里睡觉的房间。"}, {"text": "这本书的街头写着作者的名字。", "explanation": "这里应该用〈封面〉。“街头”指街道上的公共场所，不指书的外面。"}, {"text": "他把杯子放在桌子的街头。", "explanation": "这里应该用〈边上〉。“街头”只指街上的地方，不能说桌子的某个位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常在街头的吃饭。", "corrected_sentence": "他常常在街头吃饭。", "error_description": "错误：动词“吃饭”前多加了“的”。“在街头”是介词短语，后面应直接接动词，说“在街头吃饭”，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在街头里拉琴。", "corrected_sentence": "他站在街头拉琴。", "error_description": "错误：“街头”后多加了“里”。“街头”是地点名词，直接放在“在”后面，不需要加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
