INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街道上；街边靠近路口的地方。", "primary_collocate": null, "pronunciation": "jiē tóu", "ipa": "tɕjɛ˥ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "我们在街头的红绿灯下见面。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在街头等车。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街头有一家小花店。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往前走到街头，向左转。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，街头那家面包店开门了。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在街头的邮筒旁寄信。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车停在街头，不能再往前开了。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街头的红灯亮了，大家都停下来。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在街头等着我放学。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了街头，你就能看见地铁站。", "target_word": "街头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "街頭", "label": "繁体"}, {"form": "街头艺人", "label": "复合"}], "register": "中性", "sense_fingerprint": "街头：街边靠近路口的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街头", "is_correct": true, "explanation": "正确：街头指路口边的位置，红绿灯就设在这里，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海上没有红绿灯，“大海的红绿灯”与常识不符。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：红绿灯设在道路交叉口，不设在草地上，“草地的红绿灯”搭配不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是设置红绿灯的地方。"}], "explanations": {"街头": "正确：街头指路口边的位置，红绿灯就设在这里，符合句意。", "大海": "语义：大海上没有红绿灯，“大海的红绿灯”与常识不符。", "草地": "搭配：红绿灯设在道路交叉口，不设在草地上，“草地的红绿灯”搭配不通。", "书包": "语义：书包是装东西的袋子，不是设置红绿灯的地方。"}, "sentence_index": 0, "correct_answer": "街头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他沿着街头走了很远。", "explanation": "这里应该用〈街道〉。沿着一条路走要说“街道”；“街头”指一个地点，不指可以沿着走的路。"}, {"text": "街头从东到西有五公里长。", "explanation": "这里应该用〈街道〉。“街头”指街边靠近路口的地方，不指可以量长度的整条道路；说道路有多长要用“街道”。"}, {"text": "街头中间有一个分隔带。", "explanation": "这里应该用〈马路〉。分隔带设在道路中间，说路中间的分隔带要用“马路”；“街头”指路口边的位置，不指整条道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街头", "is_correct": true, "explanation": "正确：街头指街边靠近路口的地方，车可以停在那里，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：车不能停在天空中，句意不通。"}, {"text": "床底", "is_correct": false, "explanation": "语义：车不能停在床底下，与“不能再往前开”的句意无关。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：停车的地方应是道路或停车场，“停在书桌”搭配不通。"}], "explanations": {"街头": "正确：街头指街边靠近路口的地方，车可以停在那里，符合句意。", "天空": "语义：车不能停在天空中，句意不通。", "床底": "语义：车不能停在床底下，与“不能再往前开”的句意无关。", "书桌": "搭配：停车的地方应是道路或停车场，“停在书桌”搭配不通。"}, "sentence_index": 6, "correct_answer": "街头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在信的街头写上了日期。", "explanation": "这里应该用〈开头〉。“街头”指街边靠近路口的地方，不指信的开始部分。"}, {"text": "我们坐在教室的街头。", "explanation": "这里应该用〈后面〉。“街头”只指街上的位置，不能用于教室里。"}, {"text": "她把花放在窗台的街头。", "explanation": "这里应该用〈角上〉。“街头”指街边路口的位置，不指窗台的某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条街头的那家小店关门了。", "corrected_sentence": "街头的那家小店关门了。", "error_description": "错误：“街头”前多加了量词“一条”。“街头”是地点，不用“条”（“条”用于街道、河流等狭长的事物），直接说“街头的那家小店”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在街头里的书店门口等朋友。", "corrected_sentence": "他在街头的书店门口等朋友。", "error_description": "错误：“街头”后多加了“里”。“街头”后应直接用“的”修饰“书店门口”，不能加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
