INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "揭开是把盖着的东西拿开。", "primary_collocate": null, "pronunciation": "jiē kāi", "ipa": "tɕjɛ˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "他揭开锅盖，看了看汤。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把盘子上的布揭开了。", "target_word": "揭开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你揭开这张纸看看。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她轻轻揭开了箱子的盖子。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我揭开杯盖，喝了一口茶。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子揭开毯子，跳下了床。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把桌子上的布揭开，下面是一本书。", "target_word": "揭开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生揭开伤口上的纱布，检查了一下。", "target_word": "揭开", "complexity_tier": "T3", "furigana": "yī shēng jiē kāi shāng kǒu shàng de shā bù jiǎn chá le yí xià", "sentence_source": "generated"}, {"text": "她站在桌前，揭开了蛋糕盒的盖子。", "target_word": "揭开", "complexity_tier": "T3", "furigana": "tā zhàn zài zhuō qián jiē kāi le dàn gāo hé de gài zi", "sentence_source": "generated"}, {"text": "你先揭开瓶盖，再倒水。", "target_word": "揭开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "揭开了", "label": "了体标"}, {"form": "揭开过", "label": "过体标"}, {"form": "揭開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "揭开：把盖着的东西拿开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揭开", "is_correct": true, "explanation": "揭开：把锅盖拿开，才能看到汤，与句意相符。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”会毁坏锅盖，与后文平常地“看了看汤”不符。"}, {"text": "启封", "is_correct": false, "explanation": "搭配：“启封”多用于信件、酒坛，不用于锅盖。"}, {"text": "钉上", "is_correct": false, "explanation": "语义：锅盖被钉住就拿不开，也看不到汤，与“看了看汤”矛盾。"}], "explanations": {"揭开": "揭开：把锅盖拿开，才能看到汤，与句意相符。", "打碎": "语义：“打碎”会毁坏锅盖，与后文平常地“看了看汤”不符。", "启封": "搭配：“启封”多用于信件、酒坛，不用于锅盖。", "钉上": "语义：锅盖被钉住就拿不开，也看不到汤，与“看了看汤”矛盾。"}, "sentence_index": 0, "correct_answer": "揭开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她轻轻揭开了那扇柜门。", "explanation": "这里应该用〈打开〉。柜门是开合的，不是覆盖物。"}, {"text": "她揭开了耳环，放进盒子里。", "explanation": "这里应该用〈摘下〉。耳环戴在身上，不是覆盖物。"}, {"text": "他揭开了外套的拉链，拿出了钱包。", "explanation": "这里应该用〈拉开〉。拉链是拉动开合的，不是盖在上面的东西；揭开指把盖着的东西拿开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揭开", "is_correct": true, "explanation": "揭开：把布拿开，露出下面的书，与句意相符。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”会毁坏布，下面露出书的情形无法成立。"}, {"text": "绣上", "is_correct": false, "explanation": "搭配：“绣上”指在布上绣花，不能表示把布拿开。"}, {"text": "剪碎", "is_correct": false, "explanation": "语义：“剪碎”会把布剪成碎片，与“下面是一本书”的情形不符。"}], "explanations": {"揭开": "揭开：把布拿开，露出下面的书，与句意相符。", "撕碎": "语义：“撕碎”会毁坏布，下面露出书的情形无法成立。", "绣上": "搭配：“绣上”指在布上绣花，不能表示把布拿开。", "剪碎": "语义：“剪碎”会把布剪成碎片，与“下面是一本书”的情形不符。"}, "sentence_index": 6, "correct_answer": "揭开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他揭开了抽屉，找到了钥匙。", "explanation": "这里应该用〈拉开〉。抽屉是推拉开合的，不是覆盖物。"}, {"text": "她揭开了扇子，轻轻扇了几下。", "explanation": "这里应该用〈打开〉。扇子是折叠后展开的，不是盖着的东西，不能说揭开。"}, {"text": "他揭开了鞋带，又系了一次。", "explanation": "这里应该用〈解开〉。鞋带、绳结用“解开”，不说揭开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸揭开了了碗上的保鲜膜。", "corrected_sentence": "爸爸揭开了碗上的保鲜膜。", "error_description": "错误形式是“揭开了了”，在“了”后又重复了一个“了”；“揭开”后只需一个“了”，正确形式是“揭开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他揭开了过那个饭盒。", "corrected_sentence": "他揭开过那个饭盒。", "error_description": "错误在于同时使用“了”和“过”。“揭开”后表示曾经做过时只用“过”，不能再加“了”；正确形式是“揭开过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
