INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国共产党市级委员会的简称。", "primary_collocate": null, "pronunciation": "shì wěi", "ipa": "ʂʐ̩˥˩ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市委今天开会，讨论城市发展。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委决定今年在郊区修一条新地铁。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的市委领导昨天来学校看望老师。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市委工作，每天都很忙。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委发出通知，要求大家注意安全。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委的干部下乡，了解农民的生活。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委召开会议，决定修建新的公园。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委大楼在市中心，旁边就是市政府。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市委最近提出了一个新计划，要改善空气质量。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是市委的工作人员，常常写报告。", "target_word": "市委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市委书记", "label": "复合"}, {"form": "市委机关", "label": "复合"}], "register": "正式", "sense_fingerprint": "中国共产党在市一级的领导机构，常说市委开会、市委决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791cf11e-78f7-4ed5-8644-accd5f3a7eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市委", "is_correct": true, "explanation": "正确答案：市委（shì wěi），指市一级的中国共产党委员会。"}, {"text": "侍卫", "is_correct": false, "explanation": "第二音节声调不同（wèi，第四声），意思是护卫的人员，不是党的机构。"}, {"text": "示威", "is_correct": false, "explanation": "第二音节声调不同（wēi，第一声），意思是公开表达意见或抗议。"}, {"text": "视为", "is_correct": false, "explanation": "第二音节声调不同（wéi，第二声），意思是“看作”，不是党的机构。"}], "explanations": {"市委": "正确答案：市委（shì wěi），指市一级的中国共产党委员会。", "侍卫": "第二音节声调不同（wèi，第四声），意思是护卫的人员，不是党的机构。", "示威": "第二音节声调不同（wēi，第一声），意思是公开表达意见或抗议。", "视为": "第二音节声调不同（wéi，第二声），意思是“看作”，不是党的机构。"}, "sentence_index": null, "correct_answer": "市委"}, "level_3": {"options": [{"text": "市委", "is_correct": true, "explanation": "正确：市委是市级党委机构，能开会、讨论城市发展。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能开会，也不能讨论城市发展。"}, {"text": "苹果", "is_correct": false, "explanation": "配价：“开会”的主语须是团体或人，苹果不能作主语。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能开会讨论城市发展。"}], "explanations": {"市委": "正确：市委是市级党委机构，能开会、讨论城市发展。", "小狗": "语义：小狗不能开会，也不能讨论城市发展。", "苹果": "配价：“开会”的主语须是团体或人，苹果不能作主语。", "课本": "语义：课本是书，不能开会讨论城市发展。"}, "sentence_index": 0, "correct_answer": "市委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市委决定在全省推广这个新政策。", "explanation": "这里应该用〈省委〉。市委只管本市，在全省推广新政策要由省委决定。"}, {"text": "市委通过了新的环境保护法。", "explanation": "这里应该用〈人大常委会〉。市委是党的领导机构，不通过法律；法律由人大常委会通过。"}, {"text": "市委决定全国都要延长春节假期。", "explanation": "这里应该用〈中央〉。市委只管本市，全国性的假期安排由中央决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92238, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市委", "is_correct": true, "explanation": "正确答案：市委（shì wěi），指市一级的中国共产党委员会。"}, {"text": "实为", "is_correct": false, "explanation": "两个音节声调都不同（shí wéi，第二声），意思是“实际上是”，不是党的机构。"}, {"text": "施威", "is_correct": false, "explanation": "两个音节声调都不同（shī wēi，第一声），意思是“显示威风”，不是党的机构。"}, {"text": "世卫", "is_correct": false, "explanation": "第二音节声调不同（wèi，第四声），是“世界卫生组织”的简称，不是党的机构。"}], "explanations": {"市委": "正确答案：市委（shì wěi），指市一级的中国共产党委员会。", "实为": "两个音节声调都不同（shí wéi，第二声），意思是“实际上是”，不是党的机构。", "施威": "两个音节声调都不同（shī wēi，第一声），意思是“显示威风”，不是党的机构。", "世卫": "第二音节声调不同（wèi，第四声），是“世界卫生组织”的简称，不是党的机构。"}, "sentence_index": null, "correct_answer": "市委"}, "level_3": {"options": [{"text": "市委", "is_correct": true, "explanation": "正确：市委是团体，能召开会议、决定修建公园。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶不能召开会议，也不能决定修建公园。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“召开会议”的主语须是团体或人，椅子不能作主语。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不能召开会议或决定事情。"}], "explanations": {"市委": "正确：市委是团体，能召开会议、决定修建公园。", "蝴蝶": "语义：蝴蝶不能召开会议，也不能决定修建公园。", "椅子": "配价：“召开会议”的主语须是团体或人，椅子不能作主语。", "香蕉": "语义：香蕉不能召开会议或决定事情。"}, "sentence_index": 6, "correct_answer": "市委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "城里新成立了一只市委。", "explanation": "这里应该用〈个〉。市委是机构，量词用“个”；“只”多用于动物。"}, {"text": "这个区里有三条市委，管着全区的事。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，市委是机构，不说“三条市委”。"}, {"text": "市里新增了一台市委。", "explanation": "这里应该用〈个〉。“台”用于机器，市委是机构，不能用“台”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市只有一台市委。", "corrected_sentence": "这个城市只有一个市委。", "error_description": "量词错误：市委是机构，应用量词“个”；“台”用于机器，不能说“一台市委”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市委们发出了新的通知。", "corrected_sentence": "市委发出了新的通知。", "error_description": "错误在于“市委们”：市委是一个机构的名称，不能加“们”表示复数，应说“市委发出了新的通知”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71fc67ae-d9a9-44af-ab21-b5bd30195a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
