INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对政治或其他事物发表的意见和主张。", "primary_collocate": null, "pronunciation": "yán lùn", "ipa": "jɛn˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "这位官员公开发表的言论引起了社会的关注。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上发表了很多关于这件事的言论。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人发表不负责任的言论，政府马上回应了。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的政治言论受到了很多人的批评。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统的言论在电视上播出后，引起了讨论。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸经常刊登反对政府的言论。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者说，他们不能随便篡改别人的言论。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许发表伤害国家的言论。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会上有不同的言论，大家讨论得很热烈。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的言论代表了很多普通人的意见。", "target_word": "言论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "言论自由", "label": "复合"}], "register": "书面语", "sense_fingerprint": "对政治或社会事务公开发表的意见和主张，常见于报纸、网络和会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言论", "is_correct": true, "explanation": "言论指对政治或社会事务发表的意见，可以“引起关注”，是正确答案。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”是做菜用的，与官员引起社会关注无关，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是体态特征，一般不会因此引起社会的关注。"}, {"text": "课程", "is_correct": false, "explanation": "搭配：“官员的课程”这一搭配不通，句子语义不符。"}], "explanations": {"言论": "言论指对政治或社会事务发表的意见，可以“引起关注”，是正确答案。", "菜谱": "语义：“菜谱”是做菜用的，与官员引起社会关注无关，句子不通。", "身高": "体貌：“身高”是体态特征，一般不会因此引起社会的关注。", "课程": "搭配：“官员的课程”这一搭配不通，句子语义不符。"}, "sentence_index": 0, "correct_answer": "言论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在舞台上唱了一段精彩的言论，观众都鼓掌了。", "explanation": "这里应该用〈歌〉。言论指发表的意见，不能用“唱”，唱一段要用〈歌〉。"}, {"text": "城市里发生了一起严重的言论。", "explanation": "这里应该用〈事故〉。言论是发表的意见，不会“发生”，发生的严重情况要用〈事故〉。"}, {"text": "公司推出了一个新的言论，受到了欢迎。", "explanation": "这里应该用〈项目〉。言论是发表的意见，不能推出，公司推出的新事物要用〈项目〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言论", "is_correct": true, "explanation": "言论是可以被“篡改”的内容，与“篡改别人的”相符，是正确答案。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“篡改”的对象是文字、数据、话语，不能篡改笑声。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“篡改”不能用于味道这类感受，句子不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是动作留下的声音，与“篡改别人的”的含义无关。"}], "explanations": {"言论": "言论是可以被“篡改”的内容，与“篡改别人的”相符，是正确答案。", "笑声": "搭配：“篡改”的对象是文字、数据、话语，不能篡改笑声。", "味道": "搭配：“篡改”不能用于味道这类感受，句子不通。", "脚步": "语义：“脚步”是动作留下的声音，与“篡改别人的”的含义无关。"}, "sentence_index": 6, "correct_answer": "言论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校发出了一份言论，同学们都很关心。", "explanation": "这里应该用〈通知〉。学校发出的是通知，言论是发表的意见，不能说“发出一份言论”。"}, {"text": "他在会上表明了言论，态度很坚决。", "explanation": "这里应该用〈立场〉。〈表明〉搭配〈立场〉，言论是说出来的，不能用“表明”。"}, {"text": "他持有很多这家公司的言论。", "explanation": "这里应该用〈股票〉。言论是发表的意见，不能被持有，持有公司的应是〈股票〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他公开发表了一座言论，引起了热烈的讨论。", "corrected_sentence": "他公开发表了一种言论，引起了热烈的讨论。", "error_description": "量词错误：“言论”应用“种”，“座”用于山、房屋等大型建筑，不能用于言论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位记者发表了一些言论们，引起了社会的讨论。", "corrected_sentence": "这位记者发表了一些言论，引起了社会的讨论。", "error_description": "错误在“言论们”：“言论”是抽象名词，不能加“们”表示复数，应直接说“一些言论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
