INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改装是把东西改成别的样子。", "primary_collocate": null, "pronunciation": "gǎi zhuāng", "ipa": "kaɪ˨˩˦ ʈʂwaŋ˥", "syllable_count": 2, "sentences": [{"text": "他想把旧房子改装成一间小店。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把旧车库改装成了书房。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算改装这间厨房。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了很多钱改装那辆车。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店去年改装过一次。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想把教室改装成音乐室。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在改装一条旧船。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说这个旧柜子可以改装一下。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧箱子改装成了小桌子。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把阳台改装成小花园。", "target_word": "改装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改装了", "label": "体标"}, {"form": "改装过", "label": "体标"}, {"form": "改装车", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西改成别的样子或用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改装", "is_correct": true, "explanation": "正确答案：“改装”指把旧房子改成另一种用途，符合“改成一间小店”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除是拆掉，房子拆掉以后就不能再改成小店。"}, {"text": "研究", "is_correct": false, "explanation": "搭配：“研究”的对象是问题或道理，不能说“把房子研究成小店”。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，不能带“把”字宾语，也不能接“成”。"}], "explanations": {"改装": "正确答案：“改装”指把旧房子改成另一种用途，符合“改成一间小店”。", "拆除": "语义：拆除是拆掉，房子拆掉以后就不能再改成小店。", "研究": "搭配：“研究”的对象是问题或道理，不能说“把房子研究成小店”。", "出生": "配价：“出生”是不及物动词，不能带“把”字宾语，也不能接“成”。"}, "sentence_index": 0, "correct_answer": "改装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了很多时间改装自己的性格。", "explanation": "这里应该用〈改造〉。改装指给器物换装置或改变外形，改变人的性格要用改造。"}, {"text": "这件事彻底改装了他的想法。", "explanation": "这里应该用〈改变〉。改装只用于器物或建筑，不能用于人的想法。"}, {"text": "他把合同的条款改装了两处。", "explanation": "这里应该用〈修改〉。改装用于器物或建筑的装置和外形，合同条款要用修改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改装", "is_correct": true, "explanation": "正确答案：“改装”指改造船只，符合“他们正在改装一条旧船”。"}, {"text": "建造", "is_correct": false, "explanation": "语义：建造出来的是新船，与“旧船”矛盾。"}, {"text": "装载", "is_correct": false, "explanation": "搭配：“装载”的对象是货物，不能说“装载一条船”。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”用于活动或会议，不能用于船只。"}], "explanations": {"改装": "正确答案：“改装”指改造船只，符合“他们正在改装一条旧船”。", "建造": "语义：建造出来的是新船，与“旧船”矛盾。", "装载": "搭配：“装载”的对象是货物，不能说“装载一条船”。", "举办": "搭配：“举办”用于活动或会议，不能用于船只。"}, "sentence_index": 6, "correct_answer": "改装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说被改装成了电影。", "explanation": "这里应该用〈改编〉。作品改成另一种形式要用改编，改装只用于器物。"}, {"text": "政府努力改装居民的生活条件。", "explanation": "这里应该用〈改善〉。改装指改换器物的装置或样子，生活条件要用改善。"}, {"text": "他改装了文章的结构。", "explanation": "这里应该用〈改动〉。改装用于器物，文章的结构要用改动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把老房子改装了成餐厅。", "corrected_sentence": "他们把老房子改装成了餐厅。", "error_description": "错误：“了”插在动词和结果补语“成”之间，写成了“改装了成”。正确：“改装成了”，“了”应放在补语“成”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们准备把仓库改装到工作室。", "corrected_sentence": "我们准备把仓库改装成工作室。", "error_description": "错误：表示“变成”的结果补语要用“成”，不能用“到”。正确：“改装成工作室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
