INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "疑问兼反问用语，表示无人知晓或事情出乎意料。", "primary_collocate": null, "pronunciation": "shéi zhī dào", "ipa": "ʂei˧˥ ʈʂɻ̩˥ tɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "谁知道他去了哪儿呢？", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事谁知道呢，没人说得清。", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走了以后，谁知道会怎么样？", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我本来想去，谁知道临时有事了。", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁知道明年的事呢？", "target_word": "谁知道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那家店看起来很小，谁知道里面特别大。", "target_word": "谁知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚睡下，谁知道电话又响了。", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上会遇到什么，谁知道呢？", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给他打了电话，谁知道关机了。", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁知道将来会发生什么事？", "target_word": "谁知道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "反问无人知晓；引出出乎意料的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁料", "is_correct": false, "explanation": "语义：“谁料”引出出乎意料的结果，不能用来带出“他去了哪儿”这个疑问。"}, {"text": "谁知道", "is_correct": true, "explanation": "正确：表示无人知晓，用来引出对他去向的疑问。"}, {"text": "岂料", "is_correct": false, "explanation": "语域：“岂料”偏书面，口语中不用；且同样不能带出这个疑问。"}, {"text": "谁不知道", "is_correct": false, "explanation": "语义：“谁不知道”是反问，表示人人都知道，与询问无人知晓的意思相反。"}], "explanations": {"谁料": "语义：“谁料”引出出乎意料的结果，不能用来带出“他去了哪儿”这个疑问。", "谁知道": "正确：表示无人知晓，用来引出对他去向的疑问。", "岂料": "语域：“岂料”偏书面，口语中不用；且同样不能带出这个疑问。", "谁不知道": "语义：“谁不知道”是反问，表示人人都知道，与询问无人知晓的意思相反。"}, "sentence_index": 0, "correct_answer": "谁知道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早就算到会下雨，谁知道下雨了。", "explanation": "这里应该用〈果然〉。谁知道表示没想到，前面说“早就算到”，应用“果然”。"}, {"text": "大家都知道他去了北京，谁知道他去了哪儿呢？", "explanation": "这里不能用“谁知道”。它表示无人知晓，和前面的“大家都知道”矛盾。"}, {"text": "我天天拨他的电话，谁知道他的号码。", "explanation": "这里不能用“谁知道”。它表示无人知晓，与“天天拨他的电话”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，电话又响了不值得庆幸，与刚睡下后的意外语境不合。"}, {"text": "谁知道", "is_correct": true, "explanation": "正确：表示没想到，引出刚睡下后电话又响的意外情况。"}, {"text": "反正", "is_correct": false, "explanation": "语义：“反正”表示无论如何结果不变，与刚睡下后的意外不合。"}, {"text": "所幸", "is_correct": false, "explanation": "语域：“所幸”偏书面，口语句子中不合适；且庆幸的意思与语境不符。"}], "explanations": {"幸好": "语义：“幸好”表示庆幸，电话又响了不值得庆幸，与刚睡下后的意外语境不合。", "谁知道": "正确：表示没想到，引出刚睡下后电话又响的意外情况。", "反正": "语义：“反正”表示无论如何结果不变，与刚睡下后的意外不合。", "所幸": "语域：“所幸”偏书面，口语句子中不合适；且庆幸的意思与语境不符。"}, "sentence_index": 6, "correct_answer": "谁知道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的家就在这儿，谁知道他的家在哪儿。", "explanation": "这里不能用“谁知道”。它表示无人知晓，与“就在这儿”矛盾，应直接说“他的家就在这儿”。"}, {"text": "这件事大家都清楚，谁知道这件事。", "explanation": "这里不能用“谁知道”。它表示无人知晓，与“大家都清楚”矛盾。"}, {"text": "我每天都给妈妈打电话，谁知道她的号码。", "explanation": "这里不能用“谁知道”。它表示无人知晓，与“每天都给妈妈打电话”矛盾，应直接说“我知道她的号码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谁知道的他明天去不去呢？", "corrected_sentence": "谁知道他明天去不去呢？", "error_description": "错误：“谁知道的他”。正确：“谁知道他”。“谁知道”后面不能加“的”，直接接句子的主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚进门，谁知道了电话又响了。", "corrected_sentence": "我刚进门，谁知道电话又响了。", "error_description": "错误：“谁知道了”。正确：“谁知道”。“谁知道”后面不加“了”，直接接后面的分句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
