INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究、讨论某一问题的专门文章。", "primary_collocate": null, "pronunciation": "lùn wén", "ipa": "lwən˥˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "他在杂志上发表了一篇论文。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇论文讨论的是空气污染问题。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先读这篇论文。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的论文得到了很多人的好评。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授写过很多论文。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文的题目要简单清楚。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了写论文，去了很多图书馆。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇论文里有不少新的看法。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在看一篇关于环保的论文。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把论文发给了几位专家。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}, {"form": "学术论文", "label": "复合"}, {"form": "毕业论文", "label": "复合"}, {"form": "論文", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究、讨论某一问题的专门文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "论文", "is_correct": true, "explanation": "正确：“论文”是研究、讨论问题的专门文章，可以在杂志上发表。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能被发表，与“在杂志上发表”的意思相矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”不是可以发表的文字作品，与“在杂志上发表”矛盾。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“饭菜”不能用“发表了一篇”来计量，搭配不当。"}], "explanations": {"论文": "正确：“论文”是研究、讨论问题的专门文章，可以在杂志上发表。", "石头": "语义：“石头”不能被发表，与“在杂志上发表”的意思相矛盾。", "花园": "语义：“花园”不是可以发表的文字作品，与“在杂志上发表”矛盾。", "饭菜": "搭配：“饭菜”不能用“发表了一篇”来计量，搭配不当。"}, "sentence_index": 0, "correct_answer": "论文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一篇论文，讲了一个侦探破案的故事。", "explanation": "这里应该用〈小说〉。“论文”指研究、讨论问题的专门文章，不能用来讲故事。"}, {"text": "她写了一篇论文，抒发了对故乡的思念。", "explanation": "这里应该用〈散文〉。“论文”指研究、讨论问题的专门文章，不是抒发感情的文学作品。"}, {"text": "我给远方的朋友写了一篇论文，告诉他最近的生活。", "explanation": "这里应该用〈信〉。“论文”指研究、讨论问题的专门文章，不能用来写给朋友的私人信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "论文", "is_correct": true, "explanation": "正确：“写论文”是常用搭配，指写研究讨论问题的文章，与去图书馆查资料相符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“写”的对象不能是“面包”，说“为了写面包”搭配不当。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”不能被“写”，与“为了写”搭配不当。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不是可以写的东西，与“为了写”的目的矛盾。"}], "explanations": {"论文": "正确：“写论文”是常用搭配，指写研究讨论问题的文章，与去图书馆查资料相符。", "面包": "搭配：“写”的对象不能是“面包”，说“为了写面包”搭配不当。", "汽车": "搭配：“汽车”不能被“写”，与“为了写”搭配不当。", "椅子": "语义：“椅子”不是可以写的东西，与“为了写”的目的矛盾。"}, "sentence_index": 6, "correct_answer": "论文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上唱了一篇论文，观众很激动。", "explanation": "这里应该用〈歌曲〉。“论文”指研究、讨论问题的专门文章，不能用“唱”来表达。"}, {"text": "他每天晚上都玩论文，玩到很晚才睡。", "explanation": "这里应该用〈游戏〉。“论文”是专门文章，不能用“玩”来搭配。"}, {"text": "他在桌上摆了一些论文，请大家吃。", "explanation": "这里应该用〈饼干〉。“论文”指研究、讨论问题的专门文章，不是可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
