INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了三只论文。", "corrected_sentence": "他写了三篇论文。", "error_description": "量词用错：“论文”应用量词“篇”，“只”用于动物等，不能计量论文，应说“三篇论文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
