INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放话是故意先把话说出去。", "primary_collocate": null, "pronunciation": "fàng huà", "ipa": "faŋ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "他先放话说下个月要搬家。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司还没决定，就先放话说要涨价。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意放话，想看看大家有什么反应。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板放话说明年会招很多新人。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先向朋友放话，说自己要去留学。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队还没比赛，就放话要拿冠军。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放话说周末请大家吃饭，结果没人当真。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前放话，说下周公司有大变动。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校放话说今年会建新图书馆。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上有人放话说这家店要关门了。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放了话", "label": "体标（了）"}, {"form": "放过话", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "故意提前把消息或想法说出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抛弃", "is_correct": false, "explanation": "配价：“抛弃”需带被抛弃的人或事物作宾语，不能直接接“说”引出的内容。"}, {"text": "放话", "is_correct": true, "explanation": "正确。“放话”表示故意先把话说出去，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”表示不让人知道，与“先说出去”的意思相反。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”后面不能接“说”引出的消息内容，搭配不成立。"}], "explanations": {"抛弃": "配价：“抛弃”需带被抛弃的人或事物作宾语，不能直接接“说”引出的内容。", "放话": "正确。“放话”表示故意先把话说出去，符合句意。", "隐瞒": "语义：“隐瞒”表示不让人知道，与“先说出去”的意思相反。", "收拾": "搭配：“收拾”后面不能接“说”引出的消息内容，搭配不成立。"}, "sentence_index": 0, "correct_answer": "放话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一不小心放话，说明年要搬家。", "explanation": "这里应该用〈说漏嘴〉。“放话”指有意先把话说出去，不小心把话说出去应说“说漏嘴”。"}, {"text": "他放话把箱子搬到了门口。", "explanation": "这里“放话”的意思不对：它指有意先把话传出去，不表示搬运东西，搬运应用〈运〉。"}, {"text": "妈妈放话给我买了一台新电脑。", "explanation": "这里应该用〈答应〉。“放话”指有意先把话传出去、表明态度，答应买东西应用“答应”，不能说“放话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保密", "is_correct": false, "explanation": "语义：“保密”表示不让人知道，与“说周末请大家吃饭”的句意矛盾。"}, {"text": "放话", "is_correct": true, "explanation": "正确。“放话”表示故意把话说出去，符合句意。"}, {"text": "鼓掌", "is_correct": false, "explanation": "搭配：“鼓掌”不能带“说”引出的消息内容，搭配不成立。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”表示藏起来不让人知道，与“说出去”的句意相反。"}], "explanations": {"保密": "语义：“保密”表示不让人知道，与“说周末请大家吃饭”的句意矛盾。", "放话": "正确。“放话”表示故意把话说出去，符合句意。", "鼓掌": "搭配：“鼓掌”不能带“说”引出的消息内容，搭配不成立。", "隐藏": "语义：“隐藏”表示藏起来不让人知道，与“说出去”的句意相反。"}, "sentence_index": 6, "correct_answer": "放话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府放话，把全城的井盖全都换掉了。", "explanation": "这里“放话”的意思不对：它指有意先把话传出去，不能表示更换井盖，应说〈更换〉。"}, {"text": "他放话把地上的纸捡了起来。", "explanation": "这里“放话”的意思不对：它指有意先把话传出去，不表示捡东西，捡东西应用〈拾〉。"}, {"text": "他是无意中放话的，自己也没想到消息会传出去。", "explanation": "这里应该用〈说漏嘴〉。“放话”是有意先把话放出去，无意中把消息传出去应说“说漏嘴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很放话说要请大家喝茶。", "corrected_sentence": "他放话说要请大家喝茶。", "error_description": "错误：“很放话”；正确：“放话”。“很”是程度副词，不能直接修饰动词“放话”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前放话过，后来真的搬走了。", "corrected_sentence": "他以前放过话，后来真的搬走了。", "error_description": "错误：“放话过”；正确：“放过话”。“过”是经历体标记，要插在“放”和“话”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
