INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有意把话传出去，多指表明态度或威胁。", "primary_collocate": null, "pronunciation": "fàng huà", "ipa": "faŋ˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "他放话说，谁敢来闹事就不客气。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方放话要告我们，我们并不害怕。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板放话说，再迟到就扣工资。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向所有人放话，这个项目谁也别想抢走。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷放话说，输了比赛就不再来看球。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放话要让我好看，我一点也不怕。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有人放话，不许外人到山上打猎。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放话说，谁也别想让她改变主意。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司互相放话，谁都不肯让步。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放话说要辞职，其实只是想让老板加薪。", "target_word": "放话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放了话", "label": "体标（了）"}, {"form": "放过话", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "公开表态或放出威胁的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”表示藏起来，与“说出来警告对方”的意思相反。"}, {"text": "放话", "is_correct": true, "explanation": "正确。“放话”表示公开放出威胁或表态，符合句意。"}, {"text": "鼓掌", "is_correct": false, "explanation": "搭配：“鼓掌”不能带“说”引出的威胁内容，搭配不成立。"}, {"text": "抛弃", "is_correct": false, "explanation": "配价：“抛弃”需带被抛弃的人或事物作宾语，不能直接接“说”引出的威胁内容。"}], "explanations": {"隐藏": "语义：“隐藏”表示藏起来，与“说出来警告对方”的意思相反。", "放话": "正确。“放话”表示公开放出威胁或表态，符合句意。", "鼓掌": "搭配：“鼓掌”不能带“说”引出的威胁内容，搭配不成立。", "抛弃": "配价：“抛弃”需带被抛弃的人或事物作宾语，不能直接接“说”引出的威胁内容。"}, "sentence_index": 0, "correct_answer": "放话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一不小心放话，把这个项目的消息说了出去。", "explanation": "这里应该用〈说漏嘴〉。“放话”是有意公开表态或放出威胁，不小心把消息说出去应说“说漏嘴”。"}, {"text": "他放话把窗户推开了。", "explanation": "这里“放话”的意思不对：它指公开表态或放威胁，不能表示开窗，开窗应说〈打开〉。"}, {"text": "他放话把书包背在了肩上。", "explanation": "这里“放话”的意思不对：它指公开表态或放威胁，不能表示背东西，背书包应说〈背〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举报", "is_correct": false, "explanation": "语义：“举报”指向有关部门检举违法行为，与“不许外人到山上打猎”的句意不合。"}, {"text": "放话", "is_correct": true, "explanation": "正确。“放话”表示公开放出话来，符合“村里有人放话，不许外人到山上打猎”的句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指悠闲地走走，与发布禁令的句意无关，句子不通。"}, {"text": "种植", "is_correct": false, "explanation": "配价：“种植”需带所种的植物作宾语，句中缺少宾语，句意不通。"}], "explanations": {"举报": "语义：“举报”指向有关部门检举违法行为，与“不许外人到山上打猎”的句意不合。", "放话": "正确。“放话”表示公开放出话来，符合“村里有人放话，不许外人到山上打猎”的句意。", "散步": "语义：“散步”指悠闲地走走，与发布禁令的句意无关，句子不通。", "种植": "配价：“种植”需带所种的植物作宾语，句中缺少宾语，句意不通。"}, "sentence_index": 6, "correct_answer": "放话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在心里放话，决定以后再也不说这样的话。", "explanation": "这里应该用〈暗下决心〉。“放话”是对外公开表态或放威胁，只在心里打定主意应说“暗下决心”。"}, {"text": "他放话把这份文件递给了老板。", "explanation": "这里应该用〈交〉。“放话”是有意公开表态或放威胁，不能表示递交文件，应说“交”。"}, {"text": "他放话的时候，什么也没说，只是想让老板加薪。", "explanation": "这里应该用〈沉默〉。“放话”是有意把话传出去，保持沉默就不能叫放话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有人很放话，说要把这片山封起来。", "corrected_sentence": "有人放话，说要把这片山封起来。", "error_description": "错误：“很放话”；正确：“放话”。“很”是程度副词，不能直接修饰动词“放话”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人以前放话过，说要和我绝交。", "corrected_sentence": "那个人以前放过话，说要和我绝交。", "error_description": "错误：“放话过”；正确：“放过话”。“过”是经历体标记，要插在“放”和“话”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
