INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92251, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照顾小孩。", "primary_collocate": null, "pronunciation": "dài hái zi", "ipa": "tai˥˩ xai˧˥ tsɨ", "syllable_count": 3, "sentences": [{"text": "奶奶每天在家带孩子。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天不上班，在家带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈一边工作一边带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她请了人帮她带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带孩子很累，她常常睡不好。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不会带孩子，所以很着急。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人来帮我们带孩子。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我太太在家带孩子，不上班。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带孩子需要很多时间和耐心。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我晚上要带孩子，不能出去玩。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "带了孩子", "label": "体标"}, {"form": "带过孩子", "label": "体标"}], "register": "口语", "sense_fingerprint": "带孩子：日常照顾小孩，看护孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带孩子", "is_correct": true, "explanation": "正确。“奶奶每天在家带孩子”指在家照看小孩，与“在家”相符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指到外地办公，与“在家”相互矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：“在家上学”的说法不符合“奶奶在家照看孩子”的情境。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指离开国境，与“在家”的句意冲突。"}], "explanations": {"带孩子": "正确。“奶奶每天在家带孩子”指在家照看小孩，与“在家”相符。", "出差": "语义：“出差”指到外地办公，与“在家”相互矛盾。", "上学": "搭配：“在家上学”的说法不符合“奶奶在家照看孩子”的情境。", "出国": "语义：“出国”指离开国境，与“在家”的句意冲突。"}, "sentence_index": 0, "correct_answer": "带孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事由我来带孩子。", "explanation": "这里应该用〈处理〉。“带孩子”指照看小孩，不指处理事务；处理事务要用“处理”。"}, {"text": "这块石头每天带孩子们背单词。", "explanation": "“带孩子”的施事应是能照看孩子的人，石头不能照看孩子。"}, {"text": "这辆公交车每天在家带孩子。", "explanation": "“带孩子”要求施事是能照看孩子的人；公交车不能照看孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带孩子", "is_correct": true, "explanation": "正确。“老人来帮我们带孩子”指老人来帮忙照看小孩，与句意相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”是自己的事，别人不能“帮我们退休”。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：“熬夜”指晚睡，不能用来表示帮家里做事。"}, {"text": "当兵", "is_correct": false, "explanation": "语义：老人不能“帮我们当兵”，当兵是本人的事，句意不通。"}], "explanations": {"带孩子": "正确。“老人来帮我们带孩子”指老人来帮忙照看小孩，与句意相符。", "退休": "语义：“退休”是自己的事，别人不能“帮我们退休”。", "熬夜": "语义：“熬夜”指晚睡，不能用来表示帮家里做事。", "当兵": "语义：老人不能“帮我们当兵”，当兵是本人的事，句意不通。"}, "sentence_index": 6, "correct_answer": "带孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库由他带孩子看守。", "explanation": "这里应该用〈看守〉。“带孩子”指照看小孩，不指看守仓库；看守仓库要用“看守”。"}, {"text": "这台电视机带孩子去看了一场电影。", "explanation": "“带孩子”的施事应是能照看孩子的人，电视机不能照看孩子。"}, {"text": "这个问题我一直在带孩子。", "explanation": "“带孩子”是照看孩子的行为，不能用来处理一个问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天在家带孩子得很辛苦。", "corrected_sentence": "她每天在家带孩子带得很辛苦。", "error_description": "错误：“带孩子”后漏掉了重复的动词“带”。动宾结构后接补语时要重复动词，应说“带孩子带得很辛苦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天带过孩子，没时间去开会。", "corrected_sentence": "我明天要带孩子，没时间去开会。", "error_description": "体标错误：“过”表示经历，不能用于“明天”这样的将来安排。应去掉“过”，用“要”，说“明天要带孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
