INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92252, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照看、抚养孩子。", "primary_collocate": null, "pronunciation": "dài hái zi", "ipa": "tai˥˩ xai˧˥ tsɨ", "syllable_count": 3, "sentences": [{"text": "她一个人带孩子十年了。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们夫妻俩一起带孩子。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了带孩子，她辞了工作。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶带孩子很有经验。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她一边上班一边带孩子，非常辛苦。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷以前在农村带孩子。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "带孩子比上班还累。", "target_word": "带孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "年轻妈妈常常不知道怎么带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休以后，主要的事就是带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多爷爷奶奶都帮着带孩子。", "target_word": "带孩子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "带了孩子", "label": "体标"}, {"form": "带过孩子", "label": "体标"}], "register": "口语", "sense_fingerprint": "带孩子：长期照看并抚养孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带孩子", "is_correct": true, "explanation": "正确。“她一个人带孩子十年了”指一个人长期照看、抚养孩子，与句意相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“一个人结婚”不成立，结婚需要两个人。"}, {"text": "上幼儿园", "is_correct": false, "explanation": "语义：“上幼儿园”是孩子的活动，不能说成“她一个人上幼儿园”。"}, {"text": "生宝宝", "is_correct": false, "explanation": "搭配：“一个人生宝宝十年”与“生”的时间性不搭配，无法表示长期照看。"}], "explanations": {"带孩子": "正确。“她一个人带孩子十年了”指一个人长期照看、抚养孩子，与句意相符。", "结婚": "语义：“一个人结婚”不成立，结婚需要两个人。", "上幼儿园": "语义：“上幼儿园”是孩子的活动，不能说成“她一个人上幼儿园”。", "生宝宝": "搭配：“一个人生宝宝十年”与“生”的时间性不搭配，无法表示长期照看。"}, "sentence_index": 0, "correct_answer": "带孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔账由她来带孩子。", "explanation": "这里应该用〈结清〉。“带孩子”指照看小孩，不指处理账目；结清账目要用“结清”。"}, {"text": "这台冰箱带孩子背诗，很有经验。", "explanation": "“带孩子”的施事应是能照看孩子的人，冰箱不能照看孩子。"}, {"text": "这座雕像一个人带孩子很多年。", "explanation": "“带孩子”的施事应是能照看孩子的人，雕像不能照看孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带孩子", "is_correct": true, "explanation": "正确。“带孩子比上班还累”指照看孩子比上班更累，与句意相符。"}, {"text": "照镜子", "is_correct": false, "explanation": "语义：“照镜子”不是需要比较劳累的活动，句意不通。"}, {"text": "吸烟", "is_correct": false, "explanation": "搭配：“比上班还累”多用于劳动或照顾人的情境，与“吸烟”不搭配。"}, {"text": "听音乐", "is_correct": false, "explanation": "语义：“听音乐”通常是放松的活动，与“比上班还累”的比较相矛盾。"}], "explanations": {"带孩子": "正确。“带孩子比上班还累”指照看孩子比上班更累，与句意相符。", "照镜子": "语义：“照镜子”不是需要比较劳累的活动，句意不通。", "吸烟": "搭配：“比上班还累”多用于劳动或照顾人的情境，与“吸烟”不搭配。", "听音乐": "语义：“听音乐”通常是放松的活动，与“比上班还累”的比较相矛盾。"}, "sentence_index": 6, "correct_answer": "带孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同由她带孩子签署。", "explanation": "这里应该用〈签署〉。“带孩子”指照看小孩，不指签署文件；签署文件要用“签署”。"}, {"text": "这座桥每天在家带孩子。", "explanation": "“带孩子”的施事应是能照看孩子的人，桥不能照看孩子。"}, {"text": "这台电视机带孩子去了三次医院。", "explanation": "“带孩子”的施事应是能照看孩子的人，电视机不能照看孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
