INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远期", "is_correct": true, "explanation": "正确。“远期”指较长远的时期，与指离现在不远的“近期”构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是具体物品，与“近期”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”指水流，与表示时间的“近期”没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是物品，与“近期”没有反义关系。"}], "correct_answer": "远期", "explanations": {"远期": "正确。“远期”指较长远的时期，与指离现在不远的“近期”构成反义。", "桌子": "“桌子”是具体物品，与“近期”没有反义关系。", "河流": "“河流”指水流，与表示时间的“近期”没有反义关系。", "书包": "“书包”是物品，与“近期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
