INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "近期是离现在不远的这几天或几个月。", "primary_collocate": null, "pronunciation": "jìn qī", "ipa": "tɕin˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "近期天气很冷，请多穿衣服。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近期我很忙，没有时间见你。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近期要去上海工作。", "target_word": "近期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司近期会有新的计划。", "target_word": "近期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "近期的新闻，我每天都看。", "target_word": "近期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司近期开了三个新店。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近期有一次大考，同学们都在复习。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近期不要去海边，那里常常下雨。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近期我最想做的事，是去一次北京。", "target_word": "近期", "complexity_tier": "T3", "furigana": "jìn qī wǒ zuì xiǎng zuò de shì shì qù yí cì běi jīng", "sentence_source": "generated"}, {"text": "近期，我们学校会有一次比赛。", "target_word": "近期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近期目标", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：离现在不远的几天或几个月，常指不久的将来或刚过去的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近期", "is_correct": true, "explanation": "正确。“近期天气很冷”指最近几天的天气，与“请多穿衣服”相符。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指过去的事情，不能作“天气很冷”的主语。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能与“天气很冷”搭配，句子意思不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不能说“花园天气很冷”。"}], "explanations": {"近期": "正确。“近期天气很冷”指最近几天的天气，与“请多穿衣服”相符。", "历史": "语义：“历史”指过去的事情，不能作“天气很冷”的主语。", "身体": "搭配：“身体”不能与“天气很冷”搭配，句子意思不通。", "花园": "语义：“花园”是地方，不能说“花园天气很冷”。"}, "sentence_index": 0, "correct_answer": "近期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近期十年，我想去国外工作。", "explanation": "这里应该用〈未来〉。“近期”指离现在不远的几天或几个月，不能用于十年这样的长期。"}, {"text": "近期三年，我一直在学习。", "explanation": "这里应该用〈过去〉。“近期”指离现在不远的时段，不能用于三年这样较长的时间。"}, {"text": "近期，人们住在山洞里。", "explanation": "这里应该用〈远古〉。“近期”指离现在不远的时段，不能指远古的时代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近期", "is_correct": true, "explanation": "正确。“近期有一次大考”指不久之后有一次考试，与“同学们都在复习”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能作“有一次大考”的主语，句子不通。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”与“大考”没有关系，“工厂有一次大考”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能与“有一次大考”搭配，句子意思不通。"}], "explanations": {"近期": "正确。“近期有一次大考”指不久之后有一次考试，与“同学们都在复习”相符。", "天气": "语义：“天气”不能作“有一次大考”的主语，句子不通。", "工厂": "语义：“工厂”与“大考”没有关系，“工厂有一次大考”说不通。", "工资": "搭配：“工资”不能与“有一次大考”搭配，句子意思不通。"}, "sentence_index": 6, "correct_answer": "近期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个王朝近期灭亡了，已经是几千年前的事了。", "explanation": "这里应该用〈久远〉。“近期”指离现在不远的几天或几个月，不能用于几千年前的事。"}, {"text": "这位学者的近期贡献是在十八世纪。", "explanation": "这里应该用〈早年〉。“近期”指离现在不远的时段，不能指十八世纪这样遥远的时间。"}, {"text": "这件事近期发生，已经是一百年前的旧闻了。", "explanation": "这里应该用〈当年〉。“近期”指离现在不远的时段，不能指一百年前的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们近期的要搬到新的办公室。", "corrected_sentence": "我们近期要搬到新的办公室。", "error_description": "多加“的”：“近期”作时间状语修饰后面的动词时不加“的”，应说“我们近期要搬到新的办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近期地天气很好，我们去爬山吧。", "corrected_sentence": "近期的天气很好，我们去爬山吧。", "error_description": "“的”“地”混用：“近期”修饰名词“天气”应用“的”，不能用“地”（“地”用于修饰动词或形容词）。正确说法是“近期的天气很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
