INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想。", "primary_collocate": null, "pronunciation": "xīn shuō", "ipa": "ɕin⁵⁵ ʂuo⁵⁵", "syllable_count": 2, "sentences": [{"text": "听她这么一说，我心说这事儿不简单。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上答应了，心说我才不去呢。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明看着窗外的雨，心说今天不用跑步了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心说，这件衣服真好看，可惜太贵了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练没说话，心说这孩子有前途。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心说，今天说什么也要把作业写完。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看了看表，心说儿子怎么还没回来？", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接过红包，心说：这下可发财了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌又睡着了，我心说老师马上就要来了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着镜子里的自己，心说我真的瘦了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "心里想，口语，引出内心活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心说", "is_correct": true, "explanation": "心说：心里想，口语，表示内心的判断。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”不能带“这事儿不简单”这样的小句作宾语，这里说的是内心判断。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声唱歌，不是心里的判断。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是身体动作，不能用于“这事儿不简单”这样的判断。"}], "explanations": {"心说": "心说：心里想，口语，表示内心的判断。", "笑": "配价：“笑”不能带“这事儿不简单”这样的小句作宾语，这里说的是内心判断。", "唱": "语义：“唱”是发声唱歌，不是心里的判断。", "跑": "语义：“跑”是身体动作，不能用于“这事儿不简单”这样的判断。"}, "sentence_index": 0, "correct_answer": "心说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对我心说，这件衣服真好看，可惜太贵了。", "explanation": "这里应该用〈告诉〉。“心说”只表示心里想，不能对人说出口；告诉我要用〈告诉〉。"}, {"text": "她大声心说，这件衣服真好看，可惜太贵了。", "explanation": "语义：这里误把〈心说〉用成了出声的说话；〈心说〉只表示心里想，不出声。"}, {"text": "她站在柜台前，当众心说：这件衣服真好看，可惜太贵了。", "explanation": "语义：这里误把〈心说〉用成了当众说出口；〈心说〉只表示心里想，不能当众说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心说", "is_correct": true, "explanation": "心说：心里想，口语，引出内心的疑问。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能引出“儿子怎么还没回来”这样的内心疑问。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食动作，不能引出内心疑问。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是睡眠动作，不能引出内心疑问。"}], "explanations": {"心说": "心说：心里想，口语，引出内心的疑问。", "哭": "配价：“哭”不能引出“儿子怎么还没回来”这样的内心疑问。", "吃": "语义：“吃”是进食动作，不能引出内心疑问。", "睡": "语义：“睡”是睡眠动作，不能引出内心疑问。"}, "sentence_index": 6, "correct_answer": "心说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她当着店员的面心说：这条裙子真好看。", "explanation": "这里应该用〈说出来〉。“心说”只表示心里想，不能当着别人的面说出口；当面说要用〈说出来〉。"}, {"text": "她对着镜子大声心说我真的瘦了。", "explanation": "语义：这里误把〈心说〉用成了出声的说话；〈心说〉只表示心里想，不出声，与“大声”矛盾。"}, {"text": "她站在门口，高声心说：开门！", "explanation": "语义：这里误把〈心说〉用成了出声的喊话；〈心说〉只表示心里想，不出声，应用〈喊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我心说给你，这次考试肯定没问题。", "corrected_sentence": "我心说，这次考试肯定没问题。", "error_description": "错误：“心说”是心里想，不能对人说，后面不能带“给你”。应说“我心说，这次考试肯定没问题。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈看了看钟，心说给女儿怎么还没到家？", "corrected_sentence": "妈妈看了看钟，心说女儿怎么还没到家？", "error_description": "错误：“心说”不能对人说，后面不能带“给女儿”。“心说”表示心里想，应直接接想法的内容，应说“妈妈看了看钟，心说女儿怎么还没到家？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
