INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里说；心想（口语）。", "primary_collocate": null, "pronunciation": "xīn shuō", "ipa": "ɕin⁵⁵ ʂuo⁵⁵", "syllable_count": 2, "sentences": [{"text": "他看了看成绩单，心说：这次总算及格了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心说，他今天怎么这么早就来了？", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈嘴上不说，心说孩子终于长大了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板走进来，我心说：糟了，他都听到了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着点头，心说这人真有意思。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到桌上的蛋糕，弟弟心说：今天一定是我的生日。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心说，这么贵的东西我可买不起。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心说你别骗我了，我早就知道了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机心说：前面这么堵，又要迟到了。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没出声，心说这道题他一定会做错。", "target_word": "心说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "心里说；心想，口语，后接心里的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心说", "is_correct": true, "explanation": "心说：心里说，口语，引出内心的想法。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是睡眠动作，不能引出一句话，后面不能接冒号引出内容。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能引出一句话，这里的冒号引语无法与之搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，不是心里说话。"}], "explanations": {"心说": "心说：心里说，口语，引出内心的想法。", "睡": "配价：“睡”是睡眠动作，不能引出一句话，后面不能接冒号引出内容。", "哭": "配价：“哭”不能引出一句话，这里的冒号引语无法与之搭配。", "唱": "语义：“唱”是发出歌声，不是心里说话。"}, "sentence_index": 0, "correct_answer": "心说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小声心说：这次总算及格了。", "explanation": "这里应该用〈嘀咕〉。“心说”只表示心里想，不出声；要小声说出来应用〈嘀咕〉。"}, {"text": "他站在门口，冲着屋里心说。", "explanation": "这里应该用〈叫喊〉。“心说”只表示心里想，不出声；冲着屋里喊要用〈叫喊〉。"}, {"text": "他走进办公室，向老师心说：您好。", "explanation": "这里应该用〈问候〉。“心说”只表示心里想，不能对人开口；向老师打招呼要用〈问候〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心说", "is_correct": true, "explanation": "心说：心里说，口语，引出内心的话。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是身体动作，不能引出内心的一句话。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的对象是食物，不能引出一句话。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是身体动作，不能引出内心的感叹。"}], "explanations": {"心说": "心说：心里说，口语，引出内心的话。", "跑": "语义：“跑”是身体动作，不能引出内心的一句话。", "吃": "配价：“吃”的对象是食物，不能引出一句话。", "跳": "语义：“跳”是身体动作，不能引出内心的感叹。"}, "sentence_index": 6, "correct_answer": "心说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我心说给老师听，这道题他一定会做错。", "explanation": "这里应该用〈告诉〉。“心说”只表示心里想，不能说给别人听；把想法告诉老师要用〈告诉〉。"}, {"text": "我大声心说，这道题他一定会做错。", "explanation": "语义：这里误把〈心说〉用成了出声的说话；〈心说〉只表示心里想，不出声。"}, {"text": "妈妈当面心说：路上小心。", "explanation": "这里应该用〈叮嘱〉。“心说”只表示心里想，不能当面对人开口；当面嘱咐要用〈叮嘱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我心说得，这次一定要早点睡。", "corrected_sentence": "我心说，这次一定要早点睡。", "error_description": "错误：“心说”后面不能直接接“得”，“得”需要接补语，这里没有补语，应去掉“得”，说“我心说，这次一定要早点睡。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心说话，这次旅行的费用可不便宜。", "corrected_sentence": "他心说，这次旅行的费用可不便宜。", "error_description": "错误：“心说”后面多加了“话”，成了“心说话”。“心说”是一个词，不能加字，应说“他心说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抓住", "is_correct": true, "explanation": "与「放走」相反：放走让东西离开，抓住则把它留在手中。"}, {"text": "修理", "is_correct": false, "explanation": "修理与「放走」没有反义关系，二者不是对立的动作。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏与「放走」没有反义关系，二者不构成对立。"}, {"text": "观察", "is_correct": false, "explanation": "观察与「放走」没有反义关系，二者不是相反的动作。"}], "correct_answer": "抓住", "explanations": {"抓住": "与「放走」相反：放走让东西离开，抓住则把它留在手中。", "修理": "修理与「放走」没有反义关系，二者不是对立的动作。", "欣赏": "欣赏与「放走」没有反义关系，二者不构成对立。", "观察": "观察与「放走」没有反义关系，二者不是相反的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留住", "is_correct": true, "explanation": "与「放走」相反：放走让动物离开，留住则使其留下。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗与「放走」没有反义关系，二者不是对立的动作。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与「放走」没有反义关系，二者不构成对立。"}, {"text": "提醒", "is_correct": false, "explanation": "提醒与「放走」没有反义关系，二者不是相反的动作。"}], "correct_answer": "留住", "explanations": {"留住": "与「放走」相反：放走让动物离开，留住则使其留下。", "清洗": "清洗与「放走」没有反义关系，二者不是对立的动作。", "打扫": "打扫与「放走」没有反义关系，二者不构成对立。", "提醒": "提醒与「放走」没有反义关系，二者不是相反的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放走是让关着的东西离开。", "primary_collocate": null, "pronunciation": "fàng zǒu", "ipa": "faŋ˥˩ tsoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他打开笼子，把小鸟放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把抓到的蝴蝶放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把关在笼里的兔子放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫把太小的鱼放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把鸽子放走，我还要带它回家呢。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人买下笼中的鸟，全都放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们决定把养伤的小鹿放走。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意把猫放走了，不想让它待在屋里。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从网里取出小鸟，轻轻放走。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的人不能随便把动物放走。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放走了", "label": "体标（了）"}, {"form": "放走过", "label": "体标（过）"}, {"form": "放不走", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "把关着的动物等放出去让它走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关上", "is_correct": false, "explanation": "语义：「关上」与前句「打开笼子」相反，前后矛盾。"}, {"text": "放走", "is_correct": true, "explanation": "「放走」指让被关着的小鸟离开，与「打开笼子」的动作前后一致。"}, {"text": "锁上", "is_correct": false, "explanation": "语义：「锁上」与「打开笼子」的动作相反，句子前后矛盾。"}, {"text": "拆散", "is_correct": false, "explanation": "搭配：「拆散」通常用于成对或成群的事物，不能用于一只小鸟。"}], "explanations": {"关上": "语义：「关上」与前句「打开笼子」相反，前后矛盾。", "放走": "「放走」指让被关着的小鸟离开，与「打开笼子」的动作前后一致。", "锁上": "语义：「锁上」与「打开笼子」的动作相反，句子前后矛盾。", "拆散": "搭配：「拆散」通常用于成对或成群的事物，不能用于一只小鸟。"}, "sentence_index": 0, "correct_answer": "放走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我决定放走这个计划，不再努力了。", "explanation": "这里应该用〈放弃〉。放走指让被关押或被抓的人、动物离开，计划不能被放走，要说放弃计划。"}, {"text": "我把那份文件放走了，回家后才发现。", "explanation": "这里应该用〈丢失〉。放走是让被关的东西离开，文件丢了不能说放走，要说丢失。"}, {"text": "我把这件大衣放走了，没有挂起来。", "explanation": "这里应该用〈挂〉。放走是让被关着的东西离开，大衣要挂起来，不能说放走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：「养伤」是为了让小鹿痊愈，吃掉与之矛盾。"}, {"text": "放走", "is_correct": true, "explanation": "「放走」指让养伤的小鹿离开，与句意一致。"}, {"text": "宰杀", "is_correct": false, "explanation": "语义：「养伤」是照料使其康复，宰杀与之相悖。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：小鹿正在养伤，丢弃与照料它的意思矛盾。"}], "explanations": {"吃掉": "语义：「养伤」是为了让小鹿痊愈，吃掉与之矛盾。", "放走": "「放走」指让养伤的小鹿离开，与句意一致。", "宰杀": "语义：「养伤」是照料使其康复，宰杀与之相悖。", "丢弃": "语义：小鹿正在养伤，丢弃与照料它的意思矛盾。"}, "sentence_index": 6, "correct_answer": "放走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一弯腰，就把鞋带放走了。", "explanation": "这里应该用〈解开〉。放走指让被关着的东西离开，解开鞋带不能说放走。"}, {"text": "他把这一天放走了，什么也没做。", "explanation": "这里应该用〈虚度〉。放走只用于让具体的生物或被关押的东西离开，不能用于时间。"}, {"text": "他把这道数学题放走了，因为太难了。", "explanation": "这里应该用〈跳过〉。放走是让被关着的动物离开，题目不能被放走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人把受伤的鹰放走着。", "corrected_sentence": "老人把受伤的鹰放走了。", "error_description": "错误：“放走着”；正确：“放走了”。“放走”是瞬间完成的动作，不能用“着”表示持续，完成的动作应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "护林员把那只养好伤的狐狸放走着。", "corrected_sentence": "护林员把那只养好伤的狐狸放走了。", "error_description": "错误：“放走着”；正确：“放走了”。“放走”是瞬间完成的动作，不能用“着”表示持续，完成的动作应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
