INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "扣留", "is_correct": true, "explanation": "与「放走」相反：放走是释放，扣留则是留住不放。"}, {"text": "送别", "is_correct": false, "explanation": "送别与「放走」没有反义关系，二者不构成对立。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰与「放走」没有反义关系，二者不是相反的动作。"}, {"text": "讲解", "is_correct": false, "explanation": "讲解与「放走」没有反义关系，二者不构成对立。"}], "correct_answer": "扣留", "explanations": {"扣留": "与「放走」相反：放走是释放，扣留则是留住不放。", "送别": "送别与「放走」没有反义关系，二者不构成对立。", "装饰": "装饰与「放走」没有反义关系，二者不是相反的动作。", "讲解": "讲解与「放走」没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "释放使离去。", "primary_collocate": null, "pronunciation": "fàng zǒu", "ipa": "faŋ˥˩ tsoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察不小心把嫌疑人放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绑匪最后把人质放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评了他，然后把他放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们答应放走所有的俘虏。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心软，把偷东西的孩子放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方不肯放走我们的朋友。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队放走了俘虏，双方停止了战斗。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问完话，就把他放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗收到钱后，放走了船上的人。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门的人查了证件，发现是误抓的，就把他放走了。", "target_word": "放走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放走了", "label": "体标（了）"}, {"form": "放走过", "label": "体标（过）"}, {"form": "放不走", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "把被扣押或被抓的人释放让其离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判决", "is_correct": false, "explanation": "语义：判决须由法院作出，警察不能判决嫌疑人。"}, {"text": "放走", "is_correct": true, "explanation": "「放走」指不慎让嫌疑人离开，与「不小心」相符。"}, {"text": "审讯", "is_correct": false, "explanation": "语义：审讯是警察有意进行的工作，不会「不小心」审讯，与句意不符。"}, {"text": "放生", "is_correct": false, "explanation": "用法：「放生」专指把动物放回自然，不用于嫌疑人。"}], "explanations": {"判决": "语义：判决须由法院作出，警察不能判决嫌疑人。", "放走": "「放走」指不慎让嫌疑人离开，与「不小心」相符。", "审讯": "语义：审讯是警察有意进行的工作，不会「不小心」审讯，与句意不符。", "放生": "用法：「放生」专指把动物放回自然，不用于嫌疑人。"}, "sentence_index": 0, "correct_answer": "放走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们决定放走这个计划，不再推进了。", "explanation": "这里应该用〈放弃〉。放走只用于让被关押的人或动物离开，计划不能被放走。"}, {"text": "他把钥匙放走了，只好请人开门。", "explanation": "这里应该用〈丢失〉。放走是让被关的东西离开，钥匙丢了不能说放走。"}, {"text": "他把这张照片放走了，想再看时找不到了。", "explanation": "这里应该用〈弄丢〉。放走是让被关着的东西离开，照片丢了不能说放走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歼灭", "is_correct": false, "explanation": "语义：歼灭是作战的结果，与「停止战斗」的前提相矛盾。"}, {"text": "俘获", "is_correct": false, "explanation": "搭配：「俘获」的对象是敌人或战利品，不用于已经被俘的人。"}, {"text": "放走", "is_correct": true, "explanation": "「放走」指释放俘虏，与前后两方停战的语境一致。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：军队不会表扬敌方俘虏，且与停战的因果无关。"}], "explanations": {"歼灭": "语义：歼灭是作战的结果，与「停止战斗」的前提相矛盾。", "俘获": "搭配：「俘获」的对象是敌人或战利品，不用于已经被俘的人。", "放走": "「放走」指释放俘虏，与前后两方停战的语境一致。", "表扬": "语义：军队不会表扬敌方俘虏，且与停战的因果无关。"}, "sentence_index": 6, "correct_answer": "放走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这件事放走了，没有告诉任何人。", "explanation": "这里应该用〈隐瞒〉。放走只用于让被关或被抓的人、动物离开，事情不能被放走。"}, {"text": "他把水龙头放走了，房间很快就湿了。", "explanation": "这里应该用〈关〉。放走是让被关着的东西离开，水龙头要说关掉，不能说放走。"}, {"text": "他把书放走，去厨房倒水。", "explanation": "这里应该用〈放下〉。放走是让被关着的东西离开，书只是放在一边，不能说放走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "狱警终于把那个犯人放走着。", "corrected_sentence": "狱警终于把那个犯人放走了。", "error_description": "错误：“放走着”；正确：“放走了”。“放走”是瞬间完成的动作，不能用“着”表示持续，完成的动作应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门卫核实了身份，就把那个路人放走着。", "corrected_sentence": "门卫核实了身份，就把那个路人放走了。", "error_description": "错误：“放走着”；正确：“放走了”。“放走”是瞬间完成的动作，不能用“着”表示持续，完成的动作应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逃是为了不被抓住，很快跑开。", "primary_collocate": null, "pronunciation": "táo", "ipa": "tʰɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "小偷看见警察，转身就逃。", "target_word": "逃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老鼠看见猫，马上逃了。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快逃，那条狗要来了！", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕有人发现，赶紧逃进了屋里。", "target_word": "逃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子跑得很快，狼追不上，它逃了。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们翻过墙，一起逃出了院子。", "target_word": "逃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人听到声音，一下子就逃了。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小偷想逃，可是门关着。", "target_word": "逃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从后门逃了，警察没追上。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子打破了杯子，转身逃进房间。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃了", "label": "体标"}, {"form": "逃过", "label": "体标"}, {"form": "逃跑", "label": "复合"}], "register": "中性", "sense_fingerprint": "为避免被抓住而迅速跑开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逃", "is_correct": true, "explanation": "逃（táo，第二声）是本词，意思是为避免被抓住而迅速跑开。"}, {"text": "掏", "is_correct": false, "explanation": "掏（tāo，第一声）与逃（táo，第二声）只差声调，意思是用手伸进去取出。"}, {"text": "讨", "is_correct": false, "explanation": "讨（tǎo，第三声）与逃（táo，第二声）只差声调，意思是索取或探讨。"}, {"text": "套", "is_correct": false, "explanation": "套（tào，第四声）与逃（táo，第二声）只差声调，意思是套子或套住。"}, {"text": "涛", "is_correct": false, "explanation": "涛（tāo，第一声）与逃（táo，第二声）只差声调，意思是大波浪。"}], "explanations": {"逃": "逃（táo，第二声）是本词，意思是为避免被抓住而迅速跑开。", "掏": "掏（tāo，第一声）与逃（táo，第二声）只差声调，意思是用手伸进去取出。", "讨": "讨（tǎo，第三声）与逃（táo，第二声）只差声调，意思是索取或探讨。", "套": "套（tào，第四声）与逃（táo，第二声）只差声调，意思是套子或套住。", "涛": "涛（tāo，第一声）与逃（táo，第二声）只差声调，意思是大波浪。"}, "sentence_index": null, "correct_answer": "逃"}, "level_3": {"options": [{"text": "逃", "is_correct": true, "explanation": "符合语境：“转身就逃”表示小偷见到警察后迅速跑开。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：小偷见到警察后转身去拥抱，与语境完全不符。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”要有送的东西和对象，小偷看见警察后转身“送”在这里说不通。"}, {"text": "亲", "is_correct": false, "explanation": "语义：小偷见到警察后转身亲吻，与“看见警察”的反应不符。"}], "explanations": {"逃": "符合语境：“转身就逃”表示小偷见到警察后迅速跑开。", "拥抱": "语义：小偷见到警察后转身去拥抱，与语境完全不符。", "送": "语义：“送”要有送的东西和对象，小偷看见警察后转身“送”在这里说不通。", "亲": "语义：小偷见到警察后转身亲吻，与“看见警察”的反应不符。"}, "sentence_index": 0, "correct_answer": "逃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他逃了我的钱，一转眼就不见了。", "explanation": "这里应该用〈卷走〉。逃是人自己躲开追捕而离开，不能带着别人的钱一起跑，拿走别人的财物要用卷走。"}, {"text": "他把钥匙逃进了抽屉。", "explanation": "这里应该用〈放〉。逃是人自己躲开追捕或危险而离开，不能用来表示把东西放进某处，放钥匙要用放。"}, {"text": "他逃了那个老朋友，连招呼都没打。", "explanation": "这里应该用〈躲开〉。逃是为躲避危险或追捕而离开某处，不能直接以人为宾语表示回避某人，躲开某人要用躲开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逃", "is_correct": true, "explanation": "逃（táo，第二声）是本词，意思是为避免被抓住而迅速跑开。"}, {"text": "台", "is_correct": false, "explanation": "台（tái）与逃（táo）韵母不同，ao 变成 ai，意思是平台或台子。"}, {"text": "驼", "is_correct": false, "explanation": "驼（tuó）与逃（táo）韵母不同，ao 变成 uo，意思是骆驼。"}, {"text": "糖", "is_correct": false, "explanation": "糖（táng，第二声）与逃（táo，第二声）只差韵母末尾，ao 变成 ang，意思是糖果。"}], "explanations": {"逃": "逃（táo，第二声）是本词，意思是为避免被抓住而迅速跑开。", "台": "台（tái）与逃（táo）韵母不同，ao 变成 ai，意思是平台或台子。", "驼": "驼（tuó）与逃（táo）韵母不同，ao 变成 uo，意思是骆驼。", "糖": "糖（táng，第二声）与逃（táo，第二声）只差韵母末尾，ao 变成 ang，意思是糖果。"}, "sentence_index": null, "correct_answer": "逃"}, "level_3": {"options": [{"text": "逃", "is_correct": true, "explanation": "符合语境：“听到声音，一下子就逃了”表示坏人听到动静后迅速离开。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者和宾语，句中缺少，不能说“一下子就给了”。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：听到声音后马上去拜访别人，不是对声音的自然反应，与语境不符。"}, {"text": "敬礼", "is_correct": false, "explanation": "语义：坏人向别人敬礼不合常理，与语境不符。"}], "explanations": {"逃": "符合语境：“听到声音，一下子就逃了”表示坏人听到动静后迅速离开。", "给": "配价：“给”需要接受者和宾语，句中缺少，不能说“一下子就给了”。", "拜访": "语义：听到声音后马上去拜访别人，不是对声音的自然反应，与语境不符。", "敬礼": "语义：坏人向别人敬礼不合常理，与语境不符。"}, "sentence_index": 6, "correct_answer": "逃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他睡过头，逃了今天的早班车。", "explanation": "这里应该用〈错过〉。逃指躲开追赶或危险而离开，没赶上车要说错过，不能用逃。"}, {"text": "他终于逃了绳子。", "explanation": "这里应该用〈挣脱〉。逃是离开追捕者，摆脱绳子的束缚要用挣脱，不能用逃。"}, {"text": "这些旧书逃了一地。", "explanation": "这里应该用〈掉〉。逃指躲开追赶的人或危险，书本散落满地要说掉，不能用逃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小偷趁机走逃了。", "corrected_sentence": "小偷趁机逃走了。", "error_description": "语序错误：“逃走”是“逃”加结果补语“走”，应说“逃走”，“走”不能放在“逃”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他逃了过警察的追捕。", "corrected_sentence": "他逃过了警察的追捕。", "error_description": "体标错误：“逃过”的体标“过”应紧跟动词，“了”不能放在“过”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
