INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逃跑；为躲避而离开。", "primary_collocate": null, "pronunciation": "táo", "ipa": "tʰɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "他想逃开这个吵闹的地方。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争开始后，他们逃到了南方。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大火烧起来，人们都往外逃。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从着火的房子里逃了出来。", "target_word": "逃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天加班，真想逃回老家。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水来了，村里的人逃上了山。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想见客人，就逃到了房间里。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到枪声，他吓坏了，只想赶快逃出去。", "target_word": "逃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们逃出了那个小镇，再也没回去。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨来临前，游客都逃进了山洞。", "target_word": "逃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃了", "label": "体标"}, {"form": "逃过", "label": "体标"}, {"form": "逃离", "label": "复合"}], "register": "中性", "sense_fingerprint": "为躲避危险或麻烦而离开某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逃", "is_correct": true, "explanation": "逃（táo，第二声）是本词，意思是为躲避危险或麻烦而离开某处。"}, {"text": "掏", "is_correct": false, "explanation": "掏（tāo，第一声）与逃（táo，第二声）只差声调，意思是用手伸进去取出。"}, {"text": "讨", "is_correct": false, "explanation": "讨（tǎo，第三声）与逃（táo，第二声）只差声调，意思是索取或探讨。"}, {"text": "套", "is_correct": false, "explanation": "套（tào，第四声）与逃（táo，第二声）只差声调，意思是套子。"}], "explanations": {"逃": "逃（táo，第二声）是本词，意思是为躲避危险或麻烦而离开某处。", "掏": "掏（tāo，第一声）与逃（táo，第二声）只差声调，意思是用手伸进去取出。", "讨": "讨（tǎo，第三声）与逃（táo，第二声）只差声调，意思是索取或探讨。", "套": "套（tào，第四声）与逃（táo，第二声）只差声调，意思是套子。"}, "sentence_index": null, "correct_answer": "逃"}, "level_3": {"options": [{"text": "逃", "is_correct": true, "explanation": "符合语境：“想逃开吵闹的地方”表示想离开一个嘈杂的地方。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推开”针对门或物体，不能用于“地方”，与“吵闹的地方”不搭。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”用于移动物品，不能用于离开某个地方。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫开”通常用于门，不能说“叫开这个地方”。"}], "explanations": {"逃": "符合语境：“想逃开吵闹的地方”表示想离开一个嘈杂的地方。", "推": "语义：“推开”针对门或物体，不能用于“地方”，与“吵闹的地方”不搭。", "搬": "语义：“搬”用于移动物品，不能用于离开某个地方。", "叫": "搭配：“叫开”通常用于门，不能说“叫开这个地方”。"}, "sentence_index": 0, "correct_answer": "逃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天早上都在公园里逃步。", "explanation": "这里应该用〈跑〉。逃是为躲避危险而离开，锻炼身体的跑步不能说逃步。"}, {"text": "他把牛奶逃进了杯子里。", "explanation": "这里应该用〈倒〉。逃是人自己躲开追赶或危险而离开，不能表示液体流入容器，倒牛奶要用倒。"}, {"text": "他把书包逃在了学校，只好回去拿。", "explanation": "这里应该用〈落〉。逃是人为躲避危险或麻烦而离开，不能表示把东西忘在某处，忘带东西要说落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逃", "is_correct": true, "explanation": "逃（táo，第二声）是本词，意思是为躲避危险或麻烦而离开某处。"}, {"text": "台", "is_correct": false, "explanation": "台（tái）与逃（táo）韵母不同，ao 变成 ai，意思是平台或台子。"}, {"text": "驼", "is_correct": false, "explanation": "驼（tuó）与逃（táo）韵母不同，ao 变成 uo，意思是骆驼。"}, {"text": "糖", "is_correct": false, "explanation": "糖（táng，第二声）与逃（táo，第二声）只差韵母末尾，ao 变成 ang，意思是糖果。"}], "explanations": {"逃": "逃（táo，第二声）是本词，意思是为躲避危险或麻烦而离开某处。", "台": "台（tái）与逃（táo）韵母不同，ao 变成 ai，意思是平台或台子。", "驼": "驼（tuó）与逃（táo）韵母不同，ao 变成 uo，意思是骆驼。", "糖": "糖（táng，第二声）与逃（táo，第二声）只差韵母末尾，ao 变成 ang，意思是糖果。"}, "sentence_index": null, "correct_answer": "逃"}, "level_3": {"options": [{"text": "逃", "is_correct": true, "explanation": "符合语境：“不想见客人，就逃到了房间里”表示为了躲避客人而离开。"}, {"text": "迎", "is_correct": false, "explanation": "语义：“迎到房间里”与“不想见客人”的语境相反。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语和接受者，句中缺少，不能说“送到了房间里”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不表示移动到某处，“就唱到了房间里”不成立。"}], "explanations": {"逃": "符合语境：“不想见客人，就逃到了房间里”表示为了躲避客人而离开。", "迎": "语义：“迎到房间里”与“不想见客人”的语境相反。", "送": "配价：“送”需要宾语和接受者，句中缺少，不能说“送到了房间里”。", "唱": "搭配：“唱”不表示移动到某处，“就唱到了房间里”不成立。"}, "sentence_index": 6, "correct_answer": "逃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子逃了一块糖，被妈妈发现了。", "explanation": "这里应该用〈偷〉。逃是自己躲开追捕而离开，不能带走别人的东西，拿走东西要用偷。"}, {"text": "他把饭逃到了桌子上。", "explanation": "这里应该用〈端〉。逃是人自己躲开追赶或危险而离开，不能表示把食物搬到桌上，端饭要用端。"}, {"text": "玻璃杯逃了一地。", "explanation": "这里应该用〈碎〉。逃指躲开追赶或危险而离开，玻璃杯碎落一地要说碎，不能用逃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他悄悄开逃了吵闹的会场。", "corrected_sentence": "他悄悄逃开了吵闹的会场。", "error_description": "语序错误：“逃开”是“逃”加结果补语“开”，应说“逃开”，“开”不能放在“逃”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们逃了过那场大火。", "corrected_sentence": "他们逃过了那场大火。", "error_description": "体标错误：“逃过”的体标“过”应紧跟动词，“了”不能放在“过”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
