INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92261, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要停也停不下来。", "primary_collocate": null, "pronunciation": "rěn bú zhù", "ipa": "ʐən˨˩ pu˧˥ ʈʂu˥˩", "syllable_count": 3, "sentences": [{"text": "我不想笑，可是忍不住一直笑。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想停下来，但是忍不住一直吃。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想哭，眼泪却忍不住地流。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我别说了，我却忍不住一直说下去。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏太好玩，我忍不住一直玩。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了水，还是忍不住一直咳嗽。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我告诉自己别看了，却忍不住一直看手机。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打嗝了，他想停，却忍不住一直打嗝。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想安静下来，可手还是忍不住一直抖。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想少吃点，但是忍不住一块接一块地吃。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "想停却停不下来，一直做下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忍不住", "is_correct": true, "explanation": "正确。想停却停不下来，一直笑下去。"}, {"text": "强迫", "is_correct": false, "explanation": "配价：“强迫”后要带宾语（强迫某人做某事），这里“强迫一直笑”不成立。"}, {"text": "记得", "is_correct": false, "explanation": "语义：“记得”指记住，与“一直笑”的状态不符。"}, {"text": "舍不得", "is_correct": false, "explanation": "语义：“舍不得”表示不忍割舍，与“一直笑”的意思搭不上，句意不通。"}], "explanations": {"忍不住": "正确。想停却停不下来，一直笑下去。", "强迫": "配价：“强迫”后要带宾语（强迫某人做某事），这里“强迫一直笑”不成立。", "记得": "语义：“记得”指记住，与“一直笑”的状态不符。", "舍不得": "语义：“舍不得”表示不忍割舍，与“一直笑”的意思搭不上，句意不通。"}, "sentence_index": 0, "correct_answer": "忍不住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们一直读，我们就忍不住一直读。", "explanation": "这里应该用〈只好〉。按别人的要求去做不是控制不住自己，不能用“忍不住”。"}, {"text": "这场考试，我忍不住了两个钟头。", "explanation": "这里应该用〈忍耐〉。“忍不住”指一下子控制不了，不能表示长时间的忍耐。"}, {"text": "她忍不住没哭。", "explanation": "这里应该用〈忍住〉。“忍不住”表示控制不了，与“没哭”这一克制结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忍不住", "is_correct": true, "explanation": "正确。想停却停不下来，一直看手机。"}, {"text": "认得", "is_correct": false, "explanation": "语义：“认得”指能辨认，与“一直看手机”搭配不通。"}, {"text": "舍得", "is_correct": false, "explanation": "语义：“舍得”表示愿意割舍，与“别看了”的劝诫相悖，句意不通。"}, {"text": "看懂", "is_correct": false, "explanation": "语义：“看懂”指理解看到的内容，与“一直看手机”的动作不搭。"}], "explanations": {"忍不住": "正确。想停却停不下来，一直看手机。", "认得": "语义：“认得”指能辨认，与“一直看手机”搭配不通。", "舍得": "语义：“舍得”表示愿意割舍，与“别看了”的劝诫相悖，句意不通。", "看懂": "语义：“看懂”指理解看到的内容，与“一直看手机”的动作不搭。"}, "sentence_index": 6, "correct_answer": "忍不住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么长的等待，我忍不住了一整夜。", "explanation": "这里应该用〈忍受〉。“忍不住”指一下子控制不了，不能表示持续一整夜的等待；忍受等待要用“忍受”。"}, {"text": "他忍不住，把笑意压了下去。", "explanation": "这里应该用〈收敛〉。忍不住表示控制不了，不能与“把笑意压了下去”这种主动收起笑意的做法搭配。"}, {"text": "医生让他每天吃药，他就忍不住每天吃药。", "explanation": "这里应该用〈按时〉。听医生的话吃药是有意去做，不是停不下来，不能用“忍不住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌太好听了，我忍不住着一直听。", "corrected_sentence": "这首歌太好听了，我忍不住一直听。", "error_description": "“着”误加：“忍不住”后面不能直接加“着”，应说“忍不住一直听”；“着”不能接在可能补语“忍不住”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想停，却忍得住一直吃。", "corrected_sentence": "他想停，却忍不住一直吃。", "error_description": "用词错误：“忍得住”表示能控制住，和“却……一直吃”的意思矛盾。他控制不住自己，应该说“忍不住一直吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
