INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "控制不住自己的情绪或动作。", "primary_collocate": null, "pronunciation": "rěn bú zhù", "ipa": "ʐən˨˩ pu˧˥ ʈʂu˥˩", "syllable_count": 3, "sentences": [{"text": "听到这个笑话，我忍不住笑了。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈，她忍不住哭了。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕太香了，我忍不住吃了一块。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里太急，忍不住问了老师。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太好看了，大家忍不住鼓掌。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忍不住想告诉他这个好消息。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到可爱的小狗，孩子忍不住摸了摸它。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说错了，同学们忍不住笑起来。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太生气了，忍不住大声说话。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着这首歌，我忍不住想起了家。", "target_word": "忍不住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "控制不住情绪，不由自主地做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忍不住", "is_correct": true, "explanation": "正确。听到笑话后控制不了自己，于是笑了出来。"}, {"text": "舍不得", "is_correct": false, "explanation": "语义：“舍不得”表示不忍割舍，与听到笑话后自然发笑的语境不符，句意不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示想不起来，与“听到笑话”后的即时反应不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示有意不做，与“听到笑话”后自然发笑的语境相反。"}], "explanations": {"忍不住": "正确。听到笑话后控制不了自己，于是笑了出来。", "舍不得": "语义：“舍不得”表示不忍割舍，与听到笑话后自然发笑的语境不符，句意不通。", "忘记": "语义：“忘记”表示想不起来，与“听到笑话”后的即时反应不符。", "拒绝": "语义：“拒绝”表示有意不做，与“听到笑话”后自然发笑的语境相反。"}, "sentence_index": 0, "correct_answer": "忍不住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会议上忍不住了三个小时。", "explanation": "这里应该用〈忍耐〉。“忍不住”指一下子控制不了，不能表示持续三个小时的克制。"}, {"text": "他忍不住没问老师。", "explanation": "这里应该用〈忍住〉。“忍不住”表示控制不了，后面不能接“没问”这种克制成功的结果。"}, {"text": "他故意忍不住，没有大声说话。", "explanation": "这里应该用〈控制住〉。忍不住表示控制不了，不能说“故意”去忍不住；主动控制要用“控制住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忍不住", "is_correct": true, "explanation": "正确。看到可爱的小狗后控制不住自己，去摸了它。"}, {"text": "不敢", "is_correct": false, "explanation": "语义：“不敢”与“摸了摸它”的动作相矛盾。"}, {"text": "不肯", "is_correct": false, "explanation": "语义：“不肯”表示拒绝去做，与“摸了摸它”矛盾。"}, {"text": "试图", "is_correct": false, "explanation": "体貌：“试图”表示尝试、未完成，不能与表示完成的“摸了摸”搭配。"}], "explanations": {"忍不住": "正确。看到可爱的小狗后控制不住自己，去摸了它。", "不敢": "语义：“不敢”与“摸了摸它”的动作相矛盾。", "不肯": "语义：“不肯”表示拒绝去做，与“摸了摸它”矛盾。", "试图": "体貌：“试图”表示尝试、未完成，不能与表示完成的“摸了摸”搭配。"}, "sentence_index": 6, "correct_answer": "忍不住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么吵的噪音，我忍不住了一整晚。", "explanation": "这里应该用〈忍受〉。“忍不住”指一下子控制不了，不能持续一整晚；忍受噪音要用“忍受”。"}, {"text": "她忍不住，把眼前的悲伤压了下去。", "explanation": "这里应该用〈压抑〉。忍不住表示控制不了，不能与“把悲伤压下去”这种主动克制搭配；主动控制情绪要用“压抑”。"}, {"text": "这次比赛很重要，他忍不住保持冷静。", "explanation": "这里应该用〈沉住气〉。忍不住表示控制不了，不能与“保持冷静”这种主动克制的结果搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到这部动画，他忍不住了哭。", "corrected_sentence": "看到这部动画，他忍不住哭了。", "error_description": "“了”位置错误：表示完成的“了”应放在动词“哭”之后，应说“忍不住哭了”，不能说“忍不住了哭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到噩耗，她忍不住哭下来了。", "corrected_sentence": "听到噩耗，她忍不住哭起来了。", "error_description": "补语错误：表示动作开始并持续时用“哭起来”，“哭下来”不能表示这一意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
