INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92263, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治思想是人们对国家怎么管的想法。", "primary_collocate": null, "pronunciation": "zhèng zhì sī xiǎng", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ sɨ˥ ɕjɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "他对政治思想很感兴趣。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了不同的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了古代的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的政治思想都不一样。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的政治思想受家人影响很大。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子有很多重要的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里有一门课讲政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的政治思想很特别。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解中国的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的政治思想变化得很快。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种政治思想", "label": "量词（种）"}, {"form": "政治思想工作", "label": "复合词"}], "register": "书面", "sense_fingerprint": "人们对国家怎么管理的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治思想", "is_correct": true, "explanation": "正确答案。“对……很感兴趣”的对象是“政治思想”这类观点。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”是时间，不是人会“感兴趣”的内容，句子说不通。"}, {"text": "周末", "is_correct": false, "explanation": "语义：“周末”是时间段，不能作为“感兴趣”的对象。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“对……感兴趣”多指知识或活动，“空气”与此搭配不当。"}], "explanations": {"政治思想": "正确答案。“对……很感兴趣”的对象是“政治思想”这类观点。", "夜晚": "语义：“夜晚”是时间，不是人会“感兴趣”的内容，句子说不通。", "周末": "语义：“周末”是时间段，不能作为“感兴趣”的对象。", "空气": "搭配：“对……感兴趣”多指知识或活动，“空气”与此搭配不当。"}, "sentence_index": 0, "correct_answer": "政治思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府制定了新的政治思想，全国都要执行。", "explanation": "这里应该用〈政策〉。政治思想是观念，不能由政府“制定”后当作规定执行。"}, {"text": "这位政治思想提出了一项新的改革计划。", "explanation": "这里应该用〈政治家〉。“这位”指人，政治思想是观念，不能作“这位”的主语。"}, {"text": "这个政治思想成立于1921年。", "explanation": "这里应该用〈政党〉。“成立”用于组织和机构，政治思想是观念，不能成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治思想", "is_correct": true, "explanation": "正确答案。“讲”的内容是课程的主题，“政治思想”可以作为课程内容。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不是课程讲授的内容。"}, {"text": "汗水", "is_correct": false, "explanation": "语义：“汗水”是身体分泌物，不是课程讲授的内容。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：“讲”后面的内容应是知识或学科，“午餐”不能作为讲授的主题。"}], "explanations": {"政治思想": "正确答案。“讲”的内容是课程的主题，“政治思想”可以作为课程内容。", "厨房": "语义：“厨房”是场所，不是课程讲授的内容。", "汗水": "语义：“汗水”是身体分泌物，不是课程讲授的内容。", "午餐": "搭配：“讲”后面的内容应是知识或学科，“午餐”不能作为讲授的主题。"}, "sentence_index": 6, "correct_answer": "政治思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去参观了政治思想。", "explanation": "这里应该用〈展览〉。“参观”的对象是展览、场所，政治思想是观念，不能参观。"}, {"text": "工人们昨天在街上举行了政治思想。", "explanation": "这里应该用〈政治运动〉。“举行”用于集会、活动，政治思想是观念，不能举行。"}, {"text": "这位政治思想去年当选了总统。", "explanation": "这里应该用〈政治家〉。“当选总统”的是人，政治思想是观念，不能当选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他了解了一把政治思想。", "corrected_sentence": "他了解了一种政治思想。", "error_description": "错误形式：“一把政治思想”；正确形式：“一种政治思想”。“把”用于有柄的器具，抽象的思想要用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把政治思想变化了很多。", "corrected_sentence": "他的政治思想变化了很多。", "error_description": "错误形式：“他把政治思想变化了很多”；正确形式：“他的政治思想变化了很多”。“把”字句要求宾语是被处置的对象，“政治思想”是变化的主体，应用“的”构成定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
