INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们对国家政权和社会治理形成的观点和理论。", "primary_collocate": null, "pronunciation": "zhèng zhì sī xiǎng", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ sɨ˥ ɕjɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这篇文章研究了西方近代的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的政治思想影响了很多国家。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者提出了一种新的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种政治思想在许多问题上不同。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上我们比较了两种政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用文章表达自己的政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的政治思想形成于战争年代。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位思想家的政治思想对后人影响很大。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些政治思想后来变成了国家的政策。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在研究政治思想。", "target_word": "政治思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两种政治思想", "label": "量词（种）"}, {"form": "政治思想工作", "label": "复合词"}], "register": "书面", "sense_fingerprint": "关于国家政权和社会治理的观点与理论体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治思想", "is_correct": true, "explanation": "正确答案。“研究”的对象是西方近代的观点与理论体系。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是可以研究的理论体系，与“西方近代的”不合。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“研究西方近代的”需要理论或思想，“体温”与此搭配不当。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”是时间，不能作为学术研究的对象。"}], "explanations": {"政治思想": "正确答案。“研究”的对象是西方近代的观点与理论体系。", "天气": "语义：“天气”是自然现象，不是可以研究的理论体系，与“西方近代的”不合。", "体温": "搭配：“研究西方近代的”需要理论或思想，“体温”与此搭配不当。", "夜晚": "语义：“夜晚”是时间，不能作为学术研究的对象。"}, "sentence_index": 0, "correct_answer": "政治思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的政治思想。", "explanation": "这里应该用〈政治家〉。政治思想是观念，不能指人。"}, {"text": "这座博物馆每年都会办一次政治思想。", "explanation": "这里应该用〈展览〉。“办一次”用于展览等活动，政治思想是观念，不能举办。"}, {"text": "该政治思想于1921年召开了全国代表大会。", "explanation": "这里应该用〈政党〉。“召开代表大会”的主语应是政党或组织，政治思想不能召开会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治思想", "is_correct": true, "explanation": "正确答案。“形成于战争年代”的主语是抽象的观点或理论。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“形成”多用于理论、局面等抽象结果，不能说“厨房形成于”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是具体场所，与“形成于战争年代”的观念之义不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“形成”不用于具体乐器，“钢琴形成于战争年代”不成立。"}], "explanations": {"政治思想": "正确答案。“形成于战争年代”的主语是抽象的观点或理论。", "厨房": "搭配：“形成”多用于理论、局面等抽象结果，不能说“厨房形成于”。", "花园": "语义：“花园”是具体场所，与“形成于战争年代”的观念之义不符。", "钢琴": "搭配：“形成”不用于具体乐器，“钢琴形成于战争年代”不成立。"}, "sentence_index": 6, "correct_answer": "政治思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在参加政治思想。", "explanation": "这里应该用〈政治运动〉。“参加”用于活动，政治思想是观念，不能参加。"}, {"text": "选民投票选出了新的政治思想。", "explanation": "这里应该用〈议员〉。“选出”的对象是人，政治思想是观念，不能被选出。"}, {"text": "这位教授下周做一场政治思想。", "explanation": "这里应该用〈讲座〉。“做一场”用于活动，政治思想不是活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他研究了过政治思想。", "corrected_sentence": "他研究过政治思想。", "error_description": "错误形式：“研究了过”；正确形式：“研究过”。“了”和“过”都是动态助词，不能同时出现在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把政治思想研究了透。", "corrected_sentence": "他把政治思想研究透了。", "error_description": "错误形式：“研究了透”；正确形式：“研究透了”。结果补语“透”要紧跟动词，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
