INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "郡是古时候国家里分出的一块地方。", "primary_collocate": null, "pronunciation": "jùn", "ipa": "tɕyn⁵¹", "syllable_count": 1, "sentences": [{"text": "郡是古代国家里的一个地方。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秦始皇在全国设立了很多郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个郡离京城很远。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，一个郡有很多县。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太守是管理一个郡的官。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从北方的郡来到了京城。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争以后，这个郡的人都搬走了。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉代有一百多个郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了秦朝的三十六郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个郡的名字现在还在用。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "郡县", "label": "复合"}], "register": "书面语", "sense_fingerprint": "古时候国家分出的一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92265, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "郡", "is_correct": true, "explanation": "郡（jùn，第四声）是本词，指古时候国家分出的一块地方。"}, {"text": "军", "is_correct": false, "explanation": "军（jūn，第一声）与郡（jùn，第四声）只差声调，意思是军队。"}, {"text": "均", "is_correct": false, "explanation": "均（jūn，第一声）与郡（jùn，第四声）只差声调，意思是平均。"}, {"text": "进", "is_correct": false, "explanation": "进（jìn）与郡（jùn）韵母不同，un 变成 in，意思是前进。"}], "explanations": {"郡": "郡（jùn，第四声）是本词，指古时候国家分出的一块地方。", "军": "军（jūn，第一声）与郡（jùn，第四声）只差声调，意思是军队。", "均": "均（jūn，第一声）与郡（jùn，第四声）只差声调，意思是平均。", "进": "进（jìn）与郡（jùn）韵母不同，un 变成 in，意思是前进。"}, "sentence_index": null, "correct_answer": "郡"}, "level_3": {"options": [{"text": "郡", "is_correct": true, "explanation": "符合语境：“郡是古代国家里的一个地方”，主语是指古时候国家分出的行政地区。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不是国家里分出的地方，句意不成立。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不是国家里的地方，与“古代国家里的一个地方”不符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是国家里分出的地方，句意不成立。"}], "explanations": {"郡": "符合语境：“郡是古代国家里的一个地方”，主语是指古时候国家分出的行政地区。", "人": "语义：人不是国家里分出的地方，句意不成立。", "车": "语义：车不是国家里的地方，与“古代国家里的一个地方”不符。", "学生": "语义：学生是人，不是国家里分出的地方，句意不成立。"}, "sentence_index": 0, "correct_answer": "郡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古时候，这座郡很高，顶上一年到头都是雪。", "explanation": "这里应该用〈山〉。郡是古代的行政区划，不是山，描写高度和积雪要用山。"}, {"text": "我每天早上都喝一杯郡。", "explanation": "这里应该用〈茶〉。郡是古代的地方区划，不是饮料，不能喝。"}, {"text": "古时候，这条郡很长，流过了许多城。", "explanation": "这里应该用〈河〉。郡不是河流，描写流经和长度要用河。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92265, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "郡", "is_correct": true, "explanation": "郡（jùn，第四声）是本词，指古时候国家分出的一块地方。"}, {"text": "君", "is_correct": false, "explanation": "君（jūn，第一声）与郡（jùn，第四声）只差声调，意思是君主。"}, {"text": "近", "is_correct": false, "explanation": "近（jìn）与郡（jùn）韵母不同，un 变成 in，意思是距离小。"}, {"text": "劲", "is_correct": false, "explanation": "劲（jìn）与郡（jùn）韵母不同，un 变成 in，意思是力气或力量。"}], "explanations": {"郡": "郡（jùn，第四声）是本词，指古时候国家分出的一块地方。", "君": "君（jūn，第一声）与郡（jùn，第四声）只差声调，意思是君主。", "近": "近（jìn）与郡（jùn）韵母不同，un 变成 in，意思是距离小。", "劲": "劲（jìn）与郡（jùn）韵母不同，un 变成 in，意思是力气或力量。"}, "sentence_index": null, "correct_answer": "郡"}, "level_3": {"options": [{"text": "郡", "is_correct": true, "explanation": "符合语境：“战争以后，这个郡的人都搬走了”是指一个地方的居民迁走。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯没有居民，“这个灯的人都搬走了”句意不成立。"}, {"text": "鸡", "is_correct": false, "explanation": "语义：鸡不能作为一个地方来说“人都搬走了”，与语境不符。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不是地方，没有居民，“这个杯子的人都搬走了”句意不成立。"}], "explanations": {"郡": "符合语境：“战争以后，这个郡的人都搬走了”是指一个地方的居民迁走。", "灯": "语义：灯没有居民，“这个灯的人都搬走了”句意不成立。", "鸡": "语义：鸡不能作为一个地方来说“人都搬走了”，与语境不符。", "杯子": "语义：杯子不是地方，没有居民，“这个杯子的人都搬走了”句意不成立。"}, "sentence_index": 6, "correct_answer": "郡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个郡很会下棋，每天都要找对手。", "explanation": "这里应该用〈人〉。郡是行政区划，不能指会下棋的人。"}, {"text": "他养了一只郡，每天都要遛它。", "explanation": "这里应该用〈狗〉。郡是行政区划，不是动物，不能养。"}, {"text": "这个郡很会唱歌，经常在街上唱。", "explanation": "这里应该用〈人〉。郡是行政区划，不能指会唱歌的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汉代有一把郡叫作东郡。", "corrected_sentence": "汉代有一个郡叫作东郡。", "error_description": "量词错误：“郡”应该用量词“个”，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汉代把这张郡并入了东郡。", "corrected_sentence": "汉代把这个郡并入了东郡。", "error_description": "量词错误：“郡”应该用量词“个”，不能用“张”。“张”用于纸、桌子等平面的东西，郡是地方，应说“这个郡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
