INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代的行政区划；也指某些国家的地方行政单位。", "primary_collocate": null, "pronunciation": "jùn", "ipa": "tɕyn⁵¹", "syllable_count": 1, "sentences": [{"text": "秦朝把全国分成了三十六个郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉朝的每个郡都有一位太守。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "郡比县大，一个郡有很多县。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员在古代的郡里工作。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的每个州都分成很多郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在美国一个很小的郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个郡的人口不多，但是风景很美。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，皇帝派人去管理各个郡。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里看到了这个郡的地图。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本的郡现在只是一个地名。", "target_word": "郡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "郡县", "label": "复合"}], "register": "书面语", "sense_fingerprint": "古代行政区划，或某些国家的地方行政单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92266, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "郡", "is_correct": true, "explanation": "郡（jùn，第四声）是本词，指古代的行政区划或某些国家的地方行政单位。"}, {"text": "军", "is_correct": false, "explanation": "军（jūn，第一声）与郡（jùn，第四声）只差声调，意思是军队。"}, {"text": "均", "is_correct": false, "explanation": "均（jūn，第一声）与郡（jùn，第四声）只差声调，意思是平均。"}, {"text": "进", "is_correct": false, "explanation": "进（jìn）与郡（jùn）韵母不同，un 变成 in，意思是前进。"}], "explanations": {"郡": "郡（jùn，第四声）是本词，指古代的行政区划或某些国家的地方行政单位。", "军": "军（jūn，第一声）与郡（jùn，第四声）只差声调，意思是军队。", "均": "均（jūn，第一声）与郡（jùn，第四声）只差声调，意思是平均。", "进": "进（jìn）与郡（jùn）韵母不同，un 变成 in，意思是前进。"}, "sentence_index": null, "correct_answer": "郡"}, "level_3": {"options": [{"text": "郡", "is_correct": true, "explanation": "符合语境：秦朝设立的行政区划，句中是“把全国分成三十六个郡”。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不能被“分成”行政区划，与“全国”的语境不符。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不能作为国家划分的单位，句意荒谬。"}, {"text": "户", "is_correct": false, "explanation": "语义：国家不是按“户”划分行政区的，“把全国分成三十六户”不合常理。"}], "explanations": {"郡": "符合语境：秦朝设立的行政区划，句中是“把全国分成三十六个郡”。", "人": "语义：人不能被“分成”行政区划，与“全国”的语境不符。", "车": "语义：车不能作为国家划分的单位，句意荒谬。", "户": "语义：国家不是按“户”划分行政区的，“把全国分成三十六户”不合常理。"}, "sentence_index": 0, "correct_answer": "郡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座郡很高，顶上常年积雪。", "explanation": "这里应该用〈山〉。郡是古代的行政区划，不是山，描写高度和积雪要用山。"}, {"text": "这条郡很长，流过了好几座城市。", "explanation": "这里应该用〈河〉。郡不是河流，描写流经和长度要用河。"}, {"text": "他饿了，吃了两碗郡。", "explanation": "这里应该用〈饭〉。郡是行政区划，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92266, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "郡", "is_correct": true, "explanation": "郡（jùn，第四声）是本词，指古代的行政区划或某些国家的地方行政单位。"}, {"text": "君", "is_correct": false, "explanation": "君（jūn，第一声）与郡（jùn，第四声）只差声调，意思是君主。"}, {"text": "近", "is_correct": false, "explanation": "近（jìn）与郡（jùn）韵母不同，un 变成 in，意思是距离小。"}, {"text": "劲", "is_correct": false, "explanation": "劲（jìn）与郡（jùn）韵母不同，un 变成 in，意思是力气或力量。"}], "explanations": {"郡": "郡（jùn，第四声）是本词，指古代的行政区划或某些国家的地方行政单位。", "君": "君（jūn，第一声）与郡（jùn，第四声）只差声调，意思是君主。", "近": "近（jìn）与郡（jùn）韵母不同，un 变成 in，意思是距离小。", "劲": "劲（jìn）与郡（jùn）韵母不同，un 变成 in，意思是力气或力量。"}, "sentence_index": null, "correct_answer": "郡"}, "level_3": {"options": [{"text": "郡", "is_correct": true, "explanation": "符合语境：“这个郡的人口不多，但是风景很美”是在描述一个行政区域。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有人口，与“这个……的人口不多”的语境不符。"}, {"text": "花", "is_correct": false, "explanation": "语义：花没有人口，句意无法成立。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有人口，“这个树的人口不多”句意不成立。"}], "explanations": {"郡": "符合语境：“这个郡的人口不多，但是风景很美”是在描述一个行政区域。", "书": "语义：书没有人口，与“这个……的人口不多”的语境不符。", "花": "语义：花没有人口，句意无法成立。", "树": "语义：树没有人口，“这个树的人口不多”句意不成立。"}, "sentence_index": 6, "correct_answer": "郡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个很有名的郡，大家都认识他。", "explanation": "这里应该用〈人〉。郡是古代的行政区划，不能用来指人。"}, {"text": "他养了一只郡，每天都要喂它。", "explanation": "这里应该用〈猫〉。郡是行政区划，不是动物，不能养。"}, {"text": "这个郡很会跑，每天都能跑十公里。", "explanation": "这里应该用〈人〉。郡是行政区划，不能指会跑步的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汉朝的一张郡有很多县。", "corrected_sentence": "汉朝的一个郡有很多县。", "error_description": "量词错误：“郡”应该用量词“个”，不能用“张”。“张”用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汉朝撤销了这条郡。", "corrected_sentence": "汉朝撤销了这个郡。", "error_description": "量词错误：“郡”应该用量词“个”，不能用“条”。“条”多用于河流、裤子等细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
