INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互相很喜欢、在谈恋爱的人。", "primary_collocate": null, "pronunciation": "qíng rén", "ipa": "tɕʰiŋ˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他们是一对情人，每天都在一起。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里坐着很多情人。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对情人从大学就在一起了。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个情人在河边慢慢走着。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人之间应该说真话。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是情人，不是普通朋友。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对情人手拉着手走进了电影院。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是一对快乐的情人，常常一起去旅行。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对年轻的情人下个月要结婚了。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人们都喜欢在海边照相。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情人们", "label": "复数"}, {"form": "情人节", "label": "复合"}], "register": "中性", "sense_fingerprint": "互相喜欢、正在恋爱的两个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：情人（qíng rén）指恋爱中互相喜欢的一方。"}, {"text": "亲人", "is_correct": false, "explanation": "qīn（第一声）与qíng（第二声）韵母不同（in与ing），意思是亲人（家人）。"}, {"text": "请人", "is_correct": false, "explanation": "qǐng（第三声）与qíng（第二声）声调不同，意思是请人帮忙。"}, {"text": "穷人", "is_correct": false, "explanation": "qióng（第二声）与qíng韵母不同（iong与ing），意思是贫穷的人。"}], "explanations": {"情人": "正确：情人（qíng rén）指恋爱中互相喜欢的一方。", "亲人": "qīn（第一声）与qíng（第二声）韵母不同（in与ing），意思是亲人（家人）。", "请人": "qǐng（第三声）与qíng（第二声）声调不同，意思是请人帮忙。", "穷人": "qióng（第二声）与qíng韵母不同（iong与ing），意思是贫穷的人。"}, "sentence_index": null, "correct_answer": "情人"}, "level_3": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：“一对情人”指恋爱中的一对，与“每天都在一起”相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“每天都在一起”矛盾，句意不通。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”是偶然相遇的人，与“每天都在一起”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：句中的“他们”指人，“手机”不能指代人，不能说“他们是一对手机”。"}], "explanations": {"情人": "正确：“一对情人”指恋爱中的一对，与“每天都在一起”相符。", "陌生人": "语义：“陌生人”与“每天都在一起”矛盾，句意不通。", "路人": "语义：“路人”是偶然相遇的人，与“每天都在一起”矛盾。", "手机": "搭配：句中的“他们”指人，“手机”不能指代人，不能说“他们是一对手机”。"}, "sentence_index": 0, "correct_answer": "情人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈是我的情人，她总是很爱我。", "explanation": "这里应该用〈亲人〉。“情人”指恋爱中互相喜欢的一方，不用于父母等亲属。"}, {"text": "这两位情人是亲兄弟，从小一起长大。", "explanation": "这里应该用〈亲属〉。“情人”指恋爱中互相喜欢的一方，亲兄弟是亲属关系，不用“情人”。"}, {"text": "我家的小狗是我的情人，它天天陪我玩。", "explanation": "这里应该用〈伙伴〉。“情人”指恋爱中互相喜欢的人，不能用来指宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：“那对情人”指恋爱中的一对，与“手拉着手”相符。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：仇人不会手拉着手走进电影院，与句中的亲密动作矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”与“手拉着手”矛盾，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“手拉着手”的主语是人，桌子不能手拉手。"}], "explanations": {"情人": "正确：“那对情人”指恋爱中的一对，与“手拉着手”相符。", "仇人": "语义：仇人不会手拉着手走进电影院，与句中的亲密动作矛盾。", "敌人": "语义：“敌人”与“手拉着手”矛盾，句意不通。", "桌子": "搭配：“手拉着手”的主语是人，桌子不能手拉手。"}, "sentence_index": 6, "correct_answer": "情人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的情人是我的亲姐姐，我们是一家人。", "explanation": "这里应该用〈家人〉。“情人”指恋爱中互相喜欢的人，姐姐是家人，不用“情人”。"}, {"text": "我的儿子是我的情人，他今年三岁。", "explanation": "这里应该用〈孩子〉。“情人”指恋爱中互相喜欢的人，父母和孩子之间不用“情人”。"}, {"text": "我的爷爷是我的情人，他每天给我讲故事。", "explanation": "这里应该用〈长辈〉。“情人”指恋爱中的对方，爷爷是长辈，不用“情人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只情人，常常一起吃饭。", "corrected_sentence": "他有一个情人，常常一起吃饭。", "error_description": "量词错误：“情人”指人，应用“个”，不用“只”（“只”用于动物或成对的器物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想把情人买一束花。", "corrected_sentence": "他想给情人买一束花。", "error_description": "介词错误：“情人”是买东西的接受者，应用“给”引出；“把”字句要求宾语被处置，不能说“把情人买一束花”，应说“给情人买一束花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
