INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "恋爱中的对方。", "primary_collocate": null, "pronunciation": "qíng rén", "ipa": "tɕʰiŋ˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他把我当成唯一的情人。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的情人在国外工作。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给情人打电话。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的情人很会做饭。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是彼此的情人，关系很亲密。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人生气了，他马上去道歉。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把情人的照片放在桌上。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想送情人一朵花。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说她的情人是一位医生。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和情人约好周末去爬山。", "target_word": "情人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情人们", "label": "复数"}, {"form": "情人节", "label": "复合"}], "register": "中性", "sense_fingerprint": "恋爱关系中的另一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：情人（qíng rén）指恋爱中的对方。"}, {"text": "亲人", "is_correct": false, "explanation": "qīn（第一声）与qíng（第二声）韵母不同（in与ing），意思是亲人（家人）。"}, {"text": "请人", "is_correct": false, "explanation": "qǐng（第三声）与qíng（第二声）声调不同，意思是请人帮忙。"}, {"text": "穷人", "is_correct": false, "explanation": "qióng（第二声）与qíng韵母不同（iong与ing），意思是贫穷的人。"}], "explanations": {"情人": "正确：情人（qíng rén）指恋爱中的对方。", "亲人": "qīn（第一声）与qíng（第二声）韵母不同（in与ing），意思是亲人（家人）。", "请人": "qǐng（第三声）与qíng（第二声）声调不同，意思是请人帮忙。", "穷人": "qióng（第二声）与qíng韵母不同（iong与ing），意思是贫穷的人。"}, "sentence_index": null, "correct_answer": "情人"}, "level_3": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：“唯一的情人”指恋爱中唯一的对方，与“把我当成”搭配。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是物品，不能作为“唯一的”恋爱对象，句意不通。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“唯一的陌生人”自相矛盾，与“把我当成”的亲密语义不符。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“把我当成”的对象应是人或关系，不能把人当成饭店。"}], "explanations": {"情人": "正确：“唯一的情人”指恋爱中唯一的对方，与“把我当成”搭配。", "汽车": "语义：“汽车”是物品，不能作为“唯一的”恋爱对象，句意不通。", "陌生人": "语义：“唯一的陌生人”自相矛盾，与“把我当成”的亲密语义不符。", "饭店": "搭配：“把我当成”的对象应是人或关系，不能把人当成饭店。"}, "sentence_index": 0, "correct_answer": "情人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的情人是我的弟弟，我们一起长大。", "explanation": "这里应该用〈家人〉。“情人”指恋爱中的对方，家人之间不用“情人”。"}, {"text": "我的情人是我的妈妈，她每天照顾我。", "explanation": "这里应该用〈亲人〉。“情人”指恋爱中的对方，妈妈是亲人，不用“情人”。"}, {"text": "我的情人是一台电脑，我每天用它写作业。", "explanation": "这里应该用〈东西〉。“情人”指恋爱中的人，不能用来指电脑等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情人", "is_correct": true, "explanation": "正确：“她把情人的照片”指恋人的照片，与“放在桌上”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音无法拍成照片，“声音的照片”句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，没有照片，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“照片”拍的是可见的人或物，味道不能拍成照片。"}], "explanations": {"情人": "正确：“她把情人的照片”指恋人的照片，与“放在桌上”相符。", "声音": "语义：声音无法拍成照片，“声音的照片”句意不通。", "时间": "语义：时间是抽象概念，没有照片，句意不通。", "味道": "搭配：“照片”拍的是可见的人或物，味道不能拍成照片。"}, "sentence_index": 6, "correct_answer": "情人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的情人是一只小猫，它很可爱。", "explanation": "这里应该用〈宠物〉。“情人”指恋爱中的对方，不能用来指动物。"}, {"text": "他的情人是他的亲妹妹，比他小五岁。", "explanation": "这里应该用〈家人〉。“情人”指恋爱中的对方，妹妹是家人，不用“情人”。"}, {"text": "他的情人是他的爷爷，他很尊敬他。", "explanation": "这里应该用〈长辈〉。“情人”指恋爱中的对方，长辈不用“情人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是他唯一的一只情人。", "corrected_sentence": "她是他唯一的情人。", "error_description": "量词错误：“情人”指人，不用“只”（“只”用于动物或成对的器物），应说“她是他唯一的情人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上周把情人买了一束花。", "corrected_sentence": "她上周给情人买了一束花。", "error_description": "介词错误：“情人”是买东西的接受者，应用“给”引出；“把”字句要求宾语被处置，不能说“把情人买了一束花”，应说“给情人买了一束花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "便宜", "is_correct": true, "explanation": "正确。“便宜”与“昂贵”构成反义，都指东西价钱的高低。"}, {"text": "温柔", "is_correct": false, "explanation": "无关：“温柔”形容性情或态度，与价钱无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或颜色，与价钱无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容看得或听得分明，与价钱无关。"}], "correct_answer": "便宜", "explanations": {"便宜": "正确。“便宜”与“昂贵”构成反义，都指东西价钱的高低。", "温柔": "无关：“温柔”形容性情或态度，与价钱无关。", "明亮": "无关：“明亮”形容光线或颜色，与价钱无关。", "清楚": "无关：“清楚”形容看得或听得分明，与价钱无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
