INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（东西）价钱很高。", "primary_collocate": null, "pronunciation": "áng guì", "ipa": "ɑŋ˧˥ kweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的东西太昂贵了，我们不买。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块手表非常昂贵，要好几万元。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市，房子很昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很昂贵，很多病人买不起。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给女朋友一件昂贵的礼物。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昂贵的衣服不一定好看。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜太昂贵，我们很少去。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为学费昂贵，他一边上学一边打工。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的医疗费用非常昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车外表漂亮，但是很昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "昂貴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "昂贵：东西价钱特别高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昂贵", "is_correct": true, "explanation": "正确。“东西太昂贵了”说明价钱太高，所以“我们不买”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物体的身材、形状，不用来说店里东西的价钱。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体或食物有益，不能用来说商品的价钱。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容人的情绪，东西不能悲伤。"}], "explanations": {"昂贵": "正确。“东西太昂贵了”说明价钱太高，所以“我们不买”。", "高大": "搭配：“高大”形容人或物体的身材、形状，不用来说店里东西的价钱。", "健康": "语义：“健康”说身体或食物有益，不能用来说商品的价钱。", "悲伤": "语义：“悲伤”形容人的情绪，东西不能悲伤。"}, "sentence_index": 0, "correct_answer": "昂贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张旧照片的颜色很昂贵。", "explanation": "这里应该用〈鲜艳〉。颜色用“鲜艳”形容，“昂贵”只说价钱高。"}, {"text": "这首歌的旋律很昂贵。", "explanation": "这里应该用〈优美〉。旋律的好坏用“优美”形容，“昂贵”只说价钱高。"}, {"text": "这件事给他带来的心理压力很昂贵。", "explanation": "这里应该用〈沉重〉。压力、负担是“沉重”，不是价钱高，不能用“昂贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昂贵", "is_correct": true, "explanation": "正确。“这家饭店的菜太昂贵”说明价钱太高，所以“我们很少去”。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，菜不会寂寞。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”形容动物或力量，不用来形容饭店的菜。"}, {"text": "庞大", "is_correct": false, "explanation": "搭配：“庞大”形容规模或体积，不说菜“太庞大”。"}], "explanations": {"昂贵": "正确。“这家饭店的菜太昂贵”说明价钱太高，所以“我们很少去”。", "寂寞": "语义：“寂寞”形容人的心情，菜不会寂寞。", "凶猛": "语义：“凶猛”形容动物或力量，不用来形容饭店的菜。", "庞大": "搭配：“庞大”形容规模或体积，不说菜“太庞大”。"}, "sentence_index": 6, "correct_answer": "昂贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的愿望很昂贵。", "explanation": "这里应该用〈强烈〉。愿望的程度用“强烈”，“昂贵”只说价钱高。"}, {"text": "鸟的叫声很昂贵。", "explanation": "这里应该用〈清脆〉。叫声用“清脆”，“昂贵”只说价钱高。"}, {"text": "她的笑容很昂贵。", "explanation": "这里应该用〈灿烂〉。笑容用“灿烂”形容，“昂贵”不用来形容表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条裙子昂贵不得了。", "corrected_sentence": "这条裙子昂贵得不得了。", "error_description": "补语错误：程度补语前要加“得”，应说“昂贵得不得了”，不能说“昂贵不得了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些古董昂贵地普通人都买不起。", "corrected_sentence": "这些古董昂贵得普通人都买不起。", "error_description": "补语错误：“昂贵”后引出结果补语要用“得”，应说“昂贵得普通人都买不起”，不能说“昂贵地普通人都买不起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
