INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92270, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价格很高。", "primary_collocate": null, "pronunciation": "áng guì", "ipa": "ɑŋ˧˥ kweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的咖啡很昂贵，一杯要六十元。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一台新电脑的费用很昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游旺季，机票变得更加昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画昂贵得没有人买得起。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在一家昂贵的酒店里。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些昂贵的鞋子，她只穿过一次。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的东西都很昂贵，因为路很远。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然这把小提琴很昂贵，但他还是买了。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的房租越来越昂贵。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昂贵的东西不一定好，便宜的也不一定不好。", "target_word": "昂贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "昂貴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "昂贵：价格很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昂贵", "is_correct": true, "explanation": "正确。“这里的咖啡很昂贵，一杯要六十元”说明价格高。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容人的情绪，咖啡不能悲伤。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地势，不说咖啡很陡峭。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人或动物的身材，咖啡没有身材可言。"}], "explanations": {"昂贵": "正确。“这里的咖啡很昂贵，一杯要六十元”说明价格高。", "悲伤": "语义：“悲伤”形容人的情绪，咖啡不能悲伤。", "陡峭": "搭配：“陡峭”形容山坡等地势，不说咖啡很陡峭。", "瘦弱": "体貌：“瘦弱”形容人或动物的身材，咖啡没有身材可言。"}, "sentence_index": 0, "correct_answer": "昂贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张奖状的气味很昂贵。", "explanation": "这里应该用〈清香〉。气味用“清香”形容，“昂贵”只说价钱高。"}, {"text": "他在公司的地位很昂贵。", "explanation": "这里应该用〈高〉。地位说高低，“昂贵”只说价钱高。"}, {"text": "这份合同的字迹很昂贵。", "explanation": "这里应该用〈清晰〉。字迹的好坏用“清晰”，“昂贵”只说价钱高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昂贵", "is_correct": true, "explanation": "正确。“山上的东西都很昂贵，因为路很远”，路远使东西变贵，句意通顺。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“因为路很远”说明东西会变贵，说“便宜”与这个因果相矛盾。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容房间或空间，不说东西很宽敞。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，东西不能高兴。"}], "explanations": {"昂贵": "正确。“山上的东西都很昂贵，因为路很远”，路远使东西变贵，句意通顺。", "便宜": "语义：“因为路很远”说明东西会变贵，说“便宜”与这个因果相矛盾。", "宽敞": "搭配：“宽敞”形容房间或空间，不说东西很宽敞。", "高兴": "语义：“高兴”形容人的心情，东西不能高兴。"}, "sentence_index": 6, "correct_answer": "昂贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很昂贵，大家都听见了。", "explanation": "这里应该用〈响亮〉。声音的大小用“响亮”，“昂贵”只说价钱高。"}, {"text": "他的眼神很昂贵。", "explanation": "这里应该用〈温暖〉。眼神的感觉用“温暖”，“昂贵”不用来形容眼神。"}, {"text": "今天的天气很昂贵。", "explanation": "这里应该用〈寒冷〉。天气的冷暖用“寒冷”，“昂贵”只说价钱高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块手表昂贵的让人吃惊。", "corrected_sentence": "这块手表昂贵得让人吃惊。", "error_description": "结构错误：“昂贵”后引出结果补语要用“得”，此处用“的”后面没有名词可修饰，应说“昂贵得让人吃惊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
