INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“难过”意思相反，指心里愉快。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“难过”没有反义关系，指没有声音或心情平静。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”与“难过”没有反义关系，指头脑反应快。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”与“难过”没有反义关系，指身材或物体很高。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“难过”意思相反，指心里愉快。", "安静": "“安静”与“难过”没有反义关系，指没有声音或心情平静。", "聪明": "“聪明”与“难过”没有反义关系，指头脑反应快。", "高大": "“高大”与“难过”没有反义关系，指身材或物体很高。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "“高兴”与“难过”意思相反，指心里愉快。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“难过”没有反义关系，指光线充足或颜色鲜亮。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“难过”没有反义关系，指好看。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”与“难过”没有反义关系，指人多、有声音的场面。"}], "correct_answer": "高兴", "explanations": {"高兴": "“高兴”与“难过”意思相反，指心里愉快。", "明亮": "“明亮”与“难过”没有反义关系，指光线充足或颜色鲜亮。", "漂亮": "“漂亮”与“难过”没有反义关系，指好看。", "热闹": "“热闹”与“难过”没有反义关系，指人多、有声音的场面。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "难过是心里不舒服，想哭。", "primary_collocate": null, "pronunciation": "nán guò", "ipa": "nan˧˥ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个坏消息，我很难过。", "target_word": "难过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友搬走了，他难过得哭了。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她考试没考好，心里很难过。", "target_word": "难过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到小狗死了，孩子难过极了。", "target_word": "难过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别难过，明天会更好。", "target_word": "难过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈生病了，我心里难过，想哭。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他难过地低下了头。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着照片，越想越难过。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟丢了玩具，难过了一下午。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最好的朋友要走了，我真难过。", "target_word": "难过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "難過", "label": "繁体"}], "register": "口语", "sense_fingerprint": "因坏事而心里不舒服、想哭的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "难过", "is_correct": true, "explanation": "nán guò 是“难过”，指心里不舒服、想哭。"}, {"text": "瞒过", "is_correct": false, "explanation": "mán 与 nán 声母不同（m／n），意思是“瞒过”，不是“难过”。"}, {"text": "玩过", "is_correct": false, "explanation": "wán 与 nán 声母不同（w／n），意思是“玩过”，不是“难过”。"}, {"text": "谈过", "is_correct": false, "explanation": "tán 与 nán 声母不同（t／n），意思是“谈过”（如谈过恋爱），不是“难过”。"}], "explanations": {"难过": "nán guò 是“难过”，指心里不舒服、想哭。", "瞒过": "mán 与 nán 声母不同（m／n），意思是“瞒过”，不是“难过”。", "玩过": "wán 与 nán 声母不同（w／n），意思是“玩过”，不是“难过”。", "谈过": "tán 与 nán 声母不同（t／n），意思是“谈过”（如谈过恋爱），不是“难过”。"}, "sentence_index": null, "correct_answer": "难过"}, "level_3": {"options": [{"text": "难过", "is_correct": true, "explanation": "“难过”指心里伤心，与“听到坏消息”的情绪一致。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示开心，与“坏消息”矛盾。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”表示激动的喜悦，与“坏消息”矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示没有负担、心情放松，与听到坏消息的情绪不符。"}], "explanations": {"难过": "“难过”指心里伤心，与“听到坏消息”的情绪一致。", "高兴": "语义：“高兴”表示开心，与“坏消息”矛盾。", "兴奋": "语义：“兴奋”表示激动的喜悦，与“坏消息”矛盾。", "轻松": "语义：“轻松”表示没有负担、心情放松，与听到坏消息的情绪不符。"}, "sentence_index": 0, "correct_answer": "难过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天过生日，收到很多礼物，我很难过，一直在笑。", "explanation": "这里应该用〈高兴〉。“难过”指心里伤心，收到礼物、一直在笑表示开心，要用“高兴”。"}, {"text": "这道数学题很难过，我花了一晚上才做出来。", "explanation": "这里说的是题目难，不是心里伤心。“难过”不用来形容题目，应直接说“难”。"}, {"text": "这件衣服很难过，我不想穿。", "explanation": "这里应该用〈难看〉。“难过”指心里伤心，形容样子不好看要用“难看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难过", "is_correct": true, "explanation": "“难过”指心里伤心，用在“低下了头”这样的神态上很合适。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来修饰低头的动作。"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”指轻松活泼，与低头的沮丧神情不符。"}, {"text": "大方", "is_correct": false, "explanation": "语义：“大方”指不拘束、落落大方，与低头的样子不符。"}], "explanations": {"难过": "“难过”指心里伤心，用在“低下了头”这样的神态上很合适。", "响亮": "搭配：“响亮”形容声音，不能用来修饰低头的动作。", "欢快": "语义：“欢快”指轻松活泼，与低头的沮丧神情不符。", "大方": "语义：“大方”指不拘束、落落大方，与低头的样子不符。"}, "sentence_index": 6, "correct_answer": "难过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试前我很难过，手心一直出汗。", "explanation": "这里应该用〈紧张〉。“难过”指心里伤心，表示紧张、慌乱要用“紧张”。"}, {"text": "夜里一个人走在黑路上，听到身后有脚步声，我很难过。", "explanation": "这里应该用〈害怕〉。“难过”指心里伤心，表示恐惧要用“害怕”。"}, {"text": "他被大家夸了几句，很难过，脸红得像苹果。", "explanation": "这里应该用〈害羞〉。“难过”指心里伤心，被夸后不好意思要用“害羞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到他的话，我难过了极了。", "corrected_sentence": "听到他的话，我难过极了。", "error_description": "错误：“难过”后多加了“了”。正确：“极了”是补语，直接放在形容词后面，说“难过极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见一个难过地孩子。", "corrected_sentence": "我看见一个难过的孩子。", "error_description": "错误：“难过”修饰名词时用了“地”。正确：修饰名词要用“的”，说“难过的孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
