INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92273, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常不好。", "primary_collocate": null, "pronunciation": "è liè", "ipa": "ɤ˥˩ lie˥˩", "syllable_count": 2, "sentences": [{"text": "他对服务员的态度很恶劣。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种行为的影响非常恶劣。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的品质恶劣，大家都不喜欢他。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上的言辞很恶劣，让大家难以接受。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法太恶劣了，大家都很生气。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的脾气恶劣，常常骂人。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架时的表现很恶劣。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店服务恶劣，我再也不去了。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的性质很恶劣，必须处理。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他恶劣的行为让老师很失望。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惡劣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "态度、行为、影响非常坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶劣", "is_correct": true, "explanation": "正确：“恶劣”指态度极坏，与服务员的情境相符。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”多形容景物或外貌，不用来形容态度。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能说态度鲜艳。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”指天气明朗，与人的态度无关。"}], "explanations": {"恶劣": "正确：“恶劣”指态度极坏，与服务员的情境相符。", "美丽": "搭配：“美丽”多形容景物或外貌，不用来形容态度。", "鲜艳": "搭配：“鲜艳”形容颜色，不能说态度鲜艳。", "晴朗": "语义：“晴朗”指天气明朗，与人的态度无关。"}, "sentence_index": 0, "correct_answer": "恶劣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很恶劣。", "explanation": "这里应该用〈鲜艳〉。恶劣指行为或情况极坏，不能用来评价颜色的鲜艳程度。"}, {"text": "他们在会上的讨论很恶劣，没有结论。", "explanation": "这里应该用〈激烈〉。恶劣用于指人的态度或行为极坏，不用来形容讨论的热烈程度。"}, {"text": "这杯茶的温度很恶劣，喝起来不舒服。", "explanation": "这里应该用〈烫〉。恶劣不用来形容温度，只形容态度、行为或影响极坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶劣", "is_correct": true, "explanation": "正确：“恶劣”指表现极差，符合吵架时的情境。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用于形容表现。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”指空间广大，与表现无关。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水多，不能形容表现。"}], "explanations": {"恶劣": "正确：“恶劣”指表现极差，符合吵架时的情境。", "清脆": "搭配：“清脆”形容声音，不用于形容表现。", "辽阔": "语义：“辽阔”指空间广大，与表现无关。", "潮湿": "语义：“潮湿”指空气或物体含水多，不能形容表现。"}, "sentence_index": 6, "correct_answer": "恶劣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很恶劣地帮助邻居。", "explanation": "这里应该用〈热心〉。恶劣描述态度或行为极坏，不用来修饰帮助的方式，也不表示热心。"}, {"text": "这份说明写得很恶劣。", "explanation": "这里应该用〈清楚〉。恶劣不用于评价说明写得清楚与否。"}, {"text": "这把椅子的大小很恶劣，坐上去很难受。", "explanation": "这里应该用〈合适〉。恶劣不用来形容大小，只形容态度、行为或影响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种非常恶劣行为，让大家很失望。", "corrected_sentence": "这种非常恶劣的行为，让大家很失望。", "error_description": "错误：“非常恶劣行为”漏了“的”。副词修饰的形容词作定语时要加“的”，应为“非常恶劣的行为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这种恶劣地行为，让我们很为难。", "corrected_sentence": "他这种恶劣的行为，让我们很为难。", "error_description": "错误：“恶劣地行为”误用了“地”。恶劣修饰名词时用“的”，应为“恶劣的行为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”与“恶劣”相对，指环境或条件好。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”指清楚分明，与“恶劣”不构成反义。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指场面喧闹，与“恶劣”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不费力或心情舒畅，与“恶劣”不构成反义。"}], "correct_answer": "良好", "explanations": {"良好": "正确：“良好”与“恶劣”相对，指环境或条件好。", "清晰": "“清晰”指清楚分明，与“恶劣”不构成反义。", "热闹": "“热闹”指场面喧闹，与“恶劣”不构成反义。", "轻松": "“轻松”指不费力或心情舒畅，与“恶劣”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优越", "is_correct": true, "explanation": "正确：“优越”指条件好，与“恶劣”相对。"}, {"text": "凶猛", "is_correct": false, "explanation": "“凶猛”指凶狠猛烈，不与“恶劣”构成反义。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，不与“恶劣”构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或环境平和，不与“恶劣”构成反义。"}], "correct_answer": "优越", "explanations": {"优越": "正确：“优越”指条件好，与“恶劣”相对。", "凶猛": "“凶猛”指凶狠猛烈，不与“恶劣”构成反义。", "简单": "“简单”指不复杂，不与“恶劣”构成反义。", "安静": "“安静”指没有声音或环境平和，不与“恶劣”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "极坏的；很差的。", "primary_collocate": null, "pronunciation": "è liè", "ipa": "ɤ˥˩ lie˥˩", "syllable_count": 2, "sentences": [{"text": "今天天气很恶劣，大家都在家。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的环境非常恶劣。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的路况恶劣，开车要小心。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在恶劣的天气里，船不能出海。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住的条件很恶劣，没有水也没有电。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的生活条件非常恶劣。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天山里的气候恶劣，很少有人去。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作环境恶劣，工人们常常生病。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恶劣的天气让飞机不能起飞。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那儿的自然条件恶劣，庄稼长不好。", "target_word": "恶劣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惡劣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天气、环境、条件极差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶劣", "is_correct": true, "explanation": "正确：“恶劣”指天气极差，与后文“大家都在家”相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容天气。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用来形容天气。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”指做事专心，与天气无关。"}], "explanations": {"恶劣": "正确：“恶劣”指天气极差，与后文“大家都在家”相符。", "清脆": "搭配：“清脆”形容声音，不用来形容天气。", "热情": "搭配：“热情”形容人的态度，不能用来形容天气。", "认真": "语义：“认真”指做事专心，与天气无关。"}, "sentence_index": 0, "correct_answer": "恶劣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的风景很恶劣。", "explanation": "这里应该用〈优美〉。恶劣指环境、条件或态度极坏，不用来形容风景的好看。"}, {"text": "这首歌的旋律很恶劣。", "explanation": "这里应该用〈好听〉。恶劣指环境、条件或态度极坏，不用来评价旋律的悦耳程度。"}, {"text": "这道菜的分量很恶劣，我们每人只分到一小块。", "explanation": "这里应该用〈少〉。恶劣不用来形容分量多少，只形容天气、环境或条件极差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶劣", "is_correct": true, "explanation": "正确：“恶劣”指气候极差，与“很少有人去”相符。"}, {"text": "秀丽", "is_correct": false, "explanation": "搭配：“秀丽”形容山水景色好看，不用来说气候。"}, {"text": "灿烂", "is_correct": false, "explanation": "搭配：“灿烂”形容光辉或笑容，不说气候灿烂。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧闹，不能用来形容气候。"}], "explanations": {"恶劣": "正确：“恶劣”指气候极差，与“很少有人去”相符。", "秀丽": "搭配：“秀丽”形容山水景色好看，不用来说气候。", "灿烂": "搭配：“灿烂”形容光辉或笑容，不说气候灿烂。", "热闹": "语义：“热闹”指场面喧闹，不能用来形容气候。"}, "sentence_index": 6, "correct_answer": "恶劣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个夏天的晚上很恶劣，我们在院子里乘凉。", "explanation": "这里应该用〈凉快〉。恶劣描述环境或条件极差，不用来形容舒适的夜晚。"}, {"text": "老师的讲解很恶劣，学生们很难听懂。", "explanation": "这里应该用〈清楚〉。恶劣不用来评价讲解是否清楚。"}, {"text": "这个湖里的鱼很恶劣，村民常常去捕捞。", "explanation": "这里应该用〈丰富〉。恶劣不用来形容鱼的多少，只描述环境或条件极差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次登山遇到了非常恶劣天气。", "corrected_sentence": "这次登山遇到了非常恶劣的天气。", "error_description": "错误：“非常恶劣天气”漏了“的”。副词修饰的形容词作定语时要加“的”，应为“非常恶劣的天气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在恶劣地环境中工作，但从没抱怨。", "corrected_sentence": "我们在恶劣的环境中工作，但从没抱怨。", "error_description": "错误：“恶劣地环境”误用了“地”。恶劣修饰名词时用“的”，应为“恶劣的环境”，“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
