INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "春季是天气变暖、花开的季节。", "primary_collocate": null, "pronunciation": "chūn jì", "ipa": "ʈʂʰu̯ən˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "春季天气变暖，公园里开满了花。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季的风很轻，吹在脸上很舒服。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到春季，山上的花都开了。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季雨水多，草也长得很快。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季天气暖和，很多人去郊外玩。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季花开了，到处都很漂亮。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的春季常常有风。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季的早上有点儿凉，中午很暖。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季是最适合出去走走的时候。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春季来了，树叶变绿，小鸟也多了。", "target_word": "春季", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "春季学期", "label": "复合"}, {"form": "春季运动会", "label": "复合"}], "register": "书面", "sense_fingerprint": "天气变暖、花开的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db6fe1b3-3f76-457c-bad7-09e60fded8cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92275, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "春季", "is_correct": true, "explanation": "正确。春季指天气变暖、花开的季节。"}, {"text": "春节", "is_correct": false, "explanation": "chūn jié（第二声）与 chūn jì（第四声）第二音节的韵母和声调都不同，意思是农历新年。"}, {"text": "军纪", "is_correct": false, "explanation": "jūn jì 与 chūn jì 只有第一音节的声母不同，意思是军队的纪律。"}, {"text": "春假", "is_correct": false, "explanation": "chūn jià 与 chūn jì 第二音节的韵母和声调不同，意思是春季学校放的假。"}], "explanations": {"春季": "正确。春季指天气变暖、花开的季节。", "春节": "chūn jié（第二声）与 chūn jì（第四声）第二音节的韵母和声调都不同，意思是农历新年。", "军纪": "jūn jì 与 chūn jì 只有第一音节的声母不同，意思是军队的纪律。", "春假": "chūn jià 与 chūn jì 第二音节的韵母和声调不同，意思是春季学校放的假。"}, "sentence_index": null, "correct_answer": "春季"}, "level_3": {"options": [{"text": "春季", "is_correct": true, "explanation": "正确。春季指天气变暖、花开的季节，与句中描述一致。"}, {"text": "寒流", "is_correct": false, "explanation": "语义：“寒流”是寒冷的气流，与“天气变暖”矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不是时段，不能作“天气变暖”的主语。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：“课桌”不是时段，不能与“天气变暖”搭配。"}], "explanations": {"春季": "正确。春季指天气变暖、花开的季节，与句中描述一致。", "寒流": "语义：“寒流”是寒冷的气流，与“天气变暖”矛盾。", "冰箱": "搭配：“冰箱”不是时段，不能作“天气变暖”的主语。", "课桌": "搭配：“课桌”不是时段，不能与“天气变暖”搭配。"}, "sentence_index": 0, "correct_answer": "春季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春季是中国最重要的节日。", "explanation": "这里应该用〈春节〉。春季指季节，春节指农历新年，不能说春季是节日。"}, {"text": "我们学校每年都举办春季。", "explanation": "这里应该用〈春游〉。春季指季节，不能当作活动来举办。"}, {"text": "春季吹过湖面，水面泛起了波纹。", "explanation": "这里应该用〈春风〉。季节不会吹过湖面，吹过的是春风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92275, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "春季", "is_correct": true, "explanation": "正确。春季指天气变暖、花开的季节。"}, {"text": "军纪", "is_correct": false, "explanation": "jūn jì 与 chūn jì 第一音节的声母不同（j 与 ch），意思是军队的纪律。"}, {"text": "春景", "is_correct": false, "explanation": "chūn jǐng 与 chūn jì 第二音节的韵母和声调都不同，意思是春天的景色。"}, {"text": "春酒", "is_correct": false, "explanation": "chūn jiǔ 与 chūn jì 第二音节的韵母和声调不同，意思是春天聚会时喝的酒。"}], "explanations": {"春季": "正确。春季指天气变暖、花开的季节。", "军纪": "jūn jì 与 chūn jì 第一音节的声母不同（j 与 ch），意思是军队的纪律。", "春景": "chūn jǐng 与 chūn jì 第二音节的韵母和声调都不同，意思是春天的景色。", "春酒": "chūn jiǔ 与 chūn jì 第二音节的韵母和声调不同，意思是春天聚会时喝的酒。"}, "sentence_index": null, "correct_answer": "春季"}, "level_3": {"options": [{"text": "春季", "is_correct": true, "explanation": "正确。“北京的春季”指北京的春天，常常有风，与句意一致。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭”不是季节，不能说“北京的午饭常常有风”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不是季节，不能与“北京的”和“常常有风”搭配。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“铅笔”不是季节，不能说“北京的铅笔常常有风”。"}], "explanations": {"春季": "正确。“北京的春季”指北京的春天，常常有风，与句意一致。", "午饭": "搭配：“午饭”不是季节，不能说“北京的午饭常常有风”。", "课本": "搭配：“课本”不是季节，不能与“北京的”和“常常有风”搭配。", "铅笔": "搭配：“铅笔”不是季节，不能说“北京的铅笔常常有风”。"}, "sentence_index": 6, "correct_answer": "春季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春季是二十四节气之一。", "explanation": "这里应该用〈春分〉。春分是二十四节气之一，春季是季节，不能说春季是节气。"}, {"text": "他新买了一套春季，穿着很舒服。", "explanation": "这里应该用〈春装〉。春季是季节，不是衣服，应说“他新买了一套春装”。"}, {"text": "校园里满是春季，同学们在花园里散步。", "explanation": "这里应该用〈春色〉。“满是春色”指到处是春天的景色；“春季”是季节，不能说满是春季。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每春季，学校都会组织春游。", "corrected_sentence": "每到春季，学校都会组织春游。", "error_description": "错误在“到”的缺失。“每到春季”表示每当春季来临，缺少“到”则不成句；正确形式为“每到春季”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每条春季，我们都会去郊外玩。", "corrected_sentence": "每个春季，我们都会去郊外玩。", "error_description": "错误在量词。“条”用于细长的东西，不能修饰时间名词“春季”；应说“每个春季”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f78b142-d15e-4d56-a533-5764ffe65749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
