INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先采取措施，防止疾病、灾害等发生。", "primary_collocate": null, "pronunciation": "yù fáng", "ipa": "y⁵¹ fɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "多洗手可以预防感冒。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，打针能预防这种病。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提前预防洪水。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子每年都做好预防火灾的工作。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，要注意预防流感。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在学校学习怎么预防疾病。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府提前做了预防地震的准备。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙能预防牙病。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天运动有助于预防心脏病。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天要预防中暑，多喝水。", "target_word": "预防", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预防了", "label": "体标"}, {"form": "预防过", "label": "体标"}, {"form": "预防针", "label": "复合"}], "register": "中性", "sense_fingerprint": "事先采取措施防止疾病、灾害发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c2607d-9e0c-428b-93e6-ce2f89fb0edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预防", "is_correct": true, "explanation": "正确。“预防”指事先采取措施，使感冒不发生，与“多洗手”的作用一致。"}, {"text": "治疗", "is_correct": false, "explanation": "语义：“治疗”指病后治病，洗手是事先防范，句子说的是防范而不是治疗。"}, {"text": "加重", "is_correct": false, "explanation": "语义：洗手不会使感冒更严重，“加重”与“多洗手可以”的作用相反。"}, {"text": "传染", "is_correct": false, "explanation": "语义：“传染”指病菌传给他人，洗手是为了防止传染，句子说的恰好相反。"}], "explanations": {"预防": "正确。“预防”指事先采取措施，使感冒不发生，与“多洗手”的作用一致。", "治疗": "语义：“治疗”指病后治病，洗手是事先防范，句子说的是防范而不是治疗。", "加重": "语义：洗手不会使感冒更严重，“加重”与“多洗手可以”的作用相反。", "传染": "语义：“传染”指病菌传给他人，洗手是为了防止传染，句子说的恰好相反。"}, "sentence_index": 0, "correct_answer": "预防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位病人已经发烧三天了，医生正在预防他的高烧。", "explanation": "这里应该用〈治疗〉。预防指在病症出现之前采取措施，使其不发生；病人已经发烧，应当治疗，不能说预防。"}, {"text": "气象台提前预防了台风的路线。", "explanation": "这里应该用〈预测〉。预防是采取措施防止灾害发生，不能用来指台风的路线；提前判断台风走向应当用预测。"}, {"text": "病人明天要做手术，医生今天正在预防这台手术。", "explanation": "这里应该用〈施行〉。预防用于防止疾病、灾害等坏事发生，手术是医疗行为，应当施行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预防", "is_correct": true, "explanation": "正确。“预防”表示提前采取措施，与“提前”相合。"}, {"text": "修复", "is_correct": false, "explanation": "语义：“修复”指事后修补，与“提前”矛盾，地震也不能修复。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：地震是灾害，不能用来庆祝。"}, {"text": "救助", "is_correct": false, "explanation": "搭配：“救助”的对象多是遇险的人，不说救助地震。"}], "explanations": {"预防": "正确。“预防”表示提前采取措施，与“提前”相合。", "修复": "语义：“修复”指事后修补，与“提前”矛盾，地震也不能修复。", "庆祝": "语义：地震是灾害，不能用来庆祝。", "救助": "搭配：“救助”的对象多是遇险的人，不说救助地震。"}, "sentence_index": 6, "correct_answer": "预防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每天都努力预防学生的成绩。", "explanation": "这里应该用〈提高〉。预防只用于疾病、灾害等坏事，成绩要用提高。"}, {"text": "大家都在预防国庆节。", "explanation": "这里应该用〈庆祝〉。预防的对象是疾病、灾害，不能用于节日。"}, {"text": "工人每周都预防这台机器，让它好好工作。", "explanation": "这里应该用〈保养〉。预防的对象是疾病、灾害等坏事，不能直接以机器为对象；定期照顾机器应当说保养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生建议大家提前预防了感冒。", "corrected_sentence": "医生建议大家提前预防感冒。", "error_description": "错误：“提前预防了感冒”；正确：“提前预防感冒”。“建议”针对将要做的事，“预防”后面不能加“了”表示已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都在预防了流感。", "corrected_sentence": "大家都在预防流感。", "error_description": "错误：“在……预防了流感”；正确：“在……预防流感”。“在”表示动作正在进行，后面的动词不能再带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af02f30b-a42e-441b-bdc5-fd5ab403e75b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "没种", "is_correct": true, "explanation": "“没种”与“有种”互为反义，指没有胆量。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”与“有种”是近义词，不是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑灵活，与胆量无关，不是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”是“吵闹”的反义词，与“有种”无关。"}], "correct_answer": "没种", "explanations": {"没种": "“没种”与“有种”互为反义，指没有胆量。", "勇敢": "“勇敢”与“有种”是近义词，不是反义词。", "聪明": "“聪明”指头脑灵活，与胆量无关，不是反义词。", "安静": "“安静”是“吵闹”的反义词，与“有种”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "没种", "is_correct": true, "explanation": "“没种”与“有种”互为反义，指没有胆量。"}, {"text": "冷静", "is_correct": false, "explanation": "“冷静”指遇事沉着，与胆量无关，不是反义词。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”指性情平和，与胆量无关，不是反义词。"}, {"text": "谨慎", "is_correct": false, "explanation": "“谨慎”指做事小心，与胆量无关，不是反义词。"}], "correct_answer": "没种", "explanations": {"没种": "“没种”与“有种”互为反义，指没有胆量。", "冷静": "“冷静”指遇事沉着，与胆量无关，不是反义词。", "温和": "“温和”指性情平和，与胆量无关，不是反义词。", "谨慎": "“谨慎”指做事小心，与胆量无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有种是胆子大，什么都不怕。", "primary_collocate": null, "pronunciation": "yǒu zhǒng", "ipa": "joʊ̯˨˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他真有种，一个人敢去找老板说清楚。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有种就别跑，站在这儿说话。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩很有种，一点也不怕大狗。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有种的人才敢当面说真话。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有种，一个人走夜路也不害怕。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她有种，敢对老师说不。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有种你就跳下去，别光说不做。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要是有种，就自己去问经理。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有种，谁就来跟我比一比。", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个女孩敢上台唱歌，真有种！", "target_word": "有种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "胆子大、什么都不怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有种", "is_correct": true, "explanation": "“有种”指胆子大，与后半句“敢去找老板说清楚”一致。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”与后半句“一个人敢去找老板”矛盾。"}, {"text": "怯懦", "is_correct": false, "explanation": "语域：“怯懦”偏书面，且与“敢去找老板”的语境矛盾。"}, {"text": "怕事", "is_correct": false, "explanation": "语义：“怕事”与“敢去找老板说清楚”矛盾。"}], "explanations": {"有种": "“有种”指胆子大，与后半句“敢去找老板说清楚”一致。", "胆小": "语义：“胆小”与后半句“一个人敢去找老板”矛盾。", "怯懦": "语域：“怯懦”偏书面，且与“敢去找老板”的语境矛盾。", "怕事": "语义：“怕事”与“敢去找老板说清楚”矛盾。"}, "sentence_index": 0, "correct_answer": "有种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜真有种，味道特别好。", "explanation": "这里应该用〈好吃〉。“有种”指人胆子大，不能形容菜的味道。"}, {"text": "这件衣服很有种，颜色很好看。", "explanation": "这里应该用〈漂亮〉。“有种”指人胆子大，不能形容衣服。"}, {"text": "他数学很有种，考了一百分。", "explanation": "这里应该用〈厉害〉。“有种”指胆子大、不怕事，不表示成绩好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有种", "is_correct": true, "explanation": "“有种”指敢做，与“跳下去”“别光说不做”一致。"}, {"text": "窝囊", "is_correct": false, "explanation": "语义：“窝囊”指无能、受气，与“跳下去”的勇气相反。"}, {"text": "懦弱", "is_correct": false, "explanation": "语域：“懦弱”偏书面，且与“别光说不做”的语境相反。"}, {"text": "怂", "is_correct": false, "explanation": "语义：“怂”指胆小，与“跳下去”的行为矛盾。"}], "explanations": {"有种": "“有种”指敢做，与“跳下去”“别光说不做”一致。", "窝囊": "语义：“窝囊”指无能、受气，与“跳下去”的勇气相反。", "懦弱": "语域：“懦弱”偏书面，且与“别光说不做”的语境相反。", "怂": "语义：“怂”指胆小，与“跳下去”的行为矛盾。"}, "sentence_index": 6, "correct_answer": "有种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气真有种，阳光很好。", "explanation": "这里应该用〈好〉。“有种”指人胆子大，不能形容天气。"}, {"text": "这个手机很有种，用起来很快。", "explanation": "这里应该用〈好用〉。“有种”指人胆子大，不能形容东西。"}, {"text": "她唱歌很有种，声音很好听。", "explanation": "这里应该用〈好听〉。“有种”指敢做事，不表示声音好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他真很有种，敢一个人去找老板理论。", "corrected_sentence": "他真有种，敢一个人去找老板理论。", "error_description": "错误在于副词：“真”和“很”不能同时修饰“有种”，应说“他真有种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谁要是不有种，就站出来说话。", "corrected_sentence": "谁要是有种，就站出来说话。", "error_description": "错误在于否定：“有种”是形容词，前面不能加“不”。表示没有胆量要说“没种”，这里应说“谁要是有种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小看", "is_correct": true, "explanation": "反义：“小看”是低估、看轻，与“高看”把人估计得比实际更好正相反。"}, {"text": "怀疑", "is_correct": false, "explanation": "“怀疑”是不相信、存疑，与“高看”不构成反义关系。"}, {"text": "嘲笑", "is_correct": false, "explanation": "“嘲笑”指用言语取笑，与“高看”不构成反义关系。"}, {"text": "劝告", "is_correct": false, "explanation": "“劝告”指提醒或建议，与“高看”的意思没有反义关系。"}], "correct_answer": "小看", "explanations": {"小看": "反义：“小看”是低估、看轻，与“高看”把人估计得比实际更好正相反。", "怀疑": "“怀疑”是不相信、存疑，与“高看”不构成反义关系。", "嘲笑": "“嘲笑”指用言语取笑，与“高看”不构成反义关系。", "劝告": "“劝告”指提醒或建议，与“高看”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小看", "is_correct": true, "explanation": "反义：“小看”是低估、看轻，与“高看”把人估计得比实际更好正相反。"}, {"text": "批评", "is_correct": false, "explanation": "“批评”指指出缺点或错误，与“高看”不构成反义关系。"}, {"text": "反对", "is_correct": false, "explanation": "“反对”指不同意、抵制，与“高看”不构成反义关系。"}, {"text": "拒绝", "is_correct": false, "explanation": "“拒绝”指不接受，与“高看”不构成反义关系。"}], "correct_answer": "小看", "explanations": {"小看": "反义：“小看”是低估、看轻，与“高看”把人估计得比实际更好正相反。", "批评": "“批评”指指出缺点或错误，与“高看”不构成反义关系。", "反对": "“反对”指不同意、抵制，与“高看”不构成反义关系。", "拒绝": "“拒绝”指不接受，与“高看”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "高看是觉得一个人比别人想的更好。", "primary_collocate": null, "pronunciation": "gāo kàn", "ipa": "kɑʊ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "大家都高看他了，其实他没那么厉害。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你太高看我了，我只是个普通人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人都夸他能干，但我觉得你太高看他了。", "target_word": "高看", "complexity_tier": "T3", "furigana": "bié rén dōu kuā tā néng gàn, dàn wǒ juéde nǐ tài gāo kàn tā le.", "sentence_source": "generated"}, {"text": "我没有高看自己，只是想试试。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的能力其实一般，你别高看她。", "target_word": "高看", "complexity_tier": "T3", "furigana": "tā de nénglì qíshí yìbān, nǐ bié gāo kàn tā.", "sentence_source": "generated"}, {"text": "这个人没什么特别的，别高看他。", "target_word": "高看", "complexity_tier": "T3", "furigana": "zhè ge rén méi shénme tèbié de, bié gāo kàn tā.", "sentence_source": "generated"}, {"text": "他总高看新同事，觉得他们都很能干。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这么说是高看我了，我做不到。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以前真是高看他了，其实他很一般。", "target_word": "高看", "complexity_tier": "T3", "furigana": "wǒ yǐqián zhēn shì gāo kàn tā le, qíshí tā hěn yìbān.", "sentence_source": "generated"}, {"text": "朋友们都高看他，觉得他样样都行。", "target_word": "高看", "complexity_tier": "T3", "furigana": "péngyǒumen dōu gāo kàn tā, juéde tā yàngyàng dōu xíng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "高看了", "label": "体标"}, {"form": "高看过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把某人估计得比实际或一般看法更好、更有能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：高看，把人估计得比实际更好。"}, {"text": "高亢", "is_correct": false, "explanation": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。"}, {"text": "高干", "is_correct": false, "explanation": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。"}, {"text": "高坎", "is_correct": false, "explanation": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}], "explanations": {"高看": "正确：高看，把人估计得比实际更好。", "高亢": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。", "高干": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。", "高坎": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}, "sentence_index": null, "correct_answer": "高看"}, "level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是把人估计得比实际更好，与后句“其实他没那么厉害”相照应。"}, {"text": "小看", "is_correct": false, "explanation": "语义：“小看”是看轻、低估，与“其实他没那么厉害”所说的评价方向相反，句意矛盾。"}, {"text": "低估", "is_correct": false, "explanation": "语义：“低估”是估计得比实际低，与后句“其实他没那么厉害”的转折不合，句意矛盾。"}, {"text": "鄙视", "is_correct": false, "explanation": "语域：“鄙视”语气强烈、偏书面，含轻蔑之意，与口语化的“大家都……了，其实……”不协调。"}], "explanations": {"高看": "正确：“高看”是把人估计得比实际更好，与后句“其实他没那么厉害”相照应。", "小看": "语义：“小看”是看轻、低估，与“其实他没那么厉害”所说的评价方向相反，句意矛盾。", "低估": "语义：“低估”是估计得比实际低，与后句“其实他没那么厉害”的转折不合，句意矛盾。", "鄙视": "语域：“鄙视”语气强烈、偏书面，含轻蔑之意，与口语化的“大家都……了，其实……”不协调。"}, "sentence_index": 0, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他高看那个陌生人，却觉得他一无是处。", "explanation": "这里应该用〈小看〉。高看与后句“一无是处”矛盾。"}, {"text": "他站在山顶，高看远处的村庄。", "explanation": "这里应该用〈俯瞰〉。高看是对人的能力作估计，不表示居高临下地看景物。"}, {"text": "他站在窗前，高看那片天空，半天没动。", "explanation": "这里应该用〈仰望〉。高看是对人的评价，不表示抬头看景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是把人估计得比实际更好，与后句“觉得他们都很能干”照应。"}, {"text": "瞧不起", "is_correct": false, "explanation": "语义：“瞧不起”是看不起、轻视，与后句“觉得他们都很能干”的评价正相反，句意矛盾。"}, {"text": "轻慢", "is_correct": false, "explanation": "语域：“轻慢”偏书面、语气重，与口语化的“他总……，觉得……”不协调，且表示怠慢，与后句的认可矛盾。"}, {"text": "歧视", "is_correct": false, "explanation": "语义：“歧视”指因偏见而区别对待，与后句“觉得他们都很能干”的认可相矛盾。"}], "explanations": {"高看": "正确：“高看”是把人估计得比实际更好，与后句“觉得他们都很能干”照应。", "瞧不起": "语义：“瞧不起”是看不起、轻视，与后句“觉得他们都很能干”的评价正相反，句意矛盾。", "轻慢": "语域：“轻慢”偏书面、语气重，与口语化的“他总……，觉得……”不协调，且表示怠慢，与后句的认可矛盾。", "歧视": "语义：“歧视”指因偏见而区别对待，与后句“觉得他们都很能干”的认可相矛盾。"}, "sentence_index": 6, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师高看那几个调皮的学生，却总说他们不行。", "explanation": "这里应该用〈小看〉。高看与后句“总说他们不行”矛盾。"}, {"text": "他踮起脚，高看了一下墙的高度。", "explanation": "这里应该用〈量〉。高看是对人的评价，不表示测量高度。"}, {"text": "朋友们在山下抬头高看天上的飞机。", "explanation": "这里应该用〈仰望〉。高看是对人的评价，不表示抬头看飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没高看了他的能力，其实他并不行。", "corrected_sentence": "我没高看他的能力，其实他并不行。", "error_description": "错误：“没”否定时不用“了”，应说“我没高看他的能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板没高看了这位新人，也没给他机会。", "corrected_sentence": "老板没高看这位新人，也没给他机会。", "error_description": "错误：否定句中“没”之后多加了“了”，应去掉。正确形式为“没高看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
