INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看重；对人或事物给予较高的评价。", "primary_collocate": null, "pronunciation": "gāo kàn", "ipa": "kɑʊ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "公司很高看有经验的工人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师特别高看爱读书的学生。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很高看这份工作，每天都认真做。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都高看她的才华。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国人高看诚实的人。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很高看这次机会，准备了一个月。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板高看你，所以才让你负责这件事。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人都高看读书人。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最高看那些爱帮助别人的人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不高看有钱人，只看人品。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高看了", "label": "体标"}, {"form": "高看过", "label": "体标"}], "register": "口语", "sense_fingerprint": "看重某类人或某件事，给予较高评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：高看，看重某人或某事，给予较高评价。"}, {"text": "高亢", "is_correct": false, "explanation": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。"}, {"text": "高干", "is_correct": false, "explanation": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。"}, {"text": "高坎", "is_correct": false, "explanation": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}], "explanations": {"高看": "正确：高看，看重某人或某事，给予较高评价。", "高亢": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。", "高干": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。", "高坎": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}, "sentence_index": null, "correct_answer": "高看"}, "level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是看重、给予较高评价，与“有经验的工人”的价值相符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”多用于接待客人，不说招待有经验的工人。"}, {"text": "供养", "is_correct": false, "explanation": "搭配：“供养”指赡养、养活家人，不用于公司对员工的态度。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”是不相信、存疑，与“有经验的工人”所体现的能力相矛盾，且与高看的评价方向相反。"}], "explanations": {"高看": "正确：“高看”是看重、给予较高评价，与“有经验的工人”的价值相符。", "招待": "搭配：“招待”多用于接待客人，不说招待有经验的工人。", "供养": "搭配：“供养”指赡养、养活家人，不用于公司对员工的态度。", "怀疑": "语义：“怀疑”是不相信、存疑，与“有经验的工人”所体现的能力相矛盾，且与高看的评价方向相反。"}, "sentence_index": 0, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店高看这件商品，却说它一文不值。", "explanation": "这里应该用〈小看〉。高看与后句“一文不值”矛盾。"}, {"text": "我们高看那个新来的司机，却总觉得他不会开车。", "explanation": "这里应该用〈小看〉。高看与后句“总觉得他不会开车”矛盾。"}, {"text": "他站在桥上，高看河里的船。", "explanation": "这里应该用〈俯瞰〉。高看是对人或事的评价，不表示居高看景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是看重、给予较高评价，与“所以才让你负责这件事”的器重相照应。"}, {"text": "怠慢", "is_correct": false, "explanation": "语义：“怠慢”是冷淡、不重视，与“所以才让你负责这件事”的器重矛盾。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”是冷淡对待、不理睬，与“让你负责这件事”的信任矛盾。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”是不接纳、排挤，与“所以才让你负责这件事”的器重矛盾。"}], "explanations": {"高看": "正确：“高看”是看重、给予较高评价，与“所以才让你负责这件事”的器重相照应。", "怠慢": "语义：“怠慢”是冷淡、不重视，与“所以才让你负责这件事”的器重矛盾。", "冷落": "语义：“冷落”是冷淡对待、不理睬，与“让你负责这件事”的信任矛盾。", "排斥": "语义：“排斥”是不接纳、排挤，与“所以才让你负责这件事”的器重矛盾。"}, "sentence_index": 6, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司高看新人，却觉得他们一无是处。", "explanation": "这里应该用〈小看〉。高看与后句“一无是处”矛盾。"}, {"text": "他站在窗边，高看楼下的汽车。", "explanation": "这里应该用〈打量〉。高看表示给予较高评价，不表示观察景物。"}, {"text": "他把手放在额头上，高看远处的灯塔。", "explanation": "这里应该用〈眺望〉。高看是对人或事的评价，不表示观望远处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师很高看了这个学生的努力，经常表扬他。", "corrected_sentence": "老师很高看这个学生的努力，经常表扬他。", "error_description": "错误：副词“很”与动词后的“了”搭配不当，“了”应去掉。正确形式为“很高看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班主任从没高看了成绩差的学生。", "corrected_sentence": "班主任从没高看过成绩差的学生。", "error_description": "错误：“从没”表示从未发生过，动词后应用“过”而不用“了”。正确形式为“从没高看过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
