INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东侧是东面的那一边。", "primary_collocate": null, "pronunciation": "dōng cè", "ipa": "tʊŋ˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "学校的东侧有一个公园。", "target_word": "东侧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的东侧种着一棵大树。", "target_word": "东侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的东侧是新城区。", "target_word": "东侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你走到桥的东侧等我。", "target_word": "东侧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在这条街的东侧。", "target_word": "东侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "东侧的窗户很大，早上很亮。", "target_word": "东侧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖的东侧停着很多车。", "target_word": "东侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自行车放在楼的东侧。", "target_word": "东侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山的东侧天气比西侧冷。", "target_word": "东侧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市在公园的东侧，不在西侧。", "target_word": "东侧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "東側", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东侧：东面的那一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东侧", "is_correct": true, "explanation": "东侧：东面的那一边，可以作为公园所在的方位。"}, {"text": "大门", "is_correct": false, "explanation": "语义：“大门”是出入口，不能说大门里有一个公园，与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是方位词，与“有一个公园”搭配不当。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是空间位置，学校不能有“时间”这一侧。"}], "explanations": {"东侧": "东侧：东面的那一边，可以作为公园所在的方位。", "大门": "语义：“大门”是出入口，不能说大门里有一个公园，与句意不符。", "颜色": "搭配：“颜色”不是方位词，与“有一个公园”搭配不当。", "时间": "语义：“时间”不是空间位置，学校不能有“时间”这一侧。"}, "sentence_index": 0, "correct_answer": "东侧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一个很好的东侧。", "explanation": "这里应该用〈东西〉。〈东西〉指物品，东侧只表示方位，不能指物品。"}, {"text": "这个问题的东侧很难解决。", "explanation": "这里应该用〈难度〉。东侧只指具体地点的东面一边，不能指问题这类抽象事物；说问题的难易应用“难度”。"}, {"text": "他是我的东侧朋友。", "explanation": "这里应该用〈邻居〉。东侧指地点的一面，不能直接修饰人，只能用于“住在我东侧的人”这样的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东侧", "is_correct": true, "explanation": "东侧：湖的东面，车可以停在那里，与句意相符。"}, {"text": "湖底", "is_correct": false, "explanation": "语义：车不能停在湖底，与“停着很多车”矛盾。"}, {"text": "湖水", "is_correct": false, "explanation": "搭配：“停”的对象不能是水，“湖水”不能作停车的地方。"}, {"text": "湖心", "is_correct": false, "explanation": "语义：湖心在水面中央，车无法停在那里，与句意矛盾。"}], "explanations": {"东侧": "东侧：湖的东面，车可以停在那里，与句意相符。", "湖底": "语义：车不能停在湖底，与“停着很多车”矛盾。", "湖水": "搭配：“停”的对象不能是水，“湖水”不能作停车的地方。", "湖心": "语义：湖心在水面中央，车无法停在那里，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "东侧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "东侧文化源远流长。", "explanation": "这里应该用〈东方〉。东侧只指方位，不能指一种文化或地区的概括。"}, {"text": "明天的东侧会下雨。", "explanation": "这里应该用〈东部〉。“明天”是时间，不能带“东侧”这种方位；天气的方位应说“东部会下雨”。"}, {"text": "红色的东侧很漂亮。", "explanation": "这里应该用〈衣服〉。东侧只指地点的一面，不能作为可以“漂亮”的事物；应说“红色的衣服很漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校很东侧有一个花园。", "corrected_sentence": "学校东侧有一个花园。", "error_description": "错误在于在方位词“东侧”前加了程度副词“很”。“东侧”是方位词，不能被“很”修饰，正确形式是“学校东侧有一个花园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆在操场很东侧。", "corrected_sentence": "图书馆在操场的东侧。", "error_description": "错误在于在方位词“东侧”前加了程度副词“很”。“东侧”不能被“很”修饰，正确形式是“图书馆在操场的东侧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸运", "is_correct": true, "explanation": "反义：“幸运”与“不幸”相对，指遭遇好事。"}, {"text": "勤奋", "is_correct": false, "explanation": "无反义关系：“勤奋”说的是努力做事，与“遭遇坏事”不是相对的状态。"}, {"text": "富裕", "is_correct": false, "explanation": "无反义关系：“富裕”说的是经济条件，与“不幸”没有相对的关系。"}, {"text": "高大", "is_correct": false, "explanation": "无反义关系：“高大”说的是体形，与“不幸”的意思无关。"}], "correct_answer": "幸运", "explanations": {"幸运": "反义：“幸运”与“不幸”相对，指遭遇好事。", "勤奋": "无反义关系：“勤奋”说的是努力做事，与“遭遇坏事”不是相对的状态。", "富裕": "无反义关系：“富裕”说的是经济条件，与“不幸”没有相对的关系。", "高大": "无反义关系：“高大”说的是体形，与“不幸”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指生活顺利快乐。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”说的是智力，与“不幸”没有相对的关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "无反义关系：“勤劳”说的是肯干，与“遭遇坏事”不是相对的状态。"}, {"text": "狭窄", "is_correct": false, "explanation": "无反义关系：“狭窄”说的是空间，与“不幸”的意思无关。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指生活顺利快乐。", "聪明": "无反义关系：“聪明”说的是智力，与“不幸”没有相对的关系。", "勤劳": "无反义关系：“勤劳”说的是肯干，与“遭遇坏事”不是相对的状态。", "狭窄": "无反义关系：“狭窄”说的是空间，与“不幸”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不幸是遇到了很坏、很伤心的事。", "primary_collocate": null, "pronunciation": "bù xìng", "ipa": "pu˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很不幸，小时候就没有了父母。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个不幸的孩子一直住在奶奶家。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她真不幸，刚买的新车就坏了。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个不幸的消息，大家都很难过。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人一生很不幸，丈夫和儿子都走了。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己是世界上最不幸的人。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都为这个不幸的家庭担心过。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很不幸，工作丢了，家也没了。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次旅行真不幸，天天下雨，还生了病。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友很不幸，妻子生病，孩子也出了事。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人或事遇到坏事、很伤心，不幸运，可说“很不幸”“不幸的人／消息”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“不幸”指遭遇坏事、不顺利。"}, {"text": "不行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。"}, {"text": "步行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。"}, {"text": "不信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}], "explanations": {"不幸": "正确：“不幸”指遭遇坏事、不顺利。", "不行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。", "步行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。", "不信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。", "不兴": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}, "sentence_index": null, "correct_answer": "不幸"}, "level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“很不幸”说明他遭遇坏事，与后句“没有了父母”相符。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“很幸福”与后句“小时候就没有了父母”的经历相矛盾。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“很快乐”与后句叙述的丧亲经历不协调。"}, {"text": "幸运", "is_correct": false, "explanation": "语义：“很幸运”与后句“小时候就没有了父母”的经历相矛盾。"}], "explanations": {"不幸": "正确：“很不幸”说明他遭遇坏事，与后句“没有了父母”相符。", "幸福": "语义：“很幸福”与后句“小时候就没有了父母”的经历相矛盾。", "快乐": "语义：“很快乐”与后句叙述的丧亲经历不协调。", "幸运": "语义：“很幸运”与后句“小时候就没有了父母”的经历相矛盾。"}, "sentence_index": 0, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在那场比赛中获得了不幸。", "explanation": "这里应该用〈荣誉〉。“获得”搭配荣誉、奖项等好事，“不幸”指遇到的坏事，不能被获得。"}, {"text": "今天的天气很不幸，我们只好待在家里。", "explanation": "这里应该用〈糟糕〉。“不幸”形容人或事遭遇坏事，不用来形容天气。"}, {"text": "这次考试很不幸，他得了满分。", "explanation": "这里应该用〈幸运〉。“不幸”表示遇到坏事，与“得了满分”这样的好结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“这个不幸的家庭”说明家庭遭遇坏事，与“担心过”相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能用来形容一个家庭。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序的东西，不能用来形容一个家庭的遭遇。"}, {"text": "美满", "is_correct": false, "explanation": "语义：“美满”指生活圆满，与“为……担心过”的语义相冲突。"}], "explanations": {"不幸": "正确：“这个不幸的家庭”说明家庭遭遇坏事，与“担心过”相符。", "高大": "体貌：“高大”描写身材，不能用来形容一个家庭。", "整齐": "搭配：“整齐”形容排列有序的东西，不能用来形容一个家庭的遭遇。", "美满": "语义：“美满”指生活圆满，与“为……担心过”的语义相冲突。"}, "sentence_index": 6, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在公园玩得很不幸。", "explanation": "这里应该用〈开心〉。“不幸”指遭遇坏事，不能用来形容愉快的游玩。"}, {"text": "晚会很不幸。", "explanation": "这里应该用〈热闹〉。“不幸”说的是坏事，不能形容活动的气氛。"}, {"text": "看到孩子长大，他很不幸。", "explanation": "这里应该用〈欣慰〉。“欣慰”表示满意和安心，与“不幸”的坏事含义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个很不幸孩子很需要帮助。", "corrected_sentence": "这个很不幸的孩子很需要帮助。", "error_description": "“很”修饰形容词、后接名词时，中间要加“的”；“很不幸孩子”应为“很不幸的孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个孩子小时候过得很不幸了。", "corrected_sentence": "那个孩子小时候过得很不幸。", "error_description": "“很不幸”描写过去一直存在的状态，后面不能再加“了”；应去掉“了”，说成“过得很不幸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。"}, {"text": "办法", "is_correct": false, "explanation": "无反义关系：“办法”指解决问题的方式，与“不幸”没有相对的关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无反义关系：“桌子”是家具，与“不幸”的意思无关。"}, {"text": "计划", "is_correct": false, "explanation": "无反义关系：“计划”指打算要做的事，与“不幸”没有相对的关系。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。", "办法": "无反义关系：“办法”指解决问题的方式，与“不幸”没有相对的关系。", "桌子": "无反义关系：“桌子”是家具，与“不幸”的意思无关。", "计划": "无反义关系：“计划”指打算要做的事，与“不幸”没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。"}, {"text": "收获", "is_correct": false, "explanation": "无反义关系：“收获”指所得到的成果，与“不幸”没有相对的关系。"}, {"text": "天空", "is_correct": false, "explanation": "无反义关系：“天空”指自然景象，与“不幸”的意思无关。"}, {"text": "学问", "is_correct": false, "explanation": "无反义关系：“学问”指知识和学识，与“不幸”没有相对的关系。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。", "收获": "无反义关系：“收获”指所得到的成果，与“不幸”没有相对的关系。", "天空": "无反义关系：“天空”指自然景象，与“不幸”的意思无关。", "学问": "无反义关系：“学问”指知识和学识，与“不幸”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遭遇不好的事情；不顺利，令人悲伤。", "primary_collocate": null, "pronunciation": "bù xìng", "ipa": "pu˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在小时候遭遇过不幸。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想帮他走出不幸。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场不幸让全家人都很难过。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不向别人说自己的不幸。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友遇到了不幸，我们应该去看看他。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不幸发生以后，他一直不说话。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次不幸改变了他的一生。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对不幸，她没有哭，也没有放弃。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家人的不幸，让整个村子都很伤心。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活里的不幸，有时会让人变得更坚强。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词用法，指遭遇的灾难或坏事，常作“遭遇／遇到／面对”的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“不幸”作名词时指遭遇的坏事或灾难。"}, {"text": "不行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。"}, {"text": "步行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。"}, {"text": "不信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}], "explanations": {"不幸": "正确：“不幸”作名词时指遭遇的坏事或灾难。", "不行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。", "步行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。", "不信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。", "不兴": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}, "sentence_index": null, "correct_answer": "不幸"}, "level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“遭遇过不幸”指小时候遇到过坏事，与句意相合。"}, {"text": "好运", "is_correct": false, "explanation": "搭配：“遭遇”多接坏事，一般不接“好运”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“遭遇”在这里指遇到的坏事，“天气”不是这一类的事件。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“遭遇过幸福”与“遭遇”所指的坏事语境不符。"}], "explanations": {"不幸": "正确：“遭遇过不幸”指小时候遇到过坏事，与句意相合。", "好运": "搭配：“遭遇”多接坏事，一般不接“好运”。", "天气": "语义：“遭遇”在这里指遇到的坏事，“天气”不是这一类的事件。", "幸福": "语义：“遭遇过幸福”与“遭遇”所指的坏事语境不符。"}, "sentence_index": 0, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在小时候得到了一份不幸。", "explanation": "这里应该用〈礼物〉。“得到”搭配礼物、机会等好事，“不幸”指坏事，不能被得到。"}, {"text": "她每天都在享受不幸。", "explanation": "这里应该用〈幸福〉。“享受”搭配幸福、快乐等好事，不搭配坏事。"}, {"text": "他的不幸让全家人都很开心。", "explanation": "这里应该用〈喜悦〉。“不幸”指坏事，与“都很开心”的说法相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“一次不幸改变了他的一生”指一件坏事带来深远影响，与句意相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是能改变一生的事件，句中说的是一次经历。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：“星期一”是时间，不是能改变一生的事件。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是日用品，不是能改变一生的事件。"}], "explanations": {"不幸": "正确：“一次不幸改变了他的一生”指一件坏事带来深远影响，与句意相合。", "颜色": "语义：“颜色”不是能改变一生的事件，句中说的是一次经历。", "星期一": "语义：“星期一”是时间，不是能改变一生的事件。", "拖鞋": "语义：“拖鞋”是日用品，不是能改变一生的事件。"}, "sentence_index": 6, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抓住了这次不幸。", "explanation": "这里应该用〈机会〉。“抓住”搭配机会、好的时机，不搭配“不幸”。"}, {"text": "我们送去了不幸。", "explanation": "这里应该用〈祝福〉。“送去”的是美好的东西，“不幸”是坏事，不能送去。"}, {"text": "我们为他的不幸庆祝了一番。", "explanation": "这里应该用〈成功〉。“庆祝”用于值得高兴的事，“不幸”不能被庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位不幸让村子里的人都很难过。", "corrected_sentence": "一场不幸让村子里的人都很难过。", "error_description": "“不幸”指事件，量词应用“场”或“次”；“位”只用于人，不能修饰“不幸”，应为“一场不幸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一次很不幸改变了我们全家的生活。", "corrected_sentence": "一次不幸改变了我们全家的生活。", "error_description": "“不幸”作名词时不能受程度副词“很”修饰；应去掉“很”，为“一次不幸改变了我们全家的生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
