INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92287, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "校区是学校里分开的一片地方。", "primary_collocate": null, "pronunciation": "xiào qū", "ipa": "ɕiaʊ˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个校区里有教学楼和操场。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南校区只有一栋楼，比较小。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校区门口有一家小书店。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在校区里骑车，骑得很快。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个校区中间隔着一条河。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校区里不让开车进来。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个校区新种了很多花。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的校区晚上很安静。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到北校区的图书馆门口等我。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个校区分成两部分，一边上课，一边住宿。", "target_word": "校区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新校区", "label": "复合词"}, {"form": "老校区", "label": "复合词"}], "register": "中性", "sense_fingerprint": "学校内部分隔出来的一片区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8aeb2b26-e9ce-46b7-b437-2984eb43064b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：房间装不下教学楼和操场，这种空间关系不成立。"}, {"text": "校区", "is_correct": true, "explanation": "「校区」指学校内分隔出的一片地方，可以容纳教学楼和操场。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是住宿的楼，不能容纳整个操场，与句意不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包装不下教学楼和操场，句子不通。"}], "explanations": {"房间": "语义：房间装不下教学楼和操场，这种空间关系不成立。", "校区": "「校区」指学校内分隔出的一片地方，可以容纳教学楼和操场。", "宿舍": "语义：宿舍是住宿的楼，不能容纳整个操场，与句意不符。", "书包": "语义：书包装不下教学楼和操场，句子不通。"}, "sentence_index": 0, "correct_answer": "校区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个校区很聪明，每次考试都得第一名。", "explanation": "这里表示人的智力和考试成绩，校区是场所，不能有智力，所以不能这样用。"}, {"text": "这个校区很好吃，我又买了一碗。", "explanation": "这里说的是食物的味道，校区是学校的地方，不能吃，这个词不这么用。"}, {"text": "这个校区去年结了婚，大家都很高兴。", "explanation": "这里说的是人结婚，校区是地方，不能作结婚的主语，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包不能种花，与「新种了很多花」的对象不符。"}, {"text": "校区", "is_correct": true, "explanation": "「校区」是学校内的一片地方，可以种花，句意自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能种花，与「新种」的动作和对象矛盾。"}, {"text": "教材", "is_correct": false, "explanation": "搭配：「教材」与「种」不搭配，不能作为种花的场所。"}], "explanations": {"书包": "语义：书包不能种花，与「新种了很多花」的对象不符。", "校区": "「校区」是学校内的一片地方，可以种花，句意自然。", "冰箱": "语义：冰箱不能种花，与「新种」的动作和对象矛盾。", "教材": "搭配：「教材」与「种」不搭配，不能作为种花的场所。"}, "sentence_index": 6, "correct_answer": "校区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个校区每天有很多列车进出，站台上挤满了旅客。", "explanation": "这里应该用〈火车站〉。校区是学习的地方，不是列车进出的车站，这个词不这么用。"}, {"text": "这个校区关了很多犯人，门口有很多警察。", "explanation": "这里应该用〈监狱〉。校区是学习的地方，不能用来关押犯人。"}, {"text": "这个校区每天有很多货船靠岸，工人们忙着卸货。", "explanation": "这里应该用〈码头〉。校区是学校的地方，不会有货船靠岸，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只校区里有一座很大的图书馆。", "corrected_sentence": "这个校区里有一座很大的图书馆。", "error_description": "错误形式：「这只校区」；正确形式：「这个校区」。「只」是动物的量词，校区应用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校的这个区校有一个很大的操场。", "corrected_sentence": "我们学校的这个校区有一个很大的操场。", "error_description": "错误形式：「区校」；正确形式：「校区」。「校区」是固定的词序，颠倒后不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b532cfdb-8fab-49d0-96f5-809076db3b42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
