INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "他者是除了你自己以外的别的人。", "primary_collocate": null, "pronunciation": "tā zhě", "ipa": "tʰa˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "不要总是批评他者，先看看自己。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很在意他者对她的看法。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不请求他者帮忙。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该学会尊重他者。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定前，要想想会不会伤害他者。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢独处，不愿被他者打扰。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把功劳都给了他者，自己什么也不要。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以相信自己，但也要听听他者的意见。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她帮助他者，也让自己很快乐。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤独的人常常觉得他者离自己很远。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指除自己以外的别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92289, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他者", "is_correct": true, "explanation": "“他者”指除自己以外的别人，符合“批评别人”的句意。"}, {"text": "石子", "is_correct": false, "explanation": "语义：“石子”是无生命的物体，不能被批评，与句中“批评”的对象不搭。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“批评”通常针对人的言行，“树叶”不能作为批评的对象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”是自然环境，无法构成“批评”的对象，与后半句也不呼应。"}], "explanations": {"他者": "“他者”指除自己以外的别人，符合“批评别人”的句意。", "石子": "语义：“石子”是无生命的物体，不能被批评，与句中“批评”的对象不搭。", "树叶": "搭配：“批评”通常针对人的言行，“树叶”不能作为批评的对象。", "空气": "语义：“空气”是自然环境，无法构成“批评”的对象，与后半句也不呼应。"}, "sentence_index": 0, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在路上遇到一位他者，他向我问路。", "explanation": "这里应该用〈陌生人〉。他者是抽象概括的书面用语，不用来指称路上遇到的具体某人。"}, {"text": "我的手机被他者摔坏了。", "explanation": "这里应该用〈别人〉。他者不用于描述具体的事件，口语中要用“别人”。"}, {"text": "我的他者每天都陪我去公园散步。", "explanation": "这里应该用〈同伴〉。他者是抽象概括的书面用语，不用来指称每天陪我去公园的具体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他者", "is_correct": true, "explanation": "“他者”指自己以外的别人，符合“把功劳给了别人”的句意。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：“秋天”是季节，不能接受“功劳”，与前文的“给”不搭。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：“给”的对象一般是人或机构，课桌不能受赠功劳。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是物品，不能接受“功劳”，与“给”的对象不搭。"}], "explanations": {"他者": "“他者”指自己以外的别人，符合“把功劳给了别人”的句意。", "秋天": "语义：“秋天”是季节，不能接受“功劳”，与前文的“给”不搭。", "课桌": "搭配：“给”的对象一般是人或机构，课桌不能受赠功劳。", "窗帘": "语义：“窗帘”是物品，不能接受“功劳”，与“给”的对象不搭。"}, "sentence_index": 6, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天早上给他者做早饭。", "explanation": "这里应该用〈全家〉。他者是抽象概括的书面用语，不用来指称家庭成员。"}, {"text": "学长帮我解答了问题，他者真热心。", "explanation": "这里应该用〈他〉。他者是抽象概括的书面用语，不用来指代前文已提到的具体的人，此处应说“他”。"}, {"text": "我的朋友今天生日，他者很开心。", "explanation": "这里应该用〈他〉。他者是抽象概括的书面用语，不用来指代前文已提到的具体的人，此处应说“他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是把自己的想法强加在他者。", "corrected_sentence": "他总是把自己的想法强加给他者。", "error_description": "“强加”的对象要用“给”引出，应说“强加给他者”，不能说“强加在他者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孤独的人需要一只他者的陪伴。", "corrected_sentence": "孤独的人需要他者的陪伴。", "error_description": "“他者”指人，量词“只”用于动物，这里应去掉“一只”，直接说“他者的陪伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
