INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自己以外的人或事物；他人。", "primary_collocate": null, "pronunciation": "tā zhě", "ipa": "tʰa˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们不能只想自己，也要想到他者。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在哲学课上，老师讲了自我和他者的关系。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他者的看法有时能帮助我们认识自己。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人需要他者，才能知道自己是谁。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家常常写自我与他者的矛盾。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要尊重他者，不要只看重自己。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在和他者相处中慢慢长大。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他者的理解让这个社会更温暖。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不关心他者，只在意自己的利益。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化交流让我们更了解他者。", "target_word": "他者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "哲学、文化语境中指自我以外的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他者", "is_correct": true, "explanation": "“他者”指自己以外的人，与“自己”形成对比，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能与“自己”相对，句意要求的是自己以外的人。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：“蚊子”不是需要人们顾及的对象，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不是人或他人的概念，无法与“自己”形成对比。"}], "explanations": {"他者": "“他者”指自己以外的人，与“自己”形成对比，符合句意。", "石头": "语义：“石头”是无生命的物体，不能与“自己”相对，句意要求的是自己以外的人。", "蚊子": "语义：“蚊子”不是需要人们顾及的对象，句意不通。", "窗户": "语义：“窗户”是建筑部件，不是人或他人的概念，无法与“自己”形成对比。"}, "sentence_index": 0, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他者今天来我家玩了。", "explanation": "这里应该用〈他〉。他者是书面用语，指自我以外的人或事物的抽象概括，不用来指称某个具体的人。"}, {"text": "我的钱被他者偷走了。", "explanation": "这里应该用〈别人〉。他者用于抽象概括，描述具体的偷窃事件时要用“别人”。"}, {"text": "他者每天都帮我带早饭，我很感激。", "explanation": "这里应该用〈同学〉。他者是抽象概括的书面用语，不用来指称每天帮我带早饭的具体的人，应说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他者", "is_correct": true, "explanation": "“他者”指自己以外的人，在“相处”的语境中符合句意。"}, {"text": "教育", "is_correct": false, "explanation": "搭配：“相处”的对象应是人或动物，“教育”是抽象的行为，不能与之相处。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是无生命的物件，不能成为“相处中慢慢长大”的对象。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体材料，不能与孩子相处并在相处中成长。"}], "explanations": {"他者": "“他者”指自己以外的人，在“相处”的语境中符合句意。", "教育": "搭配：“相处”的对象应是人或动物，“教育”是抽象的行为，不能与之相处。", "家具": "语义：家具是无生命的物件，不能成为“相处中慢慢长大”的对象。", "墨水": "语义：墨水是液体材料，不能与孩子相处并在相处中成长。"}, "sentence_index": 6, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起去他者家吃饭吧。", "explanation": "这里应该用〈邻居〉。他者不用来指称具体的人家或地点，口语中要说“邻居家”。"}, {"text": "我的他者帮我修好了电脑。", "explanation": "这里应该用〈同事〉。“他者”不能与“我的”搭配指称熟人，表示工作关系要用“同事”。"}, {"text": "我每天和他者一起吃饭。", "explanation": "这里应该用〈家人〉。他者是抽象概括的书面用语，不能指称每天一起吃饭的具体家庭成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该尊重对他者的不同。", "corrected_sentence": "我们应该尊重他者的不同。", "error_description": "“尊重”是及物动词，直接带宾语“他者的不同”，不能加“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要学会理解一只他者的处境。", "corrected_sentence": "我们要学会理解他者的处境。", "error_description": "“他者”指人，量词“只”用于动物，这里应去掉“一只”，直接说“他者的处境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
