INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "案子是要查清楚的一件事。", "primary_collocate": null, "pronunciation": "àn zi", "ipa": "an˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "警察正在查这个案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子很复杂，还没查清楚。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天接了一个新案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子已经查了三个月。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老警察一直想着那个旧案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "案子还没有结果，大家都在等。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责的案子越来越多。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子的线索太少了。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把案子的情况告诉了队长。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这个案子，他三天没回家。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个案子", "label": "量词"}, {"form": "一件案子", "label": "量词"}], "register": "口语", "sense_fingerprint": "警方或有关人员要调查弄清楚的一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "案子", "is_correct": true, "explanation": "正确答案：“案子”指需要调查的事件，警察正在查的就是它。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”用来逗乐，不是需要调查的事，与“警察正在查”不合。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”是用来欣赏的景色，不是警察要调查的事，与“警察正在查”不合。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是纪念日，不是警察要调查的对象。"}], "explanations": {"案子": "正确答案：“案子”指需要调查的事件，警察正在查的就是它。", "笑话": "语义：“笑话”用来逗乐，不是需要调查的事，与“警察正在查”不合。", "风景": "语义：“风景”是用来欣赏的景色，不是警察要调查的事，与“警察正在查”不合。", "生日": "语义：“生日”是纪念日，不是警察要调查的对象。"}, "sentence_index": 0, "correct_answer": "案子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做的这个案子特别好吃。", "explanation": "这里应该用〈菜〉。“案子”指需要查清的事件，不能指做好的食物，所以不能说好吃。"}, {"text": "我们的婚礼是一个案子，大家都很开心。", "explanation": "“案子”指需要调查处理的事件，婚礼是喜事，这里不能用。"}, {"text": "他第一次当爸爸，这个案子让他很高兴。", "explanation": "“案子”指需要查清的事件，当爸爸是家庭中的喜事，这里不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "案子", "is_correct": true, "explanation": "正确答案：“负责的案子”指她经手处理的事件，越来越多符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是可以“负责”的事项，与这句不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能被“负责”，与这句语境不合。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”说“越来越快”，不说“越来越多”。"}], "explanations": {"案子": "正确答案：“负责的案子”指她经手处理的事件，越来越多符合句意。", "石头": "语义：“石头”不是可以“负责”的事项，与这句不合。", "月亮": "语义：“月亮”不能被“负责”，与这句语境不合。", "脚步": "搭配：“脚步”说“越来越快”，不说“越来越多”。"}, "sentence_index": 6, "correct_answer": "案子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸把这个案子送给了我当生日礼物。", "explanation": "这里应该用〈礼物〉。“案子”指需要查清的事件，不能拿来当礼物送人。"}, {"text": "我的案子是个很好的朋友，常常陪我聊天。", "explanation": "“案子”指事件，不指人，这里不能用来称呼朋友。"}, {"text": "我们约好在案子门口见面。", "explanation": "“案子”指事件，不是场所，这里不能用来指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月接了三只案子。", "corrected_sentence": "他这个月接了三个案子。", "error_description": "错误：“三只案子”；正确：“三个案子”。案子不用动物量词“只”，应用“个”或“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这台案子查清楚了。", "corrected_sentence": "他把这个案子查清楚了。", "error_description": "错误：“这台案子”；正确：“这个案子”。“台”是机器、车辆等的量词，案子应用“个”或“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
