INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "诉讼或需要调查处理的事件。", "primary_collocate": null, "pronunciation": "àn zi", "ipa": "an˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "律师今天要去法院办一个案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子明天开庭。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官还在看这个案子的材料。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是律师，手里有三个案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子终于有结果了。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想接一个简单的案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打赢了这个案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子要交给法院来处理。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人办完了那个大案子。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子在网上引起了很多人的关注。", "target_word": "案子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个案子", "label": "量词"}, {"form": "一件案子", "label": "量词"}], "register": "口语", "sense_fingerprint": "律师、法官处理的诉讼事件，常与开庭、办、打赢搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "案子", "is_correct": true, "explanation": "正确答案：“办一个案子”指律师处理诉讼案件，与“去法院”相符。"}, {"text": "派对", "is_correct": false, "explanation": "语义：“派对”是聚会娱乐，与“去法院”的场合不合。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“办”不说“办钱包”，钱包应说“买”。"}, {"text": "舞会", "is_correct": false, "explanation": "语义：“舞会”与法院的场合不合，律师不会去法院办舞会。"}], "explanations": {"案子": "正确答案：“办一个案子”指律师处理诉讼案件，与“去法院”相符。", "派对": "语义：“派对”是聚会娱乐，与“去法院”的场合不合。", "钱包": "搭配：“办”不说“办钱包”，钱包应说“买”。", "舞会": "语义：“舞会”与法院的场合不合，律师不会去法院办舞会。"}, "sentence_index": 0, "correct_answer": "案子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在院子里种了一个案子，每天浇水。", "explanation": "这里的“案子”不是植物，不能用“种”和“浇水”来说；“案子”指诉讼或要调查处理的事件。"}, {"text": "这个案子是他最喜欢的小说。", "explanation": "“案子”指诉讼中要处理的事件，小说不是，这里不能用。"}, {"text": "我们约好在案子楼下碰面。", "explanation": "“案子”指事件，不是场所，这里不能用来指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "案子", "is_correct": true, "explanation": "正确答案：“打赢了这个案子”指打赢诉讼，与句意相符。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”不说“打赢”，应说“考过”或“通过”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”不能被“打赢”，与句意不合。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不是官司或比赛，不能说“打赢”。"}], "explanations": {"案子": "正确答案：“打赢了这个案子”指打赢诉讼，与句意相符。", "考试": "搭配：“考试”不说“打赢”，应说“考过”或“通过”。", "蛋糕": "语义：“蛋糕”不能被“打赢”，与句意不合。", "电影": "语义：“电影”不是官司或比赛，不能说“打赢”。"}, "sentence_index": 6, "correct_answer": "案子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去超市买了两个案子，准备回家做饭。", "explanation": "这里应该用〈菜〉。“案子”指诉讼或要调查处理的事件，不指可以买的食材。"}, {"text": "这个案子是我最好的朋友，常常陪我聊天。", "explanation": "“案子”指事件，不指人，这里不能用来称呼朋友。"}, {"text": "他今天穿了一件新案子去上班。", "explanation": "这里应该用〈衣服〉。“案子”指要处理的事件，不能指可以穿的衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "律师法院办这个案子，很辛苦。", "corrected_sentence": "律师在法院办这个案子，很辛苦。", "error_description": "错误：“律师法院办这个案子”；正确：“律师在法院办这个案子”。表示地点的“在法院”要用介词“在”引出，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一共打赢了两只案子。", "corrected_sentence": "他们一共打赢了两个案子。", "error_description": "错误：“两只案子”；正确：“两个案子”。案子不用动物量词“只”，应用“个”或“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
