INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92295, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "正常工作是像平时一样做事，没有出问题。", "primary_collocate": null, "pronunciation": "zhèng cháng gōng zuò", "ipa": "tʂɤŋ˥˩ tʂʰɑŋ˧˥ kʊŋ˥ tswo˥˩", "syllable_count": 4, "sentences": [{"text": "医生说我明天可以正常工作了。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他感冒好了，今天能正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪的时候，大家还是要正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放假以前，公司要求我们正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她睡不好觉，第二天没法正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "就算家里有事，他也想正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说，生病时不用勉强自己正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，医院的医生仍然正常工作着。", "target_word": "正常工作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经休息过一周，下周开始正常工作。", "target_word": "正常工作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天按时上下班，一直在正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "正常工作了", "label": "了体"}, {"form": "正常工作着", "label": "着体"}], "register": "中性", "sense_fingerprint": "人像平时一样上班做事，不受影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正常工作", "is_correct": true, "explanation": "正确：“医生说我明天可以正常工作了”中，正常工作表示恢复上班，符合医生的许可。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“可以发烧了”与医生允许上班的意思相反，不合常理。"}, {"text": "开花", "is_correct": false, "explanation": "语义：人不会“开花”，“我明天可以开花了”句意不通。"}, {"text": "脸红", "is_correct": false, "explanation": "体貌：“脸红”描写脸色，不是能否上班的状态。"}], "explanations": {"正常工作": "正确：“医生说我明天可以正常工作了”中，正常工作表示恢复上班，符合医生的许可。", "发烧": "语义：“可以发烧了”与医生允许上班的意思相反，不合常理。", "开花": "语义：人不会“开花”，“我明天可以开花了”句意不通。", "脸红": "体貌：“脸红”描写脸色，不是能否上班的状态。"}, "sentence_index": 0, "correct_answer": "正常工作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放假以前，学校的学生都要正常工作。", "explanation": "这里应该用〈学习〉。正常工作指成年人上班做事，学生应说正常学习。"}, {"text": "这次考试，他的成绩正常工作。", "explanation": "这里应该用〈正常发挥〉。“正常工作”指人上班做事或机器运转，考试表现应说“正常发挥”。"}, {"text": "这只猫每天正常工作。", "explanation": "这里应该用〈正常生活〉。正常工作指人上班做事或机器运转，猫应说正常生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正常工作", "is_correct": true, "explanation": "正确：“不用勉强自己正常工作”指生病时不必硬撑着上班，符合语境。"}, {"text": "痊愈", "is_correct": false, "explanation": "语义：“痊愈”指病好了，不能说“不用勉强自己痊愈”，句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”必须带宾语，“不用勉强自己送”说不完整。"}, {"text": "脸色变白", "is_correct": false, "explanation": "体貌：“脸色变白”描写气色，不是可以勉强去做的事。"}], "explanations": {"正常工作": "正确：“不用勉强自己正常工作”指生病时不必硬撑着上班，符合语境。", "痊愈": "语义：“痊愈”指病好了，不能说“不用勉强自己痊愈”，句意不通。", "送": "配价：“送”必须带宾语，“不用勉强自己送”说不完整。", "脸色变白": "体貌：“脸色变白”描写气色，不是可以勉强去做的事。"}, "sentence_index": 6, "correct_answer": "正常工作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子每天都正常工作，不用上学。", "explanation": "这里应该用〈学习〉。正常工作指成年人上班做事，孩子应说正常学习。"}, {"text": "这盆花每天正常工作。", "explanation": "这里应该用〈正常生长〉。正常工作只用于人上班做事或机器运转，花应说正常生长。"}, {"text": "这本书一直正常工作。", "explanation": "这里应该用〈正常使用〉。正常工作只用于人上班做事或机器运转，书应说正常使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她病好以后就能了正常工作。", "corrected_sentence": "她病好以后就能正常工作。", "error_description": "“了”不能插在助动词“能”和“正常工作”之间，应去掉这个“了”，说“就能正常工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "手术之后，他已经被正常工作了。", "corrected_sentence": "手术之后，他已经可以正常工作了。", "error_description": "“正常工作”是不及物的动词短语，不能加“被”构成被动句；应说“可以正常工作了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
