INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按正常情况进行的工作；运转无误。", "primary_collocate": null, "pronunciation": "zhèng cháng gōng zuò", "ipa": "tʂɤŋ˥˩ tʂʰɑŋ˧˥ kʊŋ˥ tswo˥˩", "syllable_count": 4, "sentences": [{"text": "这台电脑修好了，现在能正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停电以后，冰箱不能正常工作了。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器太旧，已经没法正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电时，这个软件不会正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查完以后，工人让机器重新正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络太慢，网站没有正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调一直正常工作着，房间很凉快。", "target_word": "正常工作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师说，新系统已经正常工作了一个月。", "target_word": "正常工作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，红绿灯也要正常工作。", "target_word": "正常工作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里的机器必须二十四小时正常工作。", "target_word": "正常工作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正常工作了", "label": "了体"}, {"form": "正常工作着", "label": "着体"}], "register": "中性", "sense_fingerprint": "机器、设备或系统运转无误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正常工作", "is_correct": true, "explanation": "正确：“这台电脑修好了，现在能正常工作”中，正常工作表示运转无误，符合语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：电脑修好以后不能说“能唱歌”，与“修好”的语境不符。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：电脑不会“发愁”，“能发愁”与句意不通。"}, {"text": "脸红", "is_correct": false, "explanation": "体貌：电脑没有脸，不能说“脸红”。"}], "explanations": {"正常工作": "正确：“这台电脑修好了，现在能正常工作”中，正常工作表示运转无误，符合语境。", "唱歌": "语义：电脑修好以后不能说“能唱歌”，与“修好”的语境不符。", "发愁": "语义：电脑不会“发愁”，“能发愁”与句意不通。", "脸红": "体貌：电脑没有脸，不能说“脸红”。"}, "sentence_index": 0, "correct_answer": "正常工作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河一直正常工作。", "explanation": "这里应该用〈正常流动〉。正常工作用于机器、系统运转无误，河水应说正常流动。"}, {"text": "这首歌一直正常工作。", "explanation": "这里应该用〈正常播放〉。正常工作用于机器、系统运转无误，歌曲应说正常播放。"}, {"text": "这条路正常工作。", "explanation": "这里应该用〈正常通行〉。正常工作用于机器、系统运转无误，道路应说正常通行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正常工作", "is_correct": true, "explanation": "正确：“空调一直正常工作着，房间很凉快”中，正常工作着表示空调运转正常，符合语境。"}, {"text": "制热", "is_correct": false, "explanation": "语义：制热会让房间变热，与“房间很凉快”矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：空调不会“散步”，搭配与句意不通。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”说的是人的体型，不能用于空调。"}], "explanations": {"正常工作": "正确：“空调一直正常工作着，房间很凉快”中，正常工作着表示空调运转正常，符合语境。", "制热": "语义：制热会让房间变热，与“房间很凉快”矛盾。", "散步": "语义：空调不会“散步”，搭配与句意不通。", "发胖": "体貌：“发胖”说的是人的体型，不能用于空调。"}, "sentence_index": 6, "correct_answer": "正常工作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩一直正常工作。", "explanation": "这里应该用〈正常上学〉。正常工作指机器运转无误，孩子应说正常上学。"}, {"text": "这只小狗每天正常工作。", "explanation": "这里应该用〈正常活动〉。正常工作指机器运转无误，小狗应说正常活动。"}, {"text": "这本书一直正常工作。", "explanation": "这里应该用〈正常使用〉。正常工作指机器运转无误，书应说正常使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修理以后，这台打印机又能了正常工作。", "corrected_sentence": "修理以后，这台打印机又能正常工作。", "error_description": "“了”不能插在助动词“能”和“正常工作”之间，应去掉这个“了”，说“又能正常工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修理以后，这台机器被正常工作了。", "corrected_sentence": "修理以后，这台机器又开始正常工作了。", "error_description": "“正常工作”是不及物的动词短语，不能加“被”构成被动句；应说“开始正常工作了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
