INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92298, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "两个（后面直接接名词，不带量词）。", "primary_collocate": null, "pronunciation": "liǎ", "ipa": "lja˨˩˦", "syllable_count": 1, "sentences": [{"text": "我买了俩面包，一个给你，另一个我自己吃。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有俩苹果。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "给我俩鸡蛋就行。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰箱里只剩俩西红柿了。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我口袋里只有俩硬币。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给了我俩橘子。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他养了俩小猫，一只是黑的，另一只是白的。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请再给我俩杯子。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "墙上挂着俩大灯笼。", "target_word": "俩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里还有俩饺子，你吃吧。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱俩", "label": "复合"}, {"form": "俩人", "label": "复合"}], "register": "口语", "sense_fingerprint": "直接放在名词前表示“两个”，不再带量词，如“俩苹果”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de07174-1492-4745-93ea-22bca513f5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92298, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩 liǎ 表示两个，是本词的读音和意思。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn（第三声）与 liǎ 韵母不同（多了 -n），意思是脸，与数量无关。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是假，与数量无关。"}, {"text": "柳", "is_correct": false, "explanation": "liǔ（第三声）与 liǎ 韵母不同（u 与 a），意思是柳树。"}], "explanations": {"俩": "俩 liǎ 表示两个，是本词的读音和意思。", "脸": "liǎn（第三声）与 liǎ 韵母不同（多了 -n），意思是脸，与数量无关。", "假": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是假，与数量无关。", "柳": "liǔ（第三声）与 liǎ 韵母不同（u 与 a），意思是柳树。"}, "sentence_index": null, "correct_answer": "俩"}, "level_3": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩表示两个，直接修饰名词、不带量词，符合句意。"}, {"text": "一个", "is_correct": false, "explanation": "语义：“一个面包”只有一个，与后句“一个给你”暗含的多个面包相冲突。"}, {"text": "三个", "is_correct": false, "explanation": "语义：三个与“俩”表示的两个不符。"}, {"text": "仨", "is_correct": false, "explanation": "语义：仨表示三，与“俩”表示的两个不符。"}], "explanations": {"俩": "俩表示两个，直接修饰名词、不带量词，符合句意。", "一个": "语义：“一个面包”只有一个，与后句“一个给你”暗含的多个面包相冲突。", "三个": "语义：三个与“俩”表示的两个不符。", "仨": "语义：仨表示三，与“俩”表示的两个不符。"}, "sentence_index": 0, "correct_answer": "俩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰箱里只剩俩西红柿，已经空空如也。", "explanation": "“只剩俩”与“空空如也”矛盾，“俩”表示尚有两个。"}, {"text": "冰箱里只剩俩西红柿了，一个也没有。", "explanation": "“只剩俩”表示还有两个，与“一个也没有”矛盾。"}, {"text": "冰箱里只剩俩西红柿了，买来时就只有一个。", "explanation": "“只剩俩”与“买来时只有一个”矛盾，“俩”表示两个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92298, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩 liǎ 表示两个，是本词的读音和意思。"}, {"text": "咧", "is_correct": false, "explanation": "liě（第三声）与 liǎ 韵母不同（e 与 a），意思是咧嘴。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）比 liǎ 少了韵母 a，声调相同，意思是里面。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是甲。"}], "explanations": {"俩": "俩 liǎ 表示两个，是本词的读音和意思。", "咧": "liě（第三声）与 liǎ 韵母不同（e 与 a），意思是咧嘴。", "里": "lǐ（第三声）比 liǎ 少了韵母 a，声调相同，意思是里面。", "甲": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是甲。"}, "sentence_index": null, "correct_answer": "俩"}, "level_3": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩表示两个，直接修饰名词，符合句意。"}, {"text": "一只", "is_correct": false, "explanation": "语义：一只只是一只，与“俩”表示的两个不符。"}, {"text": "三只", "is_correct": false, "explanation": "语义：三只与“俩”表示的两个不符。"}, {"text": "仨", "is_correct": false, "explanation": "语义：仨表示三个，与后句“一只…另一只”所示的两只不符。"}], "explanations": {"俩": "俩表示两个，直接修饰名词，符合句意。", "一只": "语义：一只只是一只，与“俩”表示的两个不符。", "三只": "语义：三只与“俩”表示的两个不符。", "仨": "语义：仨表示三个，与后句“一只…另一只”所示的两只不符。"}, "sentence_index": 6, "correct_answer": "俩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "盘子里还有俩饺子，三个人都吃完了。", "explanation": "“还有俩饺子”与“都吃完了”矛盾，“俩”表示尚剩两个，不能说已全部吃完。"}, {"text": "盘子里还有俩饺子，我刚才全都吃光了。", "explanation": "“还有俩”与“全都吃光了”矛盾，“俩”表示尚剩两个。"}, {"text": "盘子里还有俩饺子，一个都没有。", "explanation": "“还有俩饺子”与“一个都没有”矛盾，“俩”表示两个，不能指零个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了俩个橘子，一个给你。", "corrected_sentence": "我买了俩橘子，一个给你。", "error_description": "错误形式：“俩个”；正确形式：“俩”。“俩”已表示两个，后面不能再加量词“个”，应说“俩橘子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家养了俩的小猫，很可爱。", "corrected_sentence": "他家养了俩小猫，很可爱。", "error_description": "错误形式：“俩的小猫”；正确形式：“俩小猫”。“俩”后面直接接名词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf3163b9-8689-4a32-a9b8-c52170b702b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
