INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "步伐是走路时一步一步的样子。", "primary_collocate": null, "pronunciation": "bù fá", "ipa": "pu˥˩ fa˧˥", "syllable_count": 2, "sentences": [{"text": "他的步伐很轻，像猫一样。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的步伐慢慢的，很稳。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一听他的步伐，就知道是爸爸回来了。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们的步伐整齐有力。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走路时步伐轻快，看起来很高兴。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子的步伐不大，我们走得很慢。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝多了，步伐有点乱。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，步伐要小一点。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着高跟鞋，步伐很慢，走得很小心。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍走过广场，步伐一致。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "走路时一步一步的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不凡", "is_correct": false, "explanation": "不凡 bù fán 与步伐 bù fá 韵尾不同（-án 与 -á），意思是不平凡。"}, {"text": "补发", "is_correct": false, "explanation": "补发 bǔ fā 与步伐 bù fá 两个音节声调都不同（bǔ 第三声、fā 第一声），意思是事后补着发给，如补发工资。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐 bù fá：走路时一步一步的样子，即本题所听的词。"}, {"text": "步法", "is_correct": false, "explanation": "步法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是脚步的动作方法。"}, {"text": "不符", "is_correct": false, "explanation": "不符 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不相符。"}], "explanations": {"不凡": "不凡 bù fán 与步伐 bù fá 韵尾不同（-án 与 -á），意思是不平凡。", "补发": "补发 bǔ fā 与步伐 bù fá 两个音节声调都不同（bǔ 第三声、fā 第一声），意思是事后补着发给，如补发工资。", "步伐": "步伐 bù fá：走路时一步一步的样子，即本题所听的词。", "步法": "步法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是脚步的动作方法。", "不符": "不符 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不相符。"}, "sentence_index": null, "correct_answer": "步伐"}, "level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情，不指走路的样子。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐：走路时脚步的样子，与“很轻”“像猫一样”相合。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“眼神”不能说“很轻”，与句中“很轻”不搭配。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体的高矮，不能用“很轻”描述。"}], "explanations": {"性格": "语义：“性格”指人的性情，不指走路的样子。", "步伐": "步伐：走路时脚步的样子，与“很轻”“像猫一样”相合。", "眼神": "搭配：“眼神”不能说“很轻”，与句中“很轻”不搭配。", "身高": "体貌：“身高”是身体的高矮，不能用“很轻”描述。"}, "sentence_index": 0, "correct_answer": "步伐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪地上留下了一串步伐。", "explanation": "这里应该用〈脚印〉。走路留下的痕迹叫脚印，步伐指走路时步子的样子。"}, {"text": "从家到学校的步伐有两公里。", "explanation": "这里应该用〈距离〉。步伐指走路时一步一步的样子，不能用来计量路程，两地之间的长度要用距离。"}, {"text": "这首歌的步伐很快，听起来很有活力。", "explanation": "这里应该用〈节拍〉。歌曲的快慢要用节拍，步伐指人走路的步子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92299, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不服", "is_correct": false, "explanation": "不服 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不服气、不服从。"}, {"text": "不法", "is_correct": false, "explanation": "不法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是违法。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐 bù fá：走路时一步一步的样子，即本题所听的词。"}, {"text": "不防", "is_correct": false, "explanation": "不防 bù fáng 与步伐 bù fá 韵尾不同（-áng 与 -á），意思是没有防备。"}, {"text": "不发", "is_correct": false, "explanation": "不发 bù fā 与步伐 bù fá 第二音节声调不同（fā 第一声与 fá 第二声），意思是不发出、不说出，如“不发一言”。"}], "explanations": {"不服": "不服 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不服气、不服从。", "不法": "不法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是违法。", "步伐": "步伐 bù fá：走路时一步一步的样子，即本题所听的词。", "不防": "不防 bù fáng 与步伐 bù fá 韵尾不同（-áng 与 -á），意思是没有防备。", "不发": "不发 bù fā 与步伐 bù fá 第二音节声调不同（fā 第一声与 fá 第二声），意思是不发出、不说出，如“不发一言”。"}, "sentence_index": null, "correct_answer": "步伐"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能说“有点乱”，与句意不符。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐：走路的样子，与“喝多了”相合，指走路不稳。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的重量，不能用“有点乱”描述。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指出生的日子，与喝酒后的状态无关。"}], "explanations": {"年龄": "语义：“年龄”指岁数，不能说“有点乱”，与句意不符。", "步伐": "步伐：走路的样子，与“喝多了”相合，指走路不稳。", "体重": "体貌：“体重”是身体的重量，不能用“有点乱”描述。", "生日": "语义：“生日”指出生的日子，与喝酒后的状态无关。"}, "sentence_index": 6, "correct_answer": "步伐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的步伐很高，先放一会儿再喝。", "explanation": "这里应该用〈温度〉。步伐指走路时一步一步的样子，水的冷热要用温度。"}, {"text": "这个箱子的步伐很大，放不进车里。", "explanation": "这里应该用〈体积〉。箱子的大小要用体积，步伐指走路时一步一步的样子。"}, {"text": "这件衣服的步伐很鲜艳，穿出去很显眼。", "explanation": "这里应该用〈颜色〉。衣服的色彩要用颜色，步伐指走路的步子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他迈着一只轻快的步伐走进教室。", "corrected_sentence": "他迈着轻快的步伐走进教室。", "error_description": "量词错误：“步伐”不能用量词“只”（“只”多用于动物或个体物件），“迈着……步伐”中不用量词。正确说法是“迈着轻快的步伐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他迈着沉稳地步伐走进屋里。", "corrected_sentence": "他迈着沉稳的步伐走进屋里。", "error_description": "结构助词错误：修饰名词“步伐”要用“的”，不能用“地”（“地”用于动词前）。正确说法是“沉稳的步伐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
