INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻事情进行的速度和节奏。", "primary_collocate": null, "pronunciation": "bù fá", "ipa": "pu˥˩ fa˧˥", "syllable_count": 2, "sentences": [{"text": "公司加快了发展的步伐。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革的步伐不能太慢。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要跟上时代的步伐。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市建设的步伐越来越快。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按自己的步伐学习，不着急。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家放慢了经济增长的步伐。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组的工作步伐很稳，大家都不着急。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们加快了搬家的步伐，下周就要走了。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，农村种树的步伐加快了。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赶上其他国家，我们的步伐必须加快。", "target_word": "步伐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比喻事情进行的节奏、速度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "步伐", "is_correct": true, "explanation": "步伐 bù fá：走路时的步子，或事情进行的节奏，即本题所听的词。"}, {"text": "不服", "is_correct": false, "explanation": "不服 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不服气、不服从。"}, {"text": "补发", "is_correct": false, "explanation": "补发 bǔ fā 与步伐 bù fá 两个音节声调都不同（bǔ 第三声、fā 第一声），意思是补发，如补发工资。"}, {"text": "不法", "is_correct": false, "explanation": "不法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是违法。"}, {"text": "不防", "is_correct": false, "explanation": "不防 bù fáng 与步伐 bù fá 韵尾不同（-áng 与 -á），意思是没有防备。"}], "explanations": {"步伐": "步伐 bù fá：走路时的步子，或事情进行的节奏，即本题所听的词。", "不服": "不服 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不服气、不服从。", "补发": "补发 bǔ fā 与步伐 bù fá 两个音节声调都不同（bǔ 第三声、fā 第一声），意思是补发，如补发工资。", "不法": "不法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是违法。", "不防": "不防 bù fáng 与步伐 bù fá 韵尾不同（-áng 与 -á），意思是没有防备。"}, "sentence_index": null, "correct_answer": "步伐"}, "level_3": {"options": [{"text": "方向", "is_correct": false, "explanation": "搭配：“加快”说的是速度，不能修饰“方向”。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐：指事情进行的速度与节奏，与“加快”搭配，符合句意。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：“加快”不能用于“水平”，提高水平才是常见说法。"}, {"text": "目标", "is_correct": false, "explanation": "语义：“目标”指想要达到的终点，句中说的是发展进程的快慢。"}], "explanations": {"方向": "搭配：“加快”说的是速度，不能修饰“方向”。", "步伐": "步伐：指事情进行的速度与节奏，与“加快”搭配，符合句意。", "水平": "搭配：“加快”不能用于“水平”，提高水平才是常见说法。", "目标": "语义：“目标”指想要达到的终点，句中说的是发展进程的快慢。"}, "sentence_index": 0, "correct_answer": "步伐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车的步伐很大，停在门口占了半条街。", "explanation": "这里应该用〈体积〉。车身的大小要用体积，步伐指事情进行的速度和节奏，不指物体的大小。"}, {"text": "这家工厂的步伐很高，一天能做两千件。", "explanation": "这里应该用〈效率〉。步伐指进行的节奏，单位时间的产出要用效率。"}, {"text": "这份报告的步伐很长，共有二十页。", "explanation": "这里应该用〈篇幅〉。报告的长短和页数要用篇幅，步伐指走路时步子的快慢或事情进行的节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不凡", "is_correct": false, "explanation": "不凡 bù fán 与步伐 bù fá 韵尾不同（-án 与 -á），意思是不平凡。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐 bù fá：走路时的步子，或事情进行的节奏，即本题所听的词。"}, {"text": "不符", "is_correct": false, "explanation": "不符 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不相符。"}, {"text": "步法", "is_correct": false, "explanation": "步法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是脚步的动作方法。"}, {"text": "不发", "is_correct": false, "explanation": "不发 bù fā 与步伐 bù fá 第二音节声调不同（fā 第一声与 fá 第二声），意思是不发出、不说出，如“不发一言”。"}], "explanations": {"不凡": "不凡 bù fán 与步伐 bù fá 韵尾不同（-án 与 -á），意思是不平凡。", "步伐": "步伐 bù fá：走路时的步子，或事情进行的节奏，即本题所听的词。", "不符": "不符 bù fú 与步伐 bù fá 第二音节韵母不同（fú 与 fá），意思是不相符。", "步法": "步法 bù fǎ 与步伐 bù fá 第二音节声调不同（fǎ 第三声与 fá 第二声），意思是脚步的动作方法。", "不发": "不发 bù fā 与步伐 bù fá 第二音节声调不同（fā 第一声与 fá 第二声），意思是不发出、不说出，如“不发一言”。"}, "sentence_index": null, "correct_answer": "步伐"}, "level_3": {"options": [{"text": "口气", "is_correct": false, "explanation": "搭配：“口气”指说话的语气，不能说“工作口气”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情，不指工作的进行方式。"}, {"text": "步伐", "is_correct": true, "explanation": "步伐：指工作进行的节奏与速度，与“很稳”搭配，与“不着急”呼应。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的重量，不能用来形容工作。"}], "explanations": {"口气": "搭配：“口气”指说话的语气，不能说“工作口气”。", "性格": "语义：“性格”指人的性情，不指工作的进行方式。", "步伐": "步伐：指工作进行的节奏与速度，与“很稳”搭配，与“不着急”呼应。", "体重": "体貌：“体重”是身体的重量，不能用来形容工作。"}, "sentence_index": 6, "correct_answer": "步伐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生的步伐很高，老师很满意。", "explanation": "这里应该用〈水平〉。步伐指步子或事情进行的节奏，学生的学习能力要用水平。"}, {"text": "这块石头的步伐很重，两个人都搬不动。", "explanation": "这里应该用〈重量〉。石头的轻重要用重量，步伐指事情进行的速度和节奏，不指物体的轻重。"}, {"text": "这批产品的步伐很稳定，客户都很满意。", "explanation": "这里应该用〈质量〉。步伐指进行的节奏，产品的好坏要用质量来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司以一只稳健的步伐向前发展。", "corrected_sentence": "公司以稳健的步伐向前发展。", "error_description": "量词错误：“步伐”不能用量词“只”（“只”多用于动物或个体物件），这里不需要量词。正确说法是“以稳健的步伐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们搬家的步伐加快下来了，下周就要走了。", "corrected_sentence": "他们搬家的步伐加快起来了，下周就要走了。", "error_description": "补语错误：“加快”的趋向补语应用“起来”，说“加快起来”；“下来”多用于“慢下来”“停下来”，不能与“加快”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
