INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92301, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全市是一座城市的所有地方。", "primary_collocate": null, "pronunciation": "quán shì", "ipa": "tɕʰɥɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "全市的学校今天都放假了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜大雪，全市都白了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市有三百多个公园。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路是全市最长的路。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市的路今天都很堵。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走遍了全市的大小书店。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市只有一座大桥。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市的地铁线路都很方便。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店在全市都有名。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，全市到处都是花。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一座城市的所有地方，指范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92301, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市 quán shì：整座城市的所有地方。"}, {"text": "拳师", "is_correct": false, "explanation": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。"}, {"text": "全诗", "is_correct": false, "explanation": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。"}, {"text": "全史", "is_correct": false, "explanation": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}], "explanations": {"全市": "全市 quán shì：整座城市的所有地方。", "拳师": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。", "全诗": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。", "全史": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}, "sentence_index": null, "correct_answer": "全市"}, "level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指整座城市的范围，符合“学校放假”的语境。"}, {"text": "全身", "is_correct": false, "explanation": "语义：“全身”指人或动物的整个身体，学校不是身体的一部分。"}, {"text": "全家", "is_correct": false, "explanation": "语义：“全家”指一家人，不能用来修饰“学校”。"}, {"text": "全天", "is_correct": false, "explanation": "搭配：“全天”表示整天的时长，不指学校放假的地理范围，句意不通。"}], "explanations": {"全市": "全市指整座城市的范围，符合“学校放假”的语境。", "全身": "语义：“全身”指人或动物的整个身体，学校不是身体的一部分。", "全家": "语义：“全家”指一家人，不能用来修饰“学校”。", "全天": "搭配：“全天”表示整天的时长，不指学校放假的地理范围，句意不通。"}, "sentence_index": 0, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他全市都在疼。", "explanation": "这里应该用〈全身〉。〈全市〉指整座城市，不能用来指一个人的身体。"}, {"text": "这所大学的全市学生都很努力。", "explanation": "这里应该用〈全校〉。〈全市〉指整座城市，不能用来指某一所大学的学生。"}, {"text": "我们班的全市只有五个人。", "explanation": "〈全市〉指整座城市的全体，不能用来指一个班的人数，应说“全班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指整座城市，可以拥有几座大桥，符合句子的描述。"}, {"text": "全班", "is_correct": false, "explanation": "语义：“全班”指一个班级的全体，与城市的大桥无关。"}, {"text": "全年", "is_correct": false, "explanation": "搭配：“全年”说的是时间，不能作为拥有大桥的范围。"}, {"text": "全家", "is_correct": false, "explanation": "语义：“全家”指一家人的全体，与城市的大桥无关。"}], "explanations": {"全市": "全市指整座城市，可以拥有几座大桥，符合句子的描述。", "全班": "语义：“全班”指一个班级的全体，与城市的大桥无关。", "全年": "搭配：“全年”说的是时间，不能作为拥有大桥的范围。", "全家": "语义：“全家”指一家人的全体，与城市的大桥无关。"}, "sentence_index": 6, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把作业全市做完了。", "explanation": "这里应该用〈全部〉。〈全市〉指整座城市，不能表示“所有的”。"}, {"text": "他全市都在睡觉。", "explanation": "这里应该用〈全天〉。〈全市〉指城市的范围，不能用来表示一整天。"}, {"text": "这封信的全市都很感人。", "explanation": "这里应该用〈全文〉。〈全市〉指整座城市，不能用来指一篇文章的全部内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全市地商店都关门了。", "corrected_sentence": "全市的商店都关门了。", "error_description": "错误：修饰名词「商店」的「全市」要用「的」，不能用「地」；应说「全市的商店」。「地」只用于修饰动词或形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨过后，全市很停电了。", "corrected_sentence": "暴雨过后，全市都停电了。", "error_description": "错误：副词「很」不能修饰动词「停电」，应说「全市都停电了」。「都」表示全部，应放在「全市」之后、动词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
