INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "整个城市。", "primary_collocate": null, "pronunciation": "quán shì", "ipa": "tɕʰɥɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "全市的人都在看比赛。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市人民都很高兴。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市的人都出来看烟花了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市学生明天一起考试。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字全市都知道。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市都在等这场雨。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息传遍了全市。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市的医生都来帮忙了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市一起过节，特别热闹。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说全市只有他得了第一。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整个城市，指城里的全体人或整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
